	function tocreateusertoken($get){
		global $callConfig;
		$dateTimePart = date('YmdHis'); // e.g., 20250613123045
	    $randomPart = strtoupper(bin2hex(random_bytes(4))); // 8 chars hex, uppercase
	    $token = "Infisuite#".$get['user_id']."$".$dateTimePart."@".$randomPart;
		$retun_token = base64_encode($token);
		$insert_array = array('company_id'=>$get['company_id'],'user_id'=>$get['user_id'],'login_type'=>$get['login_type'],'user_token'=>$retun_token,'is_active'=>0,'current_status'=>0,'created_by'=>$get['user_id']);
		$res=$callConfig->insertRecord($get['db_name'].'.appliccation_user_login_tokens',$insert_array);
		//echo $token; exit;
		return $retun_token;
	}
	function togetbaseurlcreate($get){
    	global $callConfig;
    	$user_email = $get['chrUserName'];
    	$query = "SELECT * FROM ".MAINDB.".registered_groups WHERE id in (SELECT group_id FROM ".MAINDB.".user_registered_groups WHERE user_email = '".$user_email."' AND is_active=0)";
    	$data = $callConfig->getRow($query);
    	
   		$subdomain = '';
   		$host = $_SERVER['HTTP_HOST'];
   		//echo "Host: ".$host;//exit;
	    $parts = explode('.', $host);
	    if (count($parts) > 2) {
	      $subdomain = $parts[0];
	      if($subdomain == "www"){
	          $subdomain = $parts[1];
	      }
	    }
	    $httpshttp = isset($_SERVER['HTTPS']) ? 'https' : 'http';
	    $baseurl = $httpshttp."://".str_replace($subdomain,$data->domain_name,$host);
	    return $baseurl;
    }
