		//print_r($rowg); exit;
		if($rowg->id != ''){
			$whr = "id = '".$rowg->zqr_connect."'";
			$query=$callConfig->selectQuery(MAINDB.'.'.TBL_DATABASE_ALLOCATIONS,'*',$whr,'','','');
