		$query=$callConfig->selectQuery($dbrow->db_name.".".TBL_USERS,'*',$whr,'','','');
		//echo $query; exit;
		$data['db_name']= $dbrow->db_name;
		$row=  $callConfig->getRow($query);
		//print_r($data); exit;
		if($row->id !=""){
