			$fieldnames=array('reset_password'=>1);
			//print_r($fieldnames); exit;
			$whrcon = "user_email ='".$data['email']."'";
			$res3=$callConfig->updateRecord(MAINDB.'.'.TBL_USER_REGISTIRED_GROUPS,$fieldnames,'','',$whrcon);

		}else{
			$res['error'] = '6009';
		}
