	function toGetblancebill($get){
		global $callConfig;
		$return =$returnpaymets = $pttrans = $pttransdue =  array();
		//$returnres['get'] = $get;
		$partyids = json_decode(urldecode($get['party_id']),1);
 		$partyid = implode(',', (array)$partyids);
 		
 		//$return['partyid'] = $partyid;
		if($get['transaction_type'] == 'customers'){
			if($get['payment_process'] == "AP"){
				$gettransactionarray[] = array('sales_orders'=>array());
			}else{
				$gettransactionarray[] = array('sales_invoices'=>array('debit_notes','credit_notes'),'rental_invoices'=>array('debit_notes','credit_notes'),'utility_rental_invoices'=>array('debit_notes','credit_notes'));
			}			
		}elseif($get['transaction_type'] == 'vendors'){
			if($get['payment_process'] == "AP"){
				$gettransactionarray[] = array('purchase_orders'=>array());
			}else{
				$gettransactionarray[] = array('supplier_bills'=>array('debit_notes','credit_notes'),'purchase_invoices'=>array('debit_notes','credit_notes'));
			}
		} 
		//$return['gettransactionarray'] = $gettransactionarray;
		if($get['transaction_type'] == 'employees'){
			
			$query = "SELECT *, expense_code as transaction_number FROM emp_expenses WHERE company_id = '".$get['company_id']."' AND emp_id IN (".$partyid.") AND pending_amount > 0 AND is_active = 0 AND current_status = '".ST_APPROVED."'";
			$data = $callConfig->getAllRows($query);
			$masterid = array();
			if(count((array)$data) !=0){
				foreach($data as $ddt){
					$masterid[$ddt->id] = $ddt->id;
				}
				$return['emp_expenses'] = $data;
			}
			if(count((array)$masterid) !="0"){
				$masterids = implode(',', (array)$masterid);
				$alreadypaysql = "SELECT pay.id, pay.transaction_no, pay.payment_date, pay.current_status, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM payments pay, payment_allocations paya WHERE pay.company_id = '".$get['company_id']."' AND pay.company_id = paya.company_id AND pay.id = paya.payment_id AND paya.transaction_table = 'emp_expenses' AND paya.transaction_id IN(".$masterids.") AND pay.is_active = paya.is_active";
				$alreadypayres = $callConfig->getAllRows($alreadypaysql);
				foreach($alreadypayres as $ddt){
					$returnpaymets['emp_expenses'][$ddt->id][] = $ddt;
				}
				$query22 = "SELECT * FROM payment_term_transactions WHERE company_id = '".$get['company_id']."' AND transaction_id IN (".$masterids.") AND transaction_table = 'emp_expenses' AND pending_amount > 0 AND is_active = 0";
				$data22 = $callConfig->getAllRows($query22);
				foreach($data22 as $ptt){
					if($ptt->due_date <= $this->dateconvertdbformat($get['due_date'])){
							$pttransdue['emp_expenses'][$ptt->transaction_id] +=$ptt->pending_amount;
					}
					$pttrans['emp_expenses'][$ptt->transaction_id][] = $ptt;
				}
			}	

		}else{
			foreach ($gettransactionarray as $masttable){
				foreach($masttable as $mastertable=>$transtable){
					$query = "SELECT * FROM ".$mastertable." WHERE company_id = '".$get['company_id']."' AND party_id IN (".$partyid.") AND due_date <= '".$this->dateconvertdbformat($get['due_date'])."' AND pending_amount > 0 AND is_active = 0 AND current_status = '".ST_APPROVED."'";
					//$returnres['query333'][] = $query;
					$data = $callConfig->getAllRows($query);
					$masterid = array();
					if(count((array)$data) !=0){
						foreach($data as $ddt){
							$masterid[$ddt->id] = $ddt->id;
						}
						$return[$mastertable] = $data;
					}
					if(count((array)$masterid) !="0"){
						$masterids = implode(',', (array)$masterid);

						if($get['transaction_type'] == 'customers'){	
							$alreadypaysql = "SELECT pay.id, pay.transaction_no, pay.payment_date, pay.current_status, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM receipts pay, receipt_allocations paya WHERE pay.company_id = '".$get['company_id']."' AND pay.company_id = paya.company_id AND pay.id = paya.receipt_id AND paya.transaction_table = '".$mastertable."' AND paya.transaction_id IN(".$masterids.") AND pay.is_active = paya.is_active";
						}else{
							$alreadypaysql = "SELECT pay.id, pay.transaction_no, pay.payment_date, pay.current_status, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM payments pay, payment_allocations paya WHERE pay.company_id = '".$get['company_id']."' AND pay.company_id = paya.company_id AND pay.id = paya.payment_id AND paya.transaction_table = '".$mastertable."' AND paya.transaction_id IN(".$masterids.") AND pay.is_active = paya.is_active";
						}
						$alreadypayres = $callConfig->getAllRows($alreadypaysql);
						foreach($alreadypayres as $ddt){
							$returnpaymets[$mastertable][$ddt->id][] = $ddt;
						}
						//$returnpaymets[$mastertable] = $alreadypayres

						$query22 = "SELECT * FROM payment_term_transactions WHERE company_id = '".$get['company_id']."' AND transaction_id IN (".$masterids.") AND transaction_table = '".$mastertable."' AND pending_amount > 0 AND is_active = 0";
						//$returnres['query22'][] = $query22;
						$data22 = $callConfig->getAllRows($query22);
						foreach($data22 as $ptt){
							if($ptt->due_date <= $this->dateconvertdbformat($get['due_date'])){
	 							$pttransdue[$mastertable][$ptt->transaction_id] +=$ptt->pending_amount;
							//}elseif($ptt->advance_offer_date <= $this->dateconvertdbformat($get['due_date'])){
							//	$pttransdue[$mastertable][$ptt->transaction_id] +=$ptt->advance_offer_amount;
							}
							$pttrans[$mastertable][$ptt->transaction_id][] = $ptt;
						}
					}
					foreach ($transtable as $subtranstable){
						//$query = "SELECT * FROM ".$subtranstable." WHERE company_id = '".$get['company_id']."' AND party_id IN (".$partyid.") AND due_date <= '".$this->dateconvertdbformat($get['due_date'])."' AND ref_type = '".$mastertable."' AND pending_amount > 0 AND is_active = 0 AND current_status = '".ST_APPROVED."'";
						
						$query = "SELECT * FROM ".$subtranstable." WHERE company_id = '".$get['company_id']."' AND party_id IN (".$partyid.") AND ref_type = '".$mastertable."' AND pending_amount > 0 AND is_active = 0 AND current_status = '".ST_APPROVED."'";
						$data = $callConfig->getAllRows($query);
						$subtabid = array();
						if(count((array)$data) !=0){
							foreach($data as $ddt){
								$subtabid[$ddt->id] = $ddt->id;
							}
							$return[$subtranstable] = $data;
						}
						if(count((array)$subtabid) !="0"){
							$subtabids = implode(',', (array)$subtabid);
							if($get['transaction_type'] == 'customers'){		
								$alreadypaysql1 = "SELECT pay.id, pay.transaction_no, pay.payment_date, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM receipts pay, receipt_allocations paya WHERE pay.company_id = '".$get['company_id']."' AND pay.company_id = paya.company_id AND pay.id = paya.receipt_id AND paya.transaction_table = '".$subtranstable."' AND paya.transaction_id IN(".$subtabids.") AND pay.is_active = paya.is_active";
							}else{
									$alreadypaysql1 = "SELECT pay.id, pay.transaction_no, pay.payment_date, paya.transaction_table, paya.transaction_id, paya.transaction_no, paya.paid_amonut, paya.tds_amount FROM payments pay, payment_allocations paya WHERE pay.company_id = '".$get['company_id']."' AND pay.company_id = paya.company_id AND pay.id = paya.payment_id AND paya.transaction_table = '".$subtranstable."' AND paya.transaction_id IN(".$subtabids.") AND pay.is_active = paya.is_active";
								
							}
							$alreadypayres1 = $callConfig->getAllRows($alreadypaysql1);
							foreach($alreadypayres1 as $ddt){
								$returnpaymets[$subtranstable][$ddt->id][] = $ddt;
							}

						}
					}
				}
			}
		}
		$returnres['transactions'] = $return;
		$returnres['transaction_payment_allocations'] = $returnpaymets;
		$returnres['payment_term_transactions'] = $pttrans;
		$returnres['payment_term_transactions_due'] = $pttransdue;
		//echo "<pre>"; print_r($returnres);
		return $returnres;
	}

