	function invoiceUpdates($table,$len){
		global $callConfig;
		
		if(count((array)$len)>1){
			$request_warehouse_id = $len['request_warehouse_id'] ?? 1;
			//$request_warehouse_id = $len['request_warehouse_id'];
			unset($len['request_warehouse_id']);
			$GRN_loc_item_wa_balances = $this->insertoupdatelocitemwabalances($len);
			$GRN_loc_item_st_balances = $this->insertoupdatelocitemstbalances($len);
			
			$reverseentry = array('stock_transfers','stock_transfer_receipts','subcontract_work_order_transfers','subcontract_work_order_receipts');

			if(in_array($len['document_type'], $reverseentry)){
				$len['transaction_warehouse_id'] = $request_warehouse_id;
				if($len['document_type'] == "stock_transfers" || $len['document_type'] == "subcontract_work_order_transfers"){
					$len['in_qty'] = $len['out_qty'];
					$len['in_value'] = $len['out_value'];
					$len['out_qty'] = 0;
					$len['out_value'] = 0;
				}else{
					$len['out_qty'] = $len['in_qty'];
					$len['out_value'] = $len['in_value'];
					$len['in_qty'] = 0;
					$len['in_value'] = 0;
				}
				$GRN_loc_item_wa_balances = $this->insertoupdatelocitemwabalances($len);
				$GRN_loc_item_st_balances = $this->insertoupdatelocitemstbalances($len);
			}
			$GRN_loc_item_ledgerst = $this->insertorupdateitem_ledgerst($len);
			$GRN_loc_item_ledgerwa = $this->insertorupdateitem_ledgerwa($len);

			$GRN_loc_item_wa_balances = $this->insertoupdateitemwabalances($len);
			
			$GRN_loc_item_st_balances = $this->insertoupdateitemstbalances($len);
			$GRN_loc_item_fifio = $this->insertorupdateitemfifo($len);
		}
	}

