		function tocreatejounalvoucherbaseallcases($table_name,$ref_id,$type=''){
		global $callConfig;	

		$defaultaccount = DEFAULTACCOUNTS; // Default account array array('inventory_asset_account' => '1003809', 'inventory_adjustment_account'=>'50000106', 'cogs_account' => '50000151', 'purchase_expense_account'=>'20003507', 'sales_revenue_account'=>'40001101', 'sales_return_account'=>'10003700', 'ap_account'=>'20003501', 'ar_account'=>'1004001', 'goods_received_not_invoiced_account'=>'20003506', 'goods_sold_not_invoiced_account'=>'1004003','default_cash_acct'=>'10005101', 'default_purchase_discount_account'=>'40001109', 'jv_suspense_acc'=>'200037018', 'tds_clearing_account'=>'20003701', 'tds_payables'=>'20003702', 'tcs_clearing_account'=>'20003701', 'tcs_payables'=>'20003716', 'default_sales_discount_account'=>'50002714', 'default_round_off_account'=>'5002557', 'config_inventory_asset_account'=>'1003809')




		$rounddigits = 2;
		$whr="id=".$ref_id;
		$query1=$callConfig->selectQuery($table_name,'*',$whr,'','','');
		$row = $callConfig->getRow($query1);
		$row = (array)$row;
		
		$partysql = "SELECT au.*, (SELECT department_id FROM cost_centers cc WHERE au.company_id = cc.company_id AND au.cost_center = cc.id AND au.is_active = cc.is_active) as department_id FROM application_users au WHERE au.company_id = '".$row['company_id']."' AND au.id = '".$row['originator']."' AND au.is_active = 0";	
		$user = $callConfig->getRow($partysql);

		$transaction_departsql = "SELECT department_id FROM cost_centers WHERE company_id = '".$row['company_id']."' AND id = '".$row['cost_center_id']."' AND is_active = 0";
		$transdepartres = $callConfig->getRow($transaction_departsql);

		$whrs = "company_id= ".$row['company_id']." AND is_active = 0";
		$query = $callConfig->selectQuery('config','*',$whrs,'','','');
		$config = $callConfig->getRow($query);
		
		$suspense_account = $config->jv_suspense_acc!=""?$config->jv_suspense_acc:$defaultaccount['jv_suspense_acc'];
		$default_round_off_account = $config->default_round_off_account!=""?$config->default_round_off_account:$defaultaccount['default_round_off_account'];

		// $whr = "application_table_name= '".$table_name."' AND field_name = '".$filed_name."'";
		// $query=$callConfig->selectQuery(TBL_DISPLAYATTRIBUTES_TYPE,'*',$whr,'','','');
		// $data = $callConfig->getRow($query);

		$display_attribute_typessql = "SELECT content FROM display_attribute_types WHERE company_id = '".$row['company_id']."' AND application_table_name = '".$table_name."' AND field_name = 'party_id'";	
		$parttable_name = $callConfig->getRow($display_attribute_typessql);
		$qquery = urldecode($parttable_name->content);
		$explosql = explode("FROM", $qquery); // splite from to get table name and other part get
		if(isset($explosql[1])){
			$explosql = explode(" ", trim($explosql[1])); //splite to space only get table name
		}
		$partytable = trim($explosql[0]); //get Table name


		if($table_name == 'debit_notes' OR $table_name == 'credit_notes'){
			if($row['ref_type'] == "purchase_invoices" || $row['ref_type'] == "supplier_bills" || $row['ref_type'] == "purchase_invoice_cancellations"  || $row['ref_type'] == "supplier_bill_cancellations" || $row['ref_type'] == "purchase_order_cancellations"){
				$partytable = "vendors";
			}elseif($row['ref_type'] == "sales_invoices" || $row['ref_type'] == "sales_invoice_cancellations" || $row['ref_type'] == "sales_order_cancellations" || $row['ref_type'] ==  "sample_orders"){
				$partytable = "customers";
			}	
		}	
