	function addjournalvouchers($post, $table, $type='',$mtable = ''){
		global $callConfig;
		$return = array();
		if($mtable ==""){
			$mtable = 'journal_vouchers';
		}
		//$mtable = 'journal_vouchers';
		$fieldarray  = $this->toGetInvoicetables();
		$return['post']= $post;
