    function upadateblukapproval($data){
    	global $callConfig;
    	$ids = trim($data['rid'],',');
    	$table = $data['table'];
    	$status = $data['status'];
    	$ids = explode(",", $ids);
    	//print_r($ids); exit;
    	foreach ($ids as $id) {
    		$array['table_name'] = $table; 
    		$array['status'] = $status; 
    		$array['hid'] = $id; 
    		$array['comments'] = '';
    		$array['user_id'] = $data['user_id'];
    		$array['company_id'] = $data['company_id'];
    		//print_r($array); exit;
    		$res = $this->upadteablukprrovals($array); 
    	}
    	return $res;
    }
