	$application_pagessql = "SELECT ap.insert_page_name,ap.application_table_name, da.page_title  FROM application_pages ap, display_attributes da WHERE ap.company_id = da.company_id AND ap.company_id = '".$company_id."' AND ap.application_table_name = da.application_table_name AND ap.is_active = da.is_active AND ap.is_active = 0"; 
