	$display_details = $callConfig->getAllRows($display_data);
	$task_details['task_list'] = $display_details;	


	if($filter_id != ""){
		//$filterurl = "select * from filter_tables where is_active='0' and company_id='".$company_id."' AND transaction_id='".$filter_id."'"; 
		$filterurl = "select * FROM filter_tables WHERE is_active='0' and company_id='".$company_id."' AND id='".$filter_id."'"; 
		$filterdetails = $callConfig->getRow($filterurl);
		$task_details['filter_data'] = $filterdetails;
	}


	$process_task_settingssql = "SELECT * FROM process_task_settings WHERE company_id='".$company_id."' AND  id = '".$get['rid']."' AND is_active='0'"; 
	$process_task_settingsres = $callConfig->getRow($process_task_settingssql);
	$task_details['process_task_settings'] = $process_task_settingsres;
	
	$task_process_typesql = "SELECT id, genc_detail_code, genc_detail_name FROM general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='TASKPROCESSTYPE' order by id ASC"; 
	$task_process_typeres = $callConfig->getAllRows($task_process_typesql);
	$task_details['task_process_type'] = $task_process_typeres;	

	$triggerdatetypesql = "SELECT id, genc_detail_code, genc_detail_name FROM general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='TRIGGERDATETYPE'"; 
	$triggerdatetyperes = $callConfig->getAllRows($triggerdatetypesql);
	$task_details['trigger_date_type'] = $triggerdatetyperes;

	$email_contentsql = "SELECT id, template_name FROM email_content where is_active='0' and company_id='".$company_id."'"; 
	$email_contentres = $callConfig->getAllRows($email_contentsql);
	$task_details['email_content'] = $email_contentres;
	

	$module_setupsql = "SELECT id, module_id, display_name FROM module_setup where company_id='".$company_id."' AND is_active='0' "; 
	$module_setupres = $callConfig->getAllRows($module_setupsql);
	$task_details['module_setup'] = $module_setupres;
	

	return $task_details;
}
function processtasksettings($post,$get) {
	global $callConfig;
	$rowid = $post['row_id'];
	$module_id = $post['module_setup_id'];
	$link_page = $post['link_page'] == '0'?"0":"1";
	if($rowid!=''){ 
		$post_array= array("module_setup_id"=>$module_id,"task_name"=>$post['task_name'],"assigned_to"=>$post['assigned_to'],"approval_type"=>$post['approval_type'],"process_id"=>$post['process_id'],"email_content_id"=>$post['email_content_id'],"process_type"=>$post['process_type'],"no_action"=>$post['no_action'],"on_the_day"=>$post['on_the_day'],"action_no"=>$post['action_no'],"action_frequency"=>$post['action_frequency'],"before_or_after"=>$post['before_or_after'],"description"=>$post['description'],"files"=>$post['files'],"display_color"=>$post['display_color'],"display_background_color"=>$post['display_background_color'],"remarks"=>$post['remarks'],"task_for"=>$post['task_for'],"link_page"=>$link_page,"page_url"=>$post['page_url'],"updated_date"=>date('Y-m-d H:i:s'),"updated_by"=>$post['created_by'],"user_id"=>$post['other_id'],"company_id"=>$get['company_id'],"is_active"=>'0',"check_list"=>$post['check_list'],'planned_day'=>$post['planned_day'],'trigger_date'=>$post['trigger_date']);
		$res=$callConfig->updateRecord(TBL_PROCESS_TASK_SETTINGS,$post_array,'id',$rowid);
	}else{
		foreach($post['module_setup_id'] as $module_id){
			$post_array= array("module_setup_id"=>$module_id,"task_name"=>$post['task_name'],"assigned_to"=>$post['assigned_to'],"process_id"=>$post['process_id'],"email_content_id"=>$post['email_content_id'],"process_type"=>$post['process_type'],"no_action"=>$post['no_action'],"on_the_day"=>$post['on_the_day'],"action_no"=>$post['action_no'],"action_frequency"=>$post['action_frequency'],"before_or_after"=>$post['before_or_after'],"description"=>$post['description'],"files"=>$post['files'],"display_color"=>$post['display_color'],"display_background_color"=>$post['display_background_color'],"remarks"=>$post['remarks'],"task_for"=>$post['task_for'],"link_page"=>$link_page,"page_url"=>$post['page_url'],"created_date"=>date('Y-m-d H:i:s'),"created_by"=>$post['created_by'],"user_id"=>$post['other_id'],"company_id"=>$get['company_id'],"is_active"=>'0',"check_list"=>$post['check_list'],"current_status"=>"0","approval_type"=>$post['approval_type'],"approval_other_id"=>$post['approval_other_id'],'planned_day'=>$post['planned_day'],'trigger_date'=>$post['trigger_date']);
			$res=$callConfig->insertRecord(TBL_PROCESS_TASK_SETTINGS,$post_array);
			$update_transaction_id = array("transaction_id"=>$res['LASTID']);
			if($post['filtertbl_rowid'] !=""){
				$res_filters=$callConfig->updateRecord(TBL_FILTER_TABLES,$update_transaction_id,'id',$post['filtertbl_rowid']);
			}
		}	
	}
	
	return $res;
}
function gettotalemployeesbyfilter($post,$get) {
	global $callConfig;
	$company_id = $get['company_id'];
	$table_name = $post['table'];
	$cond = "";
	$count=0;
	foreach ($post as $key => $value) {
		$explode = explode(",",$value);  // rohan added (1,2,3) NEW ('1','2','3')
		$vall = "'" . implode ( "', '", (array)$explode) . "'";
		if($key!='page' && $value!='' && $key!='table') {
			$cond.= " AND ".$key." IN (".$vall.")";
		}
	}
	if($cond!=''){
		$display_data = "select * from ".$table_name." where is_active='0' and company_id='".$company_id."'".$cond; 
	//echo $display_data;//exit;
		$display_details = $callConfig->getAllRows($display_data);
		$count = count((array)$display_details);

	}
	$response['count'] = $count;
	$emplist = array();
	foreach ($display_details as $value) {
		$empdata['id_value'] = $value->id;
		$empdata['display_name'] = $value->display_name;
		$empdata['image'] = $value->image;
		$emplist[] = $empdata;
	}
	$response['details'] = $emplist;
	return $response;
}
function savetofiltertable($post,$get) {
	global $callConfig;
	$rowid = $post['row_id'];
	if($rowid!='') {
		$post_array= array("application_tablename"=>$post['appln_table'],"filter_condition"=>$post['filter_condition'],"content"=>$post['jsoncontent'],"updated_date"=>$post['updated_date'],"updated_by"=>$_SESSION['user_id'],"company_id"=>$get['company_id'],"is_active"=>'0');

		$res=$callConfig->updateRecord(TBL_FILTER_TABLES,$post_array,'id',$rowid);
		$res['LASTID'] = $rowid;
	} else {
		$post_array= array("application_tablename"=>$post['appln_table'],'module_setup_id'=>$callConfig->module_id,"filter_condition"=>$post['filter_condition'],"content"=>$post['jsoncontent'],"created_date"=>$post['created_date'],"created_by"=>$post['user_id'],"company_id"=>$get['company_id'],"is_active"=>'0');
		$res=$callConfig->insertRecord(TBL_FILTER_TABLES,$post_array);
	}
	return $res;
}
