		$storedata['role_id'] = $post['role_type'];
		$storedata['field_list'] = $post['field_list'];
		$res=$callConfig->updateRecord(TBL_EMPLOYEES_DISPLAY_FIELDS,$storedata,'id',$rowid);
	} else {
		//insert
		$storedata['role_id'] = $post['role_type'];
		$storedata['company_id'] = $post['company_id'];
		$storedata['is_active'] = $post['is_active'];

		$storedata['field_list'] = $post['field_list'];
		$storedata['created_date'] = $storedata['updated_date'];
		$storedata['created_by'] = $post['user_id'];
		$res=$callConfig->insertRecord(TBL_EMPLOYEES_DISPLAY_FIELDS,$storedata);

	}
	

	return $res;
}


