    function getsalaryreportinggroupsdata($get){
    	global $callConfig;
    	$finiancial_year_start_month = 4; $total_months_in_year = 12;
    	$project_date = $get['projected_date']; 
    	$project_month = date("m", strtotime($project_date));
    	$project_year = date("Y",strtotime($project_date));
    	$project_day = date("d",strtotime($project_date));
    	$report_header = "select * from config where company_id='".$get['company_id']."' and is_active='0'";
    	$report_header_data = $callConfig->getRow($report_header);
    	$salary_reports['report_header'] = $report_header_data;
    	$payroll_day = $report_header_data->default_payroll_day;
    	$assessment_year = $report_header_data->assessment_year == "" ? "0" : $report_header_data->assessment_year;
    	$in_assessment_year = explode("-", $assessment_year);
    	$old_regime_year = ($in_assessment_year[0]-1).$in_assessment_year[0]; 
    	$assessment_date = $in_assessment_year[0]."-".$finiancial_year_start_month."-01";
    	for($m=1;$m<$total_months_in_year+1;$m++){
    		$finiancial_year_start_month = ($finiancial_year_start_month >12)?($finiancial_year_start_month-12):$finiancial_year_start_month;
    		$monthly_wise_taxyear[$finiancial_year_start_month] = $m;
    		$finiancial_year_start_month= $finiancial_year_start_month+1;
    	}
    	if($project_day > $payroll_day){
    		$month_wise_key = $project_month;
    	}else{
    		$month_wise_key = $project_month-1;
    	}
    	$month_wise_key = $month_wise_key!=0 ? $month_wise_key : 12;
    	$salary_reports['actual_months'] = $monthly_wise_taxyear[$month_wise_key];
    	$salary_reports['projected_months'] = $total_months_in_year-$salary_reports['actual_months'];

    	$employeequery1 = "SELECT * FROM `employees` WHERE id = ".$get['employee_id']." AND is_active=0 AND company_id=".$get['company_id'];
    	$empdata = $callConfig->getRow($employeequery1);
    	$designationquery1 = "SELECT * FROM `designations` WHERE id = ".$empdata->designation_id." AND is_active=0 AND company_id=".$get['company_id'];
    	$designationquerydata = $callConfig->getRow($designationquery1);
    	$salary_reports['employee_designation'] = $designationquerydata->designation_name; 
    	$salary_reports['employee_details'] = $empdata;

    	$reporting_data = "select * from salary_reporting_groups where company_id='".$get['company_id']."' and is_active='0'  order by display_seq";
    	$reporting_details = $callConfig->getAllRows($reporting_data);
    	$salary_reports['parent_group'] = $reporting_details;  

    	$fetchdate = $assessment_date;
    	for($k=0; $k<$salary_reports['actual_months']; $k++) {
    		$fetch_month = date('m',strtotime($fetchdate));
    		$fetch_year = date('Y',strtotime($fetchdate));
        	//echo "<br>".$fetch_month."||".$fetch_year."<br>";
    		$pay_run_summary_query = "select * from pay_run_summary where employee_id='".$get['employee_id']."' and pay_month='".$fetch_month."' and pay_year='".$fetch_year."' and is_active='0' and company_id=".$get['company_id'];
    		$prsde = $callConfig->getRow($pay_run_summary_query);
        	//print_r($prsde); exit;
    		$payrunsum = "select * from pay_summary_components where pay_summary_id='".$prsde->id."' and pay_month='".$fetch_month."' and pay_year='".$fetch_year."' and is_active='0' and company_id=".$get['company_id'];
           // $payrunsum = "select * from pay_run_summary where employee_id='".$get['employee_id']."' and pay_month='".$fetch_month."' and pay_year='".$fetch_year."' and is_active='0' and company_id=".$get['company_id'];
    		echo $payrunsum; exit;
    		$payrunsum_details = $callConfig->getAllRows($payrunsum);
    		foreach ($payrunsum_details as $pdetails) {
    			$payrunsum_idlist[$fetch_month."-".$fetch_month][$pdetails->component_id] = $pdetails;
    			$totalcomponent[$pdetails->component_id] = $totalcomponent[$pdetails->component_id] !="" ? $totalcomponent[$pdetails->component_id]:0;
    			$totalcomponent[$pdetails->component_id] = $totalcomponent[$pdetails->component_id]+$pdetails->salary_component_actual;
    		}
    		$fetchdate = date("Y-m-d", strtotime($fetchdate."+1 month"));
    	}
    	$salary_reports['payrunsummer_totalcomponets'] = $totalcomponent;

    	$salary_reports['payrunsummer_monthlycomponet'] = $payrunsum_idlist;
    	foreach ($salary_reports['parent_group'] as $mapped_data) {
    		$group_id = $mapped_data->id;
    		$reporting_group = "select * from earnings where company_id='".$get['company_id']."' and is_active='0' and report_group_id='".$group_id."'";
    		$reporting_group_data = $callConfig->getAllRows($reporting_group);
    		$salary_dtails[$group_id] = $reporting_group_data;
    	}
    	$salary_reports['child_group'] = $salary_dtails;

    	$salarytempquery = "SELECT max(st.affected_date) max_affected_date, stc.component_id as component_id, stc.monthly_amount as projected, salary_template_id ,FROM `salary_template` st, salary_template_components stc where st.id = stc.salary_template_id and st.company_id = stc.company_id  and st.employee_id ='".$get['employee_id']."' and  st.company_id='".$get['company_id']."' AND st.is_active = 0 and stc.is_active=0";
    	$salarytempquery_projected = $callConfig->getAllRows($salarytempquery);
    	foreach ($salarytempquery_projected as $projected) {
    		$salay_template[$projected->component_id] = $projected;
    	}
    	$salary_reports['salary_monthlycomponet'] = $salay_template;

    	$old_regime = str_replace('-', '', $old_regime_year); $assessment = str_replace('-', '', $assessment_year);
    	$salary_tax_components_pquery = "SELECT  * from salary_tax_components where company_id=".$get['company_id']." AND is_active=0 AND assesment_year in('".$old_regime."','".$assessment."')";
        //echo $salary_tax_components_pquery ;
    	$salary_tax_components_datas = $callConfig->getAllRows($salary_tax_components_pquery);
    	foreach ($salary_tax_components_datas as $salary_tax_components_data) {
    		if($salary_tax_components_data->assesment_year == $old_regime ){
    			$salary_tax_components['old_regime'][$salary_tax_components_data->salary_component_id] = $salary_tax_components_data->taxable!='' ?$salary_tax_components_data->taxable : 0;

    		}else{
    			$salary_tax_components['new_regime'][$salary_tax_components_data->salary_component_id] = $salary_tax_components_data->taxable!='' ?$salary_tax_components_data->taxable : 0;
    		}
    	}
    	$salary_reports['salary_tax_components'] = $salary_tax_components;
    	return $salary_reports;

    }  
    function saveusersettings($post,$get) {
    	global $callConfig;
    	$rowid = $post['rowid'];
    	if($rowid!='') {
    		$post_array= array("setting"=>$post['jsonsetting'],"updated_date"=>$post['load_date'],"updated_by"=>$post['user_id']);
    		$res=$callConfig->updateRecord(TBL_USER_SETTINGS,$post_array,'id',$rowid);
    		$inserted_rowid=$rowid;
    	} else {
    		$post_array = array("company_id"=>$get['company_id'], "emp_id"=>$post['emp_id'], "fieldname"=>$post['fieldname'], "setting"=>$post['jsonsetting'], "created_date"=>$post['load_date'], "created_by"=>$post['user_id'],"is_active"=>'0');
    		$res=$callConfig->insertRecord(TBL_USER_SETTINGS,$post_array);
    		$inserted_rowid = $res['LASTID'];
    	}
    	return $inserted_rowid;
    }
    
