    function togetleaveform($get){
    	global $callConfig;
    	$whr="is_active='0' and company_id=".$get['company_id'];
    	$query=$callConfig->selectQuery('leave_categories','*',$whr,'','','');
    	$categories = $callConfig->getAllRows($query);
    	$details['leave_categories'] = (array)$categories;

    	$whrcon = "is_active='0' and company_id=".$get['company_id']." and id=".$get['id'];
    	$query=$callConfig->selectQuery('leave_types','*',$whrcon,'','','');
    	$leavetypes = $callConfig->getRow($query);
    	$details['leave_types'] = $leavetypes;

    	$whrcon = "is_active='0' and company_id=".$get['company_id']." and leave_type_id=".$get['id'];
    	$query=$callConfig->selectQuery('leave_type_levels','*',$whrcon,'','','');
    	$leavetypes = $callConfig->getAllRows($query);
    	$details['leave_type_levels'] = $leavetypes;

    	$filterurl = "select * from filter_tables where is_active='0' and company_id='".$get['company_id']."' AND transaction_id='".$get['id']."' AND application_tablename = 'leave_types'"; 
    	$filterdetails = $callConfig->getRow($filterurl);
    	$details['filter_data'] = $filterdetails;
    	return $details;
    }
    function saveleaveapplication($post,$get){
    	$returnaray = array();

    	global $callConfig;
    	if($get['rid']=='') {
    		$leavetypes = array('leave_category_id'=>$post['category_name'],'leave_type_name'=>$post['leave_type_name'],'first_accrual'=>$post['first_accrual'],'accruals_happen'=>$post['accruals_happen'],'encashment'=>$post['encashment'],'percentage'=>$post['percentage'],'weekends_between_leave_period'=>$post['weekends_between_leave_period'],'holidays_between_leave_period'=>$post['holidays_between_leave_period'],'exceed_leave_balance'=>$post['exceed_leave_balance'],'duration_allowed'=>$post['duration_allowed'],'employee_filter'=>$post['employee_filter'],'weekend_leave_count'=>$post['weekend_leave_count'],'holiday_leave_count'=>$post['holiday_leave_count'],'duration_leave_count'=>$post['duration_leave_count'],'half_day'=>$post['half_day'],'filtertbl_rowid'=>$_POST['filtertbl_rowid'],'company_id'=>$get['company_id'],'created_by'=>$post['created_by'],'created_date'=>$post['created_date'],'is_active'=>'0');
    		$res=$callConfig->insertRecord(TBL_LEAVE_TYPES,$leavetypes);
    		$returnaray['TBL_LEAVE_TYPES'] = $res;
    		$leave_type_id = $res['LASTID'];
    		foreach ($post['action_number'] as $key => $value) {
    			$month_year_weeck = "";
    			$day = "";
    			if($post['accured_action_based'][$key] == "W"){
    				$month_year_weeck = $post['on_the_week'][$key]; 
    			}else if($post['accured_action_based'][$key] == "M"){
    				$day = $post['on_the_day'][$key];
    			}elseif($post['accured_action_based'][$key] == "Y"){	
    				$month_year_weeck = $post['on_the_month'][$key];
    				$day = $post['on_the_day_year'][$key];
    			}
    			$leavetypelevels = array('month_year_weeck'=>$month_year_weeck,'day'=>$day,'leave_type_id'=>$leave_type_id,'action_number'=>$post['action_number'][$key],'action_frequency'=>$post['action_frequency'][$key],'before_or_after'=>$post['before_or_after'][$key],'base_on'=>$post['base_on'][$key],'accured_action_based'=>$post['accured_action_based'][$key],'accured_action_frequency'=>$post['accured_action_frequency'][$key],'max_accured_limit'=>$post['max_accured_limit'][$key],'leave_span'=>$post['leave_span'][$key],'carry_over_limit_type'=>$post['carry_over_limit_type'][$key],'carry_over_limit'=>$post['carry_over_limit'][$key],'company_id'=>$get['company_id'],'created_by'=>$post['created_by'],'created_date'=>$post['created_date'],'is_active'=>'0');
