    function getterminatesettings($get){
    	global $callConfig;

    	if($get['Rid'] !=""){
    		$terminationsql = "SELECT * FROM ".TBL_EMPLOYEE_TERMINATIONS." WHERE company_id = '".$get['company_id']."' AND id = '".$get['Rid']."' AND is_active = 0";
    	}else{
    		$terminationsql = "SELECT * FROM ".TBL_EMPLOYEE_TERMINATIONS." WHERE company_id = '".$get['company_id']."' AND emp_id = '".$get['employee_id']."' AND current_status !=40 AND is_active = 0";
    	}
    	$terminationres =  $callConfig->getRow($terminationsql);
    	$details['employee_terminations'] = $terminationres;
    	if(isset($terminationres->id) AND $terminationres->id !=""){
    		$emp_id = 	$terminationres->emp_id;
    	}else{
    		$emp_id = $get['employee_id'];
    	} 
    	$employeessql = "SELECT id,display_name,job_title_id,user_id FROM employees WHERE company_id = '".$get['company_id']."' AND id = '".$emp_id."' AND is_active = 0";
    	$employeesres =  $callConfig->getRow($employeessql);
    	$details['employees'] = $employeesres;
    	$job_title_id = $employeesres->job_title_id;


    	$emp_assetssql = "SELECT emp_a.id,emp_a.allocation_type, (SELECT asset_description FROM assets ass where emp_a.company_id = ass.company_id AND emp_a.asset_id = ass.id AND emp_a.is_active = ass.is_active) as asset_description ,emp_a.current_status FROM user_assets emp_a WHERE emp_a.company_id = '".$get['company_id']."' AND emp_a.user_id = '".$employeesres->user_id."' AND emp_a.is_active = 0";
    	$emp_assetsres =  $callConfig->getAllRows($emp_assetssql);
    	$details['emp_assets'] = $emp_assetsres;


    	$process_task_settingssql = "SELECT id,task_name FROM process_task_settings WHERE company_id = '".$get['company_id']."' AND process_type = 'E' AND is_active = 0";
    	$process_task_settingsres =  $callConfig->getAllRows($process_task_settingssql);
    	$details['process_task_settings'] = $process_task_settingsres;


    	$whrconfig ="is_active='0' and company_id=".$get['company_id']." and id=".$job_title_id;  
    	$queryconfig=$callConfig->selectQuery('job_titles','notice_period',$whrconfig,'','','');
    	$config = $callConfig->getRow($queryconfig);
    	$notice_period = $config->notice_period;
    	if($notice_period ==""){
    		$whrconfig ="is_active='0' and company_id=".$get['company_id'];
    		$queryconfig=$callConfig->selectQuery('config','default_notice_perieod',$whrconfig,'','','');
    	$config = $callConfig->getRow($queryconfig);
    	$notice_period = $config->default_notice_perieod;
    	}
    	$details['notice_period'] = $notice_period;


    	$whr3 = "company_id = ".$get['company_id']." AND genc_code='SEPERATION_MODE' AND is_active = 0";    
    	$query3=$callConfig->selectQuery(TBL_GENRAL_CODE_DETAILS,'genc_detail_code,genc_detail_name',$whr3,'','','');
    	$gc_data = $callConfig->getAllRows($query3);
    	foreach ($gc_data as $gc) {
    		$gcdata[$gc->genc_detail_code] = $gc->genc_detail_name;
    	}
    	$details['separation_mode'] = $gcdata;

    	$whr3 = "company_id = ".$get['company_id']." AND genc_code='TERMINATION_TYPE' AND is_active = 0";    
    	$query3=$callConfig->selectQuery(TBL_GENRAL_CODE_DETAILS,'genc_detail_code,genc_detail_name',$whr3,'','','');
    	$gc_data1 = $callConfig->getAllRows($query3);
    	foreach ($gc_data1 as $gc) {
    		$gcdata1[$gc->genc_detail_code] = $gc->genc_detail_name;
    	}
    	$details['termination_type'] = $gcdata1;

    	$connect['employee_id'] = $emp_id;
    	$connect['company_id'] = $get['company_id'];
    	$returnresp  =  $this->getempconnectwithempid($connect);
    	$details['connect'] = $returnresp;
    	$details['hr_user_id'] = $returnresp['hr_connect'];
    	$details['report_to'] = $returnresp['report_to'];
    	$details['finance_connect'] = $returnresp['finance_connect'];
    	return $details;
    }
