	function insertrecognition($post,$get){
		global $callConfig;
		$whr4 = "company_id = ".$get['company_id']." AND is_active = 0";	
		$query4=$callConfig->selectQuery('recognition_badges','*',$whr4,'','','');
		$badgesdata = $callConfig->getAllRows($query4);
		foreach ($badgesdata as $badge) {
			$badges[$badge->id] = $badge->image;
		}
		$recognized_employees = explode(',',$post['recognition_to']);
		if($get['rid']==''){
			foreach ($recognized_employees as $rkey => $rvalue) {
				$recognition_to = $rvalue;
				$post['recognition_to'] = $rvalue;
				$remarks_data = array('recognition_from'=>$post['recognition_from'],'recognition_to'=>$rvalue,'badge_id'=>$post['badge_id']);
				$remarks = json_encode($remarks_data,1);
				$queryemp = "SELECT display_name FROM employees WHERE is_active=0 and company_id=".$get['company_id']." and id =".$recognition_to;
				$empdata = $callConfig->getRow($queryemp);
				$displaynameslist = $empdata->display_name;
				if($post['display_in_announcement']==0){

					$announcedata = array("company_id"=>$get['company_id'],"announcement_category_id"=>ST_RECOGINITION_ANNOUNCEMENT_CATEGORY_ID,'announcement_heading'=>$displaynameslist, 'announcement_message'=>$post['comments'],'start_date'=>date('Y-m-d'),'expiry_date'=>date('Y-m-d', strtotime($date. ' + 5 days')),'remarks'=>$remarks,'is_active'=>'0','created_by'=>$post['created_by'],'created_date'=>$post['created_date']);
					$res=$callConfig->insertRecord(TBL_COMPANY_ANNOUNCEMENTS,$announcedata);
					$post['company_announcement_id'] = $res['LASTID'];
				}
				$res=$callConfig->insertRecord(TBL_EMPLOYEE_RECOGNITIONS,$post);
			}
		}
		else{
			foreach ($recognized_employees as $rkey => $rvalue) {
				$recognition_to = $rvalue;
				$post['recognition_to'] = $rvalue;
				$remarks_data = array('recognition_from'=>$post['recognition_from'],'recognition_to'=>$rvalue,'badge_id'=>$post['badge_id']);
				$remarks = json_encode($remarks_data,1);
				$queryemp = "SELECT display_name FROM employees WHERE is_active=0 and company_id=".$get['company_id']." and id =".$recognition_to;
				$empdata = $callConfig->getRow($queryemp);
				$displaynameslist = $empdata->display_name;
				if($post['company_announcement_id']!='0'){
					if($post['display_in_announcement']==0){
						$announcedata = array("company_id"=>$get['company_id'],"announcement_category_id"=>ST_RECOGINITION_ANNOUNCEMENT_CATEGORY_ID,'announcement_heading'=>$displaynameslist, 'announcement_message'=>$post['comments'],'start_date'=>date('Y-m-d'),'expiry_date'=>date('Y-m-d', strtotime($date. ' + 5 days')),'remarks'=>$remarks,'is_active'=>'0','created_by'=>$post['created_by'],'created_date'=>$post['created_date']);
						$res=$callConfig->updateRecord(TBL_COMPANY_ANNOUNCEMENTS,$announcedata,'id',$post['company_announcement_id']);
					}else {
						$announcedata = array("is_active"=>'1');
						$res=$callConfig->updateRecord(TBL_COMPANY_ANNOUNCEMENTS,$announcedata,'id',$post['company_announcement_id']);
						$post['company_announcement_id'] = '0';
					} 
				}else{
					if($post['display_in_announcement']==0){
						$announcedata = array("company_id"=>$get['company_id'],"announcement_category_id"=>ST_RECOGINITION_ANNOUNCEMENT_CATEGORY_ID,'announcement_heading'=>$displaynameslist, 'announcement_message'=>$post['comments'],'start_date'=>date('Y-m-d'),'expiry_date'=>date('Y-m-d', strtotime($date. ' + 5 days')),'remarks'=>$remarks,'is_active'=>'0','created_by'=>$post['created_by'],'created_date'=>$post['created_date']);
						$result=$callConfig->insertRecord(TBL_COMPANY_ANNOUNCEMENTS,$announcedata);
						$post['company_announcement_id'] = $result['LASTID'];
					}
				}
				$res=$callConfig->updateRecord(TBL_EMPLOYEE_RECOGNITIONS,$post,'id',$get['rid']);
			}
		}
		return $res;
	}

