			$res=$callConfig->updateRecord(TBL_EMPLOYEES,array($fieldname => $updatevalue),'id',$avalue->emp_id);
			$res=$callConfig->updateRecord(TBL_TRANSFER_HISTORY_EMPLOYEES,array('is_active'=>'0'),'id',$avalue->id);
		}
		return $res;
	}

