  		//$array = array('id'=>$cand->id,'name'=>$emp_data[$cand->emp_id]['display_name'],'sub_name'=>'','field'=>$job[$cand->job_title],'field2'=>'','field3'=>'','link'=>'','link_id'=>$cand->id);

