            function togetjobdetails($get){
            	global $callConfig;
            	$query = "SELECT * FROM job_categories WHERE is_active=0";
            	$data = $callConfig->getAllRows($query);
            	foreach ($data as $value) {	
            		$main[$value->id] = (array)$value;
            	}
            	$query3 = "SELECT * FROM `job_titles` WHERE is_active=0" ;
            	$data3 = $callConfig->getAllRows($query3);		
            	foreach ($data3 as  $value3) {
            		$vv=array('id'=>$value3->id,'name'=>$value3->job_title);
            		$main[$value3->job_category_id]['data'][]= $vv;
            	}
            	$year = $get['year']!="" ? $get['year'] : date('Y');
            	$no_array =array('01','02','03','04','05','06','07','08','09','10','11','12');
            	foreach ($no_array as $mont) {
            		$datt = $year."-".$mont;
            		$query = "SELECT * FROM manpower_requisitions WHERE is_active=0 AND transaction_month_date='".$datt."'";
            		$data3 = $callConfig->getAllRows($query);		
            		$da[$mont]= array();
            		$len = array();
            		foreach($data3 as $dd){
            			$len[$dd->job_title_id] = $dd;
            		}
            		$da[$mont] = $len;
            	} 
            	$vquery = "SELECT id,first_name FROM vendors WHERE is_active=0";
            	$vendors = $callConfig->getAllRows($vquery);
            	$vquery = "SELECT id,location_name FROM locations WHERE is_active=0";
            	$locations = $callConfig->getAllRows($vquery);
            	$vquery = "SELECT id,department_name FROM departments WHERE is_active=0";
            	$departments = $callConfig->getAllRows($vquery);
            	$vquery = "SELECT id,job_title FROM job_titles WHERE is_active=0";
            	$job_titles = $callConfig->getAllRows($vquery);

            	$return['main'] = $main;
            	$return['job_data'] = $da;
            	$return['vendors'] = $vendors;
            	$return['locations'] = $locations;
            	$return['departments'] = $departments;
            	$return['job_titles'] = $job_titles;
            	return $return;

            }
