            	function updateprojecttimesheets($post,$get){
            		global $callConfig;
            		$query="SELECT *  FROM ".TBL_PROJECT_TIMESHEETS." WHERE id=".$post['hid']; 
            		$result = $callConfig->getRow($query);
            		$selected_date = $result->timesheet_date;
            		$emp_id = $result->emp_id;
            		$prevsun = date("Y-m-d", strtotime('sunday this week', strtotime($selected_date)));
    			// create the dates from Selectday to Sunday
            		$datediff = strtotime($prevsun) - strtotime($selected_date);
            		$counrdays = round($datediff / (60 * 60 * 24))+1;
            		for($i=0; $i<$counrdays; $i++){
            			$d = date("Y-m-d", strtotime( $selected_date." + $i day") );
            			$dates[]=$d;
            		}
            		$updatequery = "UPDATE project_timesheets SET current_status=".$post['status']." WHERE timesheet_date IN('".implode("', '",(array)$dates)."') AND company_id =".$post['company_id']." AND emp_id =".$emp_id; 
            		$details = $callConfig->executeQuery($updatequery);
            		return $details;

            	}
