    function getvmsbudgetutilization($get){
    	global $callConfig;
    	$groupbycondition = "";

    	$fieldname = "id,display_name,department_id,location_id,job_title_id";
    	$whr3 = "company_id = ".$get['company_id']." AND is_active = 0";    
    	$query3=$callConfig->selectQuery(TBL_EMPLOYEES,$fieldname,$whr3,'','','');
    	$empdata = $callConfig->getAllRows($query3);
    	foreach ($empdata as $emp) {
    		$employeedata[$emp->id] = $emp;
    	}

    	$financialchartmonths = array('1'=>'Apr','2'=>'May','3'=>'Jun','4'=>'Jul','5'=>'Aug','6'=>'Sep','7'=>'Oct','8'=>'Nov','9'=>'Dec','10'=>'Jan','11'=>'Feb','12'=>'Mar');
    	$financialactualmonths = array('04'=>'Apr','05'=>'May','06'=>'Jun','07'=>'Jul','08'=>'Aug','09'=>'Sep','10'=>'Oct','11'=>'Nov','12'=>'Dec','01'=>'Jan','02'=>'Feb','03'=>'Mar');

    	if($get['filterid']!="") {
    		$query="SELECT *  FROM `filter_tables` WHERE id=".$get['filterid'];
    		$filt = $callConfig->getRow($query);
    		$filtercontent = $filt->content;
    		$filtercontent = json_decode(substr($filtercontent, 1, -1),1);
    		$groupby = array_keys($filtercontent);
    		foreach($groupby as $filter){
    			if($filter=='location_id'){
    				$selected_locations = array_keys($filtercontent['location_id']);
    			}
    			if($filter=='department_id'){
    				$selected_departments= array_keys($filtercontent['department_id']);
    			}
    			if($filter=='job_title_id'){
    				$selected_job_titles = array_keys($filtercontent['job_title_id']);
    			}
    		}
    	}
    	if($get['fromdate']=="" && $get['todate']==""){
    		$query="SELECT *  FROM `config` WHERE company_id='".$get['company_id']."' and is_active=0 ";
    		$finstart = $callConfig->getRow($query);
    		$financial_startdate = $finstart->financial_start;
    		$financial_year = date('Y', strtotime($financial_startdate));
    		$financial_month = date('n', strtotime($financial_startdate));
    		$prev_mon = $financial_month-1;
    		$next_yr = $financial_year+1;
    		$get['fromdate']= $financial_year."-".$financial_month."-01";
    		$get['todate'] = $next_yr."-".$prev_mon."-01";
    	}

    	if($get['fromdate']!="" && $get['todate']!=""){
    		$financial_year_from = date('Y', strtotime($get['fromdate']));
    		$financial_year_frommonth = date('m', strtotime($get['fromdate']));
    		$effective_from_date = $financial_year_from."-".$financial_year_frommonth."-01";
    		$financial_year_to = date('Y', strtotime($get['todate']));
    		$financial_year_tomonth = date('m', strtotime($get['todate']));
    		$effective_to_date = $financial_year_to."-".$financial_year_tomonth."-01";
    		$overall_estimated_budget = 0;
    		$overall_utilized_budget = 0;
    		if($financial_year_frommonth <= $financial_year_tomonth) {
    			for($start=$financial_year_frommonth; $start<=$financial_year_tomonth; $start++){
    				$selected_months[] = $start;
    			}
    		}else{
    			for($start=$financial_year_tomonth; $start<=$financial_year_frommonth; $start++){
    				$selected_months[] = $start;
    			}
    		}

    		foreach($financialactualmonths as $keys=>$months){
    			if(in_array($keys,(array)$selected_months)){
    				$query=" SELECT
    				vendor_id,
    				vendor_name,
    				employee_id,
    				employee_name,
    				SUM(billable_hrs)billable_hrs,
    				SUM(nonbillable_hrs) nonbillable_hrs,
    				leave_days_from + leave_days_to,
    				current_status,
    				sum(item_price) budgeted_amount,
    				SUM(billable_hrs * (item_price/(20*8))) as billable_amount,
    				SUM(nonbillable_hrs * (item_price/(20*8))) as nonbillable_amount
    				from (
    				SELECT
    				emp.vendor_id as vendor_id,
    				vend.display_name as vendor_name,
    				emp.id employee_id,
    				emp.display_name employee_name,
    				(
    				SELECT SUM(billable_hrs)
    				FROM project_timesheets pt
    				WHERE pt.company_id = emp.company_id
    				AND pt.emp_id = emp.id
    				AND MONTH(pt.timesheet_date) = '".$keys."'
    				AND YEAR(pt.timesheet_date) = YEAR(CURRENT_DATE())
    				)billable_hrs,
    				(
    				SELECT SUM(nonbillable_hrs)
    				FROM project_timesheets pt
    				WHERE pt.company_id = emp.company_id
    				AND pt.emp_id = emp.id
    				AND MONTH(pt.timesheet_date) = '".$keys."'
    				AND YEAR(pt.timesheet_date) = YEAR(CURRENT_DATE())
    				)nonbillable_hrs,
    				vrcitems.item_price,
    				(
    				SELECT DATEDIFF (least(el.leave_to,last_day(el.leave_from)),el.leave_from)
    				FROM employee_leaves el
    				WHERE el.company_id = emp.company_id
    				AND el.employee_id = emp.id
    				AND MONTH(el.leave_from) = '".$keys."'
    				AND YEAR(el.leave_from) = YEAR(CURRENT_DATE())
    				) leave_days_from,
    				(
    				SELECT DATEDIFF (el2.leave_to, greatest(el2.leave_from,DATE_SUB(LAST_DAY(el2.leave_to),INTERVAL DAY(LAST_DAY(el2.leave_to))-
    				1 DAY)))
    				FROM employee_leaves el2
    				WHERE el2.company_id = emp.company_id
    				AND el2.employee_id = emp.id
    				AND MONTH(el2.leave_to) = '".$keys."'
    				AND YEAR(el2.leave_to) = YEAR(CURRENT_DATE())
    				) leave_days_to,
    				(
    				SELECT sts.name
    				FROM status sts
    				WHERE sts.name_value = emp.current_status
    				AND sts.company_id = emp.company_id
    				) current_status
    				FROM employees emp, vendors vend, vendor_rate_cards vrc, vrc_items vrcitems, emp_work_order ewo
    				WHERE emp.company_id = ".$get['company_id']."
    				AND emp.is_active = '0'
    				AND vend.company_id = emp.company_id
    				AND vend.id = emp.vendor_id
    				AND vrc.company_id = emp.company_id
    				AND vrcitems.company_id = vrc.company_id
    				AND vrcitems.transaction_id = vrc.id
    				AND vrc.party_id = emp.vendor_id
    				AND ewo.company_id = emp.company_id
    				AND ewo.emp_id = emp.id
    				AND vrcitems.transaction_id = ewo.work_order_id
    				AND ((vrc.effective_from_date between '".$effective_from_date."' AND '".$effective_to_date."') OR (vrc.effective_to_date between '".$effective_from_date."' AND '".$effective_to_date."'))
    				AND vrcitems.id = ewo.work_order_detail_id
    				)abc
    				GROUP by
    				vendor_id,
    				vendor_name,
    				employee_id,
    				employee_name,
    				current_status
    				";
    				$result = $callConfig->getAllRows($query);
    				$total_budget = 0 ;
    				$total_utilized = 0;
    				foreach($result as $data){
    					$empid = $data->employee_id;
    					if(in_array($employeedata[$empid]->location_id,(array)$selected_locations) || in_array($employeedata[$empid]->department_id,(array)$selected_departments) || in_array($employeedata[$empid]->job_title_id,(array)$selected_job_titles)) {
    						$budget_data_report[$empid]['department_id']  = $employeedata[$empid]->department_id;
    						$budget_data_report[$empid]['location_id'] = $employeedata[$empid]->location_id;
    						$budget_data_report[$empid]['job_title_id'] = $employeedata[$empid]->job_title_id;
    						$total_budget = $total_budget + $data->budgeted_amount;
    						$total_utilized = $total_utilized + $data->billable_amount;
    						$budget_data_report[$empid]['estimated'] = $budget_data_report[$empid]['estimated'] + $data->budgeted_amount;
    						$budget_data_report[$empid]['utilized'] = $budget_data_report[$empid]['utilized'] + $data->billable_amount;
    						$budget_data_report[$empid]['display_name'] = $employeedata[$empid]->display_name;
    					} else {
    						$budget_data_report[$empid]['department_id']  = $employeedata[$empid]->department_id;
    						$budget_data_report[$empid]['location_id'] = $employeedata[$empid]->location_id;
    						$budget_data_report[$empid]['job_title_id'] = $employeedata[$empid]->job_title_id;
    						$total_budget = $total_budget + $data->budgeted_amount;
    						$total_utilized = $total_utilized + $data->billable_amount;
    						$budget_data_report[$empid]['estimated'] = $budget_data_report[$empid]['estimated'] + $data->budgeted_amount;
    						$budget_data_report[$empid]['utilized'] = $budget_data_report[$empid]['utilized'] + $data->billable_amount;
    						$budget_data_report[$empid]['display_name'] = $employeedata[$empid]->display_name;
    					}


    				}
    				$overall_estimated_budget +=$total_budget;
    				$overall_utilized_budget +=$total_utilized;
    				$actual_budget[$months] = $total_budget;
    				$used_budget[$months] = $total_utilized;
    			} else {
    				$actual_budget[$months] = 0;
    				$used_budget[$months] = 0;
    			}
    		} 
    	}
    	$details['budgettable'] = $budget_data_report;
    	$details['estimation'] = $actual_budget;
    	$details['actual'] = $used_budget;
    	$details['totalbudget'] = $overall_estimated_budget;
    	$details['totalutilized'] = $overall_utilized_budget;
    	return $details;
    }
    function getbudgetlist($get){
    	global $callConfig;
    	$query="SELECT financial_start  FROM `config` WHERE company_id='".$get['company_id']."' and is_active='0'";
    	$config = $callConfig->getRow($query);
    	$details['financial_start'] = date('d M, Y', strtotime($config->financial_start));

    	$query="SELECT id,department_name  FROM `departments` WHERE company_id='".$get['company_id']."' and is_active='0'";
    	$depts = $callConfig->getAllRows($query);
    	foreach($depts as $deptvalues){
    		$departments[$deptvalues->id] = $deptvalues->department_name;
    	}

    	$query="SELECT id,location_name  FROM `locations` WHERE company_id='".$get['company_id']."' and is_active='0'";
    	$locs = $callConfig->getAllRows($query);
    	foreach($locs as $locvalues){
    		$locations[$locvalues->id] = $locvalues->location_name;
    	}

    	$query="SELECT id,job_title  FROM `job_titles` WHERE company_id='".$get['company_id']."' and is_active='0'";
    	$jobtitles = $callConfig->getAllRows($query);
    	foreach($jobtitles as $jobvalues){
    		$job_titles[$jobvalues->id] = $jobvalues->job_title;
    	}
    	$details['departments'] =$departments;
    	$details['locations'] =$locations;
    	$details['job_titles'] =$job_titles;

    	return $details;

    }
