	function togetepfsummary($get){
		global $callConfig;
		$company_id = $get['company_id'];
		$pay_year_from = $get['pay_year_from'];
		$pay_month_from = $get['pay_month_from'];
		$pay_year_to = $get['pay_year_to'];
		$pay_month_to = $get['pay_month_to'];
		$to_date = $get['to_date'];
		$from_date = $get['from_date'];
		$basic_component_id = $get['basic_component_id'];
		$voluntary_component_id = $get['voluntary_component_id'];
		$pass_data['company_id'] = $company_id;
		$pass_data['pay_month_to'] = $pay_month_to;
		$pass_data['pay_year_to'] = $pay_year_to;
		$pass_data['pay_year_from'] = $pay_year_from;
		$pass_data['pay_month_from'] = $pay_month_from;
		$provident_funds = $this->togetpercentofempprovidentfunds($pass_data);
		//echo "<pre>"; print_r($provident_funds);
		foreach ($provident_funds as $pf_data) {
			$emp_pf_percent = $pf_data->emp_contribution;
			$employer_pf_percent = $pf_data->employer_contribution;
			$employer_eps_percent = $pf_data->eps_rate_employer;
			$employer_edli_percent = $pf_data->edli_rate;
			$employer_pf_admin_rate = $pf_data->pf_admin_rate;
		}
		$employee_list_query = "select id,emp_code,display_name,pf_no from employees where company_id='".$company_id."' and is_active='0'";
		$employee_list = $callConfig->getAllRows($employee_list_query);
		foreach ($employee_list as $emp_data) {
			$emp_code = $emp_data->emp_code; 
			$employee_id = $emp_data->id; 
			$emp_display_name = $emp_data->display_name; 
			$emp_pf_no = $emp_data->pf_no; 
			$pass_data['employee_id'] = $employee_id;
			$basic_list = $this->togetsumofempsalaryoncomponentidbtwdates($pass_data,$basic_component_id);
			foreach ($basic_list as $basic_data) {
				$emp_basic = $basic_data->totalactual;  
			}
			//echo "<pre>"; print_r($emp_basic); exit;
			$voluntary_list = $this->togetsumofempsalaryoncomponentidbtwdates($pass_data,$voluntary_component_id);
			foreach ($voluntary_list as $voluntary_data) {
				$emp_vpf = $voluntary_data->totalactual; 
			}
			$emp_pf_amount = $emp_basic * $emp_pf_percent / 100;
			$employer_pf_amount = $emp_basic * $employer_pf_percent / 100;
			$emp_eps_rate = $emp_basic * $employer_eps_percent / 100;
			$employer_edli_amount = $emp_basic * $employer_edli_percent / 100;
			$employer_pf_admin_amount = $emp_basic * $employer_pf_admin_rate / 100;
			$total_pf_contribution = $emp_pf_amount + $employer_pf_amount +$emp_vpf+ $emp_eps_rate + $employer_edli_amount + $employer_pf_admin_amount;
			$emp_pf_list[] = array('emp_code'=>$emp_code,'emp_display_name'=>$emp_display_name,'emp_pf_number'=>$emp_pf_no,'emp_pf_wages'=>$emp_basic,'emp_pf_amount'=>$emp_pf_amount,'employer_pf_amount'=>$employer_pf_amount,'emp_voluntary_pf'=>$emp_vpf,'emp_eps_rate'=>$emp_eps_rate,'employer_edli_amount'=>$employer_edli_amount,'employer_pf_admin_amount'=>$employer_pf_admin_amount,'total_pf_contribution'=>$total_pf_contribution);
		}
		return $emp_pf_list;
	}
	function togetpayslipctcreports($get){
		global $callConfig;
		$company_id = $get['company_id'];
		$pay_year_from = $get['pay_year_from'];
		$pay_month_from = $get['pay_month_from'];
		$pay_year_to = $get['pay_year_to'];
		$pay_month_to = $get['pay_month_to'];
		$to_date = $get['to_date'];
		$from_date = $get['from_date'];
		$salary_category_query = "select * from salary_template where is_active='0'";
		//echo $salary_category_query;
		$salary_category = $callConfig->getAllRows($salary_category_query);
		$array['salary_category'] = $salary_category;
		$salary_components_query = "select * from salary_template_components where is_active='0'";
		//echo $salary_components_query;
		$salary_components = $callConfig->getAllRows($salary_components_query);
		$array['salary_components'] = $salary_components;
//print_r($array);
		$employee_list_query = "select id,emp_code,display_name from employees where company_id='".$company_id."' and is_active='0'";
		$employee_list = $callConfig->getAllRows($employee_list_query);
		foreach ($employee_list as $emp_data) {
			$employee_id = $emp_data->id; 
			$employee_code = $emp_data->emp_code; 
			$employee_name = $emp_data->display_name;
			$payslip_component_data = array("employee_id"=>$employee_code,"employee_name"=>$employee_name);
			foreach ($salary_components as $components) {
				$component_id = $components->component_id; 
				$payrunsummary_list_query = "select component_id,sum(salary_component_actual) as total from ".TBL_PAY_RUN_SUMMARY_COMPONENTS." where employee_id='".$employee_id."' and company_id='".$company_id."' and is_active='0' and pay_month>='".$pay_month_from."' and pay_month<='".$pay_month_to."' and component_id='".$component_id."'  and pay_year>='".$pay_year_from."' and pay_year<='".$pay_year_to."' group by component_id";
				$payslip_list = $callConfig->getAllRows($payrunsummary_list_query);
				if(empty($payslip_list)) {

					$payslip_component_data[$component_id] = 0;
				} else {
					foreach ($payslip_list as $pdata) {
						$component_id = $pdata->component_id;
						$total = $pdata->total;
						$payslip_component_data[$component_id] = $total;
					}
				}
			}
			$payslip_data[] = $payslip_component_data;
			$array['payslip_data'] = $payslip_data;
		}
		$payslip_data_return =  $array;
		return $payslip_data_return;
	}
