				if($response_row==""){
					unset($response_details['performance_response_details'][$i]['updated_by']);
					unset($response_details['performance_response_details'][$i]['updated_date']);
					$qresponse=$callConfig->insertRecord(TBL_PERFORMANCE_RESPONSE_DETAILS,$response_details['performance_response_details'][$i]);
				}else {
					unset($response_details['performance_response_details'][$i]['created_by']);
					unset($response_details['performance_response_details'][$i]['created_date']);
					unset($response_details['performance_response_details'][$i]['current_status']);
					$res=$callConfig->updateRecord(TBL_PERFORMANCE_RESPONSE_DETAILS,$response_details['performance_response_details'][$i],'id',$response_row);
				}
			}
		}


