		function getperformanceassessment($get){
			global $callConfig;
			$month = $get['month'];
			$year = $get['year'];
			$assessment_date = $year."-".$month."-01";
	 	$query="SELECT id from performance_setup where assessment_start_date>='".$assessment_date."'"; // and assessment_end_date<='".$assessment_date."'";
	 	$assess = $callConfig->getRow($query);
	 	$assessment_id = $assess->id;
	 	$details['assessment_id']= $assessment_id;

	 	$filterdata = urldecode($get['filterby']);
	 	$filters = json_decode($filterdata,1);
	 	if($filters!=''){
	 		$appendcondtion = " and ";
	 		foreach ($filters as $filterkey => $filtervalue) {
	 			$appendcondtion .= "emp.".$filterkey ." IN ( ";
	 			$appendcondtion .=  implode(',', array_keys((array)$filtervalue));
	 			$appendcondtion .=  " ) and ";
	 		}
	 		$appendcondtion = substr($appendcondtion, 0, -4);
	 	}

	 	$query="SELECT pr.* from performance_responses pr,employees emp where pr.assessment_id=".$assessment_id." and pr.employee_id=emp.id".$appendcondtion;
	 	$assess_resp = $callConfig->getAllRows($query);
	 	foreach($assess_resp as $resp){
	 		$rating[$resp->employee_id] = $resp;
	 	}
	 	$details['rating']= $rating;
	 	return $details;
	 }

