	 function togetVendorAgreementexpirelist($get){
	 	global $callConfig;
	 	$query= "SELECT ven.`company_id`, ven.`id`, ven.image, ven.display_name, venag.`agreement_name`, venag.`agreement_ref_no`, venag.`signed_date`, venag.`expiry_date`, venag.`file_url`, DATEDIFF(venag.`expiry_date`, NOW()) as diff_days FROM vendors ven, vendor_agreements venag WHERE ven.id = venag.vendor_id AND ven.company_id = venag.company_id AND ven.company_id = 1 AND ven.is_active = '0' AND venag.`expiry_date` < (NOW() + INTERVAL 120 day)";
	 	$exdata = $callConfig->getAllRows($query);
	 	foreach($exdata as $ex){
	 		if($ex->diff_days>0 && $ex->diff_days<8){
	 			$return['week'][] = $ex;
	 		}
	 		if( $ex->diff_days>0 && $ex->diff_days<31){
	 			$return['month'][] = $ex;
	 		}
	 		if($ex->diff_days>0 && $ex->diff_days<120){
	 			$return['qtr'][] = $ex;
	 		}
	 	}
	 	return $return;
	 }
	 function getemprequests($get) {
	 	global $callConfig;
	 	$sql = "select * from food_options where company_id='".$get['company_id']."' and is_active='0'";
	 	$foodoptions = $callConfig->getAllRows($sql);
	 	$sql = "select * from locations where company_id='".$get['company_id']."' and is_active='0'";
	 	$location = $callConfig->getAllRows($sql);

	 	$datecondition = "AND (efo.stop_date is null or (current_date() between efo.start_date and efo.stop_date))";
	 	if($get['fromdate']!='' || $get['todate']){
	 		$datecondition =  "AND (efo.stop_date<='".$get['todate']."') and efo.start_date >='".$get['fromdate']."'";
	 	}
	 	$queryresponse = "SELECT efo.location_id as location_id,
	 	efo.emp_id,
	 	emp.display_name,
	 	efo.food_options option_value,
	 	fo.food_option option_name
	 	FROM     employees emp, employee_food_requests efo, food_options fo
	 	WHERE     emp.id = efo.emp_id
	 	AND        emp.company_id = efo.company_id
	 	AND        emp.is_active = 0
	 	AND        efo.is_active = 0
	 	AND        fo.company_id = emp.company_id
	 	AND        fo.id = efo.food_options
	 	AND        fo.is_active = 0
	 	".$datecondition." order by 1, 2"; 
	 	$allresponse = $callConfig->getAllRows($queryresponse);

	 	foreach($allresponse as $data){
	 		foreach($foodoptions as $foodtype){
	 			$foodoptiondata[$foodtype->id] = $foodtype->food_option;
	 			if($foodtype->id==$data->option_value){
	 				$food_option_array[$foodtype->id][] = $data;
	 				foreach($location as $loc){
	 					if($loc->id==$data->location_id){
	 						$loc_food_option[$foodtype->id][$loc->id][$data->emp_id] = $data;
	 					}
	 				}
	 			}
	 		}

	 	}
	 	$details['summary']=$food_option_array;
	 	$details['foodoptiondata']=$foodoptiondata;
	 	$details['locfooddata']=$loc_food_option;

	 	$transport_datecondition = "AND (current_date() <= efo.created_date)";
	 	if($get['fromdate']!='' || $get['todate']){
	 		$transport_datecondition = "AND (efo.created_date between '".$get['fromdate']."' and '".$get['todate']."')";
	 	}

	 	$queryresponse = "SELECT efo.location_id as location_id,
	 	efo.employee_id,emp.display_name FROM employees emp, employee_transport_requests efo
	 	WHERE     emp.id = efo.employee_id
	 	AND        emp.company_id = efo.company_id
	 	AND        emp.is_active = 0
	 	AND        efo.is_active = 0
	 	".$transport_datecondition." order by 1, 2"; 
	 	$allresponse = $callConfig->getAllRows($queryresponse);
	 	foreach($allresponse as $data){
	 		$total_transport_req[] = $data;
	 		foreach($location as $loc){
	 			if($loc->id==$data->location_id){
	 				$transport_option[$loc->id][$data->employee_id] = $data;
	 			}
	 		}
	 	}

	 	$details['transport']=$transport_option;
	 	$details['transport_req']=count((array)$total_transport_req)==''?'0':count((array)$total_transport_req);
		//echo "<pre>"; print($details['transport_req']);
	 	return $details;
	 }


	 function getempreport($get)
	 {
	 	global $callConfig;
	 	$filterdata = urldecode($get['filterby']);
	 	$filters = json_decode($filterdata,1);
	 	if($filters!=''){
	 		$appendcondtion = " and ";
	 		foreach ($filters as $filterkey => $filtervalue) {
	 			$appendcondtion .= $filterkey ." IN ( ";
	 			$appendcondtion .=  implode(',', array_keys((array)$filtervalue));
	 			$appendcondtion .=  " ) and ";
	 		}
	 		$appendcondtion = substr($appendcondtion, 0, -4);
	 	}

	 	if($get['empidlist']!=''){
	 		$empids = urldecode($get['empidlist']);
	 		$empids = json_decode($get['empidlist'],1);
	 		$emplistfilter = implode(',',(array)$empids);
	 		$appendcondtion .= ' and id in ('.$emplistfilter.')';
	 	}

	 	$query="SELECT * from employees where company_id=".$get['company_id']." and is_active='0'".$appendcondtion;
	 	$empdata = $callConfig->getAllRows($query);
	 	foreach($empdata as $emp){
	 		$empdetails[$emp->id] = $emp;
	 	}
	 	$details['emp_data']= $empdetails;
	 	return $details;

	 }
	
 
	// Priya lastest
function getjobpostingsreport($get) {
	global $callConfig;
	$jobstypes = array('0'=>'Open','2'=>'In-Progress','1'=>'Close','3'=>'Total');
	$sql = "select * from vendors where company_id='".$get['company_id']."' and is_active='0'";
	$vendors = $callConfig->getAllRows($sql);

	$datecondition = "AND (current_date() >= jp.requested_date)";
	if($get['fromdate']!='' || $get['todate']){
		$datecondition = "AND jp.requested_date between '".$get['fromdate']."' and '".$get['todate']."'";
	}
	$queryresponse = "SELECT jpd.vendor_id, jp.current_status, jp.job_status, COUNT(jp.id) as totalcount FROM job_posting_distribute jpd, job_postings jp, job_posting_candidates jpc WHERE jp.id = jpd.job_posting_id AND jp.company_id = jpd.company_id AND jp.is_active = '0' AND jpd.is_active = '0' ".$datecondition." AND jpc.job_posting_id = jp.id AND jpc.company_id = jp.company_id AND jpc.is_active = '0' GROUP BY jpd.vendor_id, jp.current_status,jp.job_status"; 
	$allresponse = $callConfig->getAllRows($queryresponse);
	$total =0;
	foreach($jobstypes as $jobkey=>$jobtype) {
		$job_type_total =0;
		foreach($allresponse as $data){
			if($data->job_status==$jobkey){
				$job_type_total += $data->totalcount;
				$total += $data->totalcount;
			}
		}
		$job_type_array[$jobkey] = $job_type_total;
	}
	$job_type_array[3] = $total;			
	foreach($allresponse as $data){
		foreach($jobstypes as $jobkey=>$jobtype){
			foreach($vendors as $ven){
				if($ven->id==$data->vendor_id && $jobkey==$data->job_status){
					$vendor_jobs[$ven->id][$jobkey] = $data->totalcount;
				}
			}

		}
	}
	foreach($vendor_jobs as $vid=>$vjobs){
		$totalj=0;
		foreach($vjobs as $jobcount){
			$totalj +=$jobcount;
		}
		$vendor_jobs[$vid][3] = $totalj;
	}
	$details['summary']=$job_type_array;
	$details['job_type_data']=$jobstypes;
	$details['vendor_jobs']=$vendor_jobs;
		//echo "<pre>"; print_r($details);exit;
	return $details;
}

