		$return['application_roles'] = $application_rolesres;

		$application_userssql = "SELECT id, display_name, user_email, user_mobile, user_photo, role_id FROM `application_users` WHERE company_id = '".$get['company_id']."' AND is_active = 0 AND user_type IN(1,2) ORDER BY id DESC";
		$application_usersres=$callConfig->getAllRows($application_userssql);
