				$noteroleapplication_users[$uvalue->id] = $uvalue;	
			}	
		}
		$return['application_users'] = $application_users;
		$return['not_role_application_users'] = $noteroleapplication_users;

		$aplproccessql = "SELECT ap.id, ap.process_name, apr.application_role_id FROM application_process_role apr, application_process ap WHERE apr.company_id = '".$get['company_id']."' AND apr.company_id = ap.company_id AND apr.application_process_id = ap.id AND application_role_id = '".$get['roleid']."' AND apr.is_active = ap.is_active AND apr.is_active = 0";
		$aplproccesres=$callConfig->getAllRows($aplproccessql);
		$return['application_process']  = $aplproccesres;	
		$appsql = "SELECT app.id as application_process_pages_id, app.application_process_id, app.application_page_name, app.name, rp.role_id, rp.role_short_code, rp.id as rp_id, rp.permission_view, rp.permission_insert, rp.permission_update, rp.permission_delete, rp.permission_print, rp.permission_import, rp.permission_export, rp.permission_download  FROM application_process_pages app, role_permissions rp WHERE app.company_id = '".$get['company_id']."' AND app.company_id = rp.company_id AND app.id = rp.application_process_page_id AND rp.role_id = '".$get['roleid']."' AND app.is_active = rp.is_active AND app.is_active = 0 ".$condition;
		$appres=$callConfig->getAllRows($appsql);
		$return['application_process_pages']  = $appres;

		return $return;
	}

	function getRiviewsData($data){
		global $callConfig;
		$pendingapprove =array();
		$approve =array();
		$returnarray =array();
		$sendarray = $data; // AND tal.response_type='".$data['response_type']."'
		$sql = "SELECT tal.id,tal.transaction_table,tal.transaction_id,tal.request_date,tal.response_type,tal.response_date,tal.workflow_id  FROM transaction_approval_logs tal WHERE tal.company_id = '".$data['company_id']."'  AND tal.user_id = '".$data['user_id']."'";
		$reviewdata=$callConfig->getAllRows($sql);
		$statuse = array();
		$workflowid = array();
		$logtableandid = array();
		$logtabledetails = array();
		$statusres = array();
		foreach($reviewdata as $reviewda){  // only store table name and id 
			$logtableandid[$reviewda->transaction_table][] = $reviewda->transaction_id;
		}
		
		foreach($logtableandid as $tablename =>  $logtableandidres){  // only store table name and id 
			$idlist = implode(",",(array)$logtableandidres);
			
			$sqldyntable = "SELECT * FROM ".$tablename." WHERE company_id = '".$data['company_id']."' AND id IN(".$idlist.") AND is_active = '0'";
			$dyntableres=$callConfig->getAllRows($sqldyntable);
			foreach($dyntableres as $dyntablere){
				$logtabledetails[$tablename][$dyntablere->id] = $dyntablere;
			}
			
			$statussql = "SELECT id,name,status,action_label FROM status_progress WHERE company_id = '".$data['company_id']."' AND table_name = '".$tablename."'  AND is_active = '0' ORDER BY `id` ASC";
			$statusress = $callConfig->getAllRows($statussql);
			if(!isset($statusress[0]->id)){
				$statusres[$tablename][] = array('status'=>'0');
			}else{
				$statusres[$tablename] = $statusress;
			}
			$query = "SELECT id,display_field,value_field,attribute_type,content,company_id,field_name FROM display_attribute_types WHERE company_id = '".$data['company_id']."' AND application_table_name = '".$tablename."' ";
			$datares = $callConfig->getAllRows($query);

			foreach($datares as $datadd){
				$attributes = array();
				$display = $datadd->display_field;
				$value = $datadd->value_field;
			//$attributes['type'] = $data->attribute_type;
				if($datadd->attribute_type == 'custom_sql'){
					$qquery = urldecode($datadd->content);
					if(strpos($qquery,'WHERE')){
						$cwhr = "AND company_id=".$datadd->company_id." ORDER BY";
					}else{
						$cwhr = "WHERE company_id=".$datadd->company_id." ORDER BY";
					}
					$qquery = str_replace('ORDER BY', $cwhr, $qquery);
					$custom_sql = $callConfig->getAllRows($qquery);
					foreach ($custom_sql as $custom){
						$array1[$custom->$value] = $custom->$display;
					}
					$attributes = $array1;
				}else{
					$attributes = json_decode($datadd->content,1);
				}
				$arrayattributes[$tablename][$datadd->field_name] = $attributes;
			}		
		}
		$return["attributes"] = $arrayattributes;
		foreach($reviewdata as $reviewda){
			
			$tabledetails = array();
			$workflowid[$reviewda->workflow_id] = $reviewda->workflow_id;
			$tabledetails = $logtabledetails[$reviewda->transaction_table][$reviewda->transaction_id]; 
			$return["table_details"][$reviewda->transaction_table][$reviewda->transaction_id] = $tabledetails;
			if(count((array)$statusename[$reviewda->transaction_table]) == '0'){			
				$getstatuslistname =  $statusres[$reviewda->transaction_table];
				foreach($getstatuslistname as $getstatuse){
					$statusename[$reviewda->transaction_table][$getstatuse->status] = $getstatuse->name;
					$statusaction_label[$reviewda->transaction_table][$getstatuse->status] = $getstatuse->name;
				}
			}

			if($reviewda->response_type == "0"){

				$pendingapprove = array();
				$sendarray['transaction_id'] =$reviewda->transaction_id;
				$sendarray['table'] = $reviewda->transaction_table;
				$sendarray['currnet_status'] =$tabledetails->current_status;
				$pendingapprove['created_by'] =$tabledetails->created_by;
				$pendingapprove['workflow_id'] =$reviewda->workflow_id;
				$pendingapprove['request_date'] =$reviewda->request_date;	
				$pendingapprove['table'] = $reviewda->transaction_table;
				$pendingapprove['transaction_id'] = $reviewda->transaction_id;
				$pendingapprove['status'] = $this->getUserStatusStep($sendarray); //get next steps stauts
				$pendingapprove['status']['approve']['action_label'] = $statusename[$reviewda->transaction_table][$pendingapprove['status']['approve']['status']]; //get next steps stauts
				$pendingapprove['status']['reject']['action_label'] = $statusaction_label[$reviewda->transaction_table][$pendingapprove['status']['reject']['status']];
				$return["pending"][]= $pendingapprove;

			}else{
				$approve['table'] = $reviewda->transaction_table;
				$approve['transaction_id'] = $reviewda->transaction_id;
				$approve['created_by'] =$tabledetails->created_by;
				$approve['workflow_id'] =$reviewda->workflow_id;
				$approve['currnet_status'] =$tabledetails->current_status;
				$approve['request_date'] =$reviewda->request_date;
				$approve['status'] = $tabledetails->current_status;
				$approve['status_name'] = $statusename[$reviewda->transaction_table][$tabledetails->current_status];
				$return["approve"][]= $approve;
			}
		}
		$implodeworkflowid = implode(",",(array)$workflowid);
		$workfsql = "SELECT wf.id,wf.approve_field FROM workflow_configuration wf WHERE wf.company_id = '".$data['company_id']."' AND wf.is_active = '0' AND wf.id IN(".$implodeworkflowid.")";
		$workfres=$callConfig->getAllRows($workfsql);
		foreach($workfres as $workfres){
			$return["workflow_details"][$workfres->id]= $workfres;
		}
 //echo "<pre>"; print_r($return); 
		//echo "<pre>"; print_r($return); 

		$query = "SELECT em.id as id , em.display_name as name, em.user_id, em.image FROM `employee_terminations` et  JOIN employees em ON em.id = et.emp_id AND em.is_active = 0  WHERE em.id NOT IN(select emp_id from user_assets ua where company_id=".$data['company_id']." AND is_active =0 ) AND et.company_id=".$data['company_id']." AND et.is_active=0";
		$return['reg_emp_query'] = $query;
		$return['reg_emp_data'] = $callConfig->getAllRows($query);

		$query = "SELECT em.id as id , em.display_name as name, em.user_id, em.image FROM `employee_terminations` et  JOIN employees em ON em.id = et.emp_id AND em.is_active = 0  WHERE em.id  IN(select emp_id from user_assets ua where company_id=".$data['company_id']." AND is_active =0 ) AND et.company_id=".$data['company_id']." AND et.is_active=0";
		$return['reg_emp_com_query'] = $query;
		$return['reg_emp_com_data'] = $callConfig->getAllRows($query);

		$query = "SELECT id , display_name as name, user_id, image FROM `employees`  WHERE id  IN( SELECT  ua.emp_id from user_assets ua WHERE company_id=".$data['company_id']." AND emp_id NOT IN (SELECT emp_id FROM employee_terminations WHERE company_id=".$data['company_id']." AND is_active = 0 ) AND  is_active =0 ) AND company_id=".$data['company_id']." AND is_active=0";
		$return['reg_emp_wo_query'] = $query;
		$return['reg_emp_wo_data'] = $callConfig->getAllRows($query);

		$yesterday = date('Y-m-d', strtotime('-1 day'));

	    $sql = "
	        SELECT eda.id,eda.company_id,eda.employee_id,CONCAT(emp.emp_code, ' - ', emp.display_name) AS employee_name, eda.attendace_date,eda.clock_in,eda.clock_out,eda.leave_type_id,eda.attendance_key_short_code
	        FROM employee_daily_attendances AS eda
	        LEFT JOIN employees AS emp ON emp.id = eda.employee_id AND emp.company_id=eda.company_id AND emp.is_active=0
	        WHERE eda.company_id = '".intval($data['company_id'])."'
	          AND eda.attendace_date = '".$yesterday."'
	          AND (eda.clock_in IS NULL OR eda.clock_in = '' OR eda.clock_in = '00:00:00'
	                OR
	                eda.clock_out IS NULL OR eda.clock_out = '' OR eda.clock_out = '00:00:00')
	          AND eda.is_active = 0 AND eda.employee_id !='' ORDER BY eda.employee_id ASC";
	    $return['emp_miss_punch_list'] =  $callConfig->getAllRows($sql);

		return $return;
	}  
	
