	function resetNewPassword($data){
		global $callConfig;

		$old_password = $callConfig->passwordEncrypt($data['old_password']);
		$confirm_password = $callConfig->passwordEncrypt($data['confirm_password']);
		$sql1 = "SELECT id,company_id, display_name, user_email, user_mobile FROM `application_users` where user_password = '".$old_password."' AND id='".$data['Rid']."'";
		$passwordoldverification = $callConfig->getRow($sql1);
		if(isset($passwordoldverification->id)){

			$updatefileds = array('user_password'=>$confirm_password,'updated_by'=>$data['userid']);
			$where = "id = '".$passwordoldverification->id."'";
			$res=$callConfig->updateRecord("application_users",$updatefileds,"","",$where);
			$return = $res;
			$emailarray['to_company_id'] = $passwordoldverification->company_id;
			$emailarray['session_company_id'] = $passwordoldverification->company_id;
			$emailarray['temp_password'] = $data['confirm_password'];
			$emailarray['user_company_id'] = $passwordoldverification->company_id;
			$emailarray['user_display_name'] = $passwordoldverification->display_name;
			$emailarray['user_email_id'] = $passwordoldverification->user_email;
			$emailarray['user_phone_number'] = $passwordoldverification->user_mobile;
			$emailarray['user_id'] = $passwordoldverification->id; 
			$emailarray['created_by'] = $data['user_id'];
			$notarry =array();
			//$return = $emailarray;
			$email  =$this->sendNotificationAndEmails($notarry,$emailarray,27);
			//print_r($email);
			$return = array("status"=>"500","sql"=>$email);
		}else{
			$return = array("status"=>"404","sql"=>$sql1);
		} 
		
		return $return;
	}
	function insertEmailContain($data){
		global $callConfig;
		$modulelist = $data['application_module_list'];
		unset($data['application_module_list']);
		if($data['id'] !=""){
			$where = "id = '".$data['id']."'";
			$data['updated_by'] = $data['user_id'];
			$data['updated_date'] = date('Y-m-d H:i:s');
			unset($data['user_id']);
			unset($data['id']);
			unset($data['application_module']);
			unset($data['module_group_id']);
			$data['application_module'] = $modulelist;
			$res=$callConfig->updateRecord("email_content",$data,"","",$where);
		}else{
			$data['is_active'] = '0';
			$data['current_status']='0';
			$data['created_by'] = $data['user_id'];
			$data['created_date'] = date('Y-m-d H:i:s');
			unset($data['user_id']);
			foreach($modulelist as $module_id){
				$data['application_module'] = 	$module_id;
				$res=$callConfig->insertRecord("email_content",$data);	
			}	
		}
		return $res;
	}
