			$where="id=".$data['Rid'];
			$fieldnames['updated_by'] = $data['user_id'];
			$fieldnames['updated_date'] = date('Y-m-d H:i:s');
			$res=$callConfig->updateRecord("workflow_configurations_new",$fieldnames,"","",$where);
			foreach($data['approval_level_criteria'] as $seq=>$vl){
				$fieldnames=array('company_id'=>$data['company_id'],'workflow_id'=>$data['Rid'],'approval_level_criteria'=>$vl,'doa_amount'=>json_encode($data['doa_amount_convert'][$seq]),'final_approval'=>$data['final_approval_'.$seq],'is_active'=>'0');
				if($data['wfd_id'][$seq] !=""){
