		// $hrconnect_data = "select * from employee_buddies where employee_id='".$employee_id."' and is_active='0' and company_id='".$company_id."'";
		// $hrconnect_details = $callConfig->getRow($hrconnect_data);
		if($checkcriteria['sub_approve_type']=="AB"){
			$buddy_id = $edata->admin_buddy;
		}elseif($checkcriteria['sub_approve_type']=="FB"){
			$buddy_id = $edata->finance_buddy;
		}elseif($checkcriteria['sub_approve_type']=="HB"){
			$buddy_id = $edata->hr_buddy;
		}elseif($checkcriteria['sub_approve_type']=="PB"){
			$buddy_id = $edata->project_buddy;
		}
		if($buddy_id==0 || $buddy_id==""){
			$hrconnect_data = "select * from locations where company_id='".$company_id."' and is_active='0' and id='".$location_id."'";
			$hrconnect_details = $callConfig->getRow($hrconnect_data);
			if($checkcriteria['sub_approve_type']=="AB"){
				$buddy_id = $hrconnect_details->admin_connect;
			}elseif($checkcriteria['sub_approve_type']=="FB"){
				$buddy_id = $hrconnect_details->finance_connect;
			}elseif($checkcriteria['sub_approve_type']=="HB"){
				$buddy_id = $hrconnect_details->hr_connect;
			}elseif($checkcriteria['sub_approve_type']=="PB"){
				$buddy_id = $hrconnect_details->project_connect;
			}
			if($buddy_id==0 || $buddy_id=="") {
				$hrconnect_data = "select * from config where company_id='".$company_id."' and is_active='0'";
				$hrconnect_details = $callConfig->getAllRows($hrconnect_data);
				$buddy_id = $hrconnect_details[0]->default_hr;
			}
		}
		return $buddy_id;
	}


function emailSendWorkflow($data,$workflow,$type){
	global $callConfig;
	$sendstatus = 1;
	if($workflow->after_approval_email !="" AND $type ="approve"){
		$emailcontain_id = $workflow->after_approval_email;
		$emailtype = $workflow->send_aproval_email_to;
		$sendstatus =0;
	}elseif($workflow->after_rejection_email !="" AND $type ="reject"){
		$emailcontain_id = $workflow->after_rejection_email;
		$emailtype = $workflow->send_rejection_email_to;
		$sendstatus =0;
	}
	if($sendstatus =='0'){
		$insert_id = $data['rid'];
		$emailsql = "select * FROM email_content where id = '".$emailcontain_id."'";
		$emailresult = $callConfig->getRow($emailsql);
		$urlpagename = "COM_INSERT_".ucwords($data['table']);
		$datas = array('company_id'=>$data['company_id'],'transaction_number'=>$data['transaction_id'],'transaction_type'=>ucwords(str_replace("_"," ",$data['table'])), 'transaction_date'=>date("d-m-Y"), 'action_label'=>'Submit for Approval', 'option'=>$urlpagename ,'Rid'=>$insert_id,'email_template'=>$emailcontain_id,'email_content_id'=>$emailcontain_id,'status'=>$data['status'],'updated_by'=>$data['user_id']);
		
		$detailsurl = "select * FROM ".$data['table']." where id = ".$insert_id;
		$detailsdata = $callConfig->getRow($detailsurl);
		foreach($detailsdata as $key =>$detailsdata){
			$datas[$data['table'].".".$key] = $detailsdata;
		}
		if($emailtype == 'everyone_approve'){
			$emaillistevryapprove = "select au.user_email as email FROM transaction_approval_logs tal left join application_users au on tal.user_id = au.id where tal.transaction_table ='".$data['table']."' AND  tal.transaction_id = '".$data['rid']."'  order by tal.id asc";
			$emaillistevryapproved = $callConfig->getAllRows($emaillistevryapprove);
			foreach($emaillistevryapproved as $drow){
				$emails[] =$drow->email;
			}
		}elseif($emailtype == 'everyone_till_approved'){
			$emaillisttillapprove = "select au.user_email as email FROM transaction_approval_logs tal left join application_users au on tal.user_id = au.id where tal.transaction_table ='".$data['table']."' AND  tal.transaction_id = '".$data['rid']."' AND tal.response_type IS NOT NULL";
			$emaillisttillapproves = $callConfig->getAllRows($emaillisttillapprove);
			foreach($emaillisttillapproves as $drow){
				$emails[] =$drow->email;
			}
		}else{
			$emaillistevryapprove = "select au.user_email as email FROM transaction_approval_logs tal left join application_users au on tal.user_id = au.id where tal.transaction_table ='".$data['table']."' AND  tal.transaction_id = '".$data['rid']."'  order by tal.id asc";
			$emaillistevryapproved = $callConfig->getAllRows($emaillistevryapprove);
			$emails[] =$emaillistevryapproved[0]->email;

		}
		$emails[] = $email_data;
		$email_array = $this->emailtemplate($datas);
		$file_name = 'email'.'_'.time().uniqid().'.'.'html';
		$email_array ['content'] = $file_name;
		$email_array['revicer'] = $email;
		$email_array['email_type'] = 1;
		$email = $email_array['mesg'];
		$file_path='uploads/email/'.$file_name;
		file_put_contents($file_path, $email);
		//fclose($file_path);
		$lenn = $this->sendEmailslist($email_array);
	}
}

