function checkEmployeeLeaveAvailableOrNot($data){
	global $callConfig;
	$leavestartdate = $data['leave_from'];
	$leaveenddate = $data['leave_to'];
	$start_half_day = ($data['start_half_day'] =='1' OR $data['start_half_day'] =='2')?"1":"0";
	$end_half_day =($data['end_half_day'] =='1' OR $data['end_half_day'] =='2')?"1":"0";
	$leaveaplye = 0;
	$halfdayscnt = 0;
	$dayarrays =["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
	$returnresultarray = array('leaveaplye'=>'0');
	$returnresultarray['unpaid_days'] = '0';
	$returnresultarray['error_msg'] = "";
	$returnresultarray['halfdays'] = "start - ".$start_half_day." -- ".$end_half_day;
//employee detrails
	$employee_leavesslq = "select id FROM employee_leaves where is_active='0' and company_id = '".$data['company_id']."' and employee_id='".$data['emp_id']."' AND id != '".$data['rid']."' AND   ((leave_from >= '".$this->dateconvertdbformat($leavestartdate)."' AND leave_from <= '".$this->dateconvertdbformat($leaveenddate)."' )OR ( leave_to >= '".$this->dateconvertdbformat($leavestartdate)."' AND leave_to <= '".$this->dateconvertdbformat($leaveenddate)."'))";
	$returnresultarray['employee_leavesslq'] =$employee_leavesslq;
	
	$employee_leavesres = $callConfig->getRow($employee_leavesslq);
	if($employee_leavesres->id !=""){
		$returnresultarray['leaveaplye'] = '1';
		$returnresultarray['error_code'] = '8011';
	}
	$returnresultarray['allready_leave'] = $employee_leavesres->id;
	//$returnresultarray['employee_leavesslq'] = $employee_leavesslq;
//balance and leaeve type	
	
//employee detrails
	$employee_detailsurl = "select id,joining_date,location_id FROM employees where is_active='0' and company_id = '".$data['company_id']."' and id='".$data['emp_id']."'";
	$employee_details = $callConfig->getRow($employee_detailsurl);
//balance and leaeve type
	$attendance_settingurl = "select * FROM attendance_settings where is_active='0' and company_id = '".$data['company_id']."' and location_id='".$employee_details->location_id."'";
	$attendance_settings = $callConfig->getRow($attendance_settingurl);
	//print_r($attendance_settings->working_days);
	$working_days =  json_decode($attendance_settings->working_days,1);
	foreach($dayarrays as $dayarray){
		if (!in_array($dayarray, (array)$working_days)){
			$weekenddays[] = $dayarray;
		}
	}
	//echo $emp_leave_balancesurl = "select elb.id as elbid,elb.applicable_leaves,elb.consumed_leaves,elb.leave_year,elb.weekend_leave_consume,elb.holiday_leave_consume,lt.* FROM emp_leave_balances elb LEFT JOIN leave_types lt on elb.leave_type = lt.id  where elb.is_active='0' and elb.company_id = '".$data['company_id']."' and elb.employee_id='".$data['emp_id']."' and lt.leave_category_id='".$data['leavetype']."'";
	$emp_leave_balancesurl ="SELECT elb.id as elbid,elb.applicable_leaves,elb.consumed_leaves,elb.unapproved_leaves,elb.leave_year,elb.weekend_leave_consume,elb.holiday_leave_consume,lt.* FROM emp_leave_balances elb ,leave_types lt WHERE lt.company_id = '".$data['company_id']."' AND lt.company_id = elb.company_id AND lt.leave_category_id = '".$data['leavetype']."' AND elb.employee_id='".$data['emp_id']."' AND lt.id = elb.leave_type AND lt.is_active=0";
	$returnresultarray['emp_leave_balancesurl'] =$emp_leave_balancesurl;

	$emp_leave_balances = $callConfig->getRow($emp_leave_balancesurl);
	//$employee_filter = json_decode($emp_leave_balances->employee_filter,1);
	$returnresultarray['leavebalanceid'] = $emp_leave_balances->elbid;
	//$returnresultarray['emp_leave_balancesurl'] = $emp_leave_balancesurl;
	/*counsume leave check updatetime*/ 	
	$returnresultarray['data'] =$data;
	if($data['rid']!=""){ 
		//$emp_leave_balances->consumed_leaves = ($emp_leave_balances->consumed_leaves - $data['old_leave_days']);
		$consumed_leaves = (($emp_leave_balances->consumed_leaves+$emp_leave_balances->unapproved_leaves) - $data['old_leave_days']);
	}else{
		$consumed_leaves = $emp_leave_balances->consumed_leaves+$emp_leave_balances->unapproved_leaves;
	} 
	/*counsume leave check updatetime*/ 	
	$leave_type_levels = "SELECT * FROM `leave_type_levels` where is_active='0' and company_id = '".$data['company_id']."' and leave_type_id='".$emp_leave_balances->id."'";
	$leave_type_levels = $callConfig->getRow($leave_type_levels);
//hoilidays list
	$holidays = "SELECT holiday_date FROM holidays WHERE is_active=0 and company_id=".$data['company_id']." AND holiday_year=".date('Y',strtotime($leavestartdate));
	$holidaysdata = $callConfig->getAllRows($holidays);
	foreach ($holidaysdata as $hkey=>$hvalue){
		$holidaysdatas[] = $hvalue->holiday_date;
	}
//Accrual Schedule start day to leave
	if($leave_type_levels->before_or_after=="B"){$before_or_after  = "-";}else{$before_or_after = "+"; }
	if($leave_type_levels->action_frequency  == 'W'){$startleavetype = "week";}elseif($leave_type_levels->action_frequency  == 'M'){$startleavetype = "months"; }elseif($leave_type_levels->action_frequency  == 'Y'){ 	$startleavetype = "years"; }else{ 	$startleavetype = "days"; }
	$leavestart = strtotime($employee_details->joining_date. ' '.$before_or_after.' '.round($leave_type_levels->action_number).' '.$startleavetype);
// End Accrual Schedule start day to leave
if(!isset($emp_leave_balances->id)){ // leave policy not defind
	$returnresultarray['leaveaplye'] = '1';
	$returnresultarray['error_code'] = '8007';
	return $returnresultarray;
}

if($leavestart <= strtotime(date('d-m-Y'))){
	$dateFrom = new DateTime($leavestartdate);
	$dateTo = new DateTime($leaveenddate);
	$datenames = [];
	$holidayleave = 0;
	$weekenddaysc = 0;
	$weeckendandholidayscount =0;
	while ($dateFrom <= $dateTo) {
		$datenames[] = $dateFrom->format('l');
		if(in_array($dateFrom->format('Y-m-d'),(array)$holidaysdatas)){
			$holidayleave++;
		}
		$dateFrom->modify('+1 days');
	}

	$count_array_days = array_count_values((array)$datenames);
	foreach ($weekenddays as $value){
		$weekenddaysc = $weekenddaysc+$count_array_days[$value];
	}
$weekend_leave_consume  = $emp_leave_balances->weekend_leave_consume + $weekenddaysc;  //extra weeckend check added or not
$holiday_leave_consume  = $emp_leave_balances->holiday_leave_consume + $holidayleave; //extra holidays check added or not

//leave sandwitch leave
if($emp_leave_balances->weekends_between_leave_period == '0'){   //weekend periad status
	if($weekend_leave_consume > $emp_leave_balances->weekend_leave_count){  // so weekend leaves and limit check 		
		//$returnresultarray['leaveaplye'] = '1';
		//$returnresultarray['error_code'] = '8003';
		//$returnresultarray['error_msg_val'] = '8003';
		
	}else{
		$weeckendandholidayscount += $weekenddaysc;
	}
} 
//hoplidays
if($emp_leave_balances->holidays_between_leave_period == '0'){
	//echo "</br> holidays cunsume - ".$holiday_leave_consume ."  - limite  - ".$emp_leave_balances->holiday_leave_count."</br>";
	if($holiday_leave_consume > $emp_leave_balances->holiday_leave_count){
		//$returnresultarray['leaveaplye'] = '1';
		//$returnresultarray['error_code'] = '8004';
		//$returnresultarray['holiday_leave_consume'] = $holiday_leave_consume;
	}else{
		$weeckendandholidayscount += $holidayleave;
	}
}
$returnresultarray['weeckendandholidayscount'] = $weeckendandholidayscount;
$returnresultarray['weeckendandnumberdate'] = $weekenddaysc;
$returnresultarray['holidaysnumberdate'] = $holidayleave;

$availabeleaves = $emp_leave_balances->applicable_leaves - $consumed_leaves;
$finalappllayleavecount = count((array)$datenames)-$weeckendandholidayscount;

$returnresultarray['withouthlfdays'] = $finalappllayleavecount;
if($start_half_day == '1' OR $end_half_day == '1'){ //half day check or not
	$halfdayscnt = 0;
	if($start_half_day == '1' AND $end_half_day == '1'){ //Both half day check this true 1 days counsume
		$halfdayscnt = 1;
	}elseif($start_half_day == '1' OR $end_half_day == '1'){ //single half day check this true 0.5 days counsume
		$halfdayscnt = 0.5;
	}
	if($finalappllayleavecount > 1){
		$finalappllayleavecount = $finalappllayleavecount-$halfdayscnt;
	}else{
		$finalappllayleavecount = $finalappllayleavecount-0.5;
	}
}
$returnresultarray['withhlfdays'] = $finalappllayleavecount;
$returnresultarray['final_appllay_leave_count'] = $finalappllayleavecount;
$returnresultarray['availabe_leaves'] = $availabeleaves;
$returnresultarray['consumed_leaves'] = $consumed_leaves;
if($availabeleaves < 0){
	$returnresultarray['leaveaplye'] = '1';
	$returnresultarray['error_code'] = '8008';	
//$returnresultarray['error_code33333333333333333333333'] = '3';
} 
//duration Not leave
if($emp_leave_balances->duration_allowed == '0' AND $emp_leave_balances->duration_allowed !=""){
	$todaydate = strtotime("- ".$emp_leave_balances->duration_leave_count." day", strtotime(date('d-m-Y')));
	$leavestartdate =strtotime($leavestartdate);
	$returnresultarray['duration_allowed'] = date('d-m-Y',$leavestartdate);
	$returnresultarray['today_date'] = date('d-m-Y',$leavestartdate);
	if($todaydate > $leavestartdate){
			//echo "duration Not leave";
		$returnresultarray['duration Not leave'] = $emp_leave_balances->duration_leave_count;
		$returnresultarray['leaveaplye'] = '1';
		$returnresultarray['error_code'] = '8009';
		$returnresultarray['error_msg'] = $emp_leave_balances->duration_leave_count;
	}
}
 	if(round($leave_type_levels->leave_span) < $finalappllayleavecount AND $leave_type_levels->leave_span !="" AND $leave_type_levels->leave_span !="0"){  	// leaev type leavels excide
 		$returnresultarray['leaveaplye'] = '1';
 		$returnresultarray['error_code'] = '8010';
 		$returnresultarray['leave_span'] = $leave_type_levels->leave_span;
 	} 
	if($availabeleaves < $finalappllayleavecount){   // exced leave yes or not
		if($emp_leave_balances->exceed_leave_balance == '1'){
			$returnresultarray['leaveaplye'] = '0';	
			$returnresultarray['unpaid_days'] = $finalappllayleavecount;
		}elseif($emp_leave_balances->exceed_leave_balance == '2'){
			$returnresultarray['leaveaplye'] = '0';	
			$returnresultarray['unpaid_days'] = $finalappllayleavecount;
		}else{
			$returnresultarray['exceed_leave_balance'] = $emp_leave_balances->exceed_leave_balance;
			$returnresultarray['leaveaplye'] = '1';	
			$returnresultarray['error_code'] = '8005';
			$returnresultarray['error_msg']= $availabeleaves;
		}
	} 
}else{
	$returnresultarray['leaveaplye'] = '1';
	$returnresultarray['error_code']= '8001';
	$returnresultarray['error_msg']= date('d-m-Y',$leavestart);
} 
return $returnresultarray;
//return $data;
}
