function insertLeaveRequest($data){

	global $callConfig;
	$returnarray = array();
	$returnarray['post'] = $data;
	$rid = $data['rid'];
	$userid = $data['user_id'];
	unset($data['rid']);unset($data['user_id']);
	if($rid!=""){
		$emp_leavesql = "select leave_days,employee_id,leave_type_id From employee_leaves WHERE company_id = '".$data['company_id']."' AND is_active = 0 AND id = '".$rid."'";
		$emp_leaveres = $callConfig->getRow($emp_leavesql);
		$returnarray['emp_leaveres'] = $emp_leavesql;
	}
	$newdata = $data;
	$newdata['emp_id'] = $data['employee_id'];
	$newdata['leavetype'] = $data['leave_type_id'];
	$newdata['old_leave_days'] = $emp_leaveres->leave_days!=""?$emp_leaveres->leave_days:0;
	$newdata['rid'] = $rid;
	$checkleave = $this->checkEmployeeLeaveAvailableOrNot($newdata);
	$returnarray["leavestatus"] = $checkleave;
	if($checkleave['leaveaplye']=='0'){
		$data['unpaid_days'] = $checkleave['unpaid_days'];
		$data['weekend_leave_consume'] = $checkleave['weeckendandnumberdate'];
		$data['holiday_leave_consume'] = $checkleave['holidaysnumberdate'];
		if($rid!=""){
			$data['created_date'] = date('Y-m-d H:i:s');
			$data['created_by'] = $userid;
			$res=$callConfig->updateRecord('employee_leaves',$data,'id',$rid);
			$res['LASTID'] = $rid;
		}else{	
			$data['updated_date'] = date('Y-m-d H:i:s');
			$data['updated_by'] = $userid;
			$res=$callConfig->insertRecord('employee_leaves',$data);
			//$this->checkWorkFlowCriteria(array('tablename'=>'employee_leaves','company_id'=>$data['company_id'],'rid'=>$res['LASTID'])); //check workflow criteria
		}
	
		$updateval = $checkleave['final_appllay_leave_count'] - $emp_leaveres->leave_days; //allways positive value show
		if($updateval < 0){
			$sql = "UPDATE `emp_leave_balances` SET `unapproved_leaves`= unapproved_leaves -".abs($updateval).",weekend_leave_consume = weekend_leave_consume+'".$checkleave['weeckendandnumberdate']."',holiday_leave_consume = holiday_leave_consume+'".$checkleave['holidaysnumberdate']."'  WHERE `id`='".$checkleave['leavebalanceid']."' AND is_active= '0'";
		}else{
			$sql = "UPDATE `emp_leave_balances` SET `unapproved_leaves`= unapproved_leaves + ".$updateval.",weekend_leave_consume = weekend_leave_consume+'".$checkleave['weeckendandnumberdate']."',holiday_leave_consume = holiday_leave_consume+'".$checkleave['holidaysnumberdate']."'  WHERE `id`='".$checkleave['leavebalanceid']."' AND is_active= '0'";
		}
		$callConfig->executeQueryString($sql);
		$returnarray['emp_leave_balances'] = $sql;	
		$returnarray['leaveinsert'] = $res;	 
	} 
		/*else{
			$sql = "UPDATE `emp_leave_balances` SET `consumed_leaves`= consumed_leaves + ".$emp_leaveres->leave_days." WHERE employee_id ='".$emp_leaveres->employee_id."' AND leave_type = '".$levtyperes->id."' AND is_active= '0'";
			$callConfig->executeQueryString($sql);
		}*/
		return $returnarray;
	}
	function rolelevelworkflow($checkcriteria,$data,$looprun){
		global $callConfig;
		$returnuserid = "";
		$emplyeesql = "SELECT id,display_name,company_id,user_id,role_id,sub_section_id,section_id,department_id,division_id FROM employees where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['emp_id']."'";
		$employeerow=$callConfig->getRow($emplyeesql);
		$tepstorereprtid = 0;
		for($jk=1;$jk <= $looprun; $jk++){ 	
			if($jk == 1){
				$emplyeerolsql = "SELECT id,reports_to_role FROM employment_roles where is_active = 0 and company_id = '".$data['company_id']."' and id='".$employeerow->role_id."'";
				$employeerolrow=$callConfig->getRow($emplyeerolsql);
				$tepstorereprtid = $employeerolrow->reports_to_role;
			}else{
				$emplyeerolsql = "SELECT id,reports_to_role FROM employment_roles where is_active = 0 and company_id = '".$data['company_id']."' and id='".$tepstorereprtid."'";
				$employeerolrow=$callConfig->getRow($emplyeerolsql);
				$tepstorereprtid = $employeerolrow->reports_to_role;
			}
		}
		if($tepstorereprtid !=""){
			$subsectionsql = "SELECT user_id FROM employees where is_active = 0 and company_id = '".$data['company_id']."' and sub_section_id='".$employeerow->sub_section_id."' and role_id ='".$tepstorereprtid."'";
			$subsectionrow=$callConfig->getRow($subsectionsql);
			if(isset($subsectionrow->user_id)){
				$returnuserid  = $subsectionrow->user_id;
			}else{ 
				$sectionsql = "SELECT user_id FROM employees where is_active = 0 and company_id = '".$data['company_id']."' and section_id='".$employeerow->section_id."' and role_id ='".$tepstorereprtid."'";
				$sectionrow=$callConfig->getRow($sectionsql);
				if(isset($sectionrow->user_id)){   //section match
					$returnuserid  = $sectionrow->user_id;
				}else{
					$departmentsql = "SELECT user_id FROM employees where is_active = 0 and company_id = '".$data['company_id']."' and department_id='".$employeerow->department_id."' and role_id ='".$tepstorereprtid."'";
					$departmebtrow=$callConfig->getRow($departmentsql);
					if(isset($departmebtrow->user_id)){  ////department match
						$returnuserid  = $departmebtrow->user_id;
					}else{
						$divisionsql = "SELECT user_id FROM employees where is_active = 0 and company_id = '".$data['company_id']."' and division_id='".$employeerow->division_id."' and role_id ='".$tepstorereprtid."'";
						$divisionrow=$callConfig->getRow($divisionsql);
						if(isset($divisionrow->user_id)){ //division match
							$returnuserid  = $divisionrow->user_id;
						}else{
							$comanysql = "SELECT hr_connect FROM companies where is_active = 0 and id ='".$employeerow->company_id."'";
							$companyrow=$callConfig->getRow($comanysql);
							$returnuserid  = $companyrow->hr_connect;
						}
					}
				}
			}
		}else{
			$returnuserid = "-1";
		}	
		return $returnuserid;
	}
