function workFlowFieldId($status,$data){
	global $callConfig;
	$gettablesql = "select ".$status['work_flow_field']." from ".$data['table']." where is_active='0' and company_id = '".$data['company_id']."' AND id='".$data['rid']."'";
	$resutltable = $callConfig->getRow($gettablesql);
	return (array)$resutltable;
}
function updatedynamicapprovallognew($data){
	global $callConfig;
	$fields1 = array('response_type' =>$data['status'],'response_date' =>date("Y-m-d H:i:s"),'comments' =>$data['comment']);
	$whrcon1 = "id='".$data['transaction_id']."' AND send_back_flag  = '0'";
	$res = $callConfig->updateRecord('transaction_approval_logs',$fields1,'','',$whrcon1);
	$workflowsql = "select * from workflow_configuration where is_active='0' and company_id = '".$data['company_id']."' AND id='".$data['workflow_id']."'";
	$resutlworkflow = $callConfig->getRow($workflowsql);
	$status = json_decode($resutlworkflow->approve_update_status,1);
	if($data['status'] == ST_SEND_BACK){
		$workf['workflow_configuration'] = $resutlworkflow;
		$returnarray = $this->setSendBack($data,$workf);
	}else{

		if($data['type']=="approve"){
			if($resutlworkflow->approval_type == 'email_groups' || $resutlworkflow->approval_type == 'access_levels' || $resutlworkflow->approval_type == 'individual_employee_role'){
				$samestatusrescntsql = "select count(id) as cnt from transaction_approval_logs where transaction_table = '".$data['table']."' AND transaction_id='".$data['rid']."' AND response_type = '".$data['status']."' AND send_back_flag  = '0'";
