			}		
			if($resutlworkflow->approval_type != 'email_groups' || $resutlworkflow->approval_type != 'access_levels' || $resutlworkflow->approval_type != 'individual_employee_role'){
				$getstatus='0';
				$key ="";
				$incrementkey = "";
				foreach($status as $keyy=>$statuse){
				if($data['status']==$statuse['status']){ //check next position status
					$incrementkey = $keyy;	//incerment key
					$incrementkey += 1;
				}
