					$getstatus = $statuse['status'];
					$key =  $keyy;
					echo "troue";
				}*/			
			}
			if(isset($status[$incrementkey])){ //incerment key get available or not
				$getstatus = $status[$incrementkey]['status'];
				$key =  $incrementkey;
			}
			if($getstatus !='0'){  //next status available or not
				if($resutlworkflow->approval_type == 'custom_process'){  //custom process only
					$addone = $key;
					$conjson = json_decode($resutlworkflow->sub_approve_type,1);
