					$returnarray['next_user']= $datareportid->reports_to;
					if($datareportid->reports_to !=""){
						$resf=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);	
					}
					$getuserids = $datareportid->reports_to;
					$returnarray['workflowsendnotifiction'] = $this->workflowsendnotifiction($resutlworkflow,$data,$datareportid->reports_to);
				}
			}else{
				$returnarray['next_user']="approved";	
			}
		}	



	}else{
		$returnarray = array();
