//updateleavedays($dynamic_status,$post);
function updateleavedays($status,$post){
	global $callConfig;
	if($status == ST_APPROVED1){
		$emp_leavesql = "select leave_days,employee_id,leave_type_id From employee_leaves WHERE company_id = '".$post['company_id']."' AND is_active = 0 AND id = '".$post['transaction_no']."'";
		$emp_leaveres = $callConfig->getRow($emp_leavesql);
		$levtypesql = "select id From leave_types WHERE company_id = '".$post['company_id']."' AND is_active = 0 AND leave_category_id = '".$emp_leaveres->leave_type_id."'";
		$levtyperes = $callConfig->getRow($levtypesql);
		$sql = "UPDATE `emp_leave_balances` SET `unapproved_leaves`= unapproved_leaves -".$emp_leaveres->leave_days.",`consumed_leaves`= consumed_leaves +".$emp_leaveres->leave_days." WHERE employee_id ='".$emp_leaveres->employee_id."' AND leave_type= '".$levtyperes->id."' AND is_active= '0'";
		$callConfig->executeQueryString($sql);
		$fieldnames = array('is_active'=>'0','company_id'=>$post['company_id'],'employee_id'=>$emp_leaveres->employee_id,'leave_type'=>$emp_leaveres->leave_type_id,'consumed_leaves'=>$emp_leaveres->leave_days,'current_status'=>'0','leave_year'=>date('Y'),'transaction_date'=>date('Y-m-d'),'type'=>'1');
		$res = $callConfig->insertRecord('emp_leave_allocations',$fieldnames);	
	}
	if($status == ST_REJECTED OR $status == ST_CALLBACK OR $status == ST_SEND_BACK){
		$emp_leavesql = "select leave_days,employee_id,leave_type_id From employee_leaves WHERE company_id = '".$post['company_id']."' AND is_active = 0 AND id = '".$post['transaction_no']."'";
		$emp_leaveres = $callConfig->getRow($emp_leavesql);
		$levtypesql = "select id From leave_types WHERE company_id = '".$post['company_id']."' AND is_active = 0 AND leave_category_id = '".$emp_leaveres->leave_type_id."'";
		$levtyperes = $callConfig->getRow($levtypesql);
		$sql = "UPDATE `emp_leave_balances` SET `unapproved_leaves`= unapproved_leaves +".$emp_leaveres->leave_days.",`consumed_leaves`= consumed_leaves -".$emp_leaveres->leave_days." WHERE employee_id ='".$emp_leaveres->employee_id."' AND leave_type= '".$levtyperes->id."' AND is_active= '0'";
		$callConfig->executeQueryString($sql);
		$fieldnames = array('is_active'=>'0','company_id'=>$post['company_id'],'employee_id'=>$emp_leaveres->employee_id,'leave_type'=>$emp_leaveres->leave_type_id,'applicable_leaves'=>$emp_leaveres->leave_days,'current_status'=>'0','leave_year'=>date('Y'),'transaction_date'=>date('Y-m-d'),'type'=>'2');
		$res = $callConfig->insertRecord('emp_leave_allocations',$fieldnames);	
	}	
	return $res; 
}

function insertTransactionApprovalLogs($data,$post,$workflowdetails){
	global $callConfig;
	$returnarry = array();
	$post_array= array("current_status"=>$data['status'],"status_date"=>date('Y-m-d'));
	$res=$callConfig->updateRecord($data['tablename'],$post_array,'id',$data['rid']);
	$returnarry['update_transaction_table'][]= $res;
	if($workflowdetails['workflow_configuration']->after_approve_call_function != ""){
		$dynamic_status = $data['status'];
		$dynamic_post = $post;
		$functions = $workflowdetails['workflow_configuration']->after_approve_call_function;
		//$details = $this->$funtt;
		//$returnarry['funtt'][]  = $funtt;
		//$returnarry['cdsdfcd'][]  = $details;
		$returnarry['dddd'][]  = $this->$functions($dynamic_status,$dynamic_post);
		//$returnarry['dddd'][]  = $this->updateleavedays($dynamic_status,$post);
	}
	
	foreach($data['userid'] as $row1){
		$rid = $data['rid'];
		$userid  = $row1;
		$already = "select id from transaction_approval_logs where transaction_table  = '".$data['tablename']."' and transaction_id   = '".$rid."' and user_id  = '".$userid."'  and company_id = '".$post['company_id']."' AND workflow_id = '".$data['workflow_id']."' AND send_back_flag  = '0'";
		$returnarry['already'][]= $already; 
		$alreadydata = $callConfig->getRow($already);
		$returnarry['alreadydata'][]= $alreadydata; 
		//print_r($already);
		if(!isset($alreadydata->id)){
			$inserttransactionapprovelog =array('company_id'=>$post['company_id'],'module_setup_id'=>$callConfig->module_id,'transaction_table'=>$data['tablename'],'transaction_id'=>$rid,'response_type'=>'0','user_id'=>$userid,'request_date'=>date("Y-m-d H:i:s"),'workflow_id'=>$data['workflow_id']);
