	$msg =$this->workFlowSendNotificatin($post,$workflowdetails,'approve_message'); //approve_message,reject_message,sendback_message,completed_workflow_message,employee_message
	$user_ids  = $data['userid'];
	if($post['pagename']!=""){
		$option = $post['pagename'];	
	}else{
		$option = "COM_INSERT_".strtoupper($post['tablename']);	
	}
	//$option = "COM_INSERT_".strtoupper($data['tablename']);
	$notdataa = array('company_id'=>$post['company_id'], 'notification_message'=>$msg, 'id'=>$data['rid'], 'application_table_name'=>$data['tablename'], 'type'=>'ACTION', 'notification_users'=>$user_ids,'option'=>$option);
	$returnarry['noti_array']= $notdataa;
	$notres = $this->tosendnotifiations($notdataa);
	$returnarry['noti_res']= $notres;
	//End Next Aprovel message Send 
	//Employee message Send 
	$cretedby = "SELECT created_by FROM ".$data['tablename']." where company_id = '".$post['company_id']."' and id='".$data['rid']."'";
	$cretedbyid=$callConfig->getRow($cretedby);
	$returnarry['cretedbysql']= $cretedby;
	$returnarry['cretedbyid']= $cretedbyid;
	//$option = "COM_INSERT_".strtoupper($data['tablename']);
	if($post['pagename']!=""){
		$option = $post['pagename'];	
	}else{
		$option = "COM_INSERT_".strtoupper($data['tablename']);	
	}
	//$msg1 = $data['tablename']." - ".$rid." Send For Approval";
	$msg1 =$this->workFlowSendNotificatin($post,$workflowdetails,'employee_message'); //approve_message,reject_message,sendback_message,completed_workflow_message,employee_message
	$user_ids1  = array($cretedbyid->created_by);
	$crfeatebynotdataa = array('company_id'=>$data['company_id'], 'notification_message'=>$msg1, 'id'=>$data['rid'], 'application_table_name'=>$data['tablename'], 'type'=>'INFORMATION', 'notification_users'=>$user_ids1,'option'=>$option);
	$notres1 = $this->tosendnotifiations($crfeatebynotdataa);
	$returnarry['createdbynoti']= $notres1;
	//Employee message Send 
	//$returnarry['transaction_msg_fun']= 
	return $returnarry;
}
function workFlowSendNotificatin($post,$workflowdetails,$msg_type){
	global $callConfig;
	$returnarray = array();
	//echo "<pre>"; //print_r($workflowdetails);
	$transaction_message = json_decode($workflowdetails['workflow_configuration']->transaction_message,1);
	$msg = $transaction_message[$msg_type];
	
	$returnarray['transaction_message'] = $msg;
	//$process = array("process_name"=>ucwords(str_replace("_"," ",($post['tablename']))));
	$process = array("process_name"=>$workflowdetails['workflow_configuration']->process_name);
	$msg = $this->replacestringwithpreview($post['tablename'],$process,$msg);
	
	$transaction_sql = "SELECT * FROM ".$post['tablename']." where company_id = '".$post['company_id']."' AND id='".$post['rid']."' AND is_active = 0";
	$transaction_details=$callConfig->getRow($transaction_sql);
	$returnarray['transaction_details'] = $transaction_details;
	$msg = $this->replacestringwithpreview($post['tablename'],$transaction_details,$msg);
	
	$transaction_employee_sql = "SELECT * FROM employees where company_id = '".$post['company_id']."' AND user_id='".$transaction_details->created_by."' AND is_active = 0";
	$transaction_employee_detals=$callConfig->getRow($transaction_employee_sql);
	$returnarray['transaction_employee_detals'] = $transaction_employee_detals;
	$msg = $this->replacestringwithpreview('employee',$transaction_employee_detals,$msg);
	
	$sessionuser_sql = "SELECT * FROM application_users where company_id = '".$post['company_id']."' AND id='".$post['user_id']."' AND is_active = 0";
	$sessionuser_details=$callConfig->getRow($sessionuser_sql);
	$returnarray['sessionuser_details'] = $sessionuser_details;
	$msg = $this->replacestringwithpreview('session_user',$sessionuser_details,$msg);
	
	$sessionemployee_sql = "SELECT * FROM employees where company_id = '".$post['company_id']."' AND user_id='".$post['user_id']."' AND is_active = 0";
	$sessionemployee_details=$callConfig->getRow($sessionemployee_sql);
	$returnarray['sessionemployee_details'] = $sessionemployee_details;
	$msg = $this->replacestringwithpreview('session_employee',$sessionemployee_details,$msg);
	if($msg_type =="employee_message"){ //status name include message
		$statussql = "SELECT name FROM status_progress where company_id = '".$post['company_id']."' and status='".$post['status']."' AND table_name = '".$post['tablename']."'";
		$statusres=$callConfig->getRow($statussql);
		$msg .= " ".$statusres->name;
	}
	//$returnarray['msg'] = $msg;
	//$msg .= $msg_type;
	//print_r($returnarray);
	return $msg; 
} 
function replacestringwithpreview($tablename,$array,$msg){
	//$values = urldecode($val);
	$str = "";
	foreach($array as $key => $value){
		$repl =  str_replace("{[".$tablename.".".$key."]}", $value, $msg);
		$msg = $repl;
	}
	return $msg;
}


function checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row){
	global $callConfig;
	if($data['tablename']=="project_timesheets"){ $rids = explode(',',$data['rid']); $rid = $rids[0]; }else{ $rid = $data['rid']; }
	$already = "select * from transaction_approval_logs where transaction_table  = '".$checkcriteria['workflow_configuration']->process_type."' and transaction_id   = '".$rid."' and user_id  = '".$row['reports_to']."'  and company_id = '".$data['company_id']."' AND workflow_id = '".$checkcriteria['workflow_configuration']->id."' AND send_back_flag  = '0'"; 
	$alreadydata = $callConfig->getRow($already);
	if(!isset($alreadydata->id)){
		$inserttransactionapprovelog =array('company_id'=>$data['company_id'],'module_setup_id'=>$callConfig->module_id,'transaction_table'=>$checkcriteria['workflow_configuration']->process_type,'transaction_id'=>$rid,'response_type'=>'','user_id'=>$row['reports_to'],'request_date'=>date("Y-m-d H:i:s"),'workflow_id'=>$checkcriteria['workflow_configuration']->id,'ref_field'=>$data['rid']);
		$statusincode = json_decode($checkcriteria['workflow_configuration']->approve_update_status);
		if($statusincode[0]->status !="" ||	$statusincode[0]->status !="-1"){
			$updatequery ="UPDATE ".$data['tablename']." SET current_status = ".$statusincode[0]->status." WHERE id IN(".$data['rid'].")";
			$res1 = $callConfig->executeQuery($updatequery);
		}
		$res=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);
		$this->workflowsendnotifiction($checkcriteria,$data,$row['reports_to']);
	}	
	return $res;
}
function getUserStatusStep($data){
	global $callConfig;
	$data['tablename']  = $data['table'];
	$maindata = "select id,workflow_id from transaction_approval_logs where transaction_table = '".$data['table']."' AND transaction_id='".$data['transaction_id']."' AND user_id = '".$data['user_id']."' AND response_type ='0' AND send_back_flag  = '0'";
	$maindatares = $callConfig->getRow($maindata);
	//print_r($maindatares);
	$cdsc['maindatares'] = $maindatares;
	$workflowid = $maindatares->workflow_id;
	$transactionlogid = $maindatares->id;
	if(isset($maindatares->id) AND $maindatares->id !=""){
	//if($totalworkresponscnt->cnt > $updateworkresponscnt->cnt  || $totalworkresponscnt->cnt=='0'){  //steps update
		$workflowsql = "select * from workflow_configuration where is_active='0' and company_id = '".$data['company_id']."' AND id='".$workflowid."'";
		$workrespons = $callConfig->getRow($workflowsql);
		//approve 
		$statuse = json_decode($workrespons->approve_update_status,1);
		$incrementkey = "";
		if($workrespons->approval_type == 'email_groups' || $workrespons->approval_type == 'access_levels' || $workrespons->approval_type == 'buddy'){
			$st = ($statuse[1]['status']=="" ||	$statuse[1]['status']=="-1")?"-1":$statuse[1]['status'];
			$approvestatus= array('status'=>$st,'transaction_id'=>$transactionlogid,'workflow_id'=>$workflowid);
		}else{
			foreach($statuse as $key=>$statuse){
				if($data['currnet_status']==$statuse['status']){
					$incrementkey = $key+1;	
				}
				if($incrementkey == $key){
					$st = ($statuse['status']=="" || $statuse['status']=="-1")?"-1":$statuse['status'];
					$approvestatus= array('status'=>$st,'transaction_id'=>$transactionlogid,'workflow_id'=>$workflowid);
				}	
			}
		}
		//approve 
		//reject
		$statuse = json_decode($workrespons->rejection_update_status,1);
		$st = ($statuse[0]['status']=="" ||	$statuse[0]['status']=="-1")?ST_REJECTED:$statuse[0]['status'];
		$rejectstatus= array('status'=>$st,'transaction_id'=>$transactionlogid,'workflow_id'=>$workflowid);
	 	//reject
		$retrunstaus['approve'] = $approvestatus; 
		$retrunstaus['reject'] = $rejectstatus;
	}else{
		$wchistoriessql = "select approve_update_status from workflow_configuration_histories where company_id = '".$data['company_id']."' AND process_type = '".$data['table']."' AND transaction_id='".$data['transaction_id']."' AND is_active ='0'";
		$wchistoriesres = $callConfig->getRow($wchistoriessql);
		$statuse = json_decode($wchistoriesres->approve_update_status,1);
		$retrunstaus['staus'] = $statuse[0];
		$retrunstaus['error'] = '404'; 
	}
	return $retrunstaus;
}
function getStatusWorkFlow($data){
    // who approw this task enter and return status getReportToWorkFlow
	global $callConfig;
	$checkcriteria = $this->checkCriteria($data);
	$reporttolist = array();
	$reporttolist = $checkcriteria;
	if(isset($checkcriteria['workflow_configuration'])){
		//$checkcriteria['workflow_configuration']->approval_type = 'access_levels';
		if($checkcriteria['workflow_configuration']->approval_type == 'manager'){
				$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['user_id']."'";  // table name and exicution type creation and update
				$rowd = $callConfig->getRow($sql); 
				$reporttolist['nextstepuid'][]  = $rowd->reports_to;
			}elseif($checkcriteria['workflow_configuration']->approval_type == 'Managers_Manager'){
				$sql = "select reports_to FROM application_users WHERE is_active = 0  and company_id = '".$data['company_id']."' AND id IN(select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['user_id']."')";
			$rows = $callConfig->getRow($sql); //manager
			$reporttolist['nextstepuid'][]  = $rows->reports_to;

		}elseif($checkcriteria['workflow_configuration']->approval_type == 'user'){
			$reporttolist['nextstepuid'][]  = $checkcriteria['workflow_configuration']->sub_approve_type;

		}elseif($checkcriteria['workflow_configuration']->approval_type == 'custom_process'){
			$conjson = json_decode($checkcriteria['workflow_configuration']->sub_approve_type,1);
			$m = $data['level'];
			$reporttolist['nextstepuid'][]  = $conjson['step_'.$m];;
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'access_levels'){
			$like = "'".'%"'.$checkcriteria['workflow_configuration']->sub_approve_type.'"%'."'";
			$sql = "SELECT id FROM `application_users` WHERE  is_active = 0 AND company_id = '".$data['company_id']."' AND role_id like ".$like;
			$row=$callConfig->getAllRows($sql);
			foreach($row as $ro){
				$reporttolists[] = $ro->id;
			}
			$reporttolist['nextstepuid'] = $reporttolists;
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'role_levels'){
			$conjson = $checkcriteria['workflow_configuration']->sub_approve_type;	
			$m = $data['level'];
			$getuserid =$this->rolelevelworkflow($checkcriteria,$data,$m);
			$reporttolist['nextstepuid'][] = $getuserid;
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'user_hierarchical'){
			$reportid = '';
			$step =  $data['level'];
			for($i=1;$i <= $step; $i++){ 	
				if($i==1){
					$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$data['user_id']."'";
					$rows=$callConfig->getRow($sql);
					$reportid  = $rows->reports_to;
				}else{
					$sql = "select reports_to from application_users where is_active = 0 and company_id = '".$data['company_id']."' and id='".$reportid."'";
					$rows=$callConfig->getRow($sql);
					$reportid  = $rows->reports_to;
				}
			}
			$reporttolist['nextstepuid'][] = $reportid!=""?$reportid:"404";
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'buddy'){
			$reporttolist['nextstepuid'][] = $this->findbuddyid($checkcriteria,$data);
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'individual_employee_role'){
			$empdata = "select user_id from employees where role_id=".$checkcriteria['workflow_configuration']->sub_approve_type." and is_active='0' and company_id = '".$data['company_id']."'"; 
			$row=$callConfig->getAllRows($empdata);
			foreach($row as $ro){
				$reporttolists[] = $ro->user_id;
			}
			$reporttolist['nextstepuid'] =  $reporttolists;
		}elseif($checkcriteria['workflow_configuration']->approval_type == 'email_groups'){
			$emailgroup = "SELECT e.user_id FROM `email_group_emails` ege left JOIN email e on ege.email_id=e.id WHERE ege.email_groups_id =".$checkcriteria['workflow_configuration']->sub_approve_type." and ege.is_active='0' and ege.company_id = '".$data['company_id']."' "; 
			$emailgrouprows=$callConfig->getAllRows($emailgroup);
			foreach($emailgrouprows as $emailgrouprows){
				$reporttolists[] = $emailgrouprows->user_id;
			}
			$reporttolist['nextstepuid'] =  $reporttolists;
		}
		//$returns['reportto'] =  (isset($data['level']) AND $data['level']!="")?$reporttolist[$data['level']-1]:$reporttolist;
		$returns =  $reporttolist;
	//print_r($returns);
		return $returns;
	}else{
		return array("status"=>"404");
	}



}
function startWorkFlow($data){
	global $callConfig;
	$retrunarry = array();
	$details = $this->getStatusWorkFlow($data);
	$statuse = json_decode($details['workflow_configuration']->approve_update_status,1);
		//$transaction_message = json_decode($details['workflow_configuration']->transaction_message,1);
	$getstaturow = $data['level']-1; 
	$changestatus = $statuse[$getstaturow];
		//[rid] => 1 [level] => 1 [tablename] => emp_expenses [user_id] => 1 [company_id] => 1
	if(isset($details['workflow_configuration']->id) AND $details['nextstepuid']!=""){
			if($statuse[0]['work_flow_field'] !=""){ //this sttaus field name get resion used -1
				$data['table'] = $data['tablename'];
				$getfiledid = $this->workFlowFieldId($statuse[0],$data);
				$details['nextstepuid'] = array($getfiledid[$statuse[0]['work_flow_field']]);
			}else{
				$hrurl = "SELECT reports_to FROM application_users WHERE id = '".$data['user_id']."'";
				$datareportid = $callConfig->getRow($hrurl);
			}
			$aprlog = array('rid'=>$data['rid'],'userid'=>$details['nextstepuid'],'tablename'=>$data['tablename'],'workflow_id'=>$details['workflow_configuration']->id,'status'=>$changestatus['status']);
			$retrunarry['log'][]  = $aprlog;
			$insertlogandnotification = $this->insertTransactionApprovalLogs($aprlog,$data,$details);
			$retrunarry['nofiti'][]  = $insertlogandnotification;
		}else{
			$retrunarry['error'] = "404";
		}
		return $retrunarry;
	}
