	$post = array();
	$post['multiinvite'] = "Y";
	$post['company_id'] = $get['company_id'];
	$post['user_id'] = $get['user_id'];
	$post['first_name'][] = $empdata->first_name;
	$post['user_email'][] = $empdata->email_id;
	$post['user_name'][] =$empdata->emp_code;
	$post['last_name'][] =$empdata->last_name;
	$post['display_name'][] =$empdata->display_name;
	$post['role_id'][] =array($get['role_id']);
	$post['user_mobile'][] =$empdata->phone;
	$post['user_type'][] ='1';
