function getEmployeeWorkingEntrys($get){
	global $callConfig;
	$emp_list = json_decode($get['emplist'],1);
	$discrepancy = array();
	$month = $get['month'];
	$year = $get['year'];
	$shift_check = SHIFT_CHECK; //1 meaning yes
	$slctdate = date($get['year']."-".$get['month']."-".$get['monthstartday']);
	$startdate = date("Y-m-d",strtotime($slctdate));
	$enddate = date("Y-m-d",strtotime("+1 month",strtotime($slctdate)));  
	$enddate = date("Y-m-d", strtotime("-1 days", strtotime($enddate)));
	$retrunarray = array();
	if(empty($emp_list)){
		$query="SELECT id,display_name,image,emp_code,location_id  FROM `employees` WHERE company_id = '".$get['company_id']."' AND employee_type = 2 AND joining_date <= '".$enddate."' AND emp_code IS NOT NULL AND (date_of_leaving >= '".$startdate."' OR date_of_leaving IS NULL)";
	}else{
		$liemp =implode(",",(array)$emp_list);
		$query="SELECT id,display_name,image,emp_code,location_id  FROM `employees` WHERE company_id = '".$get['company_id']."' AND employee_type = 2 AND joining_date <= '".$enddate."' AND  emp_code IS NOT NULL AND (date_of_leaving >= '".$startdate."' OR date_of_leaving IS NULL) AND id IN(".$liemp.")";
	}
	$empdatas = $callConfig->getAllRows($query);
	foreach ($empdatas as $value) {
		$empidlist[$value->id] = array('display_name'=>$value->display_name,'image'=>$value->image,'location_id'=>$value->location_id,'emp_code'=>$value->emp_code);
	}
	$attstc = "SELECT * FROM attendance_settings WHERE is_active=0 and company_id=".$get['company_id'];
	$atsdata = $callConfig->getRow($attstc);
	$workingdays = json_decode($atsdata->working_days,1);
	$shiftkeys = "SELECT * FROM attendance_key_types WHERE is_active=0 and company_id=".$get['company_id'];
	$shiftkeysdata = $callConfig->getAllRows($shiftkeys);
	foreach ($shiftkeysdata as $skey=>$svalue) {
		$shift[$svalue->key_short_code] = (array)$svalue;
	}
	$holidays = "SELECT holiday_date,location_id FROM holidays WHERE is_active=0 and company_id=".$get['company_id']." AND MONTH(holiday_date) = '".$month."' AND YEAR(holiday_date) = '".$year."' AND holiday_year =".$year;
	$holidaysdata = $callConfig->getAllRows($holidays); //holidays
	foreach ($holidaysdata as $hkey=>$hvalue) {
		$holidaysdatas[$hvalue->location_id][] = $hvalue->holiday_date;
	}
	$min_working_hours = explode(":", $atsdata->minimum_hours_required);
	$half_working_hours = explode(":", $atsdata->half_day_hours);
	$i = 0;
	$timeshetetrys = array();
	$timeshettempoyee = array();
	$sql = "SELECT GROUP_CONCAT(id SEPARATOR ',') AS id,timesheet_date,SUM(billable_hrs) as billable_hrs,emp_id FROM `project_timesheets` WHERE company_id = '".$get['company_id']."' and is_active = 0  and timesheet_date >= '".$startdate."' and timesheet_date <= '".$enddate."' GROUP BY timesheet_date,emp_id";
	$timesheets = $callConfig->getAllRows($sql);
	foreach($timesheets as $timesheet){
		if($timesheet->billable_hrs > '0'){
			if($timesheet->billable_hrs < $min_working_hours[0]){
				$discrepancy[$timesheet->emp_id] = $timesheet->emp_id;
			}
			$timeshettempoyee[$timesheet->emp_id][$timesheet->timesheet_date] = array("id"=>$timesheet->id,"timesheet_date"=>$timesheet->timesheet_date,"billable_hrs"=>$timesheet->billable_hrs,"emp_id"=>$timesheet->emp_id);
		}
	}
	$leavessql = "select employee_id,leave_from,leave_to,leave_type_id,start_half_day,end_half_day,datelist 
	from employee_leaves, 
	(select adddate('1970-01-01',t4.i*10000 + t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) datelist from
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t4) as v
	where datelist>=leave_from and datelist <=leave_to AND ((MONTH(leave_from) = '".$month."' AND YEAR(leave_from) = '".$year."') OR (MONTH(leave_to) = '".$month."' AND YEAR(leave_to) = '".$year."') )";
 	$leavesdetails = $callConfig->getAllRows($leavessql); // working //absent
 	foreach ($leavesdetails as $leavesdetail) {
 		$leavesdetailsarray[$leavesdetail->employee_id][$leavesdetail->datelist] = array('type'=>$leavesdetail->leave_type_id,'start_half_day'=>$leavesdetail->start_half_day,'end_half_day'=>$leavesdetail->end_half_day);
 	}
 	foreach($empidlist as $ky => $emp){
 		$start = new DateTime($startdate);
 		$end = new DateTime($enddate);
 		$dates = array();
 		while($start <= $end){
 			$date = $start->format('Y-m-d');
 			$dy = $start->format('l');
 			if(in_array($date,(array)$holidaysdatas[$emp['location_id']])){
 				$dates[$date] = array('day'=>'H','date'=>$date,'billable_hrs'=>$timeshettempoyee[$ky][$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$ky][$date]['id'],'color_code'=>$shift['H']['color_code']);
 			}elseif(!in_array($dy, (array)$workingdays)){
 				$dates[$date] = array('day'=>'O','date'=>$date,'billable_hrs'=>$timeshettempoyee[$ky][$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$ky][$date]['id'],'color_code'=>$shift['O']['color_code']);
 			}elseif(isset($timeshettempoyee[$ky][$date])){
 				$dates[$date] = array('day'=>'W','date'=>$date,'billable_hrs'=>$timeshettempoyee[$ky][$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$ky][$date]['id'],'color_code'=>$shift['W']['color_code']);
 			}else{
 				if(isset($leavesdetailsarray[$ky][$date])){  
 					if($leavesdetailsarray[$ky][$date]['type'] == '6'){
 						$dates[$date] = array('day'=>'S','date'=>$date,'billable_hrs'=>$timeshettempoyee[$ky][$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$ky][$date]['id'],'color_code'=>$shift['S']['color_code']);
 					}else{
 						$dates[$date] = array('day'=>'V','date'=>$date,'billable_hrs'=>$timeshettempoyee[$ky][$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$ky][$date]['id'],'color_code'=>$shift['V']['color_code']);
 					}
 				}else{
 					$dates[$date] = array('day'=>'A','date'=>$date,'billable_hrs'=>$timeshettempoyee[$ky][$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$ky][$date]['id'],'color_code'=>$shift['A']['color_code']);
 				}
 			}
 			if($i=='0'){
 				$alldate[]  = $date; 
 			}	
 			$start->modify('+1 days');
 		}
 		$timeshetetrys[$ky] = $dates;
 		$i++;
 	}
 	$retrunarray['discrepancy'] = $discrepancy;
 	$retrunarray['timesheet'] = $timeshetetrys;
 	$retrunarray['date'] = $alldate;
 	$retrunarray['emplist'] = $empidlist;
 	$retrunarray['min_working_hours'] = $min_working_hours[0];
 	$retrunarray['min_working_hours_full'] = $atsdata->minimum_hours_required;
 	$retrunarray['half_working_hours'] = $half_working_hours[0];
 	return $retrunarray;
 }
