/*-------
	PF calucation 
	BASIC+DA+OA  <15000
		Yes		
			BASIC+DA+OA  *12%
		NO
			15000*12%
----------------- */
function tocalucalteepf($code_data,$val,$list=""){
	global $callConfig;
	$basic = $code_data['BASIC'];
	$da = $code_data['DA']!=""?$code_data['DA']:'0';
	$basicda = $basic+$da;
	$basic_faormula = "(BASIC+DA)*".$val."%";
	$basic_amount = $basicda;
	$cackval = $list->condition_limit;
	$basicsp = $cackval;
	if($basicda<=$cackval ){
		$sa = $code_data['OA'];
		$basicsp = $basic+$sa;
		if($basicsp<=$cackval ){
			$basic_amount = $basicsp;
			$basic_faormula = "(BASIC+OA)*".$val."%";
			$month_amount = ($basicsp*$val)/100;
		}else{
			$basic_amount = $cackval ;
			$basic_faormula = "(".$cackval .")*".$val."%";
			$month_amount = ($cackval *$val)/100;
		}
	}else{
		$month_amount = ($cackval *$val)/100;
	}
	$return = array('basic_amount'=>$basicsp,'cal_formula'=>$basic_faormula,'amount'=>$month_amount);  
	return $return;         
}
function tocalucaltesi($code_data,$val,$catcode,$type,$mon_code_data="",$pass_esi_val=""){
	global $callConfig;

	/*echo "<pre>step:1";
	print_r($code_data);
	echo "step:2";
	echo print_r($val); echo "step:3";
	print_r($catcode); echo "step:4";
	echo $type; echo "step:5";
	print_r($mon_code_data);*/

	$catlink_value = $pass_esi_val[$catcode];               
	$catlink_esvv = $val;
	$catlink_vv = $catlink_esvv[$type];
	$basic_amount = $catlink_value;
	$catlink_esvv['check_value'] = $catlink_esvv['check_value']!=""?$catlink_esvv['check_value']:21000;
	//echo  "GS:".$catlink_esvv['check_value']."cate:".$type."check_vale".$catlink_esvv['check_value']; 
	if( $catlink_esvv['check_value'] >= $catlink_value){
		if($catlink_value>0){
			$month_amount = ($catlink_value*$catlink_vv)/100;
		}else{
			$month_amount =  ($code_data['PAY_CTC']-$code_data['PF'])*((4/104)*($catlink_vv/4));
		}
		
		$basic_faormula = $catcode."*".$catlink_vv."%";
	}else{
		$month_amount =0;
	}
	$return = array('basic_amount'=>$basic_amount,'cal_formula'=>$basic_faormula,'amount'=>$month_amount); 
	//print_r($return) ; exit;
	return $return; 
}
function tocalucaltSPA($code_data){
	global $callConfig;
	//print_r($code_data) ;
    $basic = isset($code_data['BASIC']) ? $code_data['BASIC'] :0;
    $hra =   isset($code_data['HRA']) ? $code_data['HRA'] :0;
    $lta = 	isset($code_data['LTA']) ? $code_data['LTA'] :0;
    $bn = isset($code_data['BONUS']) ? $code_data['BONUS'] :0;
    $pf = isset($code_data['PF']) ? $code_data['PF'] :0;
    $esi = isset($code_data['ESI']) ? $code_data['ESI'] :0;
    $gt = isset($code_data['GRATUITY']) ? $code_data['GRATUITY'] :0;
    $mp = isset($code_data['MIP']) ? $code_data['MIP'] :0;
    $pc = isset($code_data['PAY_CTC']) ? $code_data['PAY_CTC'] :0;
    $sb = $basic+$hra+$lta+$bn+$pf+$esi+$gt+$mp;
    $cal_formula = "ctc-(basic+hra+lta+bn+pf+esi+gt+mp)";
    $month_amount = $pc-$sb;
	$return = array('basic_amount'=>$sb,'cal_formula'=>$cal_formula,'amount'=>$month_amount); 
	//print_r($return) ; echo "TTTTTTTTTTTT"; exit; 
	return $return;  
}

function tocalucaltPTX($code_data,$val,$catcode,$month,$pass_esi_val=""){
	global $callConfig;            
	/*echo "<pre>step:1";
	print_r($code_data);
	echo "step:2";
	echo print_r($val); echo "step:3";
	print_r($catcode); echo "step:4";
	echo $month; 
	print_r($month); */
	if(isset($pass_esi_val[$catcode])){
		$catlink_value = $pass_esi_val[$catcode];
	}else{
		$catlink_value = $code_data[$catcode];
	}
	
	$catlink_esvv = json_decode($val,1);
	for($i=0; $i<count((array)$catlink_esvv); $i++){
		$checks = $catlink_esvv[$i];
		if($checks['start_range']<$catlink_value && $checks['end_range']>$catlink_value){
                //$month_amount = $checks['tax_amount'];
			$month_amount = $checks['months'][intval($month)];
			break;
		}
	} 
	$return = array('basic_amount'=>$catlink_value,'cal_formula'=>$basic_faormula,'amount'=>$month_amount); 
	//print_r($return) ; exit; 
	return $return;  
}
function calucalationsum($item1,$item2,$option){
	$res ="0";
	if($option=='+'){ $res = $item1+$item2; }
	if($option=='-'){ $res = $item1-$item2; }
	if($option=='*'){ $res = $item1*$item2; }
	if($option=='/'){ $res = $item1/$item2; }
	return  $res;
}

function insertCheckPayRoll($post){
	global $callConfig;
	$ret = array();
	$checkavlsql = "SELECT id FROM `payroll_steps` WHERE company_id = '".$post['company_id']."' AND category_id = '".$post['id']."' AND pay_year = '".$post['year']."' AND pay_month = '".$post['month']."'";
	$check = $callConfig->getRow($checkavlsql);
	if(!isset($check->id)){
		$insert_array = array('company_id'=>$post['company_id'],'current_status'=>'0','is_active'=>'0','category_id'=>$post['id'],'pay_year'=>$post['year'],'pay_month'=>$post['month']);
		$insert = $callConfig->insertRecord('payroll_steps',$insert_array);
		$ret['insert'] =$insert;
	}
	$checktotal  = "SELECT COUNT(id) as num FROM `payroll_steps` WHERE company_id = '".$post['company_id']."' AND pay_year = '".$post['year']."' AND pay_month = '".$post['month']."'";
	$totalcheck  = $callConfig->getRow($checktotal);
	$ret['check'] = $totalcheck->num;
	return $ret;
}
