function getEmployeeCTCReports($get){
	global $callConfig;
	$pay_year = $get['pay_year'];
	$pay_month = $get['pay_month'];
	$sqql="SELECT emp.id,emp.emp_code,
	CONCAT(emp.first_name,' ',COALESCE(emp.middle_name,''),' ' ,emp.last_name) 'Employee Name',
	emp.joining_date 'DOJ',
	(
	SELECT dept.department_name
	FROM departments dept
	WHERE dept.id = emp.department_id
	AND dept.company_id = emp.company_id
) 'Department',
(
	SELECT de.designation_name
	FROM designations de
	WHERE de.id = emp.designation_id
	AND de.company_id = emp.company_id
)'Designation',
(
	SELECT loc.location_name
	FROM locations loc
	WHERE loc.id = emp.location_id
	AND loc.company_id = emp.company_id
)'Location',
emp.email_id,
(
	SELECT name
	FROM earnings ear
	WHERE ear.id = prsc.component_id
	AND ear.company_id = prsc.company_id
)'name',
prs.total_no_of_days 'Total Days',
prs.total_no_of_leaves 'Leaves',
prs.total_lop_days 'LWPs',
prs.total_no_of_working_days 'Working Days',
IF(IFNULL( prs.total_lop_days,0) = prs.total_no_of_working_days , 0,  (prs.total_no_of_days - IFNULL( prs.total_lop_days,0))) 'Payable Days',
prsc.salary_component_standard,
prsc.salary_component_actual,
prsc.base_amount
FROM employees emp,
pay_run_summary prs,
pay_run_summary_components prsc
WHERE emp.id = prs.employee_id
AND emp.company_id = prs.company_id
AND prs.id = prsc.pay_run_summary_id
AND prs.company_id = prsc.company_id
AND prs.is_active = 0
AND prs.pay_year = '".$pay_year."' 
AND prs.pay_month = '".$pay_month."'
ORDER BY emp.joining_date,
emp.display_name";
$result = $callConfig->getAllRows($sqql);
$ret =array();
foreach($result as $results){
	$ret1[] = $results->name;
	$ret[$results->id][] = $results;
}
$return = array("componant"=>array_unique($ret1),"list"=>$ret);
return $return;
}



