	$d2=new DateTime($date1);                                  
	$Months = $d2->diff($d1); 
	$howeverManyMonths = (($Months->y) * 12) + ($Months->m);*/
	$date1 = $get['pay_year']."-04-01";
	$datef = strtotime($date1);
	for($i=1;$i<=12;$i++){	
		$year = date("Y",$datef);
		$month = date("m",$datef);
		$employee_list_query= "SELECT pay_area_id, sum(salary_component_actual) sumpt,count(id) as emp FROM `pay_run_summary_components` WHERE pay_year = '".$year."' AND  pay_month = '".$month."'  AND is_active = 0 and company_id = '".$get['company_id']."' AND component_code = '".$get['component_code']."'";
		$employee_list = $callConfig->getAllRows($employee_list_query);
		$show_date = date('d-m-Y',$datef);
		$return[$show_date] =  $employee_list;
		$datef = strtotime("+".$i." month", strtotime($date1));
	}
	$query = "SELECT min(`pay_year`) pay_year FROM `payroll` WHERE company_id =".$get['company_id']." AND is_active = 0";
	$payyear = $callConfig->getRow($query);
	$pay_areas = $callConfig->getAllRows("SELECT id, name FROM pay_areas WHERE company_id='".$get['company_id']."' AND is_active=0");
	return array('data'=>$return,'pay_year'=>$payyear->pay_year,'pay_areas'=>$pay_areas);
}

function insertapplicationtours($data){ 
	global $callConfig;
	$data['application_table_name'] = $data['application_table_name']=="-1"?$data['table_name_txt']:$data['application_table_name'];
	foreach($data['field_name'] as $key=>$value){
		$displaystatus = (isset($data['display'][$key]))?"1":"2"; 
		if($data['rid'][$key] != ""){
			$remove_array = array('application_module'=>$data['application_module'],'help_text'=>$data['help_text'][$key],'menu_path'=>$data['menu_path'][$key],'field_name'=>$data['field_name'][$key],'reference_field_name'=>$data['reference_field_name'][$key],'field_type'=>$data['field_type'][$key],'sequence'=>$data['sequence'][$key],'display'=>$displaystatus,'updated_by'=>$post['user_id'],'updated_date'=>date("Y-m-d H:i:s"));
			$where = "id = '".$data['rid'][$key]."'";
			$res=$callConfig->updateRecord("application_tours",$remove_array,"","",$where);
			$return[] = $res;
		}else{
			$insert_array = array('application_module'=>$data['application_module'],'company_id'=>$data['company_id'],'application_table_name'=>$data['application_table_name'],'help_text'=>$data['help_text'][$key],'menu_path'=>$data['menu_path'][$key],'field_name'=>$data['field_name'][$key],'reference_field_name'=>$data['reference_field_name'][$key],'field_type'=>$data['field_type'][$key],'sequence'=>$data['sequence'][$key],'display'=>$displaystatus,'created_by'=>$post['user_id'],'created_date'=>date("Y-m-d H:i:s"));	
			$approval_id=$callConfig->insertRecord('application_tours',$insert_array);
			$return[] = $approval_id;
		}
	}
	return $return;
}
