/********************** Tickets Start****************************************/
function insertTickets($post){
	global $callConfig;
	$inserts_task=array('company_id'=>$post['company_id'],'project_id'=>$post['popupproject_id'],'task_name'=>$post['pouptask_name'],'description'=>$post['popupdescription'],'client_id'=>$post['popupcreated_by'],'priority'=>$post['popuppriority'],'follower_ids'=>$post['popupfollow_id']);
	if($post['popuprid']!=""){
		$inserts_task['updated_date'] = date('Y-m-d H:i:s');
		$inserts_task['updated_by'] = $post['user_id'];
		$res=$callConfig->updateRecord('project_tasks',$inserts_task,'id',$post['popuprid']);
		if(isset($post['fila']['filename'])){
			$insert_array = array('company_id'=>$post['company_id'],'current_status'=>'0','is_active'=>'0','file_name'=>$post['fila']['originalname'],'actual_file_name'=>$post['fila']['filename'],'file_size_mb'=>$post['fila']['filesize'],'application_table_name'=>'project_tasks','transaction_id'=>$post['popuprid'],'is_active' =>'0');
			$fileup = $callConfig->insertRecord('application_attachments',$insert_array);
		}
	}else{
		$inserts_task['is_active'] = '0';
		$inserts_task['current_status'] = '2';
		$inserts_task['created_date'] = date('Y-m-d H:i:s');
		$inserts_task['created_by'] = $post['user_id'];
		$inserts_task['client_id'] = $post['popupcreated_by'];
		$transation = $this->toGetApplicationSerialNumber('bills',$post);
		$inserts_task['ticket_id'] = $transation;
		$res=$callConfig->insertRecord('project_tasks',$inserts_task);
		if(isset($post['fila']['filename'])){
			$insert_array = array('company_id'=>$post['company_id'],'current_status'=>'0','is_active'=>'0','file_name'=>$post['fila']['originalname'],'actual_file_name'=>$post['fila']['filename'],'file_size_mb'=>$post['fila']['filesize'],'application_table_name'=>'project_tasks','transaction_id'=>$res['LASTID'],'is_active' =>'0');
			$fileup = $callConfig->insertRecord('application_attachments',$insert_array);
		}	
	}
	return $res;
}
