function updateTicketDetails($post){
	global $callConfig;	
	$condition ="";
	if($post['filed_name'] == 'emp_id'){
		$appv_fieldnames=array('response_date'=>date("Y-m-d H:i:s"),'response_type'=>ST_INPROGRESS);
		$whrs = "transaction_table = 'project_tasks' AND transaction_id='".$post['id']."'";
		$ress=$callConfig->updateRecord(TBL_TRANSACTION_APPROVAL_LOGS,$appv_fieldnames,'','',$whrs);
		$condition .= " ,`current_status`='".ST_INPROGRESS."'";
		$inserttransactionapprovelog =array('company_id'=>$post['company_id'],'module_setup_id'=>$callConfig->module_id,'transaction_table'=>'project_tasks','transaction_id'=>$post['id'],'response_type'=>'','user_id'=>$post['uid'],'request_date'=>date("Y-m-d H:i:s"));
		$ress=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);
		$msg = "Project Tasks ".$post['id']." : Resolve this issue.";
		$user_ids  = array($post['uid']);
		$option = "COM_LIST_TICKETS";
		$notdataa = array('company_id'=>'1', 'notification_message'=>$msg, 'id'=>$post['id'],'application_table_name'=>'project_tasks', 'type'=>'ACTION', 'notification_users'=>$user_ids,'option'=>$option);
		$sendnotification = $this->tosendnotifiations($notdataa);	 
	}
	$updatequery =  "UPDATE `project_tasks` SET ".$post['filed_name']." = '".$post['value']."',`updated_by`='".$post['user_id']."',`updated_date`='".date('Y-m-d H:i:s')."' ".$condition." WHERE id = '".$post['id']."'";
	$res=$callConfig->executeQuery($updatequery);
	return $res;
}


function insertProjectTaskLogs($post){
	global $callConfig;
	$logarray=array('company_id'=>$post['company_id'],'project_task_id'=>$post['rid'],'user_id'=>$post['user_id'],'description'=>$post['description'],'is_active'=>'0','current_status'=>'0','created_date'=> date('Y-m-d H:i:s'),'created_by'=>$post['user_id']);
	$res = $callConfig->insertRecord('project_task_logs',$logarray);
	foreach($post['fila'] as $key=>$valu){
		if($valu['filename'][$key] !=""){
