function getEmployeeTickets($data){
	global $callConfig;	
	$returnresul = array();
	$condition = "";
	if($data['emp_id']!=""){  $condition .= " AND emp_id = '".$data['emp_id']."'";}
	if($data['priority']!=""){ $condition .=  " AND priority = '".$data['priority']."'";  }
	if($data['current_status']!="" AND isset($data['current_status'])){ $condition .=  " AND current_status = '".$data['current_status']."'"; }
	if($data['filterfromdate']!="" AND $data['filtertodate']!=""){ $condition .=  " and created_date >= '".$data['filterfromdate']."' and created_date <= '".$data['filtertodate']."'"; }
	if($data['field']!="" AND $data['field'] !="emp_id" AND $data['user_id']!=""){ 
		$condition .=  " AND ".$data['field']." = '".$data['user_id']."'";
	}
	if($data['field']=="emp_id"){
		$condition .=  " AND (".$data['field']." = '".$data['user_id']."' OR FIND_IN_SET('".$data['user_id']."', follower_ids))"; 
	}

	
	if($data['notdisplaycurrent_status']!=""){ 
		$condition .=  " AND (current_status  >'".$data['notdisplaycurrent_status']."' OR created_by= '".$data['user_id']."')";
	}
	$query2 = "SELECT * FROM project_tasks WHERE is_active=0 AND company_id = '".$data['company_id']."' ".$condition;
	$res = $callConfig->getAllRows($query2);
	$returnresul['sql'] = $query2;
	$returnresul['tickets'] = $res;
	$dashboardsql = "SELECT id,task_name,current_status FROM project_tasks WHERE is_active=0 AND company_id = '".$data['company_id']."'";
	$dashboardres = $callConfig->getAllRows($dashboardsql);
	$returnresul['dashboard'] = $dashboardres;
	return $returnresul;
}
function getViewTicketDetails($data){
	global $callConfig;	
	$query2 = "SELECT * FROM project_tasks WHERE is_active=0 AND company_id = '".$data['company_id']."' AND id='".$data['id']."'";
	$res = $callConfig->getRow($query2);
	$retresult['tasklist'] = $res;
	$employeesql = "SELECT id,display_name,image FROM employees WHERE is_active=0 AND company_id = '".$data['company_id']."' AND id='".$res->emp_id."'";
	$employeeres = $callConfig->getRow($employeesql);
	$retresult['employee'] = $employeeres;
	$usersql = "SELECT id,display_name,user_photo FROM application_users WHERE is_active=0 AND company_id = '".$data['company_id']."' AND id='".$res->client_id."'";
	$userres = $callConfig->getRow($usersql);
	$retresult['users'] = $userres;
	$usersql1 = "SELECT id,display_name,user_photo FROM application_users WHERE is_active=0 AND company_id = '".$data['company_id']."'";
	$userres1 = $callConfig->getAllRows($usersql1);
	foreach($userres1 as $userres1){
		$userary[$userres1->id] = $userres1;
	}
	$retresult['users_list'] = $userary;
	$attachmentsql = "SELECT id,file_name,actual_file_name FROM application_attachments WHERE is_active=0 AND company_id = '".$data['company_id']."' AND application_table_name='project_tasks' AND transaction_id='".$data['id']."'";
	$attachmentres = $callConfig->getAllRows($attachmentsql);
	$retresult['application_attachments'] = $attachmentres;
	$projecttasklogssql = "SELECT id,project_task_id,user_id,description,created_date FROM project_task_logs WHERE is_active=0 AND company_id = '".$data['company_id']."' AND project_task_id='".$data['id']."'";
	$projecttasklogsres = $callConfig->getAllRows($projecttasklogssql);
	foreach($projecttasklogsres as $projecttasklogsre){
		$logs['logsdetails'][$projecttasklogsre->id] = $projecttasklogsre;
		$attachmentsqls = "SELECT id,file_name,actual_file_name FROM application_attachments WHERE is_active=0 AND company_id = '".$data['company_id']."' AND application_table_name='project_task_logs' AND transaction_id='".$projecttasklogsre->id."'";
		$attachmentress = $callConfig->getAllRows($attachmentsqls);
		$logs['attachment'][$projecttasklogsre->id] = $attachmentress;

	}
	$retresult['logs'] = $logs;
	return $retresult;
}
