function getLitsAttendancesApi($get){
	global $callConfig;
	$empidlist = array($get['emp_id']=>$get['emp_id']);
	$month = $get['month'];
	$year = $get['year'];
	$attstc = "SELECT * FROM attendance_settings WHERE company_id=".$get['company_id']." AND is_active=0";
	$atsdata = $callConfig->getRow($attstc);
	$workingdays = json_decode($atsdata->working_days,1);
	
	$shiftkeys = "SELECT * FROM attendance_key_types WHERE company_id=".$get['company_id']." AND is_active=0";
	$shiftkeysdata = $callConfig->getAllRows($shiftkeys); // working //absent
	foreach ($shiftkeysdata as $skey=>$svalue) {
		$shift[$svalue->key_short_code] = (array)$svalue;
	}

	$attendancesql = "SELECT *  FROM `employee_daily_attendances` WHERE company_id=".$get['company_id']." AND employee_id='".$get['emp_id']."' AND  (attendace_date >= concat('".$year."-".$month."-01') AND attendace_date <= last_day(concat('".$year."-".$month."-01'))) AND is_active=0";
	$attendanceres = $callConfig->getAllRows($attendancesql); // working //absent
	foreach ($attendanceres as $attendancere) {
		$attendacnearray[$attendancere->employee_id][$attendancere->attendace_date] = $attendancere;
	}
	//print_r($attendacnearray);
	$leavessql = "select employee_id,leave_from,leave_to,leave_type_id,start_half_day,end_half_day,datelist 
	from employee_leaves, 
	(select adddate('1970-01-01',t4.i*10000 + t3.i*1000 + t2.i*100 + t1.i*10 + t0.i) datelist from
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t0,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t1,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t2,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t3,
	(select 0 i union select 1 union select 2 union select 3 union select 4 union select 5 union select 6 union select 7 union select 8 union select 9) t4) as v
	where datelist>=leave_from and datelist <=leave_to AND employee_id = '".$get['emp_id']."' AND ((MONTH(leave_from) = '".$month."' AND YEAR(leave_from) = '".$year."') OR (MONTH(leave_to) = '".$month."' AND YEAR(leave_to) = '".$year."') )";
 	$leavesdetails = $callConfig->getAllRows($leavessql); // working //absent
 	foreach ($leavesdetails as $leavesdetail) {
 		$leavesdetailsarray[$leavesdetail->employee_id][$leavesdetail->datelist] = array('type'=>$leavesdetail->leave_type_id,'start_half_day'=>$leavesdetail->start_half_day,'end_half_day'=>$leavesdetail->end_half_day);
 	}
 	$holidays = "SELECT holiday_date FROM holidays WHERE company_id=".$get['company_id']." AND MONTH(holiday_date) = '".$month."' AND YEAR(holiday_date) = '".$year."' AND is_active=0 ";
	$holidaysdata = $callConfig->getAllRows($holidays); //holidays
	foreach ($holidaysdata as $hkey=>$hvalue){
		$holidaysdatas[] = $hvalue->holiday_date;
	}
	$min_working_hours = explode(":", $atsdata->minimum_hours_required);
	$half_working_hours = explode(":", $atsdata->half_day_hours);
	//$slctdate = date($get['year']."-".$get['month']."-".$get['monthstartday']);
	$enterdate = date("Y-m-d");
	if($get['reprt_type']=="W"){
		$startdate = date("Y-m-d", strtotime('monday this week', strtotime($enterdate))); 
		$enddate= date("Y-m-d", strtotime('sunday this week', strtotime($enterdate)));
	}elseif($get['reprt_type']=="M"){
		$startdate = date("Y-m"."-01",strtotime($enterdate)); 
		$enddate = date("Y-m-t",strtotime($enterdate));  
	}else{
		$startdate = $enterdate; 
		$enddate =  $enterdate;   
	}
	$timeshetetrys = array();
	$i = 0;
	foreach($empidlist as $ky => $emp){
		$monthworkingdays = 0;
		$actualworkingdays = 0;
		$start = new DateTime($startdate);
		$end = new DateTime($enddate);
		$dates = array();
		$timeshettempoyee = array();
		$retrunarray['valuedisplaytype'] = "update";
		while($start <= $end){
			$date = $start->format('Y-m-d');
			$dy = $start->format('l');
			if(in_array($date,(array)$holidaysdatas)){
				$dates[$date] = array('day'=>'H','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['H']['color_code'],'display_value'=>$shift['H']['display_value'],'key_name'=>$shift['H']['key_name'],'key_bgcolor'=>$shift['H']['key_bgcolor']);
			}elseif(!in_array($dy, (array)$workingdays)){
				$dates[$date] = array('day'=>'O','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['O']['color_code'],'display_value'=>$shift['O']['display_value'],'key_name'=>$shift['O']['key_name'],'key_bgcolor'=>$shift['O']['key_bgcolor']);
			}elseif(isset($attendacnearray[$ky][$date]) AND isset($leavesdetailsarray[$ky][$date])){
				$dates[$date] = array('day'=>'V','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['V']['color_code'],'display_value'=>$shift['V']['display_value'],'strthalfday'=>$tempdetailary[$ky][$date]['start_half_day'],'endthalfday'=>$tempdetailary[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code'],'key_name'=>$shift['V']['key_name'],'key_bgcolor'=>$shift['V']['key_bgcolor']);
				$discrepancy[$ky] = $emp;
				$monthworkingdays++;
				$actualworkingdays++;
			}elseif(isset($attendacnearray[$ky][$date])){
				$monthworkingdays++;
				$actualworkingdays++;
				$dates[$date] = array('day'=>'W','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['W']['color_code'],'display_value'=>$shift['W']['display_value'],'start'=>$attendacnearray[$ky][$date]->clock_in,'end'=>$attendacnearray[$ky][$date]->clock_out,'key_name'=>$shift['W']['key_name'],'key_bgcolor'=>$shift['W']['key_bgcolor']);
			}else{
				if(isset($leavesdetailsarray[$ky][$date])){
					$monthworkingdays++;
					$actualworkingdays++;
					if($leavesdetailsarray[$ky][$date]['type'] == '6'){
						$dates[$date] = array('day'=>'S','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['S']['color_code'],'display_value'=>$shift['S']['display_value'],'strthalfday'=>$leavesdetailsarray[$ky][$date]['start_half_day'],'endthalfday'=>$leavesdetailsarray[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code'],'key_name'=>$shift['W']['key_name'],'key_bgcolor'=>$shift['W']['key_bgcolor']);
						$discrepancy[$ky] = $emp;
					}else{
						$dates[$date] = array('day'=>'V','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['V']['color_code'],'display_value'=>$shift['V']['display_value'],'strthalfday'=>$tempdetailary[$ky][$date]['start_half_day'],'endthalfday'=>$tempdetailary[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code'],'key_name'=>$shift['W']['key_name'],'key_bgcolor'=>$shift['W']['key_bgcolor']);
						$discrepancy[$ky] = $emp;
					}
				}else{
					$monthworkingdays++;
					$dates[$date] = array('day'=>'A','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['A']['color_code'],'display_value'=>$shift['A']['display_value'],'key_name'=>$shift['A']['key_name'],'key_bgcolor'=>$shift['A']['key_bgcolor']);
					$discrepancy[$ky] = $emp;
				}
			}
			if($i=='0'){
				$alldate[]  = $date; 
			}	
			$start->modify('+1 days');
		}
	}
	// $retrunarray['monthworkingdays'] = $monthworkignday;
	// $retrunarray['actualworkingdays'] = $actualworkingday;
	// $retrunarray['discrepancy'] = $discrepancy;
	$retrunarray['timesheet'] = $dates;
	//$retrunarray['date'] = $alldate;
	$retrunarray['emplist'] = $empidlist;
	return $retrunarray;
}


function getLeaveWithStatus($data){
	global $callConfig;
	$return =array();
	$emp_listtsql = "SELECT emp.id,emp.emp_code,emp.display_name,emp.image,( SELECT department_name FROM `departments` dep WHERE dep.is_active=emp.is_active AND dep.company_id = emp.company_id AND dep.id = emp.department_id ) department_name,( SELECT designation_name FROM `designations` des WHERE des.is_active=emp.is_active AND des.company_id = emp.company_id AND des.id = emp.designation_id ) designation_name  FROM `employees` emp where emp.is_active='0' AND  emp.company_id = '".$data['company_id']."'";
	$emp_listtlist=$callConfig->getAllRows($emp_listtsql);
	foreach($emp_listtlist as $emp_listtlist){
		$emp_list[$emp_listtlist->id]=$emp_listtlist;  
	}
	if($data['emp_id']!=""){
		$condition = " AND employee_id = '".$data['emp_id']."'"; 
	}else{
		$condition = " AND ID IN(SELECT transaction_id FROM `transaction_approval_logs` WHERE transaction_table = 'employee_leaves' AND user_id = '".$data['user_id']."' AND response_type='0')";

	}
		//$leaveidsql = ";
		//$leaveidlist=$callConfig->getAllRows($leaveidsql);

	$sql = "SELECT * FROM `employee_leaves` WHERE is_active='0' AND  company_id = '".$data['company_id']."' ".$condition;
	$leavelist=$callConfig->getAllRows($sql);
	$return_array['sql'] = $sql;
	foreach ($leavelist as $key=>$leavelist) {
		$return[$leavelist->id]['leave_list'] = $leavelist;
		$pass_data = array();
		$sendstatusarray = array('table_name'=>'employee_leaves','transaction_table_id'=>$leavelist->id,'current_status'=>$leavelist->current_status,'created_by'=>$leavelist->created_by);
		$return[$leavelist->id]['data'] = $this->getuserStatusApplay($sendstatusarray,$data);
	}
	$return_array['emp_list'] = $emp_list;
	$return_array['leave'] = $return;
	return $return_array;
}
	function getuserStatusApplay($get,$data){ //$get() array pass AND $data[] post array passs 
		global $callConfig;
		$table = $get['table_name'];
		$current_status = $get['current_status'];
		$transaction_id = $get['transaction_table_id'];
		$created_by = $get['created_by'];
		$lists = $this->toGetStatusProgressActionList($table,$current_status); 
		$pass_data['status_list'] = $lists;
		$aprovallogsurl = "SELECT user_id FROM ".TBL_TRANSACTION_APPROVAL_LOGS." WHERE transaction_table = '".$table."' AND transaction_id = '".$transaction_id."'";
		$aprovallog=$callConfig->getAllRows($aprovallogsurl);
		foreach($aprovallog as $aprovallogs){
			$user[] = $aprovallogs->user_id;
			//$approvaldata[$aprovallogs->user_id] = $aprovallogs;
		}
		$appruser_list = $user;
		$pass_data['users'] =$user;
		$str = "0";
		if(count((array)$appruser_list)>0){
			if(!in_array($data['user_id'], (array)$appruser_list)){
				$str = '9002 - notin ';
			}
		}else{
			if($data['user_id'] != $created_by){
				$str = '9002 - createby';
			}
		}
		if(count((array)$lists)==0){
			$str = '9003';
		}
		$pass_data['view_status'] = $str;
		//$main=$pass_data;
		return  $pass_data;
	}
	function insertFeeds($post){
		global $callConfig;
		//$returnarray =array();
		$post['year'] = date("Y");
		$sql = "SELECT id FROM `feeds` WHERE sending_emp_id='".$post['sending_emp_id']."' AND receiving_emp_id='".$post['receiving_emp_id']."' AND birthday_anniversary_type = '".$post['birthday_anniversary_type']."' AND is_active='0' AND  company_id = '".$post['company_id']."'";
		$feedlist=$callConfig->getRow($sql);
		$returnarray["sql"] =$sql ;
		if(isset($feedlist->id)){
			$post['updated_date'] = date("Y-m-d H:i:s");
			$post['is_active'] = '0';
			$post['current_status'] = '0';
			$post['updated_by'] = $post['user_id'];
			unset($post['user_id']);
			$res = $callConfig->updateRecord('feeds',$post,'id',$feedlist->id);
			$returnarray["status"] ="old";
			$returnarray["respons"] =$res;
		}else{
			$post['created_date'] = date("Y-m-d H:i:s");
			$post['is_active'] = '0';
			$post['current_status'] = '0';
			$post['created_by'] = $post['user_id'];
			unset($post['user_id']);
			$res=$callConfig->insertRecord('feeds',$post);
			$returnarray["status"] ="new";
			$returnarray["respons"] =$res;
		}
		$commentsql = "SELECT count(id) as cnt FROM `feeds` WHERE msg_type='1' AND birthday_anniversary_type = '".$post['birthday_anniversary_type']."' AND receiving_emp_id='".$post['receiving_emp_id']."' AND year='".$post['year']."' AND is_active='0' AND  company_id = '".$post['company_id']."'";
		$commentsum=$callConfig->getRow($commentsql);
		$returnarray["sum_comments"] = $commentsum->cnt;
		$likesql = "SELECT count(id) as cnt FROM `feeds` WHERE like_type='1' AND birthday_anniversary_type = '".$post['birthday_anniversary_type']."' AND receiving_emp_id='".$post['receiving_emp_id']."' AND year='".$post['year']."' AND is_active='0' AND  company_id = '".$post['company_id']."'";
		$likesum=$callConfig->getRow($likesql);
		$returnarray["sum_like"] = $likesum->cnt;
		$returnarray["post"]= $post;
		return $returnarray;
	}

