			if($earns['COSTTOCOMPANY']==$id){ $ctc_y = $post['yearly_amount'][$key]; $ctc_m=$post['monthly_amount'][$key]; }
		}
		$inserttasks = $callConfig->updateRecord('grade_salary_template',array('yearly_gross_salary'=>$gross_early,'ctc_yearly'=>$ctc_y,'ctc_monthly'=>$ctc_m),'id',$insert['LASTID']);
		return $insert;
	}
	function togetpayrollpayarea($get){
		global $callConfig;
		$query = "SELECT * FROM `payroll_admins` WHERE company_id = ".$get['company_id']." AND  user_id =".$get['user_id']." AND is_active = 0";
		$row = $callConfig->getRow($query);
		if($row->id){
			$query1 ="SELECT paa.id,pa.name,paa.pay_area_id,paa.pay_area_id FROM payroll_area_admins paa, pay_areas pa WHERE paa.pay_area_id =pa.id AND  paa.user_id=".$get['user_id']." AND paa.is_active=0";
			$rows = $callConfig->getAllRows($query1);

			$querycc ="SELECT count(id) cc FROM `employee_daily_attendances` WHERE employee_id IN (SELECT emp_id FROM pay_area_employees WHERE pay_area_id IN (SELECT pay_area_id FROM payroll_area_admins WHERE user_id = ".$get['user_id'].")) AND YEAR(attendace_date) ='".$get['pay_year']."' AND MONTH(attendace_date) = '".$get['pay_month']."'";
			$cont = $callConfig->getRow($querycc);

			$payrollsql ="SELECT * FROM `payroll` WHERE company_id ='".$get['company_id']."' AND pay_year ='".$get['pay_year']."' AND pay_month = '".$get['pay_month']."' AND is_active = 0";
			$payrollres = $callConfig->getAllRows($payrollsql);
		}
		$return = array('pay_area'=>$rows,'query'=>$query,'query1'=>$query, 'count_emp' => $cont->cc, 'ccquery'=> $querycc,'payroll'=>$payrollres,'payrollsql'=>$payrollsql);
		return $return;
	}
	function payareapayrolldisplaydata($get, $pay_area_id){
		global $callConfig;
		$whr = "pay_year=".$get['pay_year']." AND pay_month = ".$get['pay_month']." AND company_id = ".$get['company_id']." AND is_active=0 AND pay_area_id = ".$pay_area_id;
		$hquery = $callConfig->selectQuery('payroll','*',$whr,'','','');
			//echo $hquery;
		$hudata = $callConfig->getRow($hquery);
		$whre = "pay_year=".$get['pay_year']." AND pay_month = ".$get['pay_month']." AND company_id = ".$get['company_id']." AND is_active=0 AND pay_area_id = ".$pay_area_id;
		$pequery = $callConfig->selectQuery('payroll_exclusions','*',$whre,'','','');
		$pedata = $callConfig->getAllRows($pequery);

		$whre = "pay_year=".$get['pay_year']." AND pay_month = ".$get['pay_month']." AND company_id = ".$get['company_id']." AND is_active=0 AND pay_area_id = ".$pay_area_id;
		//echo $whre; exit;
		$pequery = $callConfig->selectQuery('payroll_steps','id,category_id',$whre,'','','');
		$payroll_stepsdata = $callConfig->getAllRows($pequery);
		foreach((array)$payroll_stepsdata as $payroll_step){
			$steps[]= $payroll_step->category_id;
		}
		$pyquery = "SELECT prs.component_id, er.name , er.code , SUM(prs.salary_component_actual) as cc_amunt FROM pay_run_summary_components prs, earnings er WHERE prs.company_id = er.company_id AND prs.company_id = ".$get['company_id']." AND prs.component_id = er.id AND prs.pay_year = ".$get['pay_year']." AND prs.pay_month =".$get['pay_month']." AND prs.pay_area_id = ".$pay_area_id."  AND prs.is_active =0 GROUP BY prs.component_id";
		$paydata = $callConfig->getAllRows($pyquery);
		foreach((array)$paydata as $paydat){
			$viewdata[$paydat->code]= $paydat;
		}

		$return['status'] = '3';
		$return['payroll'] = $hudata;
		$return['exclusion'] = $pedata;
		$return['payroll_steps'] = $steps;
		$return['valdata'] = $viewdata;
		return $return;
	}
