	function toinsertdailypayrnsummarybaseemployee($post, $emps, $version){
		global $callConfig;
		//--------------Payroll Dates Config Details------------//
		$datess = $this->payrollfromtodates($post);
		$date1 = $datess['date1']; $date2 = $datess['date2'];
		$cfquery = $callConfig->selectQuery('config','default_payroll_day,show_leave_member','id=1','','','');
		$cfdata = $callConfig->getRow($cfquery);
		$daystr	= strtotime($date2) - strtotime($date1);
		$total_working_days = round($daystr / (60 * 60 * 24))+1;
 		//--------------ESI List------------//
		$esiquery = $callConfig->selectQuery('emp_state_insaurance','*','is_active=0','','','');
		$esidata = $callConfig->getRow($esiquery);
		$esidata = (array)$esidata;
 		//--------------Provident funds List------------//
		$pfquery = $callConfig->selectQuery('emp_provident_funds','*','is_active=0','','','');
		$pfdata = $callConfig->getRow($pfquery);
 		//--------------Professional Tax List List------------//
		$ptquery = $callConfig->selectQuery('professional_tax','*','is_active=0','','','');
		$ptdata = $callConfig->getRow($ptquery);
		//--------------Earnings List------------//
		$whr="company_id= '".$post['company_id']."' AND is_active=0";
		$query = $callConfig->selectQuery('earnings','*',$whr,'display_seq ASC','','');
		$details =$callConfig->getAllRows($query);

		foreach($details as $detail){
			$earns[$detail->id] = (array)$detail;
			$earn_compontnent[$detail->id] = $detail->calculation_mode;
			$earn_pro_rata[$detail->id] = $detail->pro_rata;
			$errdata[$detail->id] = $detail->calculation_mode=="ADD" ? '0' : '1';
			if($detail->calculation_mode=="ADD"){
				$inaa[] = $erans->id;
			}
		}
		$v=1;
		foreach ($emps as $emp) {
			$code_data = array();
			//if($emp->id==1){
				//$emp->id=48;
				//--------------Grade Template List Based on Employee List ------------//
			$whrst="is_active=0 and grade_id = ".$emp->job_grade_id;
			$queryst = $callConfig->selectQuery('grade_salary_template','*',$whrst,'','','');
			$datast = $callConfig->getRow($queryst);
			if($datast->id!=''){
					//--------------Grade Template Components List Based on Salary Template List ------------//
				$whrstc="is_active=0 and grade_salary_template_id=$datast->id";
				$querystc = $callConfig->selectQuery('grade_salary_template_components','*',$whrstc,'','','');
				$datastc = $callConfig->getAllRows($querystc);
				$gross_aount = $datast->yearly_gross_salary;
			   		//$gross_month_amount = $datast->company_cost_monthly;
			   		//print_r($datastc); exit;
					//--------------Employee Terminations Details AND Jion Details Check ------------//	
				
				$emp_termination_query = "SELECT * FROM `employee_terminations` WHERE `releive_date`>='".$date1."' AND `releive_date`<='".$date2."' AND current_status =".ST_APPROVED." AND emp_id=".$emp->id;
				$emp_termination_data = $callConfig->getRow($emp_termination_query);
				if($emp_termination_data->id!="" && $emp->joining_date > $date1){ 
					$leaves = $this->togetemployeeleavecalucate($emp->id,$emp->joining_date,$emp_termination_data->releive_date);
					$total_lop_days = $total_working_days - ($leaves['calender_work_days']-$leaves['total_lop_days']);
				}elseif($emp->joining_date > $date1){
					$leaves = $this->togetemployeeleavecalucate($emp->id,$emp->joining_date,$date2);
					$total_lop_days = $total_working_days - ($leaves['calender_work_days']-$leaves['total_lop_days']);
				}elseif($emp_termination_data->id!=""){
					$leaves = $this->togetemployeeleavecalucate($emp->id,$date1,$emp_termination_data->releive_date);
					$total_lop_days = $total_working_days - ($leaves['calender_work_days']-$leaves['total_lop_days']);
				}else{ 
					if($cfdata->show_leave_member==1){
						$leaves = $this->togetemployeeleavecalucate($emp->id,$date1,$date2);
						$total_no_of_leaves =$leaves['total_no_of_leaves']; 
						$total_lop_days=$leaves['total_lop_days']; 
						$total_no_of_working_days=$total_working_days-$total_no_of_leaves;
					}else{
						$total_no_of_leaves =0; 
						$total_lop_days=0; 
						$total_no_of_working_days=$total_working_days-$total_no_of_leaves;
					}
				}
				$total_month_working_days = $leaves['total_month_working_days'];
				$date_of_leaving = $emp->date_of_leaving!=""?$emp->date_of_leaving:$emp_termination_data->releive_date;

				$total_month_working_days = $leaves['total_month_working_days'];
				$date_of_leaving = $emp->date_of_leaving!=""?$emp->date_of_leaving:$emp_termination_data->releive_date;
				$insert_array =  array('company_id'=>$post['company_id'] ,'revision_no'=>$version,'pay_area_id'=>$post['pay_area_id'],'pay_year'=>$post['pay_year'],'pay_month'=>$post['pay_month'],'location_id'=>$emp->location_id,'employee_id'=>$emp->id,'designation_id'=>$emp->designation_id,'father_name'=>$emp->father_name,'date_of_birth'=>$emp->date_of_birth, 'date_of_leaving'=>$date_of_leaving, 'date_of_joining'=>$emp->joining_date,'contact_details'=>$emp->phone,'bank_id'=>$emp->bank_id,'bank_link'=>$emp->bank_link,'bank_account_no'=>$emp->bank_account_no,'cover_under_pf'=>$emp->cover_under_pf,'cover_under_esi'=>$emp->cover_under_esi,'total_no_of_leaves'=>$total_no_of_leaves,'total_no_of_days'=>$total_working_days ,'total_lop_days'=>$total_lop_days,'total_no_of_working_days'=>$total_month_working_days ,'is_active'=>'0','current_status'=>'0','created_by'=>$post['user_id'],'created_date'=>date('Y-m-d h:i:s'));
				$insert = $callConfig->insertRecord('pay_run_summary',$insert_array); 
				$insert_componet_array = array();
				foreach ($datastc as  $stc) {
					$code = $earns[$stc->component_id]['code'];
					$calculation_type = $earns[$stc->component_id]['calculation_type'];
					$display_in_payslip = $earns[$stc->component_id]['display_in_payslip'];
					$base_amount='';
						//if($earns[$stc->component_id]['pro_rata']=="0"){
					if($insert_array['total_lop_days']==$total_month_working_days){ 
						$insert_array['total_lop_days'] = $total_working_days; 
					}
					$no_working = $total_working_days-$insert_array['total_lop_days'];
					$act =  $stc->monthly_amount;
					if($earns[$stc->component_id]['calculation_type']=='A'){
						$act = $act*$no_working;
					}
					if($earns[$stc->component_id]['calculation_type']=='P'){
						$cc_code =$earns[$stc->component_id]['calculation_category'];
								//$calculation_number = $earns[$stc->component_id]['calculation_number'];
						$calculation_number = $stc->component_number;
						$base_amount=$code_data[$cc_code];								
						$calculation_formula = $base_amount."*".$calculation_number."%";
						$act = ($base_amount*$calculation_number)/100;								 
					}
					if($earns[$stc->component_id]['calculation_type']=='F'){
						$calculation_formula =  $earns[$stc->component_id]['calculation_formula'] ;							
						$formula_details = json_decode($earns[$stc->component_id]['formula_details'],1) ;
						$count = $formula_details['count'];
						$f_details = $formula_details['details'];
						for($u=0;$u<$count;$u++){
							$fcall = is_numeric($f_details[$u]['lcode']) ? $f_details[$u]['lcode'] : $code_data[$f_details[$u]['lcode']];
							$fcalr = is_numeric($f_details[$u]['rcode']) ? $f_details[$u]['rcode'] : $code_data[$f_details[$u]['rcode']];
							$cals =   $this->calucalationsum($fcall,$fcalr,$f_details[$u]['loperand']);
							if($u>0){
								$calq =  $this->calucalationsum($calq,$cals,$f_details[$u-1]['roperand']);
							}else{
								$calq = $cals;
							}
						}
						$act = $calq;
					}
					if($earns[$stc->component_id]['calculation_type']=='L'){
						$calculation_link = $earns[$stc->component_id]['calculation_link'];
						if($calculation_link == 'NHD'){											
							$act= $stc->monthly_amount;									
						}
						if($calculation_link == 'WPF'&& $emp->cover_under_pf==0){
							$pf = $this->tocalucalteepf($code_data,$pfdata->employee_contribution,$pfdata);
							$act=$pf['amount'];
							$calculation_formula=$pf['cal_formula'];
							$base_amount=$pf['basic_amount'];
						}
						if($calculation_link == 'WPF'&& $emp->cover_under_pf==1){
							$act=0;
						}
						if($calculation_link == 'WEMPLOYERPF' && $emp->cover_under_pf==0){
							$pf = $this->tocalucalteepf($code_data,$pfdata->employer_contribution,$pfdata);
							$act=$pf['amount'];
							$calculation_formula=$pf['cal_formula'];
							$base_amount=$pf['basic_amount'];
						}
						if($calculation_link == 'WEMPLOYERPF'&& $emp->cover_under_pf==1){
							$act=0;
						}
						if($calculation_link == 'WESI'){
							$pf = $this->tocalucaltesi($code_data,$esidata,$earns[$stc->component_id]['calculation_category'],'employee_contribution');
							$act=$pf['amount'];
							$calculation_formula=$pf['cal_formula'];
							$base_amount=$pf['basic_amount'];
						}
						if($calculation_link == 'WEMPLOYERESI'){
							$pf = $this->tocalucaltesi($code_data,$esidata,$earns[$stc->component_id]['calculation_category'],'employer_contribution');
							$act=$pf['amount'];
							$calculation_formula=$pf['cal_formula'];
							$base_amount=$pf['basic_amount'];
						}
						if($calculation_link == 'WPTX'){
							$pf = $this->tocalucaltPTX($code_data,$ptdata->slabs,$earns[$stc->component_id]['calculation_category'],$post['pay_month']);
							$act=$pf['amount'];
							$calculation_formula=$pf['cal_formula'];
							$base_amount=$pf['basic_amount'];
						}
