	function listoutpayareapayrolldetails($get){
		global $callConfig;
		//print_r($get);
		$pay_area_ids = explode(",",$get['PPJ']);
		foreach($pay_area_ids as $pay_area_id ){
			$whr = "pay_year=".$get['pay_year']." AND pay_month = ".$get['pay_month']." AND company_id = ".$get['company_id']." AND pay_area_id = ".$pay_area_id." AND is_active=0";
			$hquery = $callConfig->selectQuery('payroll','*',$whr,'','','');
			$hudata = $callConfig->getRow($hquery);			
			$return[$pay_area_id] = $this->payareapayrolldisplaydata($get, $pay_area_id);
		}
		$query = "SELECT id, emp_code, display_name FROM employees";
		$return['employees'] = $callConfig->getAllRows($query);
		$query = "SELECT id,name FROM pay_areas";
		$return['pay_areas'] = $callConfig->getAllRows($query);

		return $return;
	}
