	function getgrosssalarywithregim($get){
		global $callConfig;
		$query = "SELECT stc.component_id, ern.code, stc.component_name, stc.monthly_amount, stc.yearly_amount FROM salary_template st, salary_template_components stc, earnings ern WHERE st.company_id = stc.company_id AND st.id = stc.salary_template_id AND  stc.company_id = ern.company_id AND  stc.is_active = ern.is_active AND stc.component_id = ern.id AND st.employee_id = '".$get['emp_id']."' AND st.company_id = '".$get['company_id']."' AND st.affected_date <= '".$get['month_last_date']."' AND stc.is_active = 0";
		$res = $callConfig->getAllRows($query);
		$emp_metrosql =  "SELECT emp.id, loc.location_name, loc.hra_exemption_id, hra_ex.assessment_year, hra_ex.category_name, hra_ex.rate_percentage FROM employees emp, locations loc, hra_exemptions hra_ex WHERE emp.company_id = '".$get['company_id']."' AND emp.company_id = loc.company_id AND emp.company_id = hra_ex.company_id AND emp.is_active = loc.is_active AND emp.is_active = hra_ex.is_active AND emp.location_id = loc.id AND loc.hra_exemption_id = hra_ex.id AND emp.id ='".$get['emp_id']."' AND emp.is_active=0"; 
		$emp_metrores = $callConfig->getAllRows($emp_metrosql);
		$returnarray['salaray'] =$res;
		$returnarray['metro'] =$emp_metrores;
		return $returnarray;
	}



