		function getAdminDashboard($get){
			global $callConfig;
			$returnarray = array();
			$vendor_id = array();
			$todaydate = date("Y-m-d");
		
			if($get['admin_type'] != 1){
				$condition = "AND created_by = '".$get['user_id']."'";
			}
		
			$vendorssql = "SELECT id, display_name FROM vendors WHERE company_id = '".$get['company_id']."' ".$condition." AND is_active = 0"; 
			$vendorsres = $callConfig->getAllRows($vendorssql);
			foreach($vendorsres as $vendors1){
				$vendorsary[$vendors1->id] =$vendors1; 
				$vendor_id[$vendors1->id] = $vendors1->id;
			}
			$returnarray['vendors'] = $vendorsary;
			if($get['admin_type'] != '1'){
				$condition = "AND created_by = '".$get['user_id']."'";
				if(count((array)$vendor_id) != 0){
					$vendorid = implode(',', $vendor_id);
					$condition1 = "AND (party_id IN(".$vendorid.") OR originator = '".$get['user_id']."')";
					$condition2 = "AND (sb.party_id IN(".$vendorid.") OR sb.originator = '".$get['user_id']."')";
				}else{	
					$condition1 = "AND originator = '".$get['user_id']."'";
					$condition2 = "AND sb.originator = '".$get['user_id']."'";
				}
			}

			$supplierbillssql = "SELECT COUNT(*) as cnt FROM supplier_bills WHERE company_id = '".$get['company_id']."' ".$condition1." AND is_active = 0";
			$supplierbillsres = $callConfig->getRow($supplierbillssql);
			$returnarray['supplierbillssql'] = $supplierbillssql;
			$returnarray['supplier_bill_cnt'] = $supplierbillsres->cnt;

			$billapproved = "SELECT count(*) as cnt FROM supplier_bills WHERE company_id = '".$get['company_id']."' ".$condition1." AND is_active = 0 AND current_status = ".ST_APPROVED;
			$billapprores = $callConfig->getRow($billapproved);
			$returnarray['users_cnt']  =$billapprores->cnt;

			$vendorslistsql = "SELECT id,transaction_number,transaction_date,party_name,party_id,current_status,party_name,amount FROM supplier_bills WHERE company_id = '".$get['company_id']."' ".$condition1." AND is_active = 0 AND current_status NOT IN(".ST_DRAFT.")";
			$vendorslistres = $callConfig->getAllRows($vendorslistsql);
			$returnarray['purchase_invoice_list'] = $vendorslistres;


			$vendorslistsql = "SELECT vend.id, sb.party_id,sum(sb.total_amount) as total_amount, sum(sb.pending_amount) as pending_amount, vend.display_name,vend.image, vend.company, sb.due_date FROM supplier_bills sb, vendors vend WHERE sb.company_id = '".$get['company_id']."'  AND vend.company_id = sb.company_id AND sb.party_id = vend.id AND sb.is_active = vend.is_active ".$condition2." AND sb.current_status='".ST_APPROVED."' AND sb.is_active = 0 GROUP BY sb.party_id order by vend.created_date desc limit ".$get['vend_limit'];
			$vendorslistres = $callConfig->getAllRows($vendorslistsql);
			$returnarray['vendors_recent_join'] = $vendorslistres;

			$vendorslistsql = "SELECT vend.id, sb.party_id,sum(sb.total_amount) as total_amount, sum(sb.pending_amount) as pending_amount, vend.display_name,vend.image, vend.company, sb.due_date FROM supplier_bills sb, vendors vend WHERE sb.company_id = '".$get['company_id']."'  AND vend.company_id = sb.company_id AND sb.party_id = vend.id AND sb.is_active = vend.is_active ".$condition2." AND sb.current_status='".ST_APPROVED."' AND sb.is_active = 0 GROUP BY sb.party_id limit ".$get['vend_limit'];
			$vendorslistres = $callConfig->getAllRows($vendorslistsql);
			$returnarray['vendors_list'] = $vendorslistres;


			$vendorinvoicecntsql = "SELECT sum(if(current_status='".ST_APPROVED."',total_amount,0)) as total_amount, sum(if(current_status='".ST_APPROVED."' AND due_date <= '".$todaydate."',pending_amount,0)) as payment_due, sum(if(current_status='".ST_APPROVED."' AND due_date > '".$todaydate."',pending_amount,0)) as yet_to_due, sum(if(current_status='".ST_APPROVED."',pending_amount,0)) as total_pending FROM supplier_bills WHERE company_id = '".$get['company_id']."' ".$condition1." AND is_active = 0 AND current_status NOT IN(".ST_DRAFT.",".ST_ACTIVE.")";
			$vendorinvoicecntres = $callConfig->getrow($vendorinvoicecntsql);
			$returnarray['vendor_invoice_cnt'] = $vendorinvoicecntres;

			$transapprlogsql = "SELECT tal.request_date,tal.response_date, tal.response_type, sb.transaction_number as transaction_no, sb.transaction_date as payment_date, sb.total_amount as amount, sb.originator ,sb.id FROM transaction_approval_logs tal, supplier_bills sb WHERE tal.company_id = '".$get['company_id']."' AND tal.company_id = sb.company_id AND  tal.transaction_table = 'supplier_bills' AND tal.user_id = '".$get['user_id']."' ".$condition2." AND tal.transaction_id = sb.id AND sb.is_active = 0 ORDER BY sb.transaction_number DESC";
			$transapprlogres = $callConfig->getAllRows($transapprlogsql);
			$returnarray['transaction_approval_logs_sql'] = $transapprlogsql;
