			$returnarray['si_cnt']  =$billapprores->cnt;

			$vendorslistsql = "SELECT id,transaction_number,transaction_date,party_name,party_id,current_status,party_name,amount FROM sales_invoices WHERE company_id = '".$get['company_id']."' ".$condition1." AND is_active = 0 AND current_status NOT IN(".ST_DRAFT.")";
