			$vendorslistsql = "SELECT vend.id, sb.party_id,sum(sb.total_amount) as total_amount, sum(sb.pending_amount) as pending_amount, vend.display_name,vend.image, vend.company, sb.due_date FROM sales_invoices sb, customers vend WHERE sb.company_id = '".$get['company_id']."'  AND vend.company_id = sb.company_id AND sb.party_id = vend.id AND sb.is_active = vend.is_active ".$condition2." AND sb.current_status='".ST_APPROVED."' AND sb.is_active = 0 GROUP BY sb.party_id order by vend.created_date desc limit ".$get['vend_limit'];
			$vendorslistres = $callConfig->getAllRows($vendorslistsql);
			$returnarray['customers_recent_join'] = $vendorslistres;

			$vendorslistsql = "SELECT vend.id, sb.party_id,sum(sb.total_amount) as total_amount, sum(sb.pending_amount) as pending_amount, vend.display_name,vend.image, vend.company, sb.due_date FROM sales_invoices sb, customers vend WHERE sb.company_id = '".$get['company_id']."'  AND vend.company_id = sb.company_id AND sb.party_id = vend.id AND sb.is_active = vend.is_active ".$condition2." AND sb.current_status='".ST_APPROVED."' AND sb.is_active = 0 GROUP BY sb.party_id limit ".$get['vend_limit'];
			$vendorslistres = $callConfig->getAllRows($vendorslistsql);
			$returnarray['customes_list'] = $vendorslistres;


			$vendorinvoicecntsql = "SELECT sum(if(current_status='".ST_APPROVED."',total_amount,0)) as total_amount, sum(if(current_status='".ST_APPROVED."' AND due_date <= '".$todaydate."',pending_amount,0)) as payment_due, sum(if(current_status='".ST_APPROVED."' AND due_date > '".$todaydate."',pending_amount,0)) as yet_to_due, sum(if(current_status='".ST_APPROVED."',pending_amount,0)) as total_pending FROM sales_invoices WHERE company_id = '".$get['company_id']."' ".$condition1." AND is_active = 0 AND current_status NOT IN(".ST_DRAFT.",".ST_ACTIVE.")";
			$vendorinvoicecntres = $callConfig->getrow($vendorinvoicecntsql);
			$returnarray['customer_invoice_cnt'] = $vendorinvoicecntres;

			$transapprlogsql = "SELECT tal.request_date,tal.response_date, tal.response_type, sb.transaction_number as transaction_no, sb.transaction_date as payment_date, sb.total_amount as amount, sb.originator ,sb.id FROM transaction_approval_logs tal, sales_invoices sb WHERE tal.company_id = '".$get['company_id']."' AND tal.company_id = sb.company_id AND  tal.transaction_table = 'sales_invoices' AND tal.user_id = '".$get['user_id']."'".$condition2."  AND tal.transaction_id = sb.id AND sb.is_active = 0 ORDER BY sb.transaction_number DESC";
			$transapprlogres = $callConfig->getAllRows($transapprlogsql);
		//	$returnarray['transaction_approval_logs_sql'] = $transapprlogsql;
			$returnarray['transaction_approval_logs_customer'] = $transapprlogres;


			$vendorssql = "SELECT id, display_name FROM customers WHERE company_id = '".$get['company_id']."' AND is_active = 0"; 
			$vendorsres = $callConfig->getAllRows($vendorssql);
			$vendors = array();
			foreach($vendorsres as $vendors1){
				$vendors[$vendors1->id] =$vendors1; 
			}
			$returnarray['all_customers'] = $vendors;
			
			//Customer
			return $returnarray;
		}
