	 function insertandupdateempexpenses($get,$getp){
	 	global $callConfig;
	 	$expense_date = str_replace('/"', '-', $get['expense_date']);
	 	$expense_date =  date('Y-m-d', strtotime($expense_date));
	 	$reference_date = str_replace('/"', '-', $get['reference_date']);
	 	$reference_date =  date('Y-m-d', strtotime($reference_date));
	 	//$returnarray['get'] = $get;
	 	$fieldnames=array('company_id'=>$get['company_id'],'emp_id'=>$get['emp_id'],'user_id'=>$get['user_id'],'expense_date'=>$expense_date,'currency_id'=>$get['currency_id'],'client_reimbursement'=>$get['client_reimbursement'],'transport_assign_id'=>$get['transport_assign_id'],'reference_date'=>$reference_date,'project_name'=>$get['project_id'],'amount'=>$get['amount'],'total_amount'=>$get['amount'],'pending_amount'=>$get['amount'],'cost_center_id'=>$get['cost_center_id'],'trip_id'=>$get['trip_id']);
	 	$returnarray['array'] = $fieldnames;	
	 	$returnarray['Rid'] = $get['Rid'];
	 	if($get['Rid'] != '0' AND $get['Rid'] != ''){
	 		$fieldnames['updated_date'] = date('Y-m-d h:i:s');
	 		$fieldnames['updated_by'] = $get['user_id'];
	 		$insert_data=$callConfig->updateRecord('emp_expenses',$fieldnames,'id',$get['Rid']);
	 		$returnarray['updateRecord'] = $insert_data;
	 		$insert_id = $get['Rid'];
	 	}else{
	 		$transation = $this->toGetApplicationSerialNumber('emp_expenses',$get);
	 		$fieldnames['expense_code'] = $transation;
	 		$fieldnames['created_by'] = $get['user_id'];
	 		$fieldnames['created_date'] = date('Y-m-d h:i:s');
	 		$fieldnames['is_active'] = '0';
	 		$fieldnames['current_status'] = ST_DRAFT;
	 		$insert_data=$callConfig->insertRecord('emp_expenses',$fieldnames);
	 		$returnarray['insertRecord'] = $insert_data;
	 		$insert_id = $insert_data['LASTID'];
	 	}
	 	$returnarray['LASTID'] =$insert_id;
	 	$bill_date = str_replace('/', '-', $get['expense_date']);
	 	$bill_date =  date('Y-m-d', strtotime($bill_date));
	 	if($get['expense_type']=='1'){
	 		$get['category'] = $get['category_mileage']; 
	 		$get['qty']  = $get['qty_mileage'];
	 		$get['rate']  = $get['rate_mileage'];
	 	}elseif($get['expense_type']=='2'){
	 		$get['category'] = $get['category_perd']; 
	 		$get['qty']  = $get['qty_perd'];
	 		$get['rate']  = $get['rate_perd'];
	 	}else{	
	 		$get['category'] = $get['category_exp']; 
	 		$get['qty']  = $get['qty_exp'];
	 		$get['rate']  = $get['rate_exp'];
	 	}
	 	$itemfieldnames=array('company_id'=>$get['company_id'],'emp_id'=>$get['emp_id'],'emp_expenses_id'=>$insert_id,'category_id'=>$get['category'],'expense_type'=>$get['expense_type'],'bill_no'=>$get['bill_no'],'description'=>$get['description'],'bill_date'=>$bill_date,'bill_file'=>$get['bill_file'],'qty'=>$get['qty'],'rate'=>$get['rate'],'tax_amount'=>$get['tax'],'expense_amount'=>$get['amount'],'merchant_name'=>$get['merchant_name'],'project_id'=>$get['project_id'],'payment_mode'=>$get['payment_mode'],'location'=>$get['location'],'is_active'=>'0','current_status'=>'0');	
	 	$returnarray['subarray'] = $itemfieldnames;
	 	if($get['exp_detail_id'] != ''){
	 		$itemfieldnames['updated_date'] = date('Y-m-d h:i:s');
	 		$itemfieldnames['updated_by'] = $get['user_id'];
	 		$item_id=$callConfig->updateRecord('emp_expenses_details',$itemfieldnames,'id',$get['exp_detail_id']);
	 		$returnarray['updatesub'] = $item_id;
	 	}else{
	 		$itemfieldnames['created_by'] = $get['user_id'];
	 		$itemfieldnames['created_date'] = date('Y-m-d h:i:s');
	 		$item_id=$callConfig->insertRecord('emp_expenses_details',$itemfieldnames);
	 		$returnarray['insertsub'] = $item_id;
	 		if($get['other_images'] !=""){
	 			$otherimages = explode(",",$get['other_images']);
				foreach($otherimages as $other_images){
					$attachmentarray = array('transaction_id'=>$item_id['LASTID'], 'application_table_name'=>'emp_expenses_details');
		            $where = "actual_file_name = '".$other_images."'";
		            $res=$callConfig->updateRecord("application_attachments",$attachmentarray,"","",$where);
				}
			}

	 		// if(count((array)$get['other_images'])>0){
			// 	foreach($get['other_images'] as $other_images){
			// 		$attachmentarray = array('transaction_id'=>$item_id['LASTID'], 'application_table_name'=>'emp_expenses_details');
		    //         $where = "actual_file_name = '".$other_images."'";
		    //         $res=$callConfig->updateRecord("application_attachments",$attachmentarray,"","",$where);
			// 	}
			// }
	 	}
	 	/*total amount updated main table*/	
	 	$sql1 = "SELECT sum(rate) as sumval, sum(tax_amount) as tax_amount, sum(expense_amount) as expense_amount FROM emp_expenses_details WHERE company_id = '".$get['company_id']."' AND is_active = 0 AND emp_expenses_id = '".$insert_id."'";
	 	$res1 = $callConfig->getRow($sql1);
	 	$updatefil['amount'] = $res1->sumval;
	 	$updatefil['total_amount'] = $res1->expense_amount;
	 	$updatefil['pending_amount'] = $res1->expense_amount;
	 	$updatefil['tax_amount'] = $res1->tax_amount;
	 	$insert_data=$callConfig->updateRecord('emp_expenses',$updatefil,'id',$insert_id);
	 	$returnarray['updateamount'] = $insert_data;
	 	/*total amount updated main table*/			
	 	return $returnarray;
	 }
	 function insertExpensesPolicies($post){
