	 function updatestatusvendordocuments($get){
	 	global $callConfig;

	 	$sql = "SELECT dl.document_name,au.display_name FROM vendor_documents vd, document_lists dl, application_users au WHERE vd.company_id = '".$get['company_id']."' AND vd.company_id = dl.company_id AND vd.company_id = au.company_id AND vd.id = '".$get['hid']."' AND vd.category_id = dl.id AND vd.vendor_user_id = au.id AND vd.is_active = dl.is_active  AND vd.is_active = au.is_active AND dl.is_active = 0";
	 	$result = $callConfig->getRow($sql);
	 	$fieldnames = array('current_status'=>$get['status']);
	 	$res=$callConfig->updateRecord($get['table'],$fieldnames,'id',$get['hid']);
	 	if($get['status'] == ST_REJECTED){
	 		$msg =  $result->display_name." (".$result->document_name.") Doument is Rejected";
	 	}else{
	 		$msg =  $result->display_name." (".$result->document_name.") Doument is Approved";
	 	}
	 	$user_idd = array('0'=>$get['user_idd'],'1'=>$get['user_id']);
	 	$option = "opt";
	 	$notdataa = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$get['vendor_register_id'],'application_table_name'=>'vendor_registers', 'type'=>'INFORMATION', 'notification_users'=>$user_idd,'option'=>$option);
	 	$sendnotification = $this->tosendnotifiations($notdataa);
	 	return $get;	
	 }
	 function reAproVevendorDoc($get){
	 	global $callConfig;
	 	$designationsquery = $callConfig->selectQuery('vendor_registers','*','id='.$get['hid'],'','','');
	 	$cdata = $callConfig->getRow($designationsquery);
	 	$returnarray['res'] = $cdata;
	 	$fied = array('current_status' =>ST_APPROVAL_PENDING);
	 	$whrcon = "vendor_user_id='".$cdata->user_id."' AND current_status = '".ST_REJECTED."'";
	 	$res1 = $callConfig->updateRecord('vendor_documents',$fied,'','',$whrcon);
	 	$returnarray['updateRecord'] = $res1;
	 	$returnarray['where'] = $whrcon;
	 	$msg = "Vendor ".$cdata->display_name." shared the documents Transaction ID : ".$get['hid'];
	 	$user_ids = array('0'=>$get['useridd']);
	 	$option = "COM_INSERT_VENDOR_REGISTERS";
	 	$notdataa = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$get['hid'],'application_table_name'=>'vendor_registers', 'type'=>'ACTION', 'notification_users'=>$user_ids,'option'=>$option);
	 	$sendnotification = $this->tosendnotifiations($notdataa);
	 	$returnarray['notdataa'] = $notdataa;
	 	return $returnarray;
	 }

