	 function getStockTakes($data){
	 	global $callConfig;
	 	$stocktakes = "SELECT * FROM stocktakes WHERE is_active =0 AND company_id = '".$data['company_id']."' AND id ='".$data['Rid']."'";
	 	$stocktakesres=$callConfig->getRow($stocktakes);
	 	$returnresult['stocktakes'] = $stocktakesres;
	 	$items = "SELECT id,item_name FROM items WHERE is_active =0 AND company_id = '".$data['company_id']."'";
	 	$itemsres=$callConfig->getAllRows($items);
	 	$returnresult['item'] = $itemsres;
	 	$itemids = json_decode($stocktakesres->item,1);
	 	$itemidstr =implode(",",(array)$itemids);
	 	if($stocktakesres->location != ""){
	 		$locs = json_decode($stocktakesres->location,1);
	 		$locss =implode(",",(array)$locs);
	 		$condition11 = " AND iloc.location_id IN(".$locss.")";
	 	}
	 	$location = "SELECT DISTINCT iloc.location_id as id, (SELECT loc.location_name FROM locations loc WHERE iloc.is_active = loc.is_active AND iloc.company_id = loc.company_id AND iloc.location_id = loc.id) as location_name  FROM  item_locations iloc  WHERE iloc.item_id IN(".$itemidstr.") AND  is_active =0 AND company_id = '".$data['company_id']."' ".$condition11;
	 	$locations=$callConfig->getAllRows($location);
	 	$returnresult['locations'] = $locations;
	 	$user = "SELECT id,display_name FROM application_users WHERE is_active =0 AND company_id = '".$data['company_id']."'";
	 	$users=$callConfig->getAllRows($user);
	 	$returnresult['users'] = $users;
	 	if($data['stoctype']=="list"){
	 		$condition = "";
	 		$itemids = json_decode($stocktakesres->item,1);
	 		$itemidstr =implode(",",(array)$itemids);
	 		if($data['filter_location'] != "null"){
	 			$locstr =implode(",",(array)json_decode($data['filter_location'],1));
	 			$condition = "AND il.location_id IN(".$locstr.")";
	 		}elseif($stocktakesres->location != ""){
	 			$locs = json_decode($stocktakesres->location,1);
	 			$locss =implode(",",(array)$locs);
	 			$condition = "AND il.location_id IN(".$locss.")";
	 		}
	 		$item_lists = "SELECT item.id,item.sale_price,item.purchase_price, il.location_id,item.default_costing_type, item.item_name,item.purchase_uom,item.purchase_uom,item.additional_attributes,uom.code FROM items item,uom, item_locations il  WHERE item.is_active =0 AND item.company_id = '".$data['company_id']."' AND item.purchase_uom = uom.id AND item.company_id = uom.company_id AND item.is_active = uom.is_active AND item.company_id = il.company_id AND item.is_active = il.is_active AND item.id = il.item_id AND item.id IN(".$itemidstr.") ".$condition." GROUP BY il.location_id,il.item_id";
	 		$itemsres=$callConfig->getAllRows($item_lists);
	 		$returnresult['item_list'] =$itemsres;
	 		$locationitemavailability =  $this->locationitemavailability($data);
	 		$returnresult['locationitemavailability']  = $locationitemavailability;
	 		$stockitemsql = "SELECT * FROM stocktake_items WHERE is_active =0 AND company_id = '".$data['company_id']."' AND stocktake_id='".$data['Rid']."'";
	 		$stockitems=$callConfig->getAllRows($stockitemsql);
	 		$returnresult['stockitems'] = $stockitems;
	 	}
	 	return $returnresult;
	 }
	 function locationitemavailability($data){
	 	global $callConfig;
	 	$locationitemsql_st =  "SELECT l1.location_id,l1.item_id, l1.closing_qty as available, l1.balance_date FROM loc_item_st_balances l1 WHERE l1.balance_date = (SELECT MAX(l2.balance_date) FROM loc_item_st_balances l2 WHERE l1.item_id = l2.item_id AND l1.location_id = l2.location_id AND l1.is_active = l2.is_active AND l1.company_id = l2.company_id ) AND l1.is_active = 0 AND l1.company_id = '".$data['company_id']."'";
	 	$locationitemres_st=$callConfig->getAllRows($locationitemsql_st);
	 	$items_st = array();
	 	foreach($locationitemres_st as $locationitemress_st){
	 		$items_loc_st[$locationitemress_st->location_id][$locationitemress_st->item_id] = $locationitemress_st;
	 	}
	 	$returarray['S'] = $items_loc_st;
	 	$locationitemsql_wa =  "SELECT l1.location_id,l1.item_id, l1.closing_qty as available, l1.balance_date FROM loc_item_wa_balances l1 WHERE l1.balance_date = (SELECT MAX(l2.balance_date) FROM loc_item_wa_balances l2 WHERE l1.item_id = l2.item_id AND l1.location_id = l2.location_id AND l1.is_active = l2.is_active AND l1.company_id = l2.company_id ) AND l1.is_active = 0 AND l1.company_id = '".$data['company_id']."'";
	 	$locationitemres_wa=$callConfig->getAllRows($locationitemsql_wa);
	 	$items_wa = array();
	 	$items_loc_wa = array();
	 	foreach($locationitemres_wa as $locationitemress_wa){
	 		$items_loc_wa[$locationitemress_wa->location_id][$locationitemress_wa->item_id] = $locationitemress_wa;
	 	}
	 	$returarray['W'] = $items_loc_wa;
	 	return $returarray;
	 }
	 function insertStockTakes($data){
	 	global $callConfig;
	 	$Planned_date = str_replace('/"', '-',$data['Planned_date']);
	 	$Planned_date =  date('Y-m-d', strtotime($Planned_date));
	 	$item = json_encode($data['item']);
	 	$item_attribute = json_encode($data['item_attribute']);
	 	$location=json_encode($data['location']);
	 	$empty_location = isset($data['empty_location'])?"0":"1";
	 	$insert_array = array( 'company_id' =>$data['company_id'],'user_id' =>$data['user']
	 		,'name' =>$data['name'],'Planned_date'=>$Planned_date,'item' =>$item,'is_active' =>'0','current_status'=>0,'item_attribute'=>$item_attribute,'location'=>$location,'empty_location'=>$empty_location);
	 	if($data['Rid'] !=""){
	 		$insert_array['updated_date'] = date('Y-m-d H:i:s');
	 		$insert_array['updated_by'] = $data['user_id'];
	 		$where = "id = '".$data['Rid']."'";
	 		$res=$callConfig->updateRecord("stocktakes",$insert_array,"","",$where);
	 	}else{
	 		$transation = $this->toGetApplicationSerialNumber('stocktakes',$data);
	 		$insert_array['transaction_number'] = $transation;
	 		$insert_array['is_active'] = '0';
	 		$insert_array['created_date'] = date('Y-m-d H:i:s');
	 		$insert_array['created_by'] = $data['user_id'];
	 		$insert_array['current_status'] = '0';
	 		$res = $callConfig->insertRecord('stocktakes',$insert_array);
	 	}
	 	return $res;
	 }
