	 					$check_i=$callConfig->getRow($check_isql); 
	 					$insert_array = array('company_id' =>$data['company_id'],'stocktake_id' =>$data['stocktake_id'],'item_id' =>$item_value,'uom_details'=>$data['uom_details'][$item_key],'count_qty'=>$data['count_qty'][$item_key],'location_id'=>$data['location_id'][$item_key]);

	 					if(isset($check_i->id)){
	 						$insert_array['updated_date'] = date('Y-m-d H:i:s');
	 						$insert_array['updated_by'] = $data['user_id'];
	 						$where = "id = '".$check_i->id."'";
	 						$res=$callConfig->updateRecord("stocktake_items",$insert_array,"","",$where);
	 						$returnresult['update'] =$res;
