function getStockTakeAdjustments($data){
	global $callConfig;
	$inserts_task['status'] = '3';
	$inserts_task['completed_date'] = date('Y-m-d H:i:s');
	$res=$callConfig->updateRecord('stocktakes',$inserts_task,'id',$data['stocktake_id']);
	$ddf = array();
	$insert_id = $data['stocktake_id'];
	$document_ref_no = $data['transaction_number'];
	$table = 'stocktakes';
	foreach($data['item_id'] as $item_key=>$item_value){
		$insert_array = array('system_qty'=>$data['system_qty'][$item_key],'variance'=>$data['available_qty'][$item_key],'updated_date'=>date('Y-m-d H:i:s'),'updated_by'=>$data['user_id']);
		$mainitem = $this->togetitemvalues($item_value);
		$day_rate = $this->togetitemwadayrate($item_value, $data['company_id']);
			//$itemselect  = $this->toGetItemcostingtyewithdata(array('item_id'=>$item_value,'date'=>date('Y-m-d')));
		if($data['available_qty'][$item_key] != "0" && $data['substoktakecheck'][$item_key] == "0"){
			$sale_price = $data['sale_price'][$item_key];
			$purchase_price = $data['purchase_price'][$item_key];
			$sale_value = $sale_price*abs($data['available_qty'][$item_key]);
			$len = array('company_id' =>$data['company_id'] , 'location_id' =>$data['location_id'][$item_key] ,'transaction_date' => date('Y-m-d') , 'item_id' =>$item_value,'document_no' =>$insert_id,'document_type' =>$table,'document_ref_no' =>$document_ref_no,'item_in_value' =>$mainitem->purchase_price*abs($data['available_qty'][$item_key]),'sale_price'=>$sale_price,'sale_value'=>$sale_value,'item_wa_cost'=>$day_rate,'item_st_cost'=>$mainitem->purchase_price);
			if($data['available_qty'][$item_key] < 0){
				$len['out_qty'] = abs($data['available_qty'][$item_key]);
				$len['out_value'] = $sale_price;
				$len['reason_id'] = '1';
			}else{
				$len['in_qty'] = abs($data['available_qty'][$item_key]);
				$len['in_value'] = $purchase_price; 
				$len['reason_id'] = '0';
			}
			//$ddf[] = $this->invoiceUpdates($table,$len);
			$insert_array['update_balance'] = "Y";
		}
		$check_isql = "SELECT id FROM stocktake_items  WHERE is_active =0 AND company_id = '".$data['company_id']."' AND stocktake_id  = '".$data['stocktake_id']."' AND item_id='".$item_value."' AND location_id='".$data['location_id'][$item_key]."'";
		$check_i=$callConfig->getRow($check_isql); 
		$where = "id = '".$check_i->id."'";
		$res=$callConfig->updateRecord("stocktake_items",$insert_array,"","",$where);
	} 
	return $ddf;
}
function getStockTakeLocations($data){
	global $callConfig;
	$location = "SELECT DISTINCT iloc.location_id, (SELECT loc.location_name FROM locations loc WHERE iloc.is_active = loc.is_active AND iloc.company_id = loc.company_id AND iloc.location_id = loc.id) as location_name  FROM  item_locations iloc  WHERE iloc.item_id IN(".$data['selectitems'].") AND  is_active =0 AND company_id = '".$data['company_id']."'";
	$locations=$callConfig->getAllRows($location);
	return $locations;
}
function softDeletedRecord($data){
	global $callConfig;
	$insert_array = array('is_active'=>null);
	$where = "id = '".$data['id']."'";
	$res=$callConfig->updateRecord($data['table'],$insert_array,"","",$where);
	if($data['table']=='building_floors'){
		$removeequipment_allocations = "UPDATE `equipment_allocations` SET is_active = null WHERE company_id = '".$data['company_id']."' AND building_floor_space_id IN(SELECT id FROM `building_floor_spaces` WHERE company_id = '".$data['company_id']."' AND building_floor_id = '".$data['id']."' AND is_active = 0) AND is_active = 0"; 
		$callConfig->executeQuery($removeequipment_allocations);

		$removebuilding_floor_spaces = "UPDATE `building_floor_spaces` SET is_active = null WHERE company_id = '".$data['company_id']."' AND building_floor_id = '".$data['id']."' AND is_active = 0"; 
		$callConfig->executeQuery($removebuilding_floor_spaces);
	}elseif($data['table']=='building_floor_spaces'){
	
		$removeequipment_allocations = "UPDATE `equipment_allocations` SET is_active = null WHERE company_id = '".$data['company_id']."' AND building_floor_space_id  = '".$data['id']."' AND is_active = 0"; 
		$callConfig->executeQuery($removeequipment_allocations);
	
	}
	
	return $res;
}

