function getJobPostings($get) {
    global $callConfig;
    $returnresult = array();
 
    // Sanitize inputs
    $company_id = (int) $get['company_id'];
    $rid = (int) $get['rid'];
 
    // 1. Job Postings
    $job_postingssql = "SELECT * FROM job_postings WHERE is_active = 0 AND company_id = ? AND id = ?";
    $returnresult['job_postings'] = $callConfig->getRowNew($job_postingssql, [$company_id, $rid]);
 
    // 2. Application Tags
    $application_tagssql = "SELECT * FROM application_tags WHERE company_id = ? AND application_table_name = 'job_postings' AND transaction_id = ?";
    $returnresult['application_tags'] = $callConfig->getAllRowsNew($application_tagssql, [$company_id, $rid]);
 
    // 3. Job Titles
    $job_titlesql = "SELECT id, job_title, job_description FROM job_titles WHERE is_active = 0 AND company_id = ?";
    $returnresult['job_titles'] = $callConfig->getAllRowsNew($job_titlesql, [$company_id]);
 
    // 4. Locations
    $locationssql = "SELECT id, location_name FROM locations WHERE is_active = 0 AND company_id = ?";
    $returnresult['locations'] = $callConfig->getAllRowsNew($locationssql, [$company_id]);
 
    // 5. Application Users
    $application_userssql = "SELECT id, display_name, role_id FROM application_users WHERE is_active = 0 AND company_id = ?";
    $returnresult['application_users'] = $callConfig->getAllRowsNew($application_userssql, [$company_id]);
 
    // 6. Departments
    $departmentssql = "SELECT id, department_name FROM departments WHERE is_active = 0 AND company_id = ?";
    $returnresult['departments'] = $callConfig->getAllRowsNew($departmentssql, [$company_id]);
 
    // 7. ESGIN Budget Approvals
    $esgin_budget_approvalssql = "SELECT id, transaction_number FROM esgin_budget_approvals WHERE is_active = 0 AND company_id = ?";
    $returnresult['esgin_budget_approvals'] = $callConfig->getAllRowsNew($esgin_budget_approvalssql, [$company_id]);
 
    // 8. Job Selection Process
    $job_selection_processsql = "SELECT id, process_name FROM job_selection_process WHERE is_active = 0 AND company_id = ?";
    $returnresult['job_selection_process'] = $callConfig->getAllRowsNew($job_selection_processsql, [$company_id]);
 
    // 9. Job Grade
    $job_gradesql = "SELECT id, job_grade_name FROM job_grade WHERE is_active = 0 AND company_id = ?";
    $returnresult['job_grade'] = $callConfig->getAllRowsNew($job_gradesql, [$company_id]);
 
    // 10. Customers
    $customerssql = "SELECT id, display_name FROM customers WHERE is_active = 0 AND company_id = ?";
    $returnresult['customers'] = $callConfig->getAllRowsNew($customerssql, [$company_id]);
 
    return $returnresult;
}
