function getAssetAllocationVms($get){
	global $callConfig;

	if($get['report']=='Y'){
		if($get['admin_type']!='1'){
			$auser = "SELECT emp.id,emp.display_name FROM application_users au, employees emp where au.approval_manager = 1 AND  au.is_active = emp.is_active AND au.company_id = emp.company_id AND emp.is_active = 0 AND emp.company_id = 1 AND emp.user_id = au.id";
			$auseres=$callConfig->getAllRows($auser);
			$returnresult['employees'] = $auseres;
		}else{
			$employeesql = "SELECT id,display_name FROM employees WHERE is_active = '0' AND company_id = '".$get['company_id']."'";
			$employeeres=$callConfig->getAllRows($employeesql);
			$returnresult['employees'] = $employeeres;
		}
		foreach ($returnresult['employees'] as $dataid) {
			$empid[] = $dataid->id;
		}
		$str_by_emp_ids = implode(",", (array)$empid);
		$empassetsql = "SELECT emp_ass.id, emp_ass.emp_id,emp_ass.start_date, emp_ass.end_date, emp_ass.asset_id,emp_ass.allocation_type,(SELECT asset_description From assets  WHERE assets.is_active = '0' AND assets.company_id = '".$get['company_id']."' AND assets.id =emp_ass.asset_id) as asset_name FROM emp_assets emp_ass WHERE emp_ass.is_active = '0' AND emp_ass.company_id = '".$get['company_id']."' AND emp_ass.emp_id IN('".$str_by_emp_ids."')";
		$empassetres=$callConfig->getAllRows($empassetsql);
		$returnresult['emp_assets'] = $empassetres;		
	}else{
		$assetsql = "SELECT emp_ass.asset_id as id, emp_ass.emp_id,emp_ass.start_date, emp_ass.end_date,emp_ass.remarks, emp_ass.asset_id,emp_ass.allocation_type,emp_ass.id as emp_asset_id,emp_ass.admin_buddy, (SELECT asset_description From assets  WHERE assets.is_active = '0' AND assets.company_id = '".$get['company_id']."' AND assets.id =emp_ass.asset_id) as asset_description FROM emp_assets emp_ass WHERE emp_ass.is_active = '0' AND emp_ass.company_id = '".$get['company_id']."' AND emp_ass.emp_id IN('".$get['employee']."')";

			//$empassetsql = "SELECT ass.id,ass.asset_code,ass.asset_description,emp_ass.end_date,emp_ass.remarks,emp_ass.allocation_type,emp_ass.id as emp_asset_id,emp_ass.admin_buddy FROM assets ass, emp_assets emp_ass WHERE ass.is_active =emp_ass.is_active AND ass.company_id = emp_ass.company_id AND ass.id = emp_ass.asset_id AND ass.emp_id = emp_ass.emp_id AND ass.is_active = '0' AND ass.company_id = '".$get['company_id']."' AND ass.emp_id = '".$get['employee']."' ";
		$assets=$callConfig->getAllRows($assetsql);
		$returnresult['list_assets'] = $assets;
	}
	return $returnresult;
}

function assetacceptreectvms($post){
	global $callConfig;
	$assetupdate= array('updated_date'=>date('Y-m-d H:i:s'),'updated_by'=>$post['user_id'],'allocation_type'=>$post['allocation_type'],'received_date'=>$this->dateconvertdbformat($post['received_date']),'received_note'=>$post['received_note']);
	$where = "id = '".$post['emp_asset_id']."'";
	$assetupdate=$callConfig->updateRecord("emp_assets",$assetupdate,"","",$where);
	if($post['allocation_type'] == '2'){
		$msg = "Asset Rejected";
		$assetupdatearray = array('updated_date'=>date('Y-m-d H:i:s'),'updated_by'=>$post['user_id'],'emp_id'=>null,'allocation_status'=>'N');
		$where = "id = '".$post['asset_id']."'";
		$assetupdate=$callConfig->updateRecord("assets",$assetupdatearray,"","",$where);
	}else{
		$msg = "Asset Accepted";
	}
	$user_ids = array('0'=>$post['admin_buddy']);
	$option = "COM_LIST_EMP_ASSET_REPORTS&EMP=".$post['emp_id'];
	$notdataa = array('company_id'=>$post['company_id'],'notification_message'=>$msg, 'id'=>$post['emp_asset_id'],'application_table_name'=>'emp_assets', 'type'=>'ACTION', 'notification_users'=>$user_ids,'option'=>$option);
	$sendnotification = $this->tosendnotifiations($notdataa);
	return $assetupdate;
}

