function insertCompliance($post){
	global $callConfig;
	$application_table = $post['application_table'];
	if($post['rid']!='') {
		$post_array= array("action_no"=>$post['action_no'],"task_name"=>$post['task_name'],"process_id"=>$post['process_id'],"sub_cat_id"=>$post['sub_cat_id'],"act_id"=>$post['act_id'],"sub_act_id"=>$post['sub_act_id'],"review"=>$post['review'],"review_process"=>$post['review_process'],"escalation"=>$post['escalation'],"escalation_process"=>$post['escalation_process'],"critical_compliance"=>$post['critical_compliance'],"email_content_id"=>$post['email_content_id'],"description"=>$post['description'],"action_frequency"=>$post['action_frequency'],"no_action"=>$post['no_action'],"process_type"=>$post['process_type'],"company_id"=>$post['company_id'],"check_list"=>$post['check_list'],"updated_by"=>$post['user_id'],"updated_date"=>date('Y-m-d H:i:s'),"on_the_month"=>$post['on_the_month'],"on_the_day"=>$post['on_the_day'],'on_the_day_year'=>$post['on_the_day_year'],'on_the_week'=>$post['on_the_week']);
		$res=$callConfig->updateRecord($application_table,$post_array,'id',$post['rid']);
	} else {
		$post_array= array("action_no"=>$post['action_no'],"task_name"=>$post['task_name'],"process_id"=>$post['process_id'],"sub_cat_id"=>$post['sub_cat_id'],"act_id"=>$post['act_id'],"sub_act_id"=>$post['sub_act_id'],"review"=>$post['review'],"review_process"=>$post['review_process'],"escalation"=>$post['escalation'],"escalation_process"=>$post['escalation_process'],"critical_compliance"=>$post['critical_compliance'],"email_content_id"=>$post['email_content_id'],"description"=>$post['description'],"action_frequency"=>$post['action_frequency'],"no_action"=>$post['no_action'],"process_type"=>$post['process_type'],"company_id"=>$post['company_id'],"is_active"=>'0',"check_list"=>$post['check_list'],"created_by"=>$post['user_id'],"created_date"=>date('Y-m-d H:i:s'),"on_the_month"=>$post['on_the_month'],"on_the_day"=>$post['on_the_day'],'on_the_day_year'=>$post['on_the_day_year'],'on_the_week'=>$post['on_the_week'],'current_status'=>'0');
		$res=$callConfig->insertRecord($application_table,$post_array);
		$update_transaction_id = array("transaction_id"=>$res['LASTID']);
		$res_filters =$callConfig->updateRecord(TBL_FILTER_TABLES,$update_transaction_id,'id',$post['filtertbl_rowid']);
	}
	return $res;
}
function setCompliance($get){
	global $callConfig;
	$ids =  explode(",", $get['id']);
	foreach($ids as $id){
		$sql = "INSERT INTO `compliances`( `company_id`,`process_id`, `sub_cat_id`, `act_id`, `sub_act_id`, `review`, `review_process`, `escalation`, `escalation_process`, `process_type`, `task_name`, `task_short_name`, `assigned_to`, `user_id`, `email_content_id`, `no_action`, `on_the_day`, `on_the_week`, `on_the_month`, `on_the_day_year`, `action_no`, `action_frequency`, `critical_compliance`, `before_or_after`, `description`, `files`, `display_color`, `display_background_color`, `remarks`, `task_for`, `check_list`, `is_active`, `current_status`,`created_date`, `created_by`) SELECT ".$get['company_id'].", `process_id`, `sub_cat_id`, `act_id`, `sub_act_id`, `review`, `review_process`, `escalation`, `escalation_process`, `process_type`, `task_name`, `task_short_name`, `assigned_to`, `user_id`, `email_content_id`, `no_action`, `on_the_day`, `on_the_week`, `on_the_month`, `on_the_day_year`, `action_no`, `action_frequency`, `critical_compliance`, `before_or_after`, `description`, `files`, `display_color`, `display_background_color`, `remarks`, `task_for`, `check_list`, `is_active`, `current_status`,'".date('Y-m-d h:i:s')."', '".$get['user_id']."' FROM `process_task_settings` WHERE is_active = 0 AND id IN('".$id."')";
		$insert_task = $callConfig->executeQuery($sql);
		$returaray['compliances'][] = $insert_task;
		$sql = "INSERT INTO `filter_tables`(`company_id`,`module_setup_id`, `application_tablename`, `transaction_id`, `content`, `filter_condition`, `is_active`, `current_status`,`created_date`, `created_by`)   SELECT '".$get['company_id']."','".$callConfig->module_id."','compliances','".$insert_task['LASTID']."', `content`, `filter_condition`, `is_active`, `current_status`,'".date('Y-m-d h:i:s')."', '".$get['user_id']."' FROM `filter_tables` WHERE application_tablename = 'process_task_settings' AND is_active = 0 AND transaction_id IN('".$id."')";
		$insert_task = $callConfig->executeQuery($sql);
		//$returaray[] = $sql;  ,'module_setup_id'=>$callConfig->module_id
		$returaray['compliances'][] = $insert_task;
	}
	return $returaray;
}

function setComplianceAllocation($get){
	global $callConfig; 
	$start_date = $get['start_date'];
	$end_date = $get['end_date'];
	$compliancesql = "SELECT id,task_name,check_list,action_frequency,no_action,on_the_day,on_the_week,on_the_month,on_the_day_year,action_no,critical_compliance FROM compliances WHERE is_active='0' and company_id='".$get['company_id']."'"; 
	$complianceres = $callConfig->getAllRows($compliancesql);
	foreach($complianceres as $getid){
		$idarry[] = $getid->id;
	}
	$complianid = implode(',',(array)$idarry);
	$filtersql = "SELECT id,content,filter_condition,transaction_id FROM filter_tables WHERE application_tablename = 'compliances' AND transaction_id IN(".$complianid.") AND is_active='0' and company_id='".$get['company_id']."'"; 
	$filterres = $callConfig->getAllRows($filtersql);
	foreach($filterres as $filterre){
		$show_filter_cond = $filterre->filter_condition;
		$show_filter_cond = explode('&',$show_filter_cond);
		foreach($show_filter_cond as $show_filter_co){
			$fieldname = explode("=",$show_filter_co);
			$show_filter_condion[$fieldname['0']]=$fieldname['1'];
		}
		$filterresult[$filterre->transaction_id] = $show_filter_condion;
	}
	foreach($complianceres as $row){
		$condition = "";
		unset($filterresult[$row->id]['table']);
		unset($filterresult[$row->id]['check']);
		foreach($filterresult[$row->id] as $keys=>$vale){
			if($vale !=""){
				$condition .= ' AND '.$keys.'  IN ('.$vale.')';
			}
		}
		$employeesql = "SELECT id FROM employees WHERE is_active='0' and company_id='".$get['company_id']."'".$condition; 
		$employeesres = $callConfig->getAllRows($employeesql);	
		$sql= "";
		$sql ="INSERT INTO `compliance_task_histories`(`company_id`, `compliance_id`, `emp_id`, `name`,`check_list`,`task_date`, `is_active`, `current_status`,`created_date`, `created_by`) VALUES"; 
		for ($i = strtotime($start_date); $i <= strtotime($end_date); $i = strtotime('+1 day', $i)) {
			$task_date = date('Y-m-d',$i);
				//echo $task_date ."</br>";
			if($row->action_frequency == 'DY'){
				foreach($employeesres as $empid){
					$sql .= "('".$get['company_id']."','".$row->id."','".$empid->id."','".$row->task_name."','".$row->check_list."','".$task_date."','0','0','".date('Y-m-d h:i:s')."','".$get['user_id']."'),";
				}
			}
			if($row->action_frequency == 'WK'){
				if(date('D',$i) == $row->on_the_week){
					foreach($employeesres as $empid){
						$sql .= "('".$get['company_id']."','".$row->id."','".$empid->id."','".$row->task_name."','".$row->check_list."','".$task_date."','0','0','".date('Y-m-d h:i:s')."','".$get['user_id']."'),";
					}
				}
			}
			if($row->action_frequency == 'MN'){
				if(date('d', $i) == $row->on_the_day){
					foreach($employeesres as $empid){
						$sql .= "('".$get['company_id']."','".$row->id."','".$empid->id."','".$row->task_name."','".$row->check_list."','".$task_date."','0','0','".date('Y-m-d h:i:s')."','".$get['user_id']."'),";
					} 
				}
			} 
			if($row->action_frequency == 'YR'){
				if(date('m', $i) == $row->on_the_month AND date('d', $i) == $row->on_the_day_year){
					foreach($employeesres as $empid){
						$sql .= "('".$get['company_id']."','".$row->id."','".$empid->id."','".$row->task_name."','".$row->check_list."','".$task_date."','0','0','".date('Y-m-d h:i:s')."','".$get['user_id']."'),";
					} 
				}
			} 
		}
		$sqln  = rtrim($sql, ",");
		$res = $callConfig->executeQuery($sqln);
		$returnarr[] = $res;
	}
	return $returnarr;
}
function getCompliancesDashbord($get){
	global $callConfig; 
	if($get['type']=="popup"){
		$taskhistorysql = "SELECT cth.id,cth.emp_id,emp.display_name,cth.name,cth.check_list,cth.comments,cth.task_date,cth.current_status FROM compliance_task_histories cth, employees emp WHERE emp.is_active=cth.is_active and cth.company_id=emp.company_id AND emp.id = cth.emp_id AND cth.is_active='0' and cth.company_id='".$get['company_id']."' AND cth.compliance_id ='".$get['id']."'  AND cth.task_date ='".$get['date']."' "; 
		$taskhistoryres = $callConfig->getAllRows($taskhistorysql); 
		$returnresult['compliance_task_histories'] = $taskhistoryres;
	}elseif($get['type']=="employeetask"){
			//$get['emp_id'] = 6;
		$taskhistorysql = "SELECT id,compliance_id,name,task_date,check_list FROM compliance_task_histories WHERE is_active='0' and company_id='".$get['company_id']."' AND emp_id = '".$get['emp_id']."' AND task_date = '".$get['date']."'"; 
		$retaray = $callConfig->getAllRows($taskhistorysql);
		$returnresult['compliance_task_histories'] = $retaray;
	}elseif($get['type']=="getsingletaskhistory"){
		$taskhistorysql = "SELECT id,compliance_id,name,task_date,check_list FROM compliance_task_histories WHERE is_active='0' and company_id='".$get['company_id']."' AND id = '".$get['id']."'"; 
		$retaray = $callConfig->getRow($taskhistorysql);
		$returnresult['compliance_task_histories'] = $retaray;
	}else{
		$start_date = $get['start_date'];
		$end_date = $get['end_date'];
		$compliancesql = "SELECT id,task_name,action_frequency FROM compliances WHERE is_active='0' and company_id='".$get['company_id']."'"; 
		$complianceres = $callConfig->getAllRows($compliancesql);
		foreach($complianceres as $getid){
			$idarry[] = $getid->id;
			$compliancretaray[$getid->action_frequency][] = $getid;
		}
		$complianid = implode(',',(array)$idarry);
		$taskhistorysql = "SELECT compliance_id,name,task_date,min(current_status) as current_status ,max(completion_date) as completion_date FROM compliance_task_histories WHERE is_active='0' and company_id='".$get['company_id']."' AND compliance_id IN(".$complianid.") GROUP BY compliance_id,task_date"; 
		$taskhistoryres = $callConfig->getAllRows($taskhistorysql);
		foreach($taskhistoryres as $taskhistoryre){
			$retaray[$taskhistoryre->compliance_id][] = $taskhistoryre;
		}
		$returnresult['compliances'] = $compliancretaray;
		$returnresult['compliance_task_histories'] = $retaray;
	}	
	return $returnresult;	
}
function insertComplianceTaskAnswer($post){
	global $callConfig;
	$alldone = 0;
	$status = '0';
	$check_list = json_decode($post['check_list'], 1);
	$check_list[$post['aryposition']]['check_value']= "0";
	$check_list[$post['aryposition']]['comment']= $post['comment'];
	$check_lists =  json_encode($check_list);
	foreach($check_list as $check_lits){
		if($check_lits['check_value']!=''){
			$alldone++;
		}
	}
	$post_array= array("check_list"=>$check_lists);
	if(count((array)$check_list) == $alldone){
		$post_array['current_status']=ST_APPROVED;
		$post_array['completion_date']=date("Y-m-d");

		$status = ST_APPROVED;
	}
	$array['count'] = count((array)$check_list);
	$array['alldone'] = $alldone;
	$array['status'] = $status;
	$res=$callConfig->updateRecord('compliance_task_histories',$post_array,'id',$post['rid']);		
	return $array;
}
