function insertApplicationUserRole($postry,$rid){
	global $callConfig;
	$updatefileds = array('is_active'=>'');
	$where = "company_id = '".$postry['company_id']."' AND module_group_id = '".$callConfig->module_group_id."' AND user_id  = '".$rid."'";
	$res1=$callConfig->updateRecord("application_user_roles",$updatefileds,"","",$where);
	$dvdfv['update'] = $res1;
	foreach($postry['role_id'] as $postary){
		$checkroleinsertsql = "SELECT id FROM application_user_roles WHERE company_id='".$postry['company_id']."' AND module_group_id='".$callConfig->module_group_id."' AND  user_id = '".$rid."' AND role_id = '".$postary."'"; 
		$checkroleinsertres = $callConfig->getRow($checkroleinsertsql);
		if(isset($checkroleinsertres->id)){
			$post_array= array("user_id"=>$rid,"module_group_id"=>$callConfig->module_group_id,"role_id"=>$postary,"current_status"=>"0","updated_date"=>date('Y-m-d H:i:s'),'company_id'=>$postry['company_id'],"updated_by"=>$postry['user_id'],'is_active'=>'0');
			$res=$callConfig->updateRecord('application_user_roles',$post_array,'id',$checkroleinsertres->id);
		}else{
