function getempbuddies($data){
	global $callConfig;
	$emp_id = $data['emp_id'];
	$company_id = $data['company_id'];
	$query_sal = "SELECT (SELECT user_id FROM employees emp2 WHERE emp2.company_id = emp1.company_id  AND emp2.id  = emp1.hr_buddy) as hr_buddy,(SELECT user_id FROM employees emp3 WHERE emp3.company_id = emp1.company_id  AND emp3.id  = emp1.finance_buddy) as finance_buddy,(SELECT user_id FROM employees emp4 WHERE emp4.company_id = emp1.company_id  AND emp4.id  = emp1.admin_buddy) as admin_buddy,(SELECT user_id FROM employees emp5 WHERE emp5.company_id = emp1.company_id  AND emp5.id  = emp1.project_buddy) as project_buddy,(SELECT user_id FROM employees emp6 WHERE emp6.company_id = emp1.company_id  AND emp6.id  = emp1.loc_buddy) as loc_buddy FROM employees emp1  WHERE emp1.company_id = '".$company_id."' AND emp1.id = '".$emp_id."' AND emp1.is_active = 0";
	$res = $callConfig->getRow($query_sal);
	$hr_connect_id = $res->hr_buddy!=''?$res->hr_buddy:"NOT-DEFINED";
	$finance_connect_id = $res->finance_buddy!=''?$res->finance_buddy:"NOT-DEFINED";
	$admin_connect_id = $res->admin_buddy!=''?$res->admin_buddy:"NOT-DEFINED";
	$project_connect_id = $res->project_buddy!=''?$res->project_buddy:"NOT-DEFINED";
	$location_connect_id = $res->project_buddy!=''?$res->project_buddy:"NOT-DEFINED";
	$connectdetails = array('hr_connect'=>$hr_connect_id,'finance_connect'=>$finance_connect_id,'admin_connect'=>$admin_connect_id,'project_connect'=>$project_connect_id,'location_connect_id'=>$location_connect_id);
	return $connectdetails;	
}
