function getWrokflowSteps($get){
	global $callConfig;
		//$logsql ="SELECT MAX(workflow_id) as workflow_id FROM `transaction_approval_logs` WHERE company_id = '".$get['company_id']."' AND transaction_table = '".$get['table']."' AND transaction_id = '".$get['rid']."' AND workflow_id IS NOT NULL";
		//$logdetails = $callConfig->getRow($logsql); 
		//$sql1 = "select * from workflow_configuration where process_type='".$get['table']."'  and company_id = '".$get['company_id']."' AND id = '".$logdetails->workflow_id."' and is_active = 0 ORDER BY `process_priority` ASC";  // table name and exicution type creation and update
		//$data1 = $callConfig->getRow($sql1);
		//$statussteps = json_decode($data1->approve_update_status,1);
	$creatsql ="SELECT created_by FROM ".$get['table']." WHERE company_id = '".$get['company_id']."'  AND id = '".$get['rid']."'";
	$creatres = $callConfig->getRow($creatsql);
	$logresar['c'] =$creatres->created_by;
	$logsql ="SELECT user_id,response_type FROM `transaction_approval_logs` WHERE company_id = '".$get['company_id']."' AND  transaction_table = '".$get['table']."' AND transaction_id = '".$get['rid']."' AND send_back_flag = 0";
	$logres = $callConfig->getAllRows($logsql);
	foreach($logres as $logres0){
		$logresar[$logres0->response_type] =$logres0->user_id;
	}

	$workfsql ="SELECT workflow_id,process_type,approve_update_status FROM `workflow_configuration_histories` WHERE company_id = '".$get['company_id']."' AND process_type = '".$get['table']."' AND transaction_id = '".$get['rid']."'";
	$workfres = $callConfig->getRow($workfsql);
	$statussteps = json_decode($workfres->approve_update_status,1);
	$returnarray['status'] = $statussteps;
	$returnarray['workflow_id'] = $logdetails->workflow_id;
		$statsu_progressql = "select status,action_label from status_progress where table_name='".$get['table']."'  and company_id = '".$get['company_id']."' and is_active = 0";  // table name and exicution type creation and update
		$statsu_progresres = $callConfig->getAllRows($statsu_progressql);
		$status = array();
		$statustep = array();
		foreach($statsu_progresres as $statsu_progresre){
			$status[$statsu_progresre->status] = $statsu_progresre->action_label;
		}
		foreach($statussteps as $statusstepr){
			$statusstepr['action_label'] = $status[$statusstepr['status']];
			$statustep[] = $statusstepr;
		}
		$returnaray = array("steps"=>$statustep,"log"=>$logresar);
		return $returnaray;
		
	}
