	function getToCheckLeaveTypeCriteria($get){
		global $callConfig;
		$respons = array(); 
		$query ="SELECT lt.employee_filter,lt.leave_category_id,lt.leave_category_id,elb.applicable_leaves,elb.consumed_leaves,(elb.applicable_leaves-elb.consumed_leaves) as available_leave, ( SELECT lc.name  from leave_categories lc  WHERE lt.leave_category_id = lc.id AND lc.is_active = lt.is_active) category_name,lt.back_ground_color,lt.icon FROM leave_types lt, emp_leave_balances elb  WHERE lt.company_id = '".$get['company_id']."' AND lt.is_active = 0 AND lt.company_id = elb.company_id AND lt.is_active = elb.is_active AND lt.id = elb.leave_type AND elb.employee_id = '".$get['emp_id']."'";

		$returnarray['query'] = $query;
		$leave_type=$callConfig->getAllRows($query); 
		foreach($leave_type as $leaevtyperesult){
			$condition = "";
			$employee_filter = json_decode($leaevtyperesult->employee_filter,1);
			$resultreturn['employee_filter'][] = $employee_filter;
			if($employee_filter !=""){  
				$jsoncontain = $leaevtyperesult->employee_filter;
				$decodejsoncontain = json_decode($jsoncontain,1);
				foreach($decodejsoncontain as $keys=>$vale){
					$st = "";
					foreach($vale as $keym=>$vs){
						$st .= "'".$keym."',";
					}
					$st =rtrim($st, ", ");
					$condition .= ' AND '.$keys.'  IN ('.$st.')';
				}
				$respons[$leaevtyperesult->leave_category_id]['leavedetails'] = $leaevtyperesult;
				//$employee_detailssql = "select id FROM employees where company_id =".$get['company_id']." AND is_active='0'".$condition;
				$employee_detailssql = "select id FROM employees where id = '".$get['emp_id']."' AND company_id = '".$get['company_id']."'  AND is_active='0' ".$condition;
				$respons[$leaevtyperesult->leave_category_id]['criteria_sql'] =$employee_detailssql;
				$empyescriteria=$callConfig->getRow($employee_detailssql);
				if(isset($empyescriteria->id)){
					$categoryavailable[$leaevtyperesult->leave_category_id] = $leaevtyperesult->category_name;
				}
			}
		}
		$returnarray['leavetype_detrails'] = $respons;
		$returnarray['available_category'] = $categoryavailable;
		$sendemployedetails = array('employee_id'=>$get['emp_id'],'company_id'=>$get['company_id']);
		$returnresp = $this->getempconnectwithempid($sendemployedetails);
		$returnarray['buddy_details'] = $returnresp;
		return $returnarray;
	}






	function getempconnectwithempid($get){
		global $callConfig;
		$employee_id = $get['employee_id'];
		$company_id = $get['company_id'];
		$query_sal = "SELECT emp1.location_id,(SELECT user_id FROM employees emp2 WHERE emp2.company_id = emp1.company_id  AND emp2.id  = emp1.hr_buddy) as hr_buddy,(SELECT user_id FROM employees emp3 WHERE emp3.company_id = emp1.company_id  AND emp3.id  = emp1.finance_buddy) as finance_buddy,(SELECT user_id FROM employees emp4 WHERE emp4.company_id = emp1.company_id  AND emp4.id  = emp1.admin_buddy) as admin_buddy,(SELECT user_id FROM employees emp5 WHERE emp5.company_id = emp1.company_id  AND emp5.id  = emp1.project_buddy) as project_buddy,(SELECT user_id FROM employees emp6 WHERE emp6.company_id = emp1.company_id  AND emp6.id  = emp1.loc_buddy) as loc_buddy,(SELECT au.reports_to FROM application_users au WHERE au.company_id = emp1.company_id  AND au.id  = emp1.user_id) as report_to FROM employees emp1  WHERE emp1.company_id = '".$company_id."' AND emp1.id = '".$employee_id."' AND emp1.is_active = 0";
		$res = $callConfig->getRow($query_sal);
		$report_to = $res->report_to!=''?$res->report_to:"0";
		$hr_connect_id = $res->hr_buddy!=''?$res->hr_buddy:"0";
		$finance_connect_id = $res->finance_buddy!=''?$res->finance_buddy:"0"; 
		$admin_connect_id = $res->admin_buddy!=''?$res->admin_buddy:"0";
		$project_connect_id = $res->project_buddy!=''?$res->project_buddy:"0";
		$location_connect_id = $res->loc_buddy!=''?$res->loc_buddy:"0";

		$location_id =$res->location_id;
		if($hr_connect_id==0 || $hr_connect_id==""){
			$hrconnect_data = "select * from locations where company_id='".$company_id."' and is_active='0' and id='".$location_id."'";
			$hrconnect_details = $callConfig->getRow($hrconnect_data);
			$hr_connect_id = $hrconnect_details->hr_connect;
			if($hr_connect_id==0 || $hr_connect_id=="" ){
				$hrconnect_data = "select * from companies where company_id='".$company_id."' and is_active='0'";
				$hrconnect_details = $callConfig->getRow($hrconnect_data);
				$hr_connect_id = $hrconnect_details->hr_connect;
			}
			if($hr_connect_id==0 || $hr_connect_id=="" ) {
				$hr_connect_id = "0";
			}
		}

		if($finance_connect_id==0 || $finance_connect_id==""){
			$hrconnect_data = "select * from locations where company_id='".$company_id."' and is_active='0' and id='".$location_id."'";
			$hrconnect_details = $callConfig->getRow($hrconnect_data);
			$finance_connect_id = $hrconnect_details->finance_connect;
			if($finance_connect_id==0 || $finance_connect_id=="" ) {
				$hrconnect_data = "select * from companies where company_id='".$company_id."' and is_active='0'";
				$hrconnect_details = $callConfig->getRow($hrconnect_data);
				$finance_connect_id = $hrconnect_details->finance_connect;
			}
			if($finance_connect_id==0 || $finance_connect_id=="" ) {
				$finance_connect_id = "0";
			}
		}

		if($admin_connect_id==0 || $admin_connect_id==""){
			$hrconnect_data = "select * from locations where company_id='".$company_id."' and is_active='0' and id='".$location_id."'";
			$hrconnect_details = $callConfig->getRow($hrconnect_data);
			$admin_connect_id = $hrconnect_details->admin_connect;
			if($admin_connect_id==0 || $admin_connect_id=="" ) {
				$hrconnect_data = "select * from companies where company_id='".$company_id."' and is_active='0'";
				$hrconnect_details = $callConfig->getRow($hrconnect_data);
				$admin_connect_id = $hrconnect_details->admin_connect;
			}
			if($admin_connect_id==0 || $admin_connect_id=="" ) {
				$admin_connect_id = "0";
			}
		}

		$connectdetails = array('hr_connect'=>$hr_connect_id,'finance_connect'=>$finance_connect_id,'admin_connect'=>$admin_connect_id,'project_connect'=>$project_connect_id,'location_connect_id'=>$location_connect_id,'report_to'=>$report_to);
		return $connectdetails;
	}
		
	function dateformates($pdate,$formate,$sparater){
		//echo $formate;
		$array = array('DD'=>'d','MM'=>'m','YYYY'=>'Y');
		$formates = explode('-', $formate);
		$return = "";
		foreach ($formates as  $value) {
			$return.= $array[$value].$sparater;
		}
		$return = trim($return,$sparater);
		return date($return, strtotime($pdate) );
	}
