	function getOrganizationGoalsSetails($get){
		global $callConfig;
		$retuenres = array();
		if($get['kra_list'] == "Y"){  //ajax call used 
			$krasql = "SELECT id,area_name,description FROM appraisal_key_result_areas WHERE id IN(".$get['kpaidlist'].") AND company_id='".$get['company_id']."' AND is_active=0"; 
			$krares = $callConfig->getAllRows($krasql);
			$retuenres['kralist'] = $krares;

			foreach($krares as $krares11){
				$kraarray[] = $krares11->id;
			}
			$kraids = implode(",",(array)$kraarray);
			$kpisql = "SELECT kpi.id,kpi.indicator_name,kpi.key_reslut_id,kpi.weightage,kpi.model,kpi.uom,kpi.display_sequence,kpi.role_id,(SELECT GROUP_CONCAT(kt.id SEPARATOR ',') AS id FROM kpi_tasks kt WHERE kpi.company_id = kt.company_id AND kpi.id = kt.kpi_id AND kpi.is_active = kt.is_active GROUP BY kt.kpi_id) as kpi_tasks_ids FROM appraisal_key_performance_indicators kpi WHERE kpi.company_id='".$get['company_id']."'  AND kpi.is_active=0 AND kpi.key_reslut_id IN(".$kraids.")"; 
			$kpires = $callConfig->getAllRows($kpisql);
			$retuenres['kpilist'] = $kpires;

			$krasql ="SELECT og.id as ogid,kra.id,og.job_title_id,og.department_id,og.location_id,og.key_performance_id,og.traget,og.assessment_frequency FROM organization_goals og, appraisal_key_result_areas kra WHERE og.company_id = kra.company_id AND og.company_id = '".$get['company_id']."' AND og.key_reslut_id = kra.id AND og.is_active = 0 AND og.is_active = kra.is_active AND og.id IN (".$get['krakpiid'].")";
			$krares = $callConfig->getAllRows($krasql);
			$retuenres['kralid'] = $krares;

		}else{ //user side list
			$krasql = "SELECT id,area_name,description FROM appraisal_key_result_areas WHERE company_id='".$get['company_id']."'  AND is_active=0"; 
			$krares = $callConfig->getAllRows($krasql);
			$retuenres['kralist'] = $krares;

			foreach($krares as $krares11){
				$kraarray[] = $krares11->id;
			}
			$kraids = implode(",",(array)$kraarray);
			$kpisql = "SELECT kpi.id,kpi.indicator_name,kpi.key_reslut_id,kpi.weightage,kpi.model,kpi.uom,kpi.display_sequence,kpi.role_id,(SELECT GROUP_CONCAT(kt.id SEPARATOR ',') AS id FROM kpi_tasks kt WHERE kpi.company_id = kt.company_id AND kpi.id = kt.kpi_id AND kpi.is_active = kt.is_active GROUP BY kt.kpi_id) as kpi_tasks_ids FROM appraisal_key_performance_indicators kpi WHERE kpi.company_id='".$get['company_id']."'  AND kpi.is_active=0 AND kpi.key_reslut_id IN(".$kraids.")"; 
			$kpires = $callConfig->getAllRows($kpisql);
			$retuenres['kpilist'] = $kpires;
		}	
		$modellistsql = "SELECT genc_detail_code,genc_detail_name  FROM ".TBL_GENRAL_CODE_DETAILS." WHERE company_id='".$get['company_id']."' AND genc_code='KPIMODAL' AND is_active=0"; 
		$modellistres = $callConfig->getAllRows($modellistsql);
		$retuenres['modellist'] = $modellistres;

		$uomsql = "SELECT genc_detail_code,genc_detail_name  FROM ".TBL_GENRAL_CODE_DETAILS." WHERE company_id='".$get['company_id']."' AND genc_code='KPIUOM' AND is_active=0"; 
		$uomres = $callConfig->getAllRows($uomsql);
		$retuenres['uomllist'] = $uomres;

		$frequencysql = "SELECT genc_detail_code,genc_detail_name  FROM ".TBL_GENRAL_CODE_DETAILS." WHERE company_id='".$get['company_id']."' AND genc_code='TASKFREQUENCY' AND is_active=0"; 
		$frequencyres = $callConfig->getAllRows($frequencysql);
		$retuenres['frequencylist'] = $frequencyres;

		return $retuenres;
	}
function getJobTitleCompetencies($get){
	global $callConfig;
	$retuenres = array();
		//$retuenres['get'] = $get;
		if($get['checkassetyear'] == 'Y'){ // check assetment year already enter or not
			$jobtitlecompetenciessql = "SELECT id FROM job_title_competencies WHERE company_id='".$get['company_id']."' AND is_active=0 AND assessment_year = '".$get['assessment_year']."'"; 
			$jobtitlecompetenciesres = $callConfig->getRow($jobtitlecompetenciessql);
			$status = (isset($jobtitlecompetenciesres->id))?"Y":"N";
			$retuenres['job_title_competencies'] = $status;
		}else{
			$competenciessql = "SELECT id,competency_name,remarks FROM competencies WHERE company_id='".$get['company_id']."' AND is_active=0"; 
			$competencieres = $callConfig->getAllRows($competenciessql);
			$retuenres['competencieslist'] = $competencieres;

			$jobtitlessql = "SELECT id,job_title FROM job_titles WHERE company_id='".$get['company_id']."' AND is_active=0"; 
			$jobtitlesres = $callConfig->getAllRows($jobtitlessql);
			$retuenres['job_titles'] = $jobtitlesres;

			$competencylevelssql = "SELECT id,competency_id,level_name,Requirement FROM competency_levels WHERE company_id='".$get['company_id']."' AND is_active=0"; 
			$competencylevelsres = $callConfig->getAllRows($competencylevelssql);
			$retuenres['competency_levels'] = $competencylevelsres;

			$jobtitlecompetenciessql = "SELECT id,job_title_id,competency_id,competency_level_id,assessment_year FROM job_title_competencies WHERE company_id='".$get['company_id']."' AND is_active=0 AND assessment_year = '".$get['assessment_year']."' AND appraisal_id = '".$get['appraisal_id']."'"; 
			$jobtitlecompetenciesres = $callConfig->getAllRows($jobtitlecompetenciessql);
