	function insertJobTitleCompetencies($post){
		global $callConfig;
		$returnaray = array();
		
		if($post['type'] == 'update'){
			$updatearray=array('competency_level_id'=>$post['competency_level_id'],'updated_date'=>date('Y-m-d h:i:s'),'updated_by'=>$post['user_id']);
			$res=$callConfig->updateRecord('job_title_competencies',$updatearray,'id',$post['id']);
		}else{
			$insertsql = "INSERT INTO `job_title_competencies`(`company_id`, `job_title_id`, `competency_id`, `competency_level_id`, `assessment_year`,`appraisal_id`, `is_active`, `current_status`, `created_date`, `created_by`) VALUES ";
			foreach($post['competency_level'] as $job_title_id => $resul1){
				foreach($resul1 as $competency_id => $resul2){ $levelid = $resul2 !=""?$resul2:0;
				$insertsql .= "('".$post['company_id']."','".$job_title_id."','".$competency_id."','".$levelid."','".$post['assessment_year']."','".$post['appraisal_id']."','0','0','".date('Y-m-d h:i:s')."','".$post['user_id']."'),";
			}
		}
		$insertsql = rtrim($insertsql, ',');
		$res = $callConfig->executeQuery($insertsql);
		$returnaray['insertsql'] = $insertsql;
	}  
	$returnaray['exicute'] = $res;
	return $returnaray;
}
