function inserPerformanaceAppraiserHeader($post){
	global $callConfig;
	$returnaray = array();
	if($post['new_entry'] =="Y"){
		$sub_header_name = '[{"field_name":"heading","type":"T","EMP":"Y","RO":"Y","HOD":"Y"}]';
		$header_display_setting = '{"EMP":"Y","RO":"Y","HOD":"Y"}';
		$insert_array = array('company_id'=>$post['company_id'],'assessment_year'=>$post['assessment_year'],'appraisal_id'=>$post['appraisal_id'],'header_name'=>'Please Enter Header','sub_header_name'=>$sub_header_name,'header_display_setting'=>$header_display_setting,'header_comment'=>'Please Enter Sub Header','sub_header_addmore'=>'0','sub_header_default_row'=>'1','is_active'=>'0','current_status'=>'0','created_by'=>$post['user_id'],'created_date'=>date('Y-m-d h:i:s'));
		$insert = $callConfig->insertRecord('performance_appraisal_headers',$insert_array); 
	}else{ 
		$sub_header_name_a = array();
		foreach($post['field_name'] as $key=>$name){
			$field_employee = (isset($post['field_employee'][$key]))?"Y":"N";
			$field_ro = (isset($post['field_ro'][$key]))?"Y":"N";
			$field_hod = (isset($post['field_hod'][$key]))?"Y":"N";
			$sub_header_name_a[] = array('field_name'=>$name,'type'=>$post['type'][$key],'EMP'=>$field_employee,'RO'=>$field_ro,'HOD'=>$field_hod);
		}
		$dynamic_page  = ($_POST['dynamic_page']=="0")?"0":"1"; 
		$sub_header_addmore  = ($_POST['sub_header_addmore']=="0")?"0":"1"; 
		$displayemployee  = $_POST['displayemployee']=="Y"?"Y":"N"; 
		$displayro  = $_POST['displayro']=="Y"?"Y":"N"; 
		$displayhod  = $_POST['displayhod']=="Y"?"Y":"N"; 
		$header_display_setting_a = array('EMP'=>$displayemployee,'RO'=>$displayro,'HOD'=>$displayhod); 
		$header_display_setting =  json_encode($header_display_setting_a); 
		$sub_header_name = json_encode($sub_header_name_a);  
		$insert_array = array('header_name'=>$post['header_name'],'header_comment'=>$post['header_comment'],'sub_header_name'=>$sub_header_name,'sub_header_addmore'=>$sub_header_addmore,'sub_header_default_row'=>$post['sub_header_default_row'],'header_display_setting'=>$header_display_setting,'dynamic_page'=>$dynamic_page,'page_name'=>$post['page_name'],'updated_by'=>$post['user_id'],'updated_date'=>date('Y-m-d h:i:s'));
		$insert = $callConfig->updateRecord('performance_appraisal_headers',$insert_array,'id',$post['pah_id']);
	}	
	$returnaray['exicute'] = $insert;
		//$returnaray['insertarray'] = $insert_array;
		//$returnaray['jsonsub_header_name'] = $header_display_setting_a;
		//$returnaray['sub_header_name_a'] = $sub_header_name_a; 
		//$returnaray['post'] = $post;
	return $returnaray;
}


