	function insertPerformanceSetup($get){
		global $callConfig;
		$returnarray = array();
		$insert_array = array('name'=>$get['name'],'url'=>$get['url'],'file_name'=>$get['file_name'],'assessment_start_date'=>$this->dateconvertdbformat($get['assessment_begin']),'assessment_end_date'=>$this->dateconvertdbformat($get['assessment_due']),'employee_start'=>$this->dateconvertdbformat($get['employee_begin']),'employee_end'=>$this->dateconvertdbformat($get['employee_end']),'manager_start'=>$this->dateconvertdbformat($get['manager_begin']),'manager_end'=>$this->dateconvertdbformat($get['manager_end']),'reporting_manager_start'=>$this->dateconvertdbformat($get['managerto_begin']),'reporting_manager_end'=>$this->dateconvertdbformat($get['managerto_end']),'assessment_month'=>$get['assessment_month'],'assessment_year'=>$get['assessment_year']);
		if($get['rid'] !=""){
			$insert_array['updated_by'] = $get['userid'];
			$insert_array['updated_date'] = date('Y-m-d h:i:s');
			$insert = $callConfig->updateRecord('performance_setup',$insert_array,'id',$get['rid']);
			$rid = $get['rid'];
		}else{
			$insert_array['company_id'] = $get['company_id'];
			$insert_array['is_active'] = '0';
			$insert_array['current_status'] = '0';
			$insert_array['created_by'] = $get['userid'];
			$insert_array['created_date'] = date('Y-m-d h:i:s');
			$insert = $callConfig->insertRecord('performance_setup',$insert_array);
			$rid = $insert['LASTID'];
		}
		$returnarray['insert'] = $insert;
		$update_transaction_id = array("transaction_id"=>$rid);
		if($get['filtertbl_rowid'] !=""){
			$res_filters =$callConfig->updateRecord(TBL_FILTER_TABLES,$update_transaction_id,'id',$get['filtertbl_rowid']);
			$returnarray['res_filters'] = $res_filters;
		}
		return $returnarray;
	}

