function getViewPerFormanceAppraisalSettig($get){
	global $callConfig;
	$retuenres = array();
	$performancesetupsql = "SELECT id,publish,assessment_year  FROM performance_setup WHERE id = '".$get['appraisal_id']."' AND  company_id = '".$get['company_id']."' AND  is_active =0 ";
	$performancesetupres = $callConfig->getRow($performancesetupsql);
	$retuenres['performance_setup'] = $performancesetupres;

	$pasettingsql = "SELECT appraisal_setting_id FROM performance_appraisal_setting_histories WHERE company_id = '".$get['company_id']."' AND is_active = 0 AND appraisal_id='".$get['appraisal_id']."' AND applicable = 0"; 
	$pasettingres = $callConfig->getAllRows($pasettingsql);
	$appraisal_setting_id = array();
	foreach($pasettingres as $pasettingres){
		$appraisal_setting_id[$pasettingres->appraisal_setting_id] = $pasettingres->appraisal_setting_id; 
	}
	$retuenres['check_performance_appraisal_settings'] = $appraisal_setting_id;

	$pasettingsql = "SELECT id,performance_area,performance_area_name,applicable,url,display_sequence,tab_sequence FROM performance_appraisal_settings WHERE company_id = '".$get['company_id']."' AND is_active = 0 order by tab_sequence ASC"; 
	$pasettingres = $callConfig->getAllRows($pasettingsql);
	$retuenres['performance_appraisal_settings'] = $pasettingres;
	return $retuenres;

}

