				$insert_array['updated_date'] =date('Y-m-d h:i:s');
				$update = $callConfig->updateRecord($post['table'],$insert_array,'id',$post['kpi_task_id_'.$i]);
				$kpitaskid[] = $post['kpi_task_id_'.$i];
				$returnaray['insertorupdate'] = $update;
			}else{
				$insert_array['created_by'] =$get['user_id'];
				$insert_array['created_date']=date('Y-m-d h:i:s');
				if($post['kpi_id'] != ''){
						$insert_array[$array_id[$post['table']]]=$post['kpi_id']; //already created kpi id
