	/*android app*/
	function getPayRunSummarySalary($get){
		global $callConfig;
		$retuenres = array();
		$frommonth = date("m",strtotime($get['startdate']));
		$fromyear = date("Y",strtotime($get['startdate']));
		$tomonth = date("m",strtotime($get['enddate']));
		$toyear = date("Y",strtotime($get['enddate']));
		$prscomponanlist = array();
		$salarytemplatesql = "SELECT id,declaration_tax FROM emp_it_declaration WHERE company_id = '".$get['company_id']."'  AND emp_id ='".$get['employee_id']."' AND assessment_year ='".$get['assessment_year']."' AND is_active =0 ";
		$salarytemplateres = $callConfig->getRow($salarytemplatesql);
		$retuenres['emp_it_declaration'] = $salarytemplatesql;
		$itd_tax_amount = $salarytemplatesql->declaration_tax;
		$salary_templatesql = "SELECT id,ctc_yearly FROM salary_template WHERE company_id = '".$get['company_id']."'  AND employee_id ='".$get['employee_id']."' AND year(status_date) = ".$get['pay_year']." AND is_active =0 ";
		$salary_templateres = $callConfig->getRow($salary_templatesql);
		$retuenres['salary_templateres'] = $salary_templatesql;
		$calslab_total = $salary_templateres->ctc_yearly - $itd_tax_amount; 

		$tax_sladssql = "SELECT id, slad_from, slad_to FROM tax_slads WHERE company_id = '".$get['company_id']."' AND assessment_year ='".$get['assessment_year']."' AND is_active =0 ";
		$tax_slab = $callConfig->getAllRows($tax_sladssql);
		$retuenres['tax_slads'] = $tax_slab;

		$cal_intax = 0;
		if($calslab_total >0){
			foreach ($tax_slab as $slab) {
				if($slab->slad_from < $calslab_total && $calslab_total < $slab->slad_to){
					$cal_amount = $calslab_total - ($slab->slad_from-1);
					$cal_intax = $cal_intax + ($cal_amount * ($slab->rate/100));
					break;
				}else{
					$cal_amount = $slab->slad_to - ($slab->slad_from-1);
					$cal_intax = $cal_intax + ($cal_amount * ($slab->rate/100));
				}
			}
		}
		$retuenres['cal_intax'] = $cal_intax;

		$itd_componentsql = "SELECT id FROM earnings WHERE company_id = '".$get['company_id']."'  AND code ='".$get['itd_code']."' AND is_active =0 ";
		$itd_component = $callConfig->getRow($itd_componentsql);
		$itd_component_id = $itd_component->id;

		$salary_componentsql = "SELECT id FROM salary_template_components WHERE company_id = '".$get['company_id']."'  AND component_type ='".$get['component_type']."' AND is_active =0 ";
		$speical_allowance_component = $callConfig->getRow($salary_componentsql);
		$speical_allowance_component_id = $speical_allowance_component['component_id'];

		$retuenres['sql1'] = $itd_componentsql;
		$retuenres['sql2'] = $salary_componentsql;

		// $prscomponantsql = "SELECT * FROM pay_run_summary_components WHERE employee_id = '".$get['employee_id']."' AND company_id = '".$get['company_id']."' AND pay_year>='".$fromyear."' AND pay_month>='".$frommonth."' AND pay_year<='".$toyear."' AND pay_month<='".$tomonth."' AND is_active =0 ";
		$prscomponantsql = "SELECT * FROM pay_run_summary_components WHERE employee_id = '".$get['employee_id']."' AND company_id = '".$get['company_id']."' AND ( (pay_year ='".$fromyear."' AND pay_month>='".$frommonth."' ) OR (pay_year<='".$toyear."' AND pay_month<='".$tomonth."')) AND is_active =0 ";
		$retuenres['prscomponantsql'] = $prscomponantsql;
		$prscomponantres = $callConfig->getAllRows($prscomponantsql);
		foreach($prscomponantres as $prscomponantre){
			$prscomponanlist[$prscomponantre->pay_year][$prscomponantre->pay_month][] = $prscomponantre;
		}
		//echo "<pre>"; print_r($prscomponanlist);echo"</pre>"; exit;
		$itd_componentsql = "SELECT * FROM earnings WHERE company_id = '".$get['company_id']."' AND is_active =0 ";
		$earcomponents = $callConfig->getAllRows($itd_componentsql);
		//$earcomponents = (array)$earcomponents;
		foreach($earcomponents as $earmponent){
			$earm[$earmponent->id] = (array)$earmponent;
		}

		//echo "<pre>"; print_r($earm);

		$startmonth0 = new DateTime($get['startdate']);
		$endmonth0 = new DateTime($get['enddate']);
		$k=0;
		while($startmonth0 <= $endmonth0){
			$data1 = array();
			$financial_year= $startmonth0->format('Y');
			$month = $startmonth0->format('m');
			$total_monthly_earnings = 0;
			$total_monthly_deductions = 0;
			$total_monthly_gross = 0;
			$data1 = $prscomponanlist[$financial_year][number_format($month)];
			//echo "<pre>"; print_r($data1);
			/*if($financial_year==2024){
					echo "<pre>"; print_r($data1); exit;
			}*/
			foreach ($data1 as $value){
				$comval = $earm[$value->component_id];
				if($comval['display_in_payslip']==0){
					if($comval['calculation_mode']=='ADD'){
						$total_monthly_earnings += $value->salary_component_actual;
						$total_earnings_in_current_year += $value->salary_component_actual;
						/*if($financial_year==2024){
							$array[$month][$value->component_id]=$value->salary_component_actual;
						}*/
					}

					if($comval['calculation_mode']=='MINUS'){
						$total_monthly_deductions  += $value->salary_component_actual; 
						$total_deductions_in_current_year += $value->salary_component_actual; 
					}
					/*if($value->component_id== $itd_component_id){
						$total_tax_paid_in_current_year += $value->salary_component_actual; 
					}
					if($value->component_id == $speical_allowance_component_id){
						$total_perks_in_current_year += $value->salary_component_actual; 
					} */

				}
				
			}
			$total_monthly_gross = $total_monthly_earnings - $total_monthly_deductions;
			if($total_monthly_gross>0){
				$payslip_array[$k] = array($month,$total_monthly_earnings,$total_monthly_deductions,$total_monthly_gross,$financial_year);
			}  
			$startmonth0->modify('+1 month');
		$k++; }
		//print_r($array); exit;
		$retuenres['payslip_array'] = $payslip_array;
		$retuenres['total_monthly_earnings'] = $total_monthly_earnings;
		$retuenres['total_earnings_in_current_year'] = $total_earnings_in_current_year;
		$retuenres['total_monthly_deductions'] = $total_monthly_deductions;
		$retuenres['total_deductions_in_current_year'] = $total_deductions_in_current_year;
		$retuenres['total_tax_paid_in_current_year'] = $total_tax_paid_in_current_year;
		$retuenres['total_perks_in_current_year'] = $total_perks_in_current_year;
		return $retuenres;
	}
	function getEmployeeNotAttendance($get){
		global $callConfig;
		$query ="SELECT emp.id, emp.display_name, emp.image, emp.emp_code,emp.phone,emp.phone,emp.email_id, (SELECT designation_name FROM designations desi WHERE desi.company_id =emp.company_id AND desi.id = emp.designation_id ) as designation_name FROM employees emp WHERE emp.company_id = '".$get['company_id']."' AND emp.employee_type = 1 AND (emp.id NOT IN(SELECT employee_id FROM employee_daily_attendances eda WHERE eda.attendace_date = '".$get['date']."' AND emp.company_id = eda.company_id AND eda.is_active = 0) OR emp.id IN(select el.employee_id from employee_leaves el where el.leave_from <= '".$get['date']."' AND  el.leave_to >= '".$get['date']."' AND el.company_id = emp.company_id AND el.current_status = 199 AND el.is_active = 0))AND emp.joining_date <= '".$get['date']."' AND (emp.date_of_leaving >= '".$get['date']."' OR emp.date_of_leaving IS NULL)";
		$res=$callConfig->getAllRows($query);
		return $res;
	}
