	function getEmployeeHRService($get){
		global $callConfig;
		$year = $get['year'];
		$month = $get['month'];
		if($get['view'] == 'Y'){
			if($get['admin_type'] != '1'){
				$condition = "AND (au.reports_to = '".$get['user_id']."' OR hr_buddy = '".$get['emp_id']."')";
			}
			$sql = "SELECT emp.id,emp.display_name,emp.image,emp.user_id,emp.emp_code FROM employees emp, application_users au WHERE emp.company_id = '".$get['company_id']."' AND emp.company_id = au.company_id AND emp.user_id = au.id AND emp.is_active = 0 AND emp.is_active = au.is_active ".$condition;
		//$return['sql'] =$sql;
			$empres = $callConfig->getAllRows($sql);
			$empids = array();
			$empdetails = array();
			foreach($empres as $empres){
				$empids[] = $empres->id;
				$empdetails[$empres->id] = $empres;
			}
			$return['emp_list'] = $empdetails;
			$empid = implode(",", (array)$empids);
			$emphrservicesql = "SELECT id,name,emp_id,request_date,response_date,current_status FROM emp_hr_services WHERE company_id = '".$get['company_id']."' AND emp_id IN(".$empid.") AND  (request_date >= concat('".$year."-".$month."-01') AND request_date <= last_day(concat('".$year."-".$month."-01'))) AND is_active = 0";
			$emphrserviceres = $callConfig->getAllRows($emphrservicesql); 
			$return['all_services'] = $emphrserviceres;
		}else{
			$emphrservicesql = "SELECT * FROM emp_hr_services WHERE company_id = '".$get['company_id']."' AND emp_id= '".$get['emp_id']."' AND is_active = 0";
			$emphrserviceres = $callConfig->getAllRows($emphrservicesql); 
			$return['all_services'] = $emphrserviceres;

			$servicesql = "SELECT * FROM emp_hr_services WHERE company_id = '".$get['company_id']."' AND is_active = 0 AND id = '".$get['rid']."'";
			$serviceres = $callConfig->getRow($servicesql); 
			$return['services'] = $serviceres;

			$sendemployedetails = array('employee_id'=>$get['emp_id'],'company_id'=>$get['company_id']);
			$returnresp = $this->getempconnectwithempid($sendemployedetails);
			$return['buddy_details'] = $returnresp;
		}
		$company_documentsql = "SELECT id,document_name,documnet_path FROM company_documents WHERE company_id = '".$get['company_id']."' AND category_id= '3' AND is_active = 0";
		$company_documentres = $callConfig->getAllRows($company_documentsql); 
		$return['company_documents'] = $company_documentres;
		return $return;
	}
	function insertHRServices($post){
		global $callConfig;
		$Rid = $post['rid'];
		unset($post['rid']);
		if($Rid !=""){
			$insert = $callConfig->updateRecord('emp_hr_services',$post,'id',$Rid);
			$rid = $Rid;
		}else{
			$insert = $callConfig->insertRecord('emp_hr_services',$post);
			$rid = $insert['LASTID'];
		}
		$this->checkWorkFlowCriteria(array('tablename'=>'emp_hr_services','company_id'=>$post['company_id'],'rid'=>$rid));
		return $insert; 
	}
	function toGetTransactionLogInbox($get){
		global $callConfig;
		$transactiores = array();
		$Alltransactiores = array();
		$condition = "";
		if($get['log_id'] !=""){
			$condition = " AND tal.id IN(".$get['log_id'].")";
		}
		$quer_5="SELECT tal.id,tal.transaction_table,tal.transaction_id,tal.request_date,tal.response_type,tal.response_date,tal.workflow_id,tal.comments  FROM `transaction_approval_logs` tal WHERE tal.company_id='".$get['company_id']."' and tal.user_id =".$get['user_id'].$condition."  ORDER BY tal.request_date DESC";
		$return['quer_5']=$quer_5;
		$tra_data = $callConfig->getAllRows($quer_5);
		$statusres = array();
		$cnttotal = 0;
		foreach($tra_data as $reviewda){  // only store table name and id 
			$alltransactionids[] = $reviewda->transaction_id;
			$logtableandid[$reviewda->transaction_table][] = $reviewda->transaction_id;
			$tranlogid[$reviewda->transaction_table][$reviewda->transaction_id] = $reviewda->id;
			$transactionlog[$reviewda->transaction_table][$reviewda->transaction_id] = $reviewda;
			$cnttotal++; 
			$tbalename[$reviewda->transaction_table] = $reviewda->transaction_table;
		}
		$transidlist = implode("','",(array)$tbalename);
		$display_attrisql="SELECT application_table_name,page_title FROM display_attributes WHERE company_id = '".$get['company_id']."' AND  application_table_name IN('".$transidlist."') AND is_active = 0";
		$display_attrires = $callConfig->getAllRows($display_attrisql);
		foreach($display_attrires as $display_attrires){  
			$return["display_attributes"][$display_attrires->application_table_name] = $display_attrires->page_title;
		}
		$return["cnt_inbox"] = $cnttotal;
		$transidlist = implode(",",(array)$alltransactionids);
		$notificationsql="SELECT nu.user_id,n.notification_message, n.application_table_name, n.transaction_number, n.notification_details FROM notification_user nu, notifications n WHERE nu.company_id = '".$get['company_id']."' AND nu.company_id = n.company_id AND nu.notification_id = n.id  AND nu.user_id = ".$get['user_id']." AND n.transaction_number IN(".$transidlist.")";
		$notificationres = $callConfig->getAllRows($notificationsql);
		foreach($notificationres as $notificationdet){  
			$notificationresult[$notificationdet->application_table_name][$notificationdet->transaction_number] = $notificationdet;	
		}	
	
		foreach($logtableandid as $tablename => $logtableandidres){  // only store table name and id 
			$idlist = implode(",",(array)$logtableandidres);
			$sqldyntable = "SELECT id,current_status,created_by FROM ".$tablename." WHERE company_id = '".$get['company_id']."' AND id IN(".$idlist.") AND is_active = '0' ORDER BY updated_date DESC";
			$dyntableres=$callConfig->getAllRows($sqldyntable); 

			foreach($dyntableres as $dyntablere){
				$dyntablere->transaction_table = $tablename;
				$Alltransactiores[] = $dyntablere;
				$logtabledetails[$tablename][$dyntablere->id] = $dyntablere;
				if($dyntablere->current_status == ST_APPROVED){
					$transactiores[$tablename][ST_APPROVED][] = $tranlogid[$tablename][$dyntablere->id];
				}elseif($dyntablere->current_status == ST_ACTIVE){
					$transactiores[$tablename][ST_ACTIVE][] = $tranlogid[$tablename][$dyntablere->id];
				}elseif($dyntablere->current_status == ST_SEND_BACK || $dyntablere->current_status == ST_REJECTED){
					$transactiores[$tablename][ST_SEND_BACK][] = $tranlogid[$tablename][$dyntablere->id];
				}else{
					$transactiores[$tablename]['inpro'][] = $tranlogid[$tablename][$dyntablere->id];
				}
			}
		} 
		$return['transactiores']= $transactiores;
		$emp_que = "SELECT id,emp_code,user_id,display_name,phone,image FROM `employees`";
		$emp_details = $callConfig->getAllRows($emp_que);
		foreach ($emp_details as $emp) {
			$emp_data[$emp->user_id] = $emp;
		}
		$return['alltransactiores']=$Alltransactiores;
		$return['transactionlog']=$transactionlog;
		$return['notificationresult']=$notificationresult;
		$return['emp']=$emp_data;
		return $return;
	}


	function getLeaveAvailability($get){
		global $callConfig;
		$respons = array(); 
		$company_id = $get['company_id'];
		$emp_id = $get['emp_id'];
		$sql = "SELECT 
		elb.consumed_leaves,
		elb.applicable_leaves,
		(elb.applicable_leaves - elb.consumed_leaves) as available_leave, 
		(
		SELECT	lc.name  
		FROM 	leave_categories lc  
		WHERE	lt.company_id = lc.company_id 
		AND		lt.leave_category_id = lc.id  
		AND		lt.is_active = lc.is_active
		) category_name	
		FROM	leave_types lt, 
		emp_leave_balances elb 
		WHERE	lt.company_id = '".$company_id."'
		AND		elb.employee_id = '".$emp_id."'
		AND		lt.id = elb.leave_type  
		AND		lt.company_id = elb.company_id  
		AND		lt.is_active = elb.is_active 
		AND		lt.is_active = 0";

 //  $sql = "SELECT elb.consumed_leaves,elb.applicable_leaves,(elb.applicable_leaves-elb.consumed_leaves) as available_leave, (SELECT lc.name  from leave_categories lc  WHERE lt.leave_category_id = lc.id  AND lc.is_active = lt.is_active) category_name FROM leave_types lt, emp_leave_balances elb WHERE lt.company_id = '".$get['company_id']."' AND lt.is_active = 0 AND lt.company_id = elb.company_id AND lt.is_active = elb.is_active  AND lt.id = elb.leave_type AND elb.employee_id = '".$get['emp_id']."'";
		$leaveres = $callConfig->getAllRows($sql);
		$respons['available_category'] =$leaveres;
		return $respons;

	}

	function getLeaveCalender($get){

		global $callConfig;

		$sql = "SELECT id,leave_to,leave_from FROM employee_leaves WHERE company_id = '".$get['company_id']."' AND is_active = 0 AND employee_id = '".$get['employee_id']."'";
		// echo $sql;
		$leaveres = $callConfig->getAllRows($sql);
		$sql = "SELECT id,leave_category_id,leave_type_name FROM leave_types WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$leavetypes = $callConfig->getAllRows($sql);
		foreach ($leavetypedata as $value){
			$leave_type[$value->leave_category_id]= $value->leave_type_name;
		}
		foreach ($leaveres as  $empat) {
			$onedayadded  = date('Y-m-d', strtotime('+1 day', strtotime($empat->leave_to)));
			$arr['title'] = "LEAVES";
			$arr['id'] = $empat->id;
			$arr['start'] = $empat->leave_from."T00:00:00";
            $arr['end'] = $onedayadded;  // because the calendar Is Showing one day less so added one day in a array
            $arr['constraint'] = "LEAVES";   
            $arr['url'] = "index.php?option=COM_INSERT_HOLIDAYS&Rid=".base64_encode(base64_encode("id:".$empat->id));
            //$arr['backgroundColor'] = strtoupper($cate[$category]['bgcolor']);
            $array_list[] = $arr;
        }
        return $array_list;
    }

    function getDynamicTableDetails($get){
    	global $callConfig;
    	$returnres['get'] = $get;
    	$application_table = $get['application_table_name'];
    	$admin_access_employee = $get['admin_access_employee'];
    	$condition = "";
		//echo "<pre>";
    	$displayattributessql = "SELECT id,application_table_name,help_text,list_attributes,empty_table_message,insert_page_type, originator_check_required_or_not, page_title FROM display_attributes WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$application_table."' AND is_active = 0";
    	$displayattributesres =  $callConfig->getRow($displayattributessql);
    	$returnres['display_attributes'] = $displayattributesres;
    	$lists = json_decode($displayattributesres->list_attributes,1);
    	$type_array = array('select','multi_select','disable_select','radio','checklist', 'color_pick','image');
    	$textfieldapplicable = array('text','email','phone','number','currency','textarea','serial_no','read_only');
    	$searchfieldapplicable = array('select','multi_select','disable_select','radio','checklist');
    	$emp_array  =$empidcheckarray = array();
    	if($get['admin_type'] !=1 OR $admin_access_employee =='Y'){
    		$emp_array= array('emp_id','employee_id');
    	}
    	if($get['user_type']==3){
    		$emp_array= array('vendor_id');
    		if($table=="vendor_rate_cards"){
    			$emp_array= array('party_id','current_status');
    		}
    		if($table=="manpower_contracts"){
    			$emp_array= array('party_id','current_status');
    		}
    	}
    	$ftextseq = 1;
    	foreach ($lists as $key => $value) {
    		if(in_array($key, (array)$emp_array)){
    			if($get['user_type']==3){
    				if($key == 'party_id'){ $condition .= " AND ".$key." = '".$get['vendor_id']."'";  }
    				if($key == 'vendor_id'){  $condition .= " AND ".$key." = '".$get['vendor_id']."'";  }
    			}else{
    				if($get['option']!='COM_LIST_SALARY'){
    					$condition .= " AND ".$key." = '".$get['emp_id']."'";
    					$empidcheckarray[$key] = $key;
    				}
    			}
    		} 
    		
    		//if(in_array($value['type'], (array)$type_array) AND $value['display_list'] ==1){ 
    		if(in_array($value['type'], (array)$searchfieldapplicable) AND $value['display_list'] ==1){ 
    			$tablefield = $this->getDyanamicSelectData($application_table, $key); 
    			if($tablefield['type'] != 'function'){ 
    				$field[$key] = $tablefield['res'];
    			}else{
    				$field[$key] =  $tablefield;
    			} 
    		}

    		if($get['filter_text'] !="" AND $value['display_list'] ==1){
	    		if(in_array($value['type'], (array)$textfieldapplicable)){ 
	    			if($ftextseq == 1){
	    				$textcondition .= " ".$key." LIKE '%".$get['filter_text']."%'";
	    			}else{
	    				$textcondition .= " OR ".$key." LIKE '%".$get['filter_text']."%'";
	    			}
	    			$ftextseq++;
	    		}
	    	}
    	}

    	if($get['filter_text'] !="" AND $textcondition !=""){  // text box item filter
    		$condition .= " AND (".$textcondition.") ";
    	}
    	if($get['filter_dynamic_select'] !=""){   // list item filter
    		$filter_dynamic_select = json_decode($get['filter_dynamic_select'],1);
    		foreach($filter_dynamic_select as $fdskey => $fds){
    			if($fds !=""){
    				$condition .= " AND ".$fdskey." = '".$fds."'";
    			}
    		}
     	}


    	$returnres['field_result']  = $field;
    	$get['table'] = $application_table;
    	$status_progress  = $this->getStatusProgressList($get);
    	foreach($status_progress as $statusprogress){
			$returnres['status_progress'][$statusprogress->status] = $statusprogress;
		}
    	if($get['curr_status'] !="-1" AND $get['curr_status'] !=""){
    		$condition .= " AND current_status = '".$get['curr_status']."'";
    	}
    	if($get['status'] =="0" || $get['status'] ==""){
    		$condition .= " AND is_active ='0'";
    	}elseif($get['status'] =="1"){
    		$condition .= " AND is_active IS null OR is_active !='0'";
    	}
    	if(($get['admin_type'] == 0 OR $admin_access_employee =='Y') AND !in_array('emp_id', (array)$empidcheckarray) AND !in_array('employee_id', (array)$empidcheckarray) AND $displayattributesres->originator_check_required_or_not == 'Y'){
    		$condition .= " AND created_by ='".$get['user_id']."'";
    	}
    	if($application_table== "process_task_settings"){
    		$condition .= " AND module_setup_id =".$callConfig->module_id;
    	}

    	if($get['limit_select'] !=0){
     			$cntsql = "SELECT COUNT(id) as cnt FROM ".$application_table." WHERE company_id = '".$get['company_id']."' ".$condition;
	     		$cntres =  $callConfig->getRow($cntsql);
	     		$returnres['total_record_cnt'] = $cntres;
	     		$respons_data_cnt =  ($cntres->cnt!="" AND $cntres->cnt !=0)?$cntres->cnt:0;

		     	$divide_limit = $respons_data_cnt/$get['limit_select'];
				$total_pages = ceil($respons_data_cnt / $get['limit_select']);
				$current_page = isset($get['current_page']) ? (int)$get['current_page'] : 1;
				$current_page = max(1, min($current_page, $total_pages));
				$start_from = ($current_page - 1) * $get['limit_select'];
				$returnres['total_pages'] = $total_pages;
				
				$dynmictablersql = "SELECT * FROM ".$application_table." WHERE company_id = '".$get['company_id']."' ".$condition." LIMIT ".$start_from.", ".$get['limit_select'];
    			$dynmictablerres =  $callConfig->getAllRows($dynmictablersql);
		}else{
    		$dynmictablersql = "SELECT * FROM ".$application_table." WHERE company_id = '".$get['company_id']."' ".$condition;
    		$dynmictablerres =  $callConfig->getAllRows($dynmictablersql);
    		$respons_data_cnt = count((array)$dynmictablerres);
    		$returnres['total_record_cnt'] = $respons_data_cnt;
    	}
    	$returnres['dynmictabler'] = $dynmictablerres;
    	$returnres['dynmicsql'] = $dynmictablersql;
    	$returnres['primarykey'] = $this->togetprimarykey($application_table, $get['data_name']);
    	return $returnres;
    }



