    function insertCompanySubscriptionPlans($post){
    	global $callConfig;
    	$returnary['post'] = $post;
	// $up_array = array('is_active'=>NULL);
	// $updateall = $callConfig->updateRecord('company_subscription_plans',$up_array,'subscription_group_id',$post['subscription_group_id']);
	// $returnary['updatealla'] = $updateall;
    	foreach($post['checkmodule'] as $modelid){
    		$planedid = $post['planedname_'.$modelid];
    		if($post['subscriptiontypeunit']=="Q"){
    			$price  = $post['standerpricequarterly_'.$planedid];
    		}elseif($post['subscriptiontypeunit']=="HY"){
    			$price  = $post['standerpricehalfyear_'.$planedid];
    		}elseif($post['subscriptiontypeunit']=="Y"){
    			$price  = $post['standerpriceyearly_'.$planedid];
    		}else{
    			$price  = $post['standerpricemonthly_'.$planedid];	
    		}
    		$insertarray =  array('company_id'=>$post['company_id'],'subscription_group_id'=>$post['subscription_group_id'],'module_id'=>$modelid,'subscription_plan_id'=>$planedid,'standard_user_limit'=>$post['standerduaerlimit_'.$planedid],'standard_price'=>$price,'lot_type'=>$post['subscriptiontypeunit'],'is_active'=>'0','current_status'=>'0');
    		$Rid = $post['subplanid'][$modelid];
    		if($Rid !=""){
    			$insert_array['updated_by'] =$post['user_id'];
    			$insert_array['updated_date'] =date('Y-m-d H:i:s');
    			$insert = $callConfig->updateRecord('company_subscription_plans',$insertarray,'id',$Rid);
    		}else{
    			$insertarray['created_by'] =$post['user_id'];
    			$insertarray['created_date']=date('Y-m-d H:i:s');
    			$insertarray['license_code']  = $this->toGetApplicationSerialNumber('company_subscription_plans',$post);
    			$insert = $callConfig->insertRecord('company_subscription_plans',$insertarray);
    		}
    		$returnary['insert'][] = $insert;
    	}
    	return $returnary;
    }

    function insertCompanySubscription($post){
    	global $callConfig;
    	$returnary['post'] = $post;
    	foreach($post['rowid'] as $key=>$rowid){
    		$startdate = date('Y-m-d');
    		if($post['planunit'][$key] == "M"){
    			$unit = "month";	
    		}elseif($escalation1['planunit']== "D"){
    			$unit = "day";
    		}elseif($escalation1['planunit']== "Y"){
    			$unit = "Year";
    		}
    		$enddate = date('Y-m-d',strtotime('+1'.$unit , strtotime($startdate))); 
	 	// $insertarray =  array('agreed_user_limit'=>$post['agreed_user_limit'][$key],'agreed_price'=>$post['agreed_price'][$key],'subscription_type'=>'Y','discounted_price'=>$post['discount_price'][$key],'start_date'=>$startdate,'end_date'=>$enddate,'number_of_licensed_users'=>$post['agreed_user_limit'][$key],'updated_by'=>$post['user_id'],'updated_date'=>date('Y-m-d H:i:s'));
   //      	$updaterow = $callConfig->updateRecord('company_subscription_plans',$insertarray,'id',$rowid);

    		if($post['subscription_type'][$key]== "N"){	
    			$updatesql = "UPDATE company_subscription_plans SET agreed_user_limit='".$post['agreed_users'][$key]."',agreed_price='".$post['agreed_price'][$key]."',subscription_type='Y',discounted_price='".$post['discount_price'][$key]."',start_date='".$startdate."',end_date='".$enddate."',number_of_licensed_users=number_of_licensed_users +".$post['agreed_users'][$key].",updated_by='".$post['user_id']."',updated_date='".date('Y-m-d H:i:s')."' WHERE id = ".$rowid;
    			$updaterow = $callConfig->executeQuery($updatesql);        	
    			$returnary['updaterowplans'][] = $updaterow;

    			$insertarray1 =  array('company_id'=>$post['company_id'],'csp_id'=>$rowid,'added_license_users'=>$post['agreed_users'][$key],'price'=>$post['agreed_price'][$key],'start_date'=>$startdate,'end_date'=>$enddate,'request_date'=>date('Y-m-d h:i:s'),'is_active'=>'0','current_status'=>'0','created_by'=>$post['user_id'],'created_date'=>date('Y-m-d h:i:s'));
    			$insert = $callConfig->insertRecord('company_subscription_plan_licenses',$insertarray1);
    			$returnary['updaterowplanslicens'][] = $insert;
    		}
    	}
    	$usage_trash_holder_type = $post['usage_trash_holder_type'] == 'Y'?"Y":"N";
    	$pro_rata_billing = $post['pro_rata_billing'] == 'Y'?"Y":"N";
    	foreach($post['fieldname'] as $kK=>$Value){
    		if($post['fieldname'][$kK] !="" AND $post['fieldvalue'][$kK] !=""){
    			$custom_field[$post['fieldname'][$kK]] =$post['fieldvalue'][$kK];
    		} 
    	}
    	$custom_fields= json_encode($custom_field);
    	$insertarraygrp =  array('custom_fields'=>$custom_fields,'invoice_footer'=>$post['invoice_footer'],'usage_trash_holder_type'=>$usage_trash_holder_type,'usage_trash_holder_day'=>$post['usage_trash_holder_day'],'pro_rata_billing'=>$pro_rata_billing,'updated_by'=>$post['user_id'],'updated_date'=>date('Y-m-d H:i:s'));
    	$updaterow = $callConfig->updateRecord(MAINDB.'.registered_groups',$insertarraygrp,'id',$post['subscription_group_id']);
    	$returnary['updaterowgrp'] = $updaterow;
    	return $returnary;
    }
