	function insertCandidateDetails($post){
		global $callConfig;	
		$return['post'] = $callConfig; 
		if($post['edittype'] == "dependancy"){
			$dependancyary =array();
			foreach ($post['dependent_name'] as $key=> $dependent_name){
				if($dependent_name != ""){
					$dependancyary['dependent_name'] = $dependent_name;
					$dependancyary['dependent_relationship_type'] = $post['dependent_relationship_type'][$key];
					$dependancyary['dependent_date_of_birth'] = $this->dateconvertdbformat($post['dependent_date_of_birth'][$key]);
					$dependancyary['occupation'] = $post['occupation'][$key];
					$dependancyary['income'] = $post['income'][$key];
					$dep[] = $dependancyary;
				}
			}
			$post['employee_dependents'] = json_encode($dep);	
		}
		if($post['edittype'] == "award"){
			$ex =array();
			foreach ($post['award_name'] as $key=> $award_name) {
				if($award_name != ""){
					$ex['award_name'] = $post['award_name'][$key];
					$ex['award_description'] = $post['award_description'][$key];
					$ex['award_year'] = $post['award_year'][$key];
					$awd[] = $ex;
				}  
			}
			$post['candidate_awards'] = json_encode($awd);
		}
		if($post['edittype'] =="skills"){
			$post['skills'] = json_encode(explode(',',$post['skills'])); 
		}
		
		if($post['edittype'] == "workexperience"){
			$ex =array();
			foreach ($post['company_name'] as $key=> $company_name) {
				if($company_name != ""){
					$compay_file = $post['hidden_file'][$key];;
					$ex['company_name'] = $company_name;
					$ex['job_descrption'] = $post['job_descrption'][$key];
					$ex['work_from'] = $post['work_from'][$key];
					$ex['work_to'] = $post['work_to'][$key];
					$ex['compay_file'] = $compay_file;
					$exp[] = $ex;
				}
			}
			$post['candidate_experiances'] = json_encode($exp);
		}
		if($post['edittype'] == "education"){
			$ex =array();
			foreach ($post['institute_name'] as $key=> $institute_name) {
				if($institute_name !=""){
					$ex['institute_name'] = $institute_name;
					$ex['education_type'] = $post['education_type'][$key];
					$ex['start_date'] = $post['start_date'][$key];
					$ex['end_date'] = $post['end_date'][$key];
					$ex['score'] = $post['score'][$key];
					$ex['subject'] = $post['subject'][$key];
					$ex['qualification_file'] = $post['hidden_qualification_file'][$key];
					$edu[] = $ex;
				}
			}
			$post['candidate_qualifications'] = json_encode($edu,1);
		}
		$return['post2'] = $post; 	
		$candidatestable = array('first_name', 'middle_name', 'last_name', 'display_name', 'address', 'post_code', 'phone', 'email_id', 'gender', 'marital_status', 'date_of_birth', 'wedding_date', 'blood_group', 'adhar_no', 'pan_number', 'father_name', 'spouse_name', 'hiring_source', 'total_experiance', 'notice_period', 'np_negotiatable', 'candidate_experiances', 'candidate_qualifications', 'employee_dependents', 'employee_contacts', 'current_location', 'reason_for_change', 'relocate', 'current_ctc', 'expected_ctc', 'image', 'location_id', 'vendor_id', 'role_id', 'job_grade', 'pay_template', 'job_tittle_id', 'job_type', 'reporting_date', 'offer_validity', 'hr_connect', 'no_of_reportees', 'candidate_current_role', 'first_role', 'current_pay', 'first_pay', 'gaps_in_employment_reason', 'performance_ratings', 'candidate_awards', 'signature', 'soc_facebook', 'soc_twitter', 'soc_linkedin', 'skills', 'bio','file','department_id','present_address','height','weight','state_id','emergency_contact_number','religion', 'caste', 'identification_mark', 'hobbies', 'present_house');
		$listcandi = array();
		foreach($post as $key => $post1){
			if(in_array($key,(array)$candidatestable)){
				if($key == "date_of_birth" || $key == "wedding_date" || $key == "reporting_date"){
					$listcandi[$key] = $this->dateconvertdbformat($post1);	
				}else{
					$listcandi[$key] = $post1;
				}	
			}
		}
		$return['listcandi'] = $listcandi; 	
		$listcandi['updated_by'] = $post['user_id'];
		$listcandi['updated_date'] = date('Y-m-d H:i:s');
		$updaterow = $callConfig->updateRecord('candidates',$listcandi,'id',$post['candidate_id']);
		$return['updaterow'] = $updaterow;

		if(isset($post['file'])){
			$jblistcandi['file'] = $post['file'];
		}
		if(isset($post['image'])){
			$jblistcandi['image'] = $post['image'];
		}
		
		if(isset($post['display_name'])){
			$jblistcandi['candidate_name'] = $post['display_name'];
		}
		if(isset($post['phone'])){
			$jblistcandi['candidate_phone'] = $post['phone'];
		}
		if(isset($post['current_location'])){
			$jblistcandi['current_location'] = $post['current_location'];
		} 
		if(isset($post['total_experiance'])){
			$jblistcandi['experience'] = $post['total_experiance']; 
		} 
		if(isset($post['current_ctc'])){
			$jblistcandi['current_salary'] = $post['current_ctc']; 
		} 
		$jblistcandi['updated_by'] = $post['user_id'];
		$jblistcandi['updated_date'] = date('Y-m-d H:i:s');
		$updaterow = $callConfig->updateRecord('job_posting_candidates',$jblistcandi,'candidate_id',$post['candidate_id']);
		$return['job_posting_candidates'] = $updaterow;
		return $return;
	}




