function sendEmails($emailarray){
	global $callConfig;
	if($emailarray['databasename'] !=""){
		$databasename = $emailarray['databasename'].".";
	}
		//$superadminsersql = "SELECT au.id, au.display_name, au.user_email,au.user_mobile, comp.name FROM application_users au, companies comp WHERE au.company_id = comp.id AND au.role_id LIKE '".'%"'.SUPERADMIN_ROLE.'"%'."' AND au.is_active = comp.is_active AND au.is_active = 0";
		// $superadminserres = $callConfig->getRow($superadminsersql);
		// $emailarray['super_admin_email_id'] = $superadminserres->user_email;
		// $emailarray['super_admin_company_name'] = $superadminserres->name;
		// $emailarray['super_admin_display_name'] = $superadminserres->display_name;
	$emailarray['super_admin_email_id'] = SUPERADMIN_EMAIL_ID;
	$emailarray['super_admin_company_name'] = SUPERADMIN_COMPNAY_NAME;
	$emailarray['super_admin_display_name'] = SUPERADMIN_DISLAY_NAME;

	if($callConfig->module_id !=""){
		$msql = "SELECT role_admin_short_code FROM ".$databasename."module_setup where module_id = '".$callConfig->module_id."'";
		$module_setupres = $callConfig->getRow($msql);
	}
	if($module_setupres->role_admin_short_code !=""){
		$adminsersql = "SELECT au.id, au.display_name, au.user_email, au.user_mobile, comp.name FROM ".$databasename."application_users au, ".$databasename."companies comp WHERE au.company_id = '".$emailarray['session_company_id']."' AND au.company_id = comp.id AND au.role_id LIKE '".'%"'.$module_setupres->role_admin_short_code.'"%'."'";
		//AND au.is_active = comp.is_active AND au.is_active = 0 account deactiveate user not fund??
		$adminserres = $callConfig->getRow($adminsersql);
	}else{
		$adminsersql = "SELECT au.id, au.display_name, au.user_email, au.user_mobile, comp.name FROM ".$databasename."application_users au, ".$databasename."companies comp WHERE au.company_id = '".$emailarray['session_company_id']."' AND au.company_id = comp.id AND au.role_id LIKE '".'%"'.ADMIN_ROLES.'"%'."'";
		//AND au.is_active = comp.is_active AND au.is_active = 0 account deactiveate user not fund??
		$adminserres = $callConfig->getRow($adminsersql);
	}
	$emailarray['admin_email_sql'] = $adminsersql;
	$emailarray['admin_email_id'] = $adminserres->user_email;
	$emailarray['admin_company_name'] = $adminserres->name;
	$emailarray['company_name'] = $adminserres->name;
	$emailarray['admin_display_name'] = $adminserres->display_name;
	$emailarray['admin_phone_number'] = $adminserres->user_mobile;
	if($emailarray['email_address_to'] !=""){
		$emailarray['email_send_type'] =  "TO";
		$email_array = $this->emailtemplate($emailarray);
		$file_name = 'email'.'_'.time().uniqid().'.'.'html';
		$email_array['content'] = $file_name;
		$email_array['revicer'] = array($this->emaildatareplace($emailarray, $emailarray['email_address_to'])); 

			//$email_array['replaseword00'] = $emailarray['email_address_to']; 
		$email_array['email_type'] = 1;
		$email = $email_array['mesg'];
		$email_array['email_content_ref_id'] = $emailarray['email_content_ref_id'];
		$email_array['created_by'] = $emailarray['user_id'];
		$email_array['databasename'] = $emailarray['databasename'];
		//attachements
		$email_array['attachment'] = $emailarray['attachment'];
		$email_array['attachment_data'] = $emailarray['attachment_data'];
		$email_array['attachment_file_name'] = $emailarray['attachment_file_name'];
		$email_array['attachment_file_path'] = $emailarray['attachment_file_path'];
		$file_path='uploads/email/'.$file_name;

		file_put_contents($file_path, $email);
		//echo $file_path;
		//fclose($file_path);
	//echo "working";

		$lenn = $this->sendEmailslist($email_array);
		$emailarray['sendmail'][] = $lenn;
	}
	if($emailarray['email_address_cc'] !=""){
		$emailarray['email_send_type'] =  "CC";
		$email_array = $this->emailtemplate($emailarray);
		$emailarray['email_template_array'] =  $email_array;
		$file_name = 'email'.'_'.time().uniqid().'.'.'html';
		$email_array['content'] = $file_name;
		$email_array['revicer'] = array($this->emaildatareplace($emailarray, $emailarray['email_address_cc'])); 
			//$email_array['replaseword11'] = $emailarray['email_address_cc'];
		$email_array['email_type'] = 1;
		$email = $email_array['mesg'];
		$email_array['email_content_ref_id'] = $emailarray['email_content_ref_id'];
		$email_array['created_by'] = $emailarray['user_id'];
		$email_array['databasename'] = $emailarray['databasename'];
		//attachements
		$email_array['attachment'] = $emailarray['attachment'];
		$email_array['attachment_data'] = $emailarray['attachment_data'];
		$email_array['attachment_file_name'] = $emailarray['attachment_file_name'];
		$email_array['attachment_file_path'] = $emailarray['attachment_file_path'];

		$file_path='uploads/email/'.$file_name;
		file_put_contents($file_path, $email);
		//fclose($file_path);
		$lenn = $this->sendEmailslist($email_array);
		$emailarray['sendmail'][] = $lenn;
	}
	
	return $email_array; 
}
function emailtemplate($send_data){
	global $callConfig;
	if($send_data['email_template'] == 1){
		$data = $this->emailtemplate1($send_data);
	}
	if($send_data['email_template'] == 2){
		$data = $this->emailtemplate2($send_data);
	}
	if($send_data['email_template'] == 3){
		$data = $this->emailtemplate3($send_data);
	}
	if($send_data['email_template'] == 4){
		$data = $this->emailtemplate4WithPDF($send_data);
	}
	return $data;
}
