function insertCandiDatesPopup($post){
	global $callConfig;
	$return = array();
	$return['post'] = $post;
	$requested_by = 0;
	$recruitment_manager = 0;
		//updatepending	
	if($post['job_posting_id'] !=""){
		$job_postingssql = "SELECT requested_by, recruitment_manager, job_code FROM job_postings where company_id = '".$post['company_id']."' and id ='".$post['job_posting_id']."' AND is_active = 0";
		$job_postingsres = $callConfig->getRow($job_postingssql);
		$requested_by = $job_postingsres->requested_by;
		$recruitment_manager = $job_postingsres->recruitment_manager;
		$job_title_id = $job_postingsres->job_code;
	}else{
		$talent_poolssql = "SELECT rm_id, hm_id, job_title_id FROM talent_pools where company_id = '".$post['company_id']."' and id ='1' AND is_active = 0";
		$talent_poolsres = $callConfig->getRow($talent_poolssql);
		$requested_by = $talent_poolsres->hm_id;
		$recruitment_manager = $talent_poolsres->rm_id;
		$job_title_id = $talent_poolsres->job_title_id;
	}
		//updatepending	
	$insertarray1 = array("company_id"=>$post['company_id'],"first_name"=>$post['first_name'],"last_name"=>$post['last_name'],"email_id"=>$post['email_id'],"phone"=>$post['phone'],"current_location"=>$post['current_location'],"current_ctc"=>$post['current_ctc'],"expected_ctc"=>$post['current_ctc'],"file"=>$post['old_files'],"location_id"=>$post['location_id'],"job_type"=>"2","total_experiance"=>$post['candidate_experiances'],'hm_id'=>$requested_by,'rm_id'=>$recruitment_manager,'job_tittle_id'=>$job_title_id,"is_active"=>"0","current_status"=>"0","created_date"=>date('Y-m-d h:i:s'),"created_by"=>$post['user_id']);
	$transation = $this->toGetApplicationSerialNumber('candidates',$post);
	$insertarray1['candidate_code'] = $transation;
	$insertarray1['display_name'] = $post['first_name']." ".$post['last_name'];
	$insert1 = $callConfig->insertRecord('candidates',$insertarray1);
	if($insert1['status'] == "sucess" AND $post['job_posting_id'] !=""){
		$post['candidate_id'] = $insert1['LASTID'];
		//$post['job_posting_id'] = array($post['job_posting_id']);
		$job_posting_candidates = $this->assigneCandidateJobPostingPopup($post);
		$return['job_posting_candidates'] = $job_posting_candidates;
	}else{
		$post['email_template_id'] = 11;
		$this->sendCandidatEmailPopup($post);
	}
	$return['insert1sql'] = $insertarray1;
	$return['insert1'] = $insert1;
	return $return;	
}
function assigneCandidateJobPostingPopup($post){
	global $callConfig;
	$return = array();
	$return['post'] = $post;
	$job_posting_id = $post['job_posting_id'];
		//updatepending	
