	$sqlcheckpostres = $callConfig->getRow($sqlcheckpostsql);
	if(!isset($sqlcheckpostres->id)){
			//updatepending	
		$updatefied = array('is_active'=>null,"updated_date"=>date('Y-m-d h:i:s'),"updated_by"=>$post['user_id']);
		$res22 = $callConfig->updateRecord('job_posting_candidates',$updatefied,'candidate_id',$post['candidate_id']);
			//updatepending	
		$query = "SELECT id, job_selection_process, requested_by, recruitment_manager, job_code FROM job_postings where id ='".$job_posting_id."' AND company_id = '".$post['company_id']."' AND is_active = 0";
		$postdetails = $callConfig->getRow($query);

		$updatefied11 = array('hm_id'=>$postdetails->requested_by,'rm_id'=>$postdetails->recruitment_manager,'job_tittle_id'=>$postdetails->job_code,"updated_date"=>date('Y-m-d h:i:s'),"updated_by"=>$post['user_id']);
		$res11 = $callConfig->updateRecord('candidates',$updatefied11,'id',$post['candidate_id']);

