function insertCandidateLogs($post){
	global $callConfig;
	$returnmes['post'] = $post;
	if($post['parent_id'] !="0"){
		$messageary = urldecode($post['replay_message_type']);
		$returnmes['messageary'] = $messageary;
		$message_typess = json_decode($messageary,1);
		$returnmes['message_type'] = $message_typess;
		$user_ids = $message_typess['user_id'];
		$message_type = $messageary;
	}else{
		$auditsql = "SELECT id, user_id,hr_connect,hm_id,rm_id  FROM candidates WHERE company_id = '".$post['company_id']."' AND id= '".$post['rid']."' AND is_active = 0";
		$returnmes['sql'] = $auditsql;
		$auditres = $callConfig->getRow($auditsql);
		if($auditres->user_id !=""){
