	function getCandidateEmailPopup($get){
		global $callConfig;
		$return = array();
		$email_contentsql = "SELECT id,template_reference_id, template_name, email_subject_to, email_content_to, application_module FROM email_content WHERE company_id = '".$get['company_id']."' AND application_module = '".$callConfig->module_id."' AND is_active = 0";
		$email_contentres = $callConfig->getAllRows($email_contentsql);
		$return['email_content'] = $email_contentres;

		$email_logssql = "SELECT id, content, email, email_source, email_date FROM email_logs WHERE company_id = '".$get['company_id']."' AND email = '".$get['email_id']."'";
		$email_logsres = $callConfig->getAllRows($email_logssql);
		$return['email_logs'] = $email_logsres;

		return $return;
	}
	function sendCandidatEmailPopup($post){
		global $callConfig;
		$return = array();
		$emailarray = $post;
		$return['post'] = $post; 
		$return['callConfig'] = $callConfig;
		$candidatessql = "SELECT *,(SELECT jt.job_title FROM job_titles jt WHERE jt.company_id = can.company_id AND jt.id = can.job_tittle_id AND  jt.is_active =can.is_active) as job_title FROM candidates can WHERE can.company_id = '".$post['company_id']."'  AND can.is_active = 0 AND can.id='".$post['candidate_id']."'";
		
		$candidatesres = $callConfig->getRow($candidatessql);
		$return['candidatessql'] = $candidatesres;
		foreach($candidatesres as $ckey=>$cval){
			$emailarray["candidates.".$ckey] = $cval;
		}
		$hm_users_sql = "SELECT * FROM application_users WHERE company_id = '".$post['company_id']."'  AND is_active = 0 AND id='".$candidatesres->hm_id."'";
		$hm_users_res = $callConfig->getRow($hm_users_sql);
		$emailarray['hm_display_name'] = $hm_users_res->display_name;
		$rm_users_sql = "SELECT * FROM application_users WHERE company_id = '".$post['company_id']."'  AND is_active = 0 AND id='".$candidatesres->rm_id."'";
		$rm_users_res = $callConfig->getRow($rm_users_sql);
		$emailarray['rm_display_name'] = $rm_users_res->display_name;
		$emailarray['rm_email_id'] = $rm_users_res->user_email;
		$emailarray['user_company_id'] = $candidatesres->company_id;
		$emailarray['session_company_id'] = $post['company_id'];
		$emailarray['creater_user_id'] = array($post['user_id']);
		$emailarray['to_company_id'] = $post['company_id'];
		$emailarray['created_by'] = $post['user_id'];
		$return['INSERT_CANDIDATE_INTERVIEW_SCHEDULE'] = INSERT_CANDIDATE_INTERVIEW_SCHEDULE;
		if(in_array($post['email_content_ref_id'], (array)INSERT_CANDIDATE_INTERVIEW_SCHEDULE) || in_array($post['email_template_id'], (array)INSERT_CANDIDATE_INTERVIEW_SCHEDULE)){
			
			$shedule_type = $post['email_content_ref_id'] == TELEPHONINC_INTERVIEW || $post['email_template_id'] == TELEPHONINC_INTERVIEW?"1":"2";	
			
			$cis_insert_array = array("company_id"=>$post['company_id'],"candidate_id"=>$post['candidate_id'],"rm_id"=>$candidatesres->rm_id,"schedule_type"=>$shedule_type,"interviewer_timezone"=>INTERVIEWER_TIMEZONE,"db_name"=>$callConfig->dbname,"request_datetime"=>date('Y-m-d h:i:s'),"is_active"=>"0","current_status"=>"0","created_date"=>date('Y-m-d h:i:s'),"created_by"=>$post['user_id']);
			$cisres = $callConfig->insertRecord('candidate_interview_schedule',$cis_insert_array);

			$shedulueurlarray = array('candidate_display_nama'=>$candidatesres->display_name,'Job_title'=>$candidatesres->job_title,'rm_name'=>$rm_users_res->display_name,'Rid'=>$cisres['LASTID'],'dbname'=>$callConfig->dbname);
			$emailarray['candidate_interview_schedule_button'] = "<a href='".SITEURL."/candidate_schedules.php?OPTION=".base64_encode(json_encode($shedulueurlarray))."'><button class='btn btn-primary waves-effect waves-light'>Schedule</button></a>";
		}
		if($post['email_template_id'] != "-1"){
			$emill = $this->sendNotificationAndEmails('',$emailarray,$post['email_template_id']);
			$return['sendmail'] = $emill;
		}else{	
			$adminsersql = "SELECT au.id, au.display_name, au.user_email, au.user_mobile, comp.name FROM application_users au, companies comp WHERE au.company_id = '".$emailarray['to_company_id']."' AND au.company_id = comp.id AND au.role_id LIKE '".'%"'.ADMIN_ROLES.'"%'."'";
			$adminserres = $callConfig->getRow($adminsersql);
			$emailarray['admin_email_sql'] = $adminsersql;
			$emailarray['admin_email_id'] = $adminserres->user_email;
			$emailarray['admin_company_name'] = $adminserres->name;
			$emailarray['company_name'] = $adminserres->name;
			$emailarray['admin_display_name'] = $adminserres->display_name;
			$emailarray['admin_phone_number'] = $adminserres->user_mobile;
			$emailarray['email_content'] = $post['email_content_to'];
			$emailarray['subject'] = $post['subject'];
			$email_array = $this->emailtemplate4($emailarray);
			$file_name = 'email'.'_'.time().uniqid().'.'.'html';
			$email_array['content'] = $file_name;
			$email_array['email_content_ref_id'] = $post['email_content_ref_id'];
			$email_array['created_by'] = $post['user_id'];
			$email_array['revicer'] = array($candidatesres->email_id); 
			//$email_array['replaseword11'] = $emailarray['email_address_cc'];
			$email_array['email_type'] = 1;
			$email = $email_array['mesg'];
			$file_path='uploads/email/'.$file_name;
			file_put_contents($file_path, $email);
			//fclose($file_path);
			$lenn = $this->sendEmailslist($email_array);
			$return['sendmail'] = $lenn;
		}
		$return['return'] = $emailarray;


		return $return;

	}
	function emailtemplate4($send_data){
		global $callConfig;
		$temp = "";
		$configsql = "SELECT name,contact_address,application_module,admin_email,display_logo FROM config WHERE id = 1";
		$configres=$callConfig->getRow($configsql);
		$send_data['company_name'] = $configres->name!=""?$configres->name:SUPERADMIN_COMPNAY_NAME;
		//$send_data['super_admin_email_id'] = $configres->admin_email;
		$send_data['contact_address'] = $configres->contact_address !=""?$configres->contact_address:SUPERADMIN_CONTACT_ADDRESS;
		$configres->display_logo = $configres->display_logo !=""?$configres->display_logo:SUPERADMIN_LOGO;
		$configres->admin_email = $configres->admin_email !=""?$configres->admin_email:SUPERADMIN_EMAIL_ID;
		$configres->application_module  = $configres->application_module !=""?$configres->application_module:$send_data['user_module_id'];
		$modulesetupsql = "SELECT module_name FROM module_setup WHERE module_id = '".$configres->application_module."'";
		$modulesetupres=$callConfig->getRow($modulesetupsql);
		$send_data['product_name'] = $modulesetupres->module_name;
		if($send_data['email_send_type'] == "TO"){
			$emailcontentsql = "SELECT email_subject_to as email_subject,email_header_to as email_header,email_content_to as email_content_1,button_label, email_footer  as email_fotter FROM email_content WHERE company_id = '".$send_data['session_company_id']."' AND  template_reference_id = '".$send_data['email_content_id'] ."' AND is_active = 0";
		}else{
			$emailcontentsql = "SELECT email_subject_cc as email_subject,email_header_cc as email_header,email_content_cc as email_content_1,button_label,email_footer  as email_fotter FROM email_content WHERE company_id = '".$send_data['session_company_id']."' AND  template_reference_id = '".$send_data['email_content_id'] ."' AND is_active = 0";
		}
		$emailcontentres=$callConfig->getRow($emailcontentsql);


		$subject =  $this->emaildatareplace($send_data, $send_data['subject']);	
		$temp = '
