	function getJobPostingPageDetails($get){
		global $callConfig;
		$return = array();

		$roleshortcodes = json_decode($get['roleshortcode'],1);
		if(in_array(HIRINGMANAGER_ROLE, (array)$roleshortcodes)){
			$whr = " AND shortlisted = 0";  // rm shortlisted show only
		}
		$job_posting_candidatessql = "SELECT id,current_status,candidate_name,candidate_id,job_selection_process_step_id, shortlisted, hm_shortlisted, ratting FROM job_posting_candidates WHERE company_id = '".$get['company_id']."' AND job_posting_id = '".$get['job_posting_id']."' AND is_active = 0 ".$whr;
		$job_posting_candidatesres=$callConfig->getAllRows($job_posting_candidatessql);
		$return['job_posting_candidates'] = $job_posting_candidatesres;

		$job_postingssql = "SELECT *,(SELECT job_title FROM job_titles jt WHERE jt.company_id = jp.company_id AND jt.id = jp.job_code AND jt.is_active = jp.is_active) as job_title_name,(SELECT department_name FROM departments dep WHERE dep.company_id = jp.company_id AND dep.id = jp.department_id AND dep.is_active = jp.is_active) as department_name, (SELECT location_name FROM locations loc WHERE loc.company_id = jp.company_id AND loc.id = jp.location_id AND loc.is_active = jp.is_active) as location_name,(SELECT process_name FROM job_selection_process jsp WHERE jsp.company_id = jp.company_id AND jsp.id = jp.job_selection_process AND jsp.is_active = jp.is_active) as process_name FROM job_postings jp WHERE jp.company_id = '".$get['company_id']."' AND jp.id = '".$get['job_posting_id']."'  AND jp.is_active = 0";
		$job_postingsres=$callConfig->getRow($job_postingssql);
		$return['job_postings'] = $job_postingsres;


		$job_selection_process_stepssql = "SELECT id,select_name FROM job_selection_process_steps WHERE company_id = '".$get['company_id']."' AND process_id = '".$job_postingsres->job_selection_process."' AND is_active = 0";
		$job_selection_process_stepsres=$callConfig->getAllRows($job_selection_process_stepssql);
		$return['job_selection_process_steps'] = $job_selection_process_stepsres;

		$candidatessql = "SELECT id,display_name,email_id,phone FROM candidates WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$candidatesres=$callConfig->getAllRows($candidatessql);
		$return['candidates'] = $candidatesres;


		return $return;

	}

	function getRecruitngManagerDashboard($get){
		global $callConfig;
		$return = array();
		$condition ="";
		if($get['field_name'] !="" AND $get['field_name'] !="All"){ 
			$condition = " AND ca.".$get['field_name']." = '".$get['value']."' ";
		}
		$job_posting_candidatessql = "SELECT jpc.id, jpc.job_posting_id, jpc.candidate_name, jpc.candidate_email, jpc.candidate_id, jpc.job_selection_process_step_id, jpc.current_status,jpc.created_date,(SELECT jhs.hiring_source_name FROM job_hiring_source jhs WHERE jhs.company_id = jpc.company_id AND jhs.id = jpc.job_hiring_source_id AND jhs.is_active = jpc.is_active) as job_hiring_source_name FROM job_posting_candidates jpc, candidates ca WHERE jpc.company_id = '".$get['company_id']."' AND jpc.company_id = ca.company_id AND jpc.candidate_id = ca.id AND jpc.job_posting_id = '".$get['job_posting_id']."' ".$condition."  AND jpc.is_active = 0 AND jpc.is_active = ca.is_active";
		$job_posting_candidatesres=$callConfig->getAllRows($job_posting_candidatessql);
		$return['job_posting_candidates'] = $job_posting_candidatesres;
		$return['sql'] = $job_posting_candidatessql;
		return $return;
	}


	function candidateRequestDocs($post){
		global $callConfig;
		$category_id = $post['category_id'];
		$due_date = "";
		if($post['reporting_date'] !=""){
			$addminus = "";
			if($post['before_or_after'] == "AF"){
				$addminus = "+";
			}elseif($post['before_or_after'] == "BF"){
				$addminus = "-";
			}
			$due_date = date('Y-m-d', strtotime($addminus.$post['day'].' day', strtotime($post['reporting_date'])));
		}
		$insert_array = array('company_id'=>$post['company_id'],'candidate_id'=>$post['candidate_id'],'category_id'=>$category_id,'document_list_id'=>$post['document_id'],'due_date'=>$due_date,'is_active'=>'0','current_status'=>ST_INPROGRESS,'created_by'=>$post['user_id'],'created_date'=>date('Y-m-d h:i:s'));
		$res = $callConfig->insertRecord('candidate_documents',$insert_array);
		return  $post;
	}



	function insertCandidateAccessRight($post){
		global $callConfig;
		$return = array();
		$return['post'] = $post;	
		$fielddata = json_encode($post['fieldgrpaccess']);
		$dashboard_field_list = json_encode($post['dashboard_field_list']);
		$return['post'] = $post;	
		if(isset($post['Rid']) AND $post['Rid'] !=""){
			$post_array= array("role_short_code"=>$post['role_short_code'],"field_list"=>$fielddata,"dashboard_field_list"=>$dashboard_field_list,"updated_by"=>$post['user_id'],"updated_date"=>date('Y-m-d H:i:s'));
			$res=$callConfig->updateRecord('candidate_display_fields',$post_array,'id',$post['Rid']);	
		}else{
			$post_array = array("company_id"=>$post['company_id'],"role_short_code"=>$post['role_short_code'],"field_list"=>$fielddata,"dashboard_field_list"=>$dashboard_field_list,"is_active"=>"0","current_status"=>"0","created_date"=>date('Y-m-d h:i:s'),"created_by"=>$post['user_id']);
			$res = $callConfig->insertRecord('candidate_display_fields',$post_array);	
		}
		$return['result'] = $res;
		return $return;
	}
