	// $return['display_attributes'] = $display_attributesres;

		$display_attributes_listsql = "SELECT id,application_table_name,page_title, list_attributes FROM display_attributes WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$display_attributes_listres=$callConfig->getAllRows($display_attributes_listsql);
		$return['display_attributes_list'] = $display_attributes_listres;

	// $status_progresssql = "SELECT id,name,status FROM status_progress WHERE company_id = '".$get['company_id']."' AND table_name ='".$workflow_configurationres->process_type."' AND is_active = 0";
	// $status_progressres=$callConfig->getAllRows($status_progresssql);
	// $return['status_progress'] = $status_progressres;

		$module_setupsql = "SELECT id,module_id,module_name FROM module_setup WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$module_setupres=$callConfig->getAllRows($module_setupsql);
		$return['module_setup'] = $module_setupres;

		$email_contentsql = "SELECT id, template_reference_id, application_module, template_name  FROM email_content WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$email_contentres=$callConfig->getAllRows($email_contentsql);
		$return['email_content'] = $email_contentres;

		$application_userssql = "SELECT id, display_name, location_id FROM application_users WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$application_usersres=$callConfig->getAllRows($application_userssql);
		$return['application_users'] = $application_usersres;

		$email_groupssql = "SELECT id, name FROM email_groups WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$email_groupsres=$callConfig->getAllRows($email_groupssql);
		foreach($email_groupsres as $lists){
			$email_groupsreslist[$lists->id] =  $lists->name;
		}
		$return['email_groups'] = $email_groupsreslist;

		$access_levelssql = "SELECT role_short_code as id, name FROM application_roles WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$access_levelsres=$callConfig->getAllRows($access_levelssql);
		foreach($access_levelsres as $lists){
			$application_roleslist[$lists->id] =  $lists->name;
		}
		$return['application_roles'] = $application_roleslist;

		$role_levelsssql = "SELECT genc_detail_code ,genc_detail_name FROM general_code_details WHERE company_id = '".$get['company_id']."' AND genc_code = 'HIERARCHICALLEVEL' AND is_active = 0";
		$role_levelssres=$callConfig->getAllRows($role_levelsssql);
		foreach($role_levelssres as $lists){
			if($lists->genc_detail_name != "Others"){
				$role_levelsslist[$lists->genc_detail_code] =  $lists->genc_detail_name;
			}
		}
		$return['role_levels'] = $role_levelsslist;

		$buddysql = "SELECT genc_detail_code ,genc_detail_name FROM general_code_details WHERE company_id = '".$get['company_id']."' AND genc_code = 'EMPLOYEEBUDDIES' AND is_active = 0";
		$buddyres=$callConfig->getAllRows($buddysql);
		foreach($buddyres as $lists){
			if($lists->genc_detail_name != "Others"){
				$buddylist[$lists->genc_detail_code] =  $lists->genc_detail_name;
			}
		}
		$return['buddy'] = $buddylist;
		$employment_rolessql = "SELECT id, role_name FROM employment_roles WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$employment_rolesres=$callConfig->getAllRows($employment_rolessql);
