		$return['employment_roles'] = $employment_roleslist;


		$listfieldssql = "SELECT id, list_attributes FROM display_attributes WHERE company_id = '".$get['company_id']."' AND application_table_name='".$workflow_configurationres->process_name."'  AND is_active = 0";
		$listfieldsres=$callConfig->getRow($listfieldssql);
		$listfields = json_decode($listfieldsres->list_attributes,1);
		foreach($listfields as $key=>$aray){
			$listval[$key] =  $aray['lable'];
		}
		$return['custom_field'] = $listval;

		if($workflow_configurationres->criteria !=""){
			$workingprocess = json_decode($workflow_configurationres->criteria,1);
		}

		if(in_array('location_id', (array)$workingprocess)){
			$fieldname[] = "CONCAT('location_id','=',locations.location_name,'=',locations.id) as location_id";
			$tablename[] = "locations";
			$joins[] = " AND locations.company_id = '".$get['company_id']."' AND locations.is_active = 0";
		} 
		if(in_array('department_id', (array)$workingprocess)){
			$fieldname[] = "CONCAT('department_id','=',departments.department_name,'=',departments.id) as department_id";
			$tablename[] = "departments";
			$joins[] = " AND departments.company_id = '".$get['company_id']."' AND departments.is_active = 0";
		}

		if(in_array('cost_center_id', (array)$workingprocess)){
			$fieldname[] = "CONCAT('cost_center_id','=',cost_centers.cost_center_name,'=',cost_centers.id) as cost_center_id";
			$tablename[] = "cost_centers";
			$joins[] = " AND cost_centers.company_id = '".$get['company_id']."' AND cost_centers.is_active = 0";
		}
		if(in_array('division_id', (array)$workingprocess)){
			$fieldname[] = "CONCAT('division_id','=',divisions.division_name,'=',divisions.id) as division_id";
			$tablename[] = "divisions";
			$joins[] = " AND divisions.company_id = '".$get['company_id']."' AND divisions.is_active = 0";
		}
		if(in_array('type', (array)$workingprocess)){
			$fieldname[] = "CONCAT('type','=',trnsacrequitype.genc_detail_name,'=',trnsacrequitype.genc_detail_code) type";
			$tablename[] = "general_code_details trnsacrequitype";
			$joins[] = " AND trnsacrequitype.genc_code = 'TRANSACTIONTYPE' AND trnsacrequitype.company_id = '".$get['company_id']."' AND trnsacrequitype.is_active = 0";
		}
		if(in_array('opex_cpex', (array)$workingprocess)){
			$fieldname[] = " CONCAT('opex_cpex','=',opex_capexs.genc_detail_name,'=',opex_capexs.genc_detail_code) as opex_capex";
			$tablename[] = "general_code_details opex_capexs";
			$joins[] = " AND opex_capexs.genc_code = 'OPEXCAPEX' AND opex_capexs.company_id = '".$get['company_id']."' AND opex_capexs.is_active = 0";
		}
		if(in_array('department_id',(array)$workingprocess) AND in_array('cost_center_id', (array)$workingprocess)){
			$joins[] = " AND departments.id = cost_centers.department_id";
		}
		if(in_array('department_id', (array)$workingprocess) AND in_array('division_id', (array)$workingprocess)){
			$joins[] = " AND departments.division_id = divisions.id";
		}
		if(count((array)$fieldname) != 0 AND count((array)$tablename) != 0){
			$sql = "SELECT ".implode(",",(array)$fieldname)." FROM ".implode(",",(array)$tablename)." WHERE 1 ".implode(" ",(array)$joins);
			$return['sql'] = $sql;
			$res=$callConfig->getAllRows($sql);
			$return['dynamic_doa_criteria'] = $res;
		}

		$ownertypesql = "SELECT genc_detail_code ,genc_detail_name FROM general_code_details WHERE company_id = '".$get['company_id']."' AND genc_code = 'OWNERTYPE' AND is_active = 0";
		$ownertyperes=$callConfig->getAllRows($ownertypesql);
		foreach($ownertyperes as $lists){
				$ownertypetype[$lists->genc_detail_code] =  $lists->genc_detail_name;
		}
		$return['ownertype'] = $ownertypetype;
		$locationsql = "SELECT id, location_name FROM locations WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$locationres=$callConfig->getAllRows($locationsql);
		$return['locations'] = $locationres;

	// $divisionssql = "SELECT id, division_name FROM divisions WHERE company_id = '".$get['company_id']."' AND is_active = 0";
	// $divisionsres=$callConfig->getAllRows($divisionssql);
	// $return['divisions'] = $divisionsres;

	// $departmentssql = "SELECT id, department_name FROM departments WHERE company_id = '".$get['company_id']."' AND is_active = 0";
	// $departmentsres=$callConfig->getAllRows($departmentssql);
	// $return['departments'] = $departmentsres;

	// $cost_centerssql = "SELECT id, cost_center_name FROM cost_centers WHERE company_id = '".$get['company_id']."' AND is_active = 0";
	// $cost_centersres=$callConfig->getAllRows($cost_centerssql);
	// $return['cost_centers'] = $cost_centersres;



	// if($get['ajax'] == 'Y'){
	// 	$status_progresssql = "SELECT id,name,status FROM status_progress WHERE company_id = '".$get['company_id']."' AND table_name ='".$get['process_type']."' AND is_active = 0";
	// 	$status_progressres=$callConfig->getAllRows($status_progresssql);
	// 	$return['status_progress'] = $status_progressres;		
