	// $return['priority'] = $priorityres;

		return $return;
	}
	function insertCandidateSchedule($post){
		global $callConfig;
		$return = array();
		$db_name = base64_decode($post['softversion']);
		$cissql = "SELECT company_id,candidate_id,db_name,interviewer_timezone,schedule_type FROM ".$db_name.".candidate_interview_schedule WHERE id= '".$post['Rid']."' AND is_active = 0";
		$cisres=$callConfig->getRow($cissql);
		$return['cisres'] = $cisres;
		$return['post'] = $post;
		$schedule_datetime = date('Y-m-d H:i:s',$post['time']);
		$actualtimezone = $post['timezone'];
		$interviewer_timezone = $this->gettTimeZone($schedule_datetime,$actualtimezone,$cisres->interviewer_timezone);
		$post_array = array("schedule_date"=>$this->dateconvertdbformat($post['schedule_date']),"interviewer_schedule_datetime"=>$interviewer_timezone['timezonedatetime'],"timezone"=>$actualtimezone,"schedule_datetime_int"=>$post['time'],"schedule_datetime"=>$schedule_datetime,"current_status"=>ST_APPROVED,"response_datetime"=>date('Y-m-d H:i:s'),"updated_date"=>date('Y-m-d H:i:s'),"updated_by"=>$post['user_id']);
		$res=$callConfig->updateRecord($db_name.'.candidate_interview_schedule',$post_array,'id',$post['Rid']);	
		$return['resut']=$res; 
		$post['candidates.schedule_time'] = $schedule_datetime;
		$post['rm_schedule_time'] = $interviewer_timezone['timezonedatetime'];
		$post['company_id'] = $cisres->company_id;
		$post['candidate_id'] = $cisres->candidate_id;
		if($cisres->schedule_type == '2'){
			$post['email_template_id'] = 20; // retiurn send mail both rm and candidate
		}else{
			$post['email_template_id'] = 19; // retiurn send mail both rm and candidate
		}
		
		$email = $this->sendCandidatEmailPopup($post);		
		$return['email']= $email;
		return $return;
	}
