	function insertAuditTrail($get){
		global $callConfig;
		$return['get'] = $get;
		$extra_details = json_decode($get['extra_details'],1);
		$return['extra_details'] = $extra_details;
		if($get['page_option'] != "COM_VIEW_AUDITTRAILS"){
			if(isset($extra_details['child_option'])){
				$audit_trailssql = "SELECT id FROM `audit_trails` WHERE page_option = '".$get['page_option']."' AND  is_active = 0 ORDER BY created_date DESC";
				$audit_trailsres=$callConfig->getRow($audit_trailssql);
				$return['audit_trails'] = $audit_trailsres;	
				$query = "INSERT INTO `at_items`(`company_id`,`user_id`, `parent_id`, `type`, `page_option`,`extra_paramiter`, `transaction_table`, `transaction_id`, `log_query`, `where_condition`, `after_transaction_details`, `is_active`, `current_status`, `created_date`, `created_by`) VALUES ('".$get['company_id']."','".$get['user_id']."','".$audit_trailsres->id."','VIEW','".$extra_details['child_option']."','".$get['extra_paramiter']."','','','','','','0','0','".date("Y-m-d H:i:s")."','".$get['user_id']."')";
				$res =$callConfig->executeQueryString($query);

			}else{	
				$query = "INSERT INTO `audit_trails`(`company_id`, `module_setup_id`, `user_id`, `type`, `page_option`,`extra_paramiter`, `transaction_table`, `transaction_id`, `log_query`, `where_condition`, `after_transaction_details`, `is_active`, `current_status`, `created_date`, `created_by`) VALUES ('".$get['company_id']."','".$get['module_id']."','".$get['user_id']."','VIEW','".$get['page_option']."','".$get['extra_paramiter']."','','','','','','0','0','".date("Y-m-d H:i:s")."','".$get['user_id']."')";
				$return['query'] = $query;
				$res =$callConfig->executeQueryString($query);
			}
		}
		return $return;
	}
	function getAuditTrails($get){
		global $callConfig;
		$return['get'] = $get;
		$decod = json_decode($get['action_type'],1);
		$user_id = isset($get['user_profie_id']) && $get['user_profie_id']!='' ? $get['user_profie_id'] : $get['user_id'];
		$return['decod'] = $decod;
		if($get['type'] == "login"){
			if($get['from_date'] !="" && $get['to_date'] !=""){
				$condition .=" AND login_from between '".$this->dateconvertdbformat($get['from_date'])." 00:00:00' AND '".$this->dateconvertdbformat($get['to_date'])." 23:59:59'";	
			}
			$audit_trailssql = "SELECT user_id,login_from, login_to FROM application_user_logins WHERE company_id = '".$get['company_id']."' ".$condition." AND user_id = '".$user_id."' ORDER BY DATE(login_from) DESC LIMIT 20";
			$audit_trailsres=$callConfig->getAllRows($audit_trailssql);
			$return['login'] = $audit_trailsres;
			$return['loginsql']= $audit_trailssql;	
		}elseif($get['type'] == "approval"){
			$json  = implode("','",(array)$decod);
			$condition .=" AND type IN('".$json."')";
			if($get['from_date'] !="" && $get['to_date'] !=""){
				$condition .=" AND request_date between '".$this->dateconvertdbformat($get['from_date'])." 00:00:00' AND '".$this->dateconvertdbformat($get['to_date'])." 23:59:59'";	
			}
			$transaction_approval_logssql = "SELECT transaction_table,transaction_id, response_type,user_id,request_date,response_date FROM transaction_approval_logs WHERE user_id = '".$user_id."' ORDER BY DATE(request_date) DESC limit 20";
			$transaction_approval_logsres=$callConfig->getAllRows($transaction_approval_logssql);
			$return['approval'] = $transaction_approval_logsres;
			$return['approvalsql']= $transaction_approval_logssql;	
		}else{	
			if($get['action_type'] !="" AND $get['action_type'] != "null"){
				$json  = implode("','",(array)$decod);
				$condition .=" AND type IN('".$json."')";
			}else{
				$condition .=" AND type IN('VIEW')";
			}
			if($get['from_date'] !="" && $get['to_date'] !=""){
				$condition .=" AND created_date between '".$this->dateconvertdbformat($get['from_date'])." 00:00:00' AND '".$this->dateconvertdbformat($get['to_date'])." 23:59:59'";	
			}
			$audit_trailssql = "SELECT * FROM audit_trails WHERE company_id = '".$get['company_id']."' AND user_id = '".$user_id."' ".$condition." AND is_active = 0 ORDER BY created_date DESC limit 20";
			$audit_trailsres=$callConfig->getAllRows($audit_trailssql);
			$return['audit_trails'] = $audit_trailsres;
			$return['sql']= $audit_trailssql;

			$application_pagessql = "SELECT application_table_name FROM application_pages WHERE company_id = '".$get['company_id']."' AND is_active = 0";
			$application_pagesres=$callConfig->getAllRows($application_pagessql);
			$return['application_pages'] = $application_pagesres;
		}	
		return $return;
	}

	function UpdateModuleSelection($post){
		global $callConfig;
		$return = array();
		$module_id  = implode(",",$post['module_id']);
		$post_array1= array("is_active"=>null,"updated_by"=>$post['user_id'],"updated_date"=>date('Y-m-d H:i:s'));
		$where= " is_active = 0 AND linking = 1";
		$res1=$callConfig->updateRecord('module_setup',$post_array1,'','',$where);

		$linkingmodulesql = "SELECT id,parent_module_id FROM module_setup_linkings WHERE company_id = '".$post['company_id']."' AND is_active = 0";
		$linkingmoduleres=$callConfig->getAllRows($linkingmodulesql);
		foreach($linkingmoduleres as $linkingmoduleres){
			$linkingmodulelist[$linkingmoduleres->parent_module_id] = $linkingmoduleres->parent_module_id;
		}
		$linkmoduleavailbleornot = 1;
		foreach($post['module_id'] as $moduleid){
			if(isset($linkingmodulelist[$moduleid])){
				$linkmoduleavailbleornot = 0;	
			}
			$post_array= array("is_active"=>'0',"updated_by"=>$post['user_id'],"updated_date"=>date('Y-m-d H:i:s'));
			$res=$callConfig->updateRecord('module_setup',$post_array,'module_id',$moduleid);
			$return['update'][] = $res;
		}
		if($linkmoduleavailbleornot ==1){
			$post_array1= array("is_active"=>null,"updated_by"=>$post['user_id'],"updated_date"=>date('Y-m-d H:i:s'));
			$where= " is_active = 0 AND linking = 0";
			$res1=$callConfig->updateRecord('module_setup',$post_array1,'','',$where);
		}
	//email send 
		$modulesql = "SELECT id,module_name FROM module_setup WHERE company_id = '".$post['company_id']."' AND is_active = 0";
		$moduleres=$callConfig->getAllRows($modulesql);
		$return['modulesql'] = $moduleres;
		$mk = 1; foreach ($moduleres as $modulename) {
			$modulenamelist .= "<p>".$mk.") ".$modulename->module_name."</p>"; 
			$mk++;
		}

		$usersetailsql = "SELECT au.id,au.user_email,au.display_name,au.company_id,dr.default_module_id FROM application_users au, ".MAINDB.".domain_registrations dr WHERE au.company_id = '".$post['company_id']."' AND au.user_email = dr.user_email AND au.id = '".$post['user_id']."' AND au.is_active = 0";
		$usersetailres=$callConfig->getRow($usersetailsql);
		$emailarray['user_email_id'] = $usersetailres->user_email;
		$emailarray['user_display_name'] = $usersetailres->display_name;
		$emailarray['to_company_id'] = $usersetailres->company_id;
		$emailarray['session_company_id'] = $usersetailres->company_id;
		$emailarray['created_by'] = $post['user_id'];
		$emailarray['user_module'] = $modulenamelist;
		$emailarray['default_module_id'] = $usersetailres->default_module_id;
		$emailarray['created_by'] = $post['user_id'];
		$return['emailarray'] = $usersetailres;
		$return['email'] = $this->sendNotificationAndEmails($notarry,$emailarray,22);
	//End email send 
		return $return;
	}
