			$cost_centersql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator, pt.party_id, pt.party_name,  pt.total_amount, pt.cost_center_id, pt.current_status, pt.pending_amount FROM ".$dmtres->application_table_name." pt, cost_centers cc WHERE pt.company_id = '".$get['company_id']."' AND pt.company_id = cc.company_id AND pt.cost_center_id = cc.id AND pt.is_active = cc.is_active AND pt.is_active = 0 ".$condition." group by pt.id,pt.cost_center_id";
