				$dtablesql = "SELECT pt.id, ".$kitnname." as transaction_number, pt.transaction_date, pt.originator, pt.parent_item_total as total_amount, pt.current_status, pt.suspense_total as pending_amount FROM ".$get['transaction_table']." pt WHERE pt.company_id = '".$get['company_id']."' ".$conditionpopup."  AND pt.is_active = 0";
			}

		//AND originator ='".$get['user_id']."'
			$dtableres=$callConfig->getAllRows($dtablesql);
			$return['status_table_list'] = $dtableres;
			$return['status_table_list_sql'] = $dtablesql;
			if($get['transaction_table'] == "debit_notes" || $get['transaction_table'] == "credit_notes" || $get['transaction_table'] == "journal_vouchers" || $get['transaction_table'] =="bank_vouchers" || $get['transaction_table'] =="cash_vouchers"){
			$lastestdtablesql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator, pt.party_name, pt.total_amount, pt.cost_center_id, pt.current_status FROM ".$dmtres->application_table_name." pt WHERE pt.company_id = '".$get['company_id']."' ".$conditionpopup."  AND pt.is_active = 0  ORDER BY updated_date DESC LIMIT 0,10";
			
			}elseif($get['transaction_table'] == "kittings" || $get['transaction_table'] == "dekittings"){
				$kitnname = $get['transaction_table'] == "kittings"?"pt.kitting_name":"pt.dekitting_name";
				$lastestdtablesql = "SELECT pt.id, ".$kitnname." as transaction_number, pt.transaction_date, pt.originator,  pt.parent_item_total as total_amount, pt.current_status, pt.suspense_total as pending_amount FROM ".$get['transaction_table']." pt WHERE pt.company_id = '".$get['company_id']."' ".$conditionpopup."  AND pt.is_active = 0  ORDER BY updated_date DESC LIMIT 0,10";
		
			}else{
				$lastestdtablesql = "SELECT pt.id, pt.transaction_number, pt.transaction_date, pt.originator, pt.party_name, pt.total_amount, pt.cost_center_id, pt.current_status, pt.pending_amount FROM ".$dmtres->application_table_name." pt WHERE pt.company_id = '".$get['company_id']."' ".$conditionpopup."  AND pt.is_active = 0  ORDER BY updated_date DESC LIMIT 0,10";

			}
			//AND originator ='".$get['user_id']."'
			$lastestdtableres=$callConfig->getAllRows($lastestdtablesql);
			$return['latest_table_list'] = $lastestdtableres;
			$return['latest_table_list_sql'] = $dtablesql;
			if($get['transaction_table'] == "kittings" || $get['transaction_table'] == "dekittings"){
				$kitnname = $get['transaction_table'] == "kittings"?"transtable.kitting_name":"transtable.dekitting_name";
				$talsql = "SELECT tal.id, tal.transaction_id, tal.request_date, tal.response_type, tal.send_back_flag, tal.call_back, ".$kitnname." as transaction_number, transtable.transaction_date as transaction_date, transtable.originator, transtable.parent_item_total as total_amount, transtable.current_status FROM transaction_approval_logs tal, ".$get['transaction_table']." transtable WHERE tal.transaction_table = '".$get['transaction_table']."' AND tal.transaction_id = transtable.id AND  tal.company_id = '".$get['company_id']."' AND tal.company_id = transtable.company_id AND tal.user_id = '".$get['user_id']."' ORDER BY tal.request_date DESC";
			}else{
				$talsql = "SELECT tal.id, tal.transaction_id, tal.request_date, tal.response_type, tal.send_back_flag, tal.call_back, transtable.transaction_number, transtable.transaction_date, transtable.originator, transtable.party_name, transtable.total_amount, transtable.cost_center_id, transtable.current_status, transtable.pending_amount FROM transaction_approval_logs tal, ".$dmtres->application_table_name." transtable WHERE tal.transaction_table = '".$dmtres->application_table_name."' AND tal.transaction_id = transtable.id AND  tal.company_id = '".$get['company_id']."' AND tal.company_id = transtable.company_id AND tal.user_id = '".$get['user_id']."' ORDER BY tal.request_date DESC";
			}
		//$talsql = "SELECT id, transaction_id, request_date, response_type, send_back_flag, call_back FROM transaction_approval_logs  WHERE transaction_table = '".$dmtres->application_table_name."' AND  company_id = '".$get['company_id']."' AND user_id = '".$get['user_id']."' ORDER BY request_date DESC";
			$talres=$callConfig->getAllRows($talsql);
			$return['transaction_approval_logs'] = $talres;
			$return['transaction_approval_logs_sql'] = $talsql;



//genarate new docs
			//$dmtsql1 ="SELECT id, page_title, application_table_name, display_table, item_table, tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$get['company_id']."' AND genrate_next_level = '".$get['transaction_table']."' AND item_table !='' AND tax_table !='' AND is_active = 0"; 
			$dmtsql1 ="SELECT id, page_title, application_table_name, display_table, item_table, tax_table FROM dynamic_mapping_tables WHERE company_id = '".$get['company_id']."' AND application_table_name IN(SELECT transaction_table FROM `dynamic_reference_tables` WHERE company_id = '".$get['company_id']."' AND reference_table = '".$get['transaction_table']."' AND is_active = 0) AND genrate_next_level = 0 AND item_table !='' AND tax_table !='' AND is_active = 0"; 
			$return['generatesql']= $dmtsql1;
			$dmtres1=$callConfig->getAllRows($dmtsql1);
			foreach ($dmtres1 as $dmtress){
				$conditionbuild = ""; 
				$get['transaction_date_check'] = date('Y-m-d');
				$get['transaction_table'] = $get['transaction_table'];
				$getdocaccesssetup = $this->getdocumentsAccessSetupsRule($get);
				$document_access_setupsres  = $getdocaccesssetup['document_access_setupsres'];
				$docaccesssetupsuser = $getdocaccesssetup['document_access_setups_user'];
				if(count((array)$docaccesssetupsuser) !="0"){
					if($docaccesssetupsuser['approved_type'] =="cost_center_id"){
						$allowcostcenter = $getdocaccesssetup['allowcostcenter'];
						$conditionbuild .=" AND po.cost_center_id IN(".implode(',',(array)$allowcostcenter).") ";
					}
					if($docaccesssetupsuser['opex_cpex'] !=""){
						$conditionbuild .=" AND po.opex_cpex = ".$docaccesssetupsuser['opex_cpex'];
					}
					if($docaccesssetupsuser['amount'] !="" AND $docaccesssetupsuser['amount'] !="0"){
						$conditionbuild .=" AND po.total_amount <= ".$docaccesssetupsuser['amount'];
					}
					$item_categorylist = json_decode($docaccesssetupsuser['item_category']);
