						$conditionbuild .=" AND poitm.item_id in (SELECT id FROM items itm WHERE category_id IN(".implode(',',(array)$item_categorylist)."))";
					}	
				}
				$query = "select po.id, po.transaction_number, po.transaction_date, po.originator, po.party_name, GROUP_CONCAT(poitm.id SEPARATOR ',') AS itemtb_id, po.total_amount, po.pending_amount From ".$dmtress->application_table_name." po,".$dmtress->item_table." poitm WHERE po.company_id = '".$get['company_id']."' AND po.company_id = poitm.company_id AND po.id = poitm.transaction_id AND po.is_active = 0 AND po.current_status = '".ST_APPROVED."' ".$conditionbuild." GROUP BY po.id,po.party_id,po.cost_center_id,po.opex_cpex,po.transaction_number,po.transaction_date,po.total_amount,po.current_status ORDER BY po.transaction_date asc";
				$return['generatessql'][]=$query;
				$results=$callConfig->getAllRows($query);
				$return['generate'][$dmtress->application_table_name] = $results;

			}
//genarate new docs

		//$return['dynamic_mapping_tables'] = $dmtres1;


		}	

	//print_r($return['generate']);
//print_r($return);
		return $return;
	}
	function togetemployeeageprofile($post, $get){
		global $callConfig;
		$return['menu_data'] = $this->toreportempdropdown($get);
		$whr = "";
		$whrarry = array('department_id'=>'departments', 'designation_id'=>'designations', 'location_id'=>'locations', 'employee_type'=>'employment_statuses', 'division_id'=>'divisions');
		foreach($whrarry  as $wrkey=>$whra){
			if(count((array)$post[$whra])>0){
				$whr.= " AND emp.".$wrkey." IN(".implode(",",(array)$post[$whra]).") ";
			}
		}
		$query = "SELECT 
		emp.id, 
		emp.emp_code, 
		emp.display_name, 
		emp.image, 
		CONCAT( FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365)) age,
		(
		SELECT 
		department_name 
		FROM 
		`departments` dep 
		WHERE 
		dep.company_id = emp.company_id 
		AND dep.id = emp.department_id
		AND dep.is_active = emp.is_active
		) department_name, 
		(
		SELECT 
		designation_name 
		FROM 
		`designations` des 
		WHERE 
		des.is_active = emp.is_active 
		AND des.company_id = emp.company_id 
		AND des.id = emp.designation_id
		) designation_name,
		(
		SELECT 
		job_title 
		FROM 
		`job_titles` jbt 
		WHERE 
		jbt.company_id = emp.company_id 
		AND jbt.id = emp.job_title_id
		AND jbt.is_active = emp.is_active 
		) job_title, 
		(
		SELECT 
		lc.location_name 
		FROM 
		locations lc 
		WHERE 
		lc.company_id = emp.company_id 
		AND lc.id = emp.location_id
		AND lc.is_active = emp.is_active 
		) location_name,
		(
		SELECT 
		es.employment_status_name 
		FROM 
		employment_statuses es 
		WHERE 
		es.company_id = emp.company_id 
		AND es.id = emp.employee_type
		AND es.is_active = emp.is_active 
		) employment_status_name,
		(
		SELECT 
		divi.division_name 
		FROM 
		divisions divi 
		WHERE 
		divi.company_id = emp.company_id 
		AND divi.id = emp.division_id
		AND divi.is_active = emp.is_active 
		) division_name
		FROM 
		employees emp
		where 
		emp.company_id = ".$get['company_id']."
		AND (
		CASE WHEN (
		emp.date_of_leaving IS NOT NULL 
		AND emp.date_of_leaving >= now()
		) THEN 1 WHEN (
		emp.date_of_leaving IS NULL 
		AND emp.is_active = 0
		) THEN 1 ELSE 2 END
		)= 1 ".$whr."
		AND emp.is_active = '0' 

		order by 
		emp.display_name ASC";
  		echo $query; exit;
		$return['emp_query'] = $query;
		$return['emp_data'] = $callConfig->getAllRows($query);
		$query = "SELECT  CONCAT( FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365 / 5 )* 5 + 1, '-', FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365 / 5 )* 5 + 5 ) AS age_range, COUNT(*) AS employee_count FROM employees emp WHERE emp.company_id = ".$get['company_id']." AND emp.date_of_birth <= DATE_SUB(NOW(), INTERVAL 20 YEAR)  AND ( CASE WHEN ( emp.date_of_leaving IS NOT NULL AND emp.date_of_leaving >= now() ) THEN 1 WHEN ( emp.date_of_leaving IS NULL AND emp.is_active = 0 ) THEN 1 ELSE 2 END )= 1 ".$whr."  GROUP BY FLOOR( DATEDIFF(NOW(), emp.date_of_birth)/ 365 / 5 ) HAVING age_range <= '60' ORDER BY age_range ASC";
		$return['age_range'] = $callConfig->getAllRows($query);
		return $return;
	}
	function toreportempdropdown($get){
		global $callConfig;
		$menudata['divisions']=array('table_name'=>'divisions','name'=>'Divisions','field'=>'division_name','data'=>'');
		$menudata['departments']=array('table_name'=>'departments','name'=>'Departments','field'=>'department_name','data'=>'');
		$menudata['locations']=array('table_name'=>'locations','name'=>'Location','field'=>'location_name','data'=>'');
		$menudata['designations']=array('table_name'=>'designations','name'=>'Designations','field'=>'designation_name','data'=>'');
	//$menudata['job_titles']=array('table_name'=>'job_titles','name'=>'Job Title','field'=>'job_title','data'=>'');
		$menudata['employment_statuses']=array('table_name'=>'employment_statuses','name'=>'Employment Statuses','field'=>'employment_status_name','data'=>'');

		foreach($menudata as $menuda){
			$query = "SELECT id,".$menuda['field']." FROM ".$menuda['table_name']." WHERE company_id = ".$get['company_id']." AND is_active = 0";
			$menudetails = $callConfig->getAllRows($query);
		//$menudetail = (array)$menudetails;
			$edata = array();
			foreach($menudetails as $menudeta){
				$filed = $menuda['field'];
			//echo $menudeta->$filed;
			//print_r($menudeta); exit;
				$edata[$menudeta->id] = $menudeta->$filed;;
			}
			$menudata[$menuda['table_name']]['data'] =  $edata;
		}
		return $menudata;
	} 
	function payRollDashboard($get){
		global $callConfig;
		$payrollenddate = $get['pay_year']."-".$get['pay_month']."-".$get['default_payroll_day'];
		$payrollstartdate = date('Y-m-d', strtotime('-1 month', strtotime($payrollenddate)));
		$payrollsixmonthstartdate = date('Y-m-d', strtotime('-5 month', strtotime($payrollenddate)));
		$return = array();
		$sql = "SELECT count(emp.id) as total_emp, sum(if((emp.joining_date  >= '".$payrollstartdate."' AND emp.joining_date <= '".$payrollenddate."'),1,0)) as this_month_join, sum(if((emp.date_of_leaving  >= '".$payrollstartdate."' AND emp.date_of_leaving <= '".$payrollenddate."'),1,0)) as this_month_leaving FROM employees emp where emp.company_id=".$get['company_id']." AND emp.is_active=0";
		$res=$callConfig->getRow($sql);
		$return['payrollempcnt'] = $res;

		$exclusionsql = "SELECT sum(if((category_id = 1),1,0)) as exclusion_cnt, sum(if((category_id = 2),1,0)) as hold_salary_cnt, sum(if((category_id = 4),1,0)) as settlement_cnt, sum(if((category_id = 6),1,0)) as revised_cnt FROM payroll_exclusions WHERE company_id=".$get['company_id']." AND pay_year = '".$get['pay_year']."' AND pay_month = '".$get['pay_month']."' AND is_active=0";
		$exclusionres=$callConfig->getRow($exclusionsql);
		$return['payroll_exclusions'] = $exclusionres;

		$payrollstepssql = "SELECT category_id,pay_area_id FROM payroll_steps WHERE company_id=".$get['company_id']." AND pay_year = '".$get['pay_year']."' AND pay_month = '".$get['pay_month']."' AND is_active=0";
		$payrollstepsres=$callConfig->getAllRows($payrollstepssql);
		$return['payroll_steps'] = $payrollstepsres;

		$statutorysql = "SELECT menu_label,page_name FROM `application_menu` WHERE company_id=".$get['company_id']." AND parent_menu = 770 AND menu_location = 'TN' AND is_active=0 ORDER BY display_priority ASC";
		$statutoryres=$callConfig->getAllRows($statutorysql);
		$return['statutory'] = $statutoryres;
		foreach($statutoryres as $statutoryval) {
			$statutorroptions[]= $statutoryval->page_name;
		}
		$options  = implode("','",(array)$statutorroptions);
		$audit_trailssql = "SELECT page_option, max(created_date) as created_date FROM `audit_trails` WHERE company_id=".$get['company_id']." AND user_id = '".$get['user_id']."' AND page_option IN ('".$options."') AND is_active=0 group BY page_option ORDER BY created_date DESC";
		$audit_trailsres=$callConfig->getAllRows($audit_trailssql);
		$return['audit_trails'] = $audit_trailsres;

		$payrollsql = "SELECT id FROM `payroll` WHERE company_id=".$get['company_id']." AND pay_year = '".$get['pay_year']."' AND pay_month = '".$get['pay_month']."' AND is_active=0";
		$payrollres=$callConfig->getRow($payrollsql);
		$return['payroll'] = $payrollres;
		$startmonth = new DateTime($payrollsixmonthstartdate);
		$endmonth = new DateTime($payrollenddate);
		while($startmonth <= $endmonth){
			$salarycomponanatsql = "SELECT sum(if((component_id = ".GROSS_SALARY."),salary_component_actual,0)) as gross_salary, sum(if((component_id = ".EMPLOYEER_PF_CONTRIBUTION." OR component_id = ".EMPLOYEER_ESI_CONTRIBUTION."),salary_component_actual,0)) as pf_salary, sum(if((component_id = ".REIMBURSEMENT_COMPONENT."),salary_component_actual,0)) as reimbursement  FROM `pay_run_summary_components` WHERE company_id =  ".$get['company_id']." AND pay_year = '".$startmonth->format('Y')."' AND pay_month = '".$startmonth->format('m')."' AND (component_id = ".GROSS_SALARY." OR component_id = ".EMPLOYEER_ESI_CONTRIBUTION." OR component_id = ".EMPLOYEER_PF_CONTRIBUTION." OR component_id = ".REIMBURSEMENT_COMPONENT.") AND is_active = 0";
			$salarycomponanatres=$callConfig->getRow($salarycomponanatsql);
			$return['pay_run_summary_components'][$startmonth->format('M-Y')] = $salarycomponanatres;
			$startmonth->modify('+1 month');
		}
		return $return;
	}
	function getDynamicWorkFlowSteps($get){
		global $callConfig;
		$return =array();
		$transaction_no = $get['transaction_no'];
		$transaction_table  = $get['transaction_table'];
		$current_status = $get['current_status'];
		$get['table'] =$get['transaction_table'];
		$status_progress = $this->getStatusProgressList($get);
		foreach($status_progress as $statusprogress){
			$return['status_progress'][$statusprogress->status] = $statusprogress;
		}
		$aurolesql = "SELECT aumr.user_id, ar.display_name FROM application_user_module_roles aumr, application_roles ar WHERE aumr.company_id = '".$get['company_id']."' AND aumr.company_id = ar.company_id AND aumr.role_id = ar.id AND aumr.is_active = ar.is_active AND aumr.is_active = 0"; 
		$auroleres = $callConfig->getAllRows($aurolesql);
		foreach($auroleres as $aurole){
			$return['application_user_module_roles'][$aurole->user_id] = $aurole->display_name;
		}

		if($transaction_table !=""){
			$transactionsql = "SELECT * FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' AND id = '".$transaction_no."' AND is_active = 0"; 
			$transactionres = $callConfig->getRow($transactionsql);
			$return['transaction_details'] = $transactionres;
			
			$workflowsql = "SELECT id, process_name,document_type_id, process_description, workflow_trigger_status, doa,doa_trigger_field, transaction_owner_field, workflow_level, criteria, approval_process,work_level_type, notification_message, transaction_owner_type, breadcrumb_view_field_type FROM workflow_configurations_new WHERE company_id = '".$get['company_id']."' AND process_name = '".$transaction_table."' AND is_active = 0";
			if($transaction_table == TBL_DOCUMENT_MANAGEMENT && $transactionres->document_type_id != ''){
				$workflowsql .= " AND document_type_id = '".$transactionres->document_type_id."'";
			}
			$workflowres = $callConfig->getRow($workflowsql);
		}
		// echo '<pre>'; print_r($workflowres); exit;

		if(isset($workflowres->id)){
			$return['workflow_details'] = $workflowres;	
			$approval_process = json_decode($workflowres->approval_process,1);
			//print_r($approval_process); exit;
			$flowstatus[$workflowres->workflow_trigger_status] = $workflowres->workflow_trigger_status;
			$transactionownerfield = $workflowres->transaction_owner_field;
			$transaction_owner_field = $temp_owner_id = $transactionres->$transactionownerfield;
			if($workflowres->transaction_owner_type !="" AND $workflowres->transaction_owner_type !="AU"){
				$uidsql = "SELECT user_id FROM ".$workflowres->transaction_owner_type." WHERE company_id = '".$get['company_id']."' AND id = ".$transaction_owner_field." AND is_active = 0"; 
				$uidres = $callConfig->getRow($uidsql);
				$transaction_owner_field = $uidres->user_id;
			}
			$return['transaction_owner_id'] = $transaction_owner_field;
			foreach($approval_process as $approvalprocess){
				$flowstatus[$approvalprocess['workflow_level_status']] = $approvalprocess['workflow_level_status'];
				$approvalprocesssetp[$approvalprocess['workflow_level_status']] = $approvalprocess;	
			}
		

			//print_r($approvalprocesssetp); exit;

			$transactionallstatus  = $flowstatus;
			$transactionallstatus[ST_APPROVED] = ST_APPROVED;
			$transactionallstatus[ST_CALLBACK] = ST_CALLBACK;
			$transactionallstatus[ST_CANCEL] = ST_CANCEL;
			$transactionallstatus[ST_REJECTED] = ST_REJECTED;
			$transactionallstatus[ST_SEND_BACK] = ST_SEND_BACK;
			$validatestatusarry = array();	
			//check current stutus workflow start ,applicable or not
			if($workflowres->workflow_trigger_status == $current_status OR in_array($current_status, (array)$transactionallstatus)){
