		}elseif($nextstepvalue['approval_type'] =="user"){

			$sql = "select id,display_name,user_email from application_users where company_id = '".$get['company_id']."' AND  id='".$nextstepvalue['sub_approve_type']."' AND is_active = 0"; 
			$rows = $callConfig->getRow($sql); 
			$detailsusers = array("user_id"=>$rows->id,"display_name"=>$rows->display_name,"user_email"=>$rows->user_email);
			$transactionflow['aproval_user'][]= $detailsusers;

		}elseif($nextstepvalue['approval_type'] == 'access_levels'){

			$like = "'".'%"'.$nextstepvalue['sub_approve_type'].'"%'."'";
			$sql = "SELECT id, display_name, user_email FROM `application_users` WHERE company_id = '".$get['company_id']."' AND is_active = 0  AND role_id like ".$like;
