		}elseif($nextstepvalue['approval_type']== 'individual_employee_role'){
			$empsql = "select id,department_id from employees where company_id = '".$get['company_id']."' AND is_active = 0 AND user_id='".$transaction_owner_field."'";
			$empres = $callConfig->getRow($empsql); 
			$empdata = "select user_id,display_name,email_id from employees where role_id=".$nextstepvalue['sub_approve_type']." AND department_id= '".$empres->department_id."' AND company_id = '".$get['company_id']."' AND is_active='0'"; 
			$rows=$callConfig->getAllRows($empdata);
