				$transactionflow['aproval_user'][]  = $detailsusers;
			}
		}elseif($nextstepvalue['approval_type'] == 'email_groups'){
			$sql = "SELECT e.user_id,e.name,e.email FROM `email_group_emails` ege, email e WHERE ege.company_id = '".$get['company_id']."' AND ege.email_id=e.id AND ege.email_groups_id =".$nextstepvalue['sub_approve_type']." AND ege.is_active='0'"; 
			$rows=$callConfig->getAllRows($sql);
			foreach($rows as $row){
				$detailsusers = array("user_id"=>$row->user_id,"display_name"=>$row->name,"user_email"=>$row->email);
				$transactionflow['aproval_user'][]  = $detailsusers;
			}
		}elseif($nextstepvalue['approval_type'] == 'custom_field'){
			$dynfield = $nextstepvalue['sub_approve_type'];
			$approvaluid = $transactionres->$dynfield;
			$sql = "SELECT id, display_name, user_email FROM `application_users` WHERE company_id = '".$get['company_id']."' AND id = '".$approvaluid."' AND is_active = 0";
			$rows=$callConfig->getRow($sql);
			$detailsusers =array();
			$detailsusers = array("user_id"=>$rows->id,"display_name"=>$rows->display_name,"user_email"=>$rows->user_email);
			$transactionflow['aproval_user'][]  = $detailsusers;
		}elseif($nextstepvalue['approval_type'] == 'location_wise'){
			$dynfield = $nextstepvalue['sub_approve_field'];
			$location_id = '';
			if($dynfield != ''){
				$location_id = $transactionres->$dynfield;
			}
			$userIds = array();
			if(count((array)$nextstepvalue['location_approvers']) > 0){
				foreach($nextstepvalue['location_approvers'] as $locRow){
					if($locRow['location_id'] == $location_id){
						if(count((array)$locRow['user_ids']) > 0){
							foreach($locRow['user_ids'] as $uid){
								if($uid != ''){
									$userIds[$uid] = $uid;
								}
							}
