	$user_id = $get['user_id'];
	$company_id = $get['company_id'];
	$query_sal = "SELECT emp1.location_id,(SELECT user_id FROM employees emp2 WHERE emp2.company_id = emp1.company_id  AND emp2.id  = emp1.hr_buddy) as hr_buddy,(SELECT user_id FROM employees emp3 WHERE emp3.company_id = emp1.company_id  AND emp3.id  = emp1.finance_buddy) as finance_buddy,(SELECT user_id FROM employees emp4 WHERE emp4.company_id = emp1.company_id  AND emp4.id  = emp1.admin_buddy) as admin_buddy,(SELECT user_id FROM employees emp5 WHERE emp5.company_id = emp1.company_id  AND emp5.id  = emp1.project_buddy) as project_buddy,(SELECT user_id FROM employees emp6 WHERE emp6.company_id = emp1.company_id  AND emp6.id  = emp1.loc_buddy) as loc_buddy,(SELECT au.reports_to FROM application_users au WHERE au.company_id = emp1.company_id  AND au.id  = emp1.user_id) as report_to FROM employees emp1  WHERE emp1.company_id = '".$company_id."' AND emp1.user_id = '".$user_id."' AND emp1.is_active = 0";
	$res = $callConfig->getRow($query_sal);
	$location_id =$res->location_id;
	$location_sql = "select hr_connect, admin_connect, finance_connect from locations where company_id='".$company_id."' and is_active='0' and id='".$location_id."'";
	$location_details = $callConfig->getRow($location_sql);

	$companiessql = "select hr_connect,finance_connect, admin_connect from companies where company_id='".$company_id."' and is_active='0'";
	$companies_details = $callConfig->getRow($companiessql);
	$report_to = $res->report_to!=''?$res->report_to:"0";
	$hr_connect_id = $res->hr_buddy!=''?$res->hr_buddy:"0";
	$finance_connect_id = $res->finance_buddy!=''?$res->finance_buddy:"0"; 
	$admin_connect_id = $res->admin_buddy!=''?$res->admin_buddy:"0";
	$project_connect_id = $res->project_buddy!=''?$res->project_buddy:"0";
	$location_connect_id = $res->loc_buddy!=''?$res->loc_buddy:"0";	
	if($hr_connect_id=='0' || $hr_connect_id==""){
		$hr_connect_id = $location_details->hr_connect;
		if($hr_connect_id=='0' || $hr_connect_id=="" ){
			$hr_connect_id = $companies_details->hr_connect;
		}
	}
	if($finance_connect_id=='0' || $finance_connect_id==""){
		$finance_connect_id = $location_details->finance_connect;
		if($finance_connect_id=='0' || $finance_connect_id=="" ) {
			$finance_connect_id = $companies_details->finance_connect;
		}
	}
	if($admin_connect_id==0 || $admin_connect_id==""){
		$admin_connect_id = $location_details->admin_connect;
		if($admin_connect_id==0 || $admin_connect_id=="" ) {
			$admin_connect_id = $companies_details->admin_connect;
		}
	}
	if($hr_connect_id=='0' || $hr_connect_id=="" ) {
		$hr_connect_id = "0";
	}
	if($finance_connect_id=='0' || $finance_connect_id=="" ) {
		$finance_connect_id = "0";
	}
	if($admin_connect_id==0 || $admin_connect_id=="" ) {
		$admin_connect_id = "0";
	}
	$connectdetails = array('hr_connect'=>$hr_connect_id,'finance_connect'=>$finance_connect_id,'admin_connect'=>$admin_connect_id,'project_connect'=>$project_connect_id,'location_connect_id'=>$location_connect_id,'report_to'=>$report_to,'purchase_connect_id'=>'0');
	return $connectdetails;
}
