function salesInvoiceThroughDeliveryOrderCreated($get){
	global $callConfig;
	$transaction_table = $get['transaction_table'];
	$clone_table = 'delivery_orders';
	$transaction_id = $get['transaction_no'];
	$user_id = $get['user_id'];
	$company_id = $get['company_id'];
	$transtablesql = "SELECT si.*, (SELECT CONCAT(so.ref_id,'||',so.ref_type) FROM sales_orders so WHERE so.company_id = si.company_id AND so.id = si.ref_id AND si.ref_type = 'sales_orders' AND so.is_active = si.is_active ) as reftypees FROM ".$transaction_table." si WHERE si.company_id='".$company_id."' AND si.id = '".$transaction_id."' AND si.is_active='0'";
	$transtableres = $callConfig->getRow($transtablesql);
	$return['transtablesql'] = $transtablesql;
	$return['transtableres'] = $transtableres;
	if($transtableres->ref_no ==""){

		$transaction_table_dmtsql = "SELECT id, page_title, application_table_name,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$company_id."' AND application_table_name = '".$transaction_table."' AND is_active = 0 AND item_table !='' AND tax_table!=''";
		$transaction_table_dmtres=$callConfig->getRow($transaction_table_dmtsql);
		$return['transaction_table_dmtres'] = $transaction_table_dmtres;

		$clone_table_dmtsql = "SELECT id, page_title, application_table_name,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$company_id."' AND application_table_name = '".$clone_table."' AND is_active = 0 AND item_table !='' AND tax_table!=''";
		$clone_table_dmtres=$callConfig->getRow($clone_table_dmtsql);
		$return['clone_table_dmtres'] = $clone_table_dmtres;
		$reftablename = $transaction_table_dmtres->application_table_name;
		$reftableid = $transaction_id;
		if($transaction_table_dmtres->application_table_name =="sales_invoices"){
			$reftablename = "sales_orders";
			$reftableid = "ref_id";
			
		}
		$refto_ref_tarn = explode('||',$transtableres->reftypees);
		$refto_ref_tarn_table = $refto_ref_tarn['1'];
		if($refto_ref_tarn_table  == 'delivery_challans'){ //approved sales invoice this time exicute
			$refto_ref_tarn_id = $refto_ref_tarn['0'];
			$dcquery = "SELECT item_id, SUM(item_quantity) as item_qty FROM dc_items WHERE company_id = '".$get['company_id']."' AND transaction_id = '".$refto_ref_tarn_id."' AND is_active = 0 GROUP BY item_id";
			$dcitemres = $callConfig->getAllRows($dcquery);
			$dvitemidwithqyt = array();
			foreach($dcitemres as $dcre){
				$dvitemidwithqyt[$dcre->item_id] = $dcre->item_qty;
			}
			$queryre = "SELECT * FROM ".$transaction_table_dmtres->item_table." WHERE company_id = '".$get['company_id']."' AND transaction_id = '".$transaction_id."' AND is_active = 0";
			$itemsrows = $callConfig->getAllRows($queryre);
			$itemtranslist = array();
			$main_amount = $main_tax_amount = 0;
			foreach($itemsrows as $itrows){
				$dc_item_qty = $dvitemidwithqyt[$itrows->item_id]; 
				if($dc_item_qty !=""){
					$item_amount = $itrows->item_amount;
					$item_price = $itrows->item_price;
					$tax_amount = $itrows->tax_amount;
					$item_quantity = $itrows->item_quantity;
					$dcamt = $item_price*$dc_item_qty;
					$discount_amount = $itrows->discount_amount;
					$tax_amount_all = $tax_amount/$item_quantity; 
					$itrows->item_amount = $itrows->total_amount = $itrows->item_amount-$dcamt;
					$itrows->item_quantity = $itrows->pending_qty = ($itrows->item_quantity-$dc_item_qty);
					$itrows->tax_amount = ($tax_amount_all*($itrows->item_quantity-$dc_item_qty));
				}
				$itemtranslist[] = $itrows;
			}
			foreach($itemtranslist as $itrow){
				$main_amount += ($itrow->item_amount-$itrow->discount_amount);
				$main_tax_amount += $itrow->tax_amount;
			}
			$main_total_amount = $main_pending_amount = ($main_amount+$main_tax_amount);
		}else{
			$queryre = "SELECT * FROM ".$transaction_table_dmtres->item_table." WHERE company_id = '".$get['company_id']."' AND transaction_id = '".$transaction_id."' AND is_active = 0";
			$itemtranslist = $callConfig->getAllRows($queryre);

			$main_tax_amount = 'tax_amount';
			$main_total_amount = 'total_amount';
			$main_pending_amount = 'total_amount';
			$main_amount = 'amount';
		}
		$return['itemtranslist'] = $itemtranslist;		
		$transaction_number	= $this->toGetApplicationSerialNumber($clone_table_dmtres->application_table_name,$get);
		$exicutesql = "INSERT INTO ".$clone_table_dmtres->application_table_name."(`company_id`, `cost_center_id`, `transaction_number`, `transaction_date`, `transaction_location_id`, `transaction_warehouse_id`, `originator_currency_id`, `currency_id`, `currency_rate`, `originator`, `party_id`, `party_name`, `party_email`, `party_tax_number`, `party_phone`, `party_address`, `party_ship_adderss`, `originator_state_id`, `supplier_state_id`, `place_of_supply`, `payment_terms`, `notes`, `printing_notes`, `amount`, `tax_amount`, `type`, `tax_type`, `discount_type`, `discount_value`, `discount_amount`, `total_amount`, `shipping_tax`, `shipping_amount`, `shipping_tax_amount`, `tax_state`, `opex_cpex`, `doc_ref_no`, `doc_ref_date`, `due_date`, `ref_type`, `ref_id`, `ref_no`, `ref_date`, `payment_term_history`, `follow_up_level_ids`, `pending_amount`, `cancel_invoice`, `cancel_invoice_date`, `cancel_invoice_reason`, `additional_charges`, `total_tds_amount`, `advance_payment`, `pending_advance_payment`, `total_tax_split_details`, `rounding_off`, `is_active`, `current_status`, `created_date`, `created_by`) SELECT  `company_id`, `cost_center_id`, '".$transaction_number."', `transaction_date`, `transaction_location_id`, `transaction_warehouse_id`, `originator_currency_id`, `currency_id`, `currency_rate`, `originator`, `party_id`, `party_name`, `party_email`, `party_tax_number`, `party_phone`, `party_address`, `party_ship_adderss`, `originator_state_id`, `supplier_state_id`, `place_of_supply`, `payment_terms`, `notes`, `printing_notes`, ".$main_amount.", ".$main_tax_amount.", `type`, `tax_type`, `discount_type`, `discount_value`, `discount_amount`, ".$main_total_amount.", `shipping_tax`, `shipping_amount`, `shipping_tax_amount`, `tax_state`, `opex_cpex`, `doc_ref_no`, `doc_ref_date`, `due_date`,'".$reftablename."', ".$reftableid.",'', `transaction_date`, `payment_term_history`, `follow_up_level_ids`,".$main_pending_amount.", `cancel_invoice`, `cancel_invoice_date`, `cancel_invoice_reason`, `additional_charges`, `total_tds_amount`, `advance_payment`, `pending_advance_payment`, `total_tax_split_details`, `rounding_off`, 0, ".ST_APPROVED.",'".date('Y-m-d H:i:s')."', '".$get['user_id']."' FROM ".$transaction_table_dmtres->application_table_name." WHERE  id='".$transaction_id."'  AND is_active = 0";
		$mainres = $callConfig->executeQuery($exicutesql);
		$return['res'][] = $mainres;
		
		if($mainres['status'] == 'sucess'){
			$main_transaction_id = $mainres['LASTID'];
			foreach($itemtranslist as $itrow){

				$itmetablesql = "INSERT INTO ".$clone_table_dmtres->item_table."( `company_id`, `transaction_id`, `item_id`, `account_code`, `item_name`, `description`, `purchase_uom`,`invoice_item_quantity`, `item_quantity`, `item_price`, `item_amount`, `tax_amount`, `discount_amount`, `total_amount`, `doc_ref_no`, `doc_ref_date`, `req_date`, `item_st_cost`, `item_fifo_cost`, `item_lifo_cost`, `item_wa_cost`, `approved_quantity`, `transaction_type`, `transaction_qty`, `pending_qty`, `item_details`, `tds_amount`, `ref_transaction_item_table_id`, `ref_transaction_table_id`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, `created_by`) 
				SELECT  `company_id`, '".$main_transaction_id."', `item_id`, `account_code`, `item_name`, `description`, `purchase_uom`, ".$itrow->item_quantity.", ".$itrow->item_quantity.", `item_price`, ".$itrow->item_amount.", ".$itrow->tax_amount.", `discount_amount`, ".$itrow->total_amount.", `doc_ref_no`, `doc_ref_date`, `req_date`, `item_st_cost`, `item_fifo_cost`, `item_lifo_cost`, `item_wa_cost`, `approved_quantity`, `transaction_type`, `transaction_qty`, 0, `item_details`, `tds_amount`, '".$itrow->id."', $transaction_id ,`is_active`, `current_status`, `status_date`, `from_date`, `to_date`, '".date("Y-m-d H:i:s")."','".$get['user_id']."' FROM ".$transaction_table_dmtres->item_table." WHERE company_id = '".$get['company_id']."' AND id = '".$itrow->id."' AND is_active = 0";	
				$itemres = $callConfig->executeQuery($itmetablesql);
				$return['items'] = $itemres;

				if($itemres['status'] == 'sucess'){
					if($refto_ref_tarn_table  == 'delivery_challans'){ //approved sales invoice this time exicute
						$tax_tax_amount = $itrow->tax_amount;
						$tax_amount = ($itrow->item_amount - $itrow->discount_amount);
						$tax_total_amount = ($itrow->item_amount - $itrow->discount_amount);
					}else{
						$tax_tax_amount = "tax_amount";
						$tax_amount = "amount";
						$tax_total_amount = "total_amount";
					}
					$taxtablesql = "INSERT INTO ".$clone_table_dmtres->tax_table." (`company_id`, `transaction_id`, `transaction_item_id`, `tax_name`, `tax_value`, `tax_id`, `amount`, `tax_amount`, `total_amount`, `tax_type`, `tax_split_details`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, `created_by`,`transaction_item_row_id`)
					 SELECT `company_id`, '".$main_transaction_id."', `transaction_item_id`, `tax_name`, `tax_value`, `tax_id`, ".$tax_amount.", ".$tax_tax_amount.", ".$tax_total_amount.", `tax_type`, `tax_split_details`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, '".date("Y-m-d H:i:s")."','".$get['user_id']."', '".$itemres['LASTID']."' FROM ".$transaction_table_dmtres->tax_table." WHERE company_id = '".$get['company_id']."' AND transaction_id = '".$transaction_id."' AND transaction_item_row_id = '".$itrow->id."' AND is_active = 0 ";	
					$return['tax'] = $callConfig->executeQuery($taxtablesql);
				}

			}
	
			$updatetrntabary=array('updated_by'=>$get['user_id'],'updated_date'=>date("Y-m-d H:i:s"),'ref_no'=>$main_transaction_id);
			$where = " id = '".$transaction_id."'";
			$transaction_log_update=$callConfig->updateRecord($transaction_table_dmtres->application_table_name,$updatetrntabary,'','',$where);

			$transtablesql = "SELECT * FROM ".$clone_table." WHERE company_id='".$company_id."' AND id = '".$main_transaction_id."' AND is_active='0'";
			$transactiondetails = $callConfig->getRow($transtablesql);
			$return['transtablesql11'] = $transtablesql;	
			$return['transactiondetails'] = $transactiondetails;			
			
			$get['transaction_table'] = $clone_table;
			$get['transaction_no'] = $main_transaction_id;
			$qtytrans = $this->updateTransactionItemsQty($get,$transactiondetails,"-");
			$return['qtytrans'] = $qtytrans;	
			
			$jvtrans = $this->tocreatejounalvoucherbaseallcases($clone_table,$main_transaction_id);
			$return['jvtrans'] = $jvtrans;	
		}
	}
	//echo "<pre>"; print_r($return);
	return 0;
}



