			$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$get['transaction_no'],'application_table_name'=>$get['transaction_table'],'type'=>'INFORMATION', 'notification_users'=>$infouser_ids,'option'=>$option,'assigner_id'=>$get['user_id']);
			$return['originator_email'] = $this->sendNotificationAndEmails($notarry,$emailarray,$emailtempid);
			//chnage part today - 2024-11-08

			

		}elseif($nextlevelstatus !=ST_APPROVED AND $transactiontableupdateornot == '0'){
			
			$loginusersql = "SELECT id, display_name, user_email FROM `application_users` WHERE company_id = '".$get['company_id']."' AND id = '".$get['user_id']."' AND is_active = 0";
			$loginuserres = $callConfig->getRow($loginusersql);	
			$msglist = $this->workFlowSendNotificatinMsg($get,$transaction_owner_id,$workflow_details,$transaction_details);
			foreach($nextlevelstatusandetails['aproval_user'] as $nextlevelstatusandetail){
				$appv_fieldnames=array('company_id'=>$get['company_id'],'module_setup_id'=>$callConfig->module_id,'transaction_table'=>$get['transaction_table'],'transaction_id'=>$get['transaction_no'],'user_id'=>$nextlevelstatusandetail['user_id'],'request_date'=>date("Y-m-d H:i:s"),'send_back_flag' => '0','response_type'=>'0','assigner_user_id'=>$get['user_id'],'previous_status'=>$get['current_status']);
				$callConfig->insertRecord(TBL_TRANSACTION_APPROVAL_LOGS,$appv_fieldnames);
				//Start users message
				$user_ids = array('0'=>$nextlevelstatusandetail['user_id']);
				$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$msglist['approve_message'], 'id'=>$get['transaction_no'],'application_table_name'=>$get['transaction_table'],'type'=>'ACTION', 'notification_users'=>$user_ids,'option'=>$option,'assigner_id'=>$get['user_id']);	
				$emailarray['approval_user_email_id'] = $nextlevelstatusandetail['user_email'];
				$emailarray['user_display_name'] = $nextlevelstatusandetail['display_name'];
				foreach($transaction_details as $fielkey=>$fieldvalue){
					$emailarray[$fielkey] = $fieldvalue;
				}
				$emailarray['transaction_date_and_time'] = date("Y-m-d H:i:s");
				$emailarray['to_company_id'] = $get['company_id'];
				$emailarray['session_company_id'] = $get['company_id'];
				$emailarray['default_module_id'] = $callConfig->module_id;
				$emailarray['created_by'] = $get['user_id'];
				if($get['requester_send'] == "N"){
					$emailarray['requester_user_email_id'] = '';
					$emailarray['requester_display_name'] = '';
				}else{
					$emailarray['requester_user_email_id'] = $loginuserres->user_email;
					$emailarray['requester_display_name'] = $loginuserres->display_name;
				}
				$return['email'] = $this->sendNotificationAndEmails($notarry,$emailarray,61);
				$infouser_ids[$transaction_owner_id] = $transaction_owner_id;
				$approvalmessage = $this->replacestringwithpreview($get['transaction_table'],array('approval_name'=>$nextlevelstatusandetail['display_name']),$msglist['employee_message']);
				$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$approvalmessage, 'id'=>$get['transaction_no'],'application_table_name'=>$get['transaction_table'],'type'=>'INFORMATION', 'notification_users'=>$infouser_ids,'option'=>$option,'assigner_id'=>$get['user_id']);
				$return['originator_email'] = $this->sendNotificationAndEmails($notarry,'',23);
			}
				//END users message
			/**
			if(in_array($get['transaction_table'], (array)$out_array) AND $get['next_status']==ST_APPROVED1){
				$this->updateTransactionItemsQty($get,$transaction_details,"+");
			}elseif(in_array($get['transaction_table'], (array)$in_array) AND $get['next_status']==ST_APPROVED1){
				$this->updateTransactionItemsQty($get,$transaction_details,"-");
			}
			**/
			// if($get['transaction_table']=="purchase_orders" AND $get['next_status']==ST_APPROVED1){
			// 	$this->updateTransactionItemsQty($get,$transaction_details,"-");
			// }
			if($get['transaction_table']=="employee_leaves"){
				$this->updateleavedays($get['next_status'],$get);
			}
		}
	}	
	$return['get'] = $get;	
	$return['transaction_update'] = $transaction_update;
	return $return;
}
function documentGenerationNextProcess($get,$transaction,$nexttransaction){
	global $callConfig;
	$return = array();
