			/** cost center check
			foreach($userwithrolepermision as $keyuid=>$uidper){
				$alluserid[$keyuid] =$keyuid;
			}
			$userccsql = "SELECT id, cost_center_id, user_id FROM user_cost_centers WHERE company_id = '".$get['company_id']."' AND user_id = '".implode(",",$alluserid)."' AND is_active = 0";
			$userccres =  $callConfig->getAllRows($userccsql);
			foreach($userccres as $userccres){
				$allowcostcenter[$userccres->user_id][$userccres->cost_center_id] = $userccres->cost_center_id;
