			$userccres1 =  $callConfig->getAllRows($divsql);
			foreach($userccres1 as $userccres){
				$allowcostcenter[$userccres->user_id][$userccres->cost_center_id] = $userccres->cost_center_id;
			}
			$divsql = "SELECT cc.cost_center_name,cc.id FROM user_departments ud, cost_centers cc WHERE ud.company_id = '".implode(",",$alluserid)."' AND ud.user_id = '".$userid."' AND ud.company_id = cc.company_id AND ud.department_id = cc.department_id AND ud.is_active = cc.is_active AND ud.is_active = 0 GROUP BY cc.id";
			$userccres2 =  $callConfig->getAllRows($divsql);
			foreach($userccres2 as $userccres){
				$allowcostcenter[$userccres->user_id][$userccres->cost_center_id] = $userccres->cost_center_id;
			}
