			$divres =  $callConfig->getAllRows($divsql);
			foreach($divres as $divress){
				$allowdivisionusers[$divress->user_id] = $divress->user_id;
			}
			$dipartmentsql = "SELECT ucc1.id, ucc1.department_id, ucc1.user_id FROM user_departments ucc1, user_departments ucc2 WHERE ucc1.company_id = '".$get['company_id']."' AND ucc1.user_id IN(".implode(",",(array)$alluserid).") AND ucc2.user_id = ".$transaction_owner_id." AND ucc1.is_active = 0 AND ucc1.department_id = ucc2.department_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
			$dipartmentres =  $callConfig->getAllRows($dipartmentsql);
			foreach($dipartmentres as $divress){
				$allowdepartmentusers[$divress->user_id] = $divress->user_id;
			}
			$userccsql = "SELECT ucc1.id, ucc1.cost_center_id, ucc1.user_id FROM user_cost_centers ucc1, user_cost_centers ucc2 WHERE ucc1.company_id = '".$get['company_id']."' AND ucc1.user_id IN(".implode(",",(array)$alluserid).") AND ucc2.user_id = ".$transaction_owner_id." AND ucc1.is_active = 0 AND ucc1.cost_center_id = ucc2.cost_center_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
			$userccres =  $callConfig->getAllRows($userccsql);
			foreach($userccres as $userccress){
				$allowcostcenterusers[$userccress->user_id] = $userccress->user_id;
			}
			$locationusersql = "SELECT ucc1.id, ucc1.location_id, ucc1.user_id FROM user_locations ucc1, user_locations ucc2 WHERE ucc1.company_id = '".$get['company_id']."' AND ucc1.user_id IN(".implode(",",(array)$alluserid).") AND ucc2.user_id = ".$transaction_owner_id." AND ucc1.is_active = 0 AND ucc1.location_id = ucc2.location_id AND ucc1.company_id = ucc2.company_id AND ucc1.is_active = ucc2.is_active";
			$locationuserres =  $callConfig->getAllRows($locationusersql);
			foreach($locationuserres as $locationress){
				$allowlocationusers[$locationress->user_id] = $locationress->user_id;
			}
		}
