// echo "deprt - "; print_r($allowdepartmentusers);
// echo "cc - "; print_r($allowcostcenterusers);
// echo "loatin - "; print_r($allowlocationusers);
// exit;
		$infouser_ids = array();
		//print_r($nextlevelcreationuser);
		foreach ($nextlevelcreationuser as $userid => $values){
			$docaccesssetupsuser = $values;
			$nomatch = 0;
			if(count((array)$docaccesssetupsuser) !="0"){
				$conditionbuild="";
				// if($docaccesssetupsuser['approved_type'] !=""){
				// 	if(in_array($transaction->cost_center_id,(array)$allowcostcenter[$userid])){ }else{
				// 		$nomatch++;
				// 	}
				// }  
				if($docaccesssetupsuser['approved_type'] !=""){
					if($docaccesssetupsuser['approved_type'] =="DIV"){
						if(isset($allowdivisionusers[$userid])){ }else{
							$nomatch++;
						}
					}elseif($docaccesssetupsuser['approved_type'] =="D"){
						if(isset($allowdepartmentusers[$userid])){ }else{
							$nomatch++;
						}
					}elseif($docaccesssetupsuser['approved_type'] =="cost_center_id"){
						if(isset($allowcostcenterusers[$userid])){ }else{
							$nomatch++;
						}
					}elseif($docaccesssetupsuser['approved_type'] =="L"){
						if(isset($allowlocationusers[$userid])){ }else{
							$nomatch++;
						}
					}
				}
				//echo $docaccesssetupsuser['approved_type']."-userid - ".$userid." -- ".$nomatch."</br>";
				if($docaccesssetupsuser['opex_cpex'] !=""){
					if($transaction->opex_cpex == $docaccesssetupsuser['opex_cpex']){ }else{
						$nomatch++;
					}
				}
				if($docaccesssetupsuser['amount'] !="" AND $docaccesssetupsuser['amount'] !="0"){
					if($transaction->total_amount <= $docaccesssetupsuser['amount']){ }else{
						$nomatch++;
					}
				}
				$item_categorylist = json_decode($docaccesssetupsuser['item_category']);
				if(count((array)$item_categorylist) !="0"){
					$matchornot = array_intersect((array)$catgoryarr, (array)$item_categorylist);
					if (count((array)$matchornot) > 0) { }else{
						$nomatch++;
					}
				}
				$transaction_type = json_decode($docaccesssetupsuser['transaction_type']);
				if(count((array)$transaction_type) !="0"){
					if(in_array($transaction->opex_cpex, (array)$transaction_type)){ }else{
						$nomatch++;
					}
				}
				if($nomatch ==0 ){
					$infouser_ids[$userid] = $userid;
				}
			}
		}
		if(count((array)$infouser_ids) !="0"){
			$msg = "Next Proceess Documents Is -".$transaction->transaction_number;
			$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$transaction->id,'application_table_name'=>$get['transaction_table'],'type'=>'ACTION', 'notification_users'=>$infouser_ids,'option'=>$dmtres->option_url,'assigner_id'=>$get['user_id']);
			$return['nextlevel_assigner_doumnets'] = $this->sendNotificationAndEmails($notarry,'',23);	
		}else{
			$msg = "Next Proceess Not Set -".$transaction->transaction_number;
			$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$transaction->id,'application_table_name'=>$get['transaction_table'],'type'=>'ACTION', 'notification_users'=>array($transaction_owner_id),'option'=>$dmtres->option_url,'assigner_id'=>$get['user_id']);
			$return['nextlevel_assigner_doumnets'] = $this->sendNotificationAndEmails($notarry,'',23);	
		}
	}
	return $return;

}

function insertESOPVestingSchedule($transaction_details,$get){
	global $callConfig;
	// $vestingschedulesql = "SELECT expected_option_benefit, options_granted, vesting_schedule FROM esop_plan_buckets WHERE company_id = '".$get['company_id']."' AND id = '".$transaction_details->esop_bucket_id."' AND is_active=0";
	// $vestingscheduleres = $callConfig->getRow($vestingschedulesql);
	
	$vesting_schedule = json_decode($transaction_details->vesting_schedule,1);
	foreach($vesting_schedule  as $vs){
		$total_amount = $transaction_details->expected_option_benefit*$transaction_details->option_granted;
		$distributamount = round(($vs['vesting_percentage']/100)*$total_amount,2);
		$distributshare = round(($vs['vesting_percentage']/100)*$transaction_details->option_granted,2);
		$inservs =array('company_id'=>$get['company_id'],'esop_allocation_id'=>$transaction_details->id,'allocation_date'=>$this->dateconvertdbformat($vs['vesting_date']),'till_date'=>$this->dateconvertdbformat($vs['till_date']),'Percentage'=>$vs['vesting_percentage'],'total_amount'=>$distributamount,'allocation_share'=>$distributshare,'is_active'=>'0','current_status'=>'0','created_by'=>$get['user_id'],'created_date'=>date("Y-m-d H:i:s"));
		$res1 = $callConfig->insertRecord('esop_vesting_schedule',$inservs);
	}
}

