function workFlowSendNotificatinMsg($get,$transaction_owner_id, $workflow_details,$transaction_details){
	global $callConfig;
	$returnarray = array();
	//echo "<pre>"; //print_r($workflowdetails);
	//$process = array("process_name"=>ucwords(str_replace("_"," ",($post['tablename']))));
	$process = array("process_name"=>$workflow_details->process_name);
	//$process = array("process_name"=>$workflow_details->process_name);
	//$msg = $this->replacestringwithpreview($get['transaction_table'],$process,$msg);
	
	//$returnarray['transaction_details'] = $transaction_details;
	//$msg = $this->replacestringwithpreview($get['transaction_table'],$transaction_details,$msg);
	
	$transaction_employee_sql = "SELECT * FROM employees where company_id = '".$get['company_id']."' AND user_id='".$transaction_owner_id."' AND is_active = 0";
	$transaction_employee_detals=$callConfig->getRow($transaction_employee_sql);
	//$msg = $this->replacestringwithpreview('employees',$transaction_employee_detals,$msg);
	
	$transaction_user_sql = "SELECT * FROM application_users where company_id = '".$get['company_id']."' AND id='".$transaction_owner_id."' AND is_active = 0";
	$transaction_user_details=$callConfig->getRow($transaction_user_sql);
	//$msg = $this->replacestringwithpreview('application_users',$transaction_user_details,$msg);
	
	$sessionuser_sql = "SELECT * FROM application_users where company_id = '".$get['company_id']."' AND id='".$get['user_id']."' AND is_active = 0";
	$sessionuser_details=$callConfig->getRow($sessionuser_sql);
	//$msg = $this->replacestringwithpreview('session_user',$sessionuser_details,$msg);
	
	$sessionemployee_sql = "SELECT * FROM employees where company_id = '".$get['company_id']."' AND user_id='".$get['user_id']."' AND is_active = 0";
	$sessionemployee_details=$callConfig->getRow($sessionemployee_sql);
	//$msg = $this->replacestringwithpreview('session_employee',$sessionemployee_details,$msg);
	
	$statussql = "SELECT name FROM status_progress where company_id = '".$get['company_id']."' and status='".$get['next_status']."' AND table_name = '".$get['transaction_table']."'";
	$statusres=$callConfig->getRow($statussql);
	if($statusres->name !=""){
		$statusres->transaction_status = $statusres->name;
	}else{
		$statusres->transaction_status = "Not Found";
	}
	//$msg = $this->replacestringwithpreview($get['transaction_table'],$statusres,$msg);
	//$msg .= " ".$statusres->name;
	$notification_message_array = array('approve_message','approve_message_information','reject_message','sendback_message','completed_workflow_message','callback','employee_message');
	foreach($notification_message_array as $msg_type){
		$notification_message = json_decode($workflow_details->notification_message,1);
		$msg = $notification_message[$msg_type];
		$msg = $this->replacestringwithpreview($get['transaction_table'],$process,$msg);
		$msg = $this->replacestringwithpreview($get['transaction_table'],$transaction_details,$msg);
		$msg = $this->replacestringwithpreview('employees',$transaction_employee_detals,$msg);
		$msg = $this->replacestringwithpreview('application_users',$transaction_user_details,$msg);
		$msg = $this->replacestringwithpreview('session_user',$sessionuser_details,$msg);
		$msg = $this->replacestringwithpreview('session_employee',$sessionemployee_details,$msg);
		$msg = $this->replacestringwithpreview($get['transaction_table'],$statusres,$msg);
		$returnarray[$msg_type] = $msg;
	}
	return $returnarray; 
} 
function getDynamicQuotationDetails($get){
	global $callConfig;
	$application_userssql = "SELECT id,display_name FROM application_users where company_id = '".$get['company_id']."'";
	$application_usersres=$callConfig->getAllRows($application_userssql);
	$return['application_users'] = $application_usersres;

	$vendorsql = "SELECT * FROM ".TBL_VENDOR." where company_id = '".$get['company_id']."'";
	$vendorres=$callConfig->getAllRows($vendorsql);
	$return['vendors'] = $vendorres;
	if($get['location_id']!=""){
		$locationsql = "SELECT * FROM ".TBL_LOCATIONS." where company_id = '".$get['company_id']."' AND id = '".$get['location_id']."'";
		$locationres=$callConfig->getRow($locationsql);
		$return['location'] = $locationres;
	}

	$return['getplaceofsuppl'] = $this->getplaceofsupply($get['company_id']);

	$frequencysql = "SELECT genc_detail_code,genc_detail_name  FROM ".TBL_GENRAL_CODE_DETAILS." WHERE company_id='".$get['company_id']."' AND genc_code='PAYMETERM' AND is_active=0"; 
	$frequencyres = $callConfig->getAllRows($frequencysql);
	$return['posresponsept'] = $frequencyres;

	$uomsql = "SELECT id as genc_detail_code,uom_short_code as genc_detail_name  FROM unit_of_measurements WHERE company_id='".$get['company_id']."' AND is_active=0"; 
	$uomres = $callConfig->getAllRows($uomsql);
	$return['uomlist'] = $uomres;

	$frequencysql = "SELECT genc_detail_code,genc_detail_name  FROM ".TBL_GENRAL_CODE_DETAILS." WHERE company_id='".$get['company_id']."' AND genc_code='TRANSACTIONTYPE' AND is_active=0"; 
	$frequencyres = $callConfig->getAllRows($frequencysql);
	$return['itemtypelist'] = $frequencyres;

	$petty_cash_boxessql = "SELECT * FROM petty_cash_boxes WHERE company_id='".$get['company_id']."' AND is_active=0"; 
	$petty_cash_boxesres = $callConfig->getAllRows($petty_cash_boxessql);
	$return['boxlist'] = $petty_cash_boxesres;
	
	$departentssql = "SELECT * FROM ".TBL_DEPARTMENTS." WHERE company_id='".$get['company_id']."' AND is_active=0"; 
	$departentsres = $callConfig->getAllRows($departentssql);
	$return['departments'] = $departentsres;
	
	$currencysql = "SELECT id,currency_list FROM ".TBL_CURRENCIES." WHERE company_id='".$get['company_id']."' AND is_active=0"; 
	$currencyres = $callConfig->getAllRows($currencysql);
	$return['currentcy_data'] = $currencyres;

	$cost_centerssql = "SELECT * FROM ".TBL_COST_CENTERS." WHERE company_id='".$get['company_id']."' AND is_active=0"; 
	$cost_centersres = $callConfig->getAllRows($cost_centerssql);
	$return['cost_centers'] = $cost_centersres;
	if($get['cos_user_id']!=""){
   		$cost_centerssql = "SELECT cost_center_id FROM ".TBL_USERS_COST_CENTERS." WHERE company_id='".$get['company_id']."' AND user_id = ".$get['cos_user_id']." AND is_active=0"; 
		$cost_centersres = $callConfig->getAllRows($cost_centerssql);
		$return['user_cost_centers'] = $cost_centersres;
	}
	$payment_termssql = "SELECT id, payment_term_name, content FROM payment_terms WHERE company_id='".$get['company_id']."' AND is_active=0"; 
	$payment_termsres = $callConfig->getAllRows($payment_termssql);
	$return['payment_terms'] = $payment_termsres;

	//$return['dynamic_mapping_tables'] = $this->toGetInvoicetables();
	$return['dynamic_mapping_tables']  = $this->toGetDynamicInvoicetables();

   // -------------------- Start chart_of_accounts ---------------------------
	$additional_chargessql = "SELECT id,charge_name FROM `additional_charges` WHERE company_id='".$get['company_id']."' AND is_active=0";
    $additional_chargesres = $callConfig->getAllRows($additional_chargessql);
    $return['additional_charges']= $additional_chargesres;	
    // -------------------- End chart_of_accounts ---------------------------
	return $return; 
}

