			$originatersql = "SELECT ud2.user_id, ud1.department_id FROM user_departments ud1, user_departments ud2  WHERE ud1.company_id ='".$get['company_id']."' AND ud1.company_id = ud2.company_id AND ud1.user_id = '".$get['user_id']."' AND ud1.department_id = ud2.department_id AND ud1.is_active = ud2.is_active AND ud1.is_active = 0 GROUP BY ud2.user_id, ud1.department_id";
			$originaterres =  $callConfig->getAllRows($originatersql);
			foreach($originaterres as $originater0){
				$originator[$originater0->user_id] = $originater0->user_id;
			}
		}elseif($approvedusercriteria['onbehalf'] == "cost_center_id"){
			$originatersql = "SELECT ud2.user_id, ud1.cost_center_id FROM user_cost_centers ud1, user_cost_centers ud2  WHERE ud1.company_id ='".$get['company_id']."' AND ud1.company_id = ud2.company_id AND ud1.user_id = '".$get['user_id']."' AND ud1.cost_center_id = ud2.cost_center_id AND ud1.is_active = ud2.is_active AND ud1.is_active = 0 GROUP BY ud2.user_id, ud1.cost_center_id ";
			$originaterres =  $callConfig->getAllRows($originatersql);
			foreach($originaterres as $originater0){
				$originator[$originater0->user_id] = $originater0->user_id;
			}
		}elseif($approvedusercriteria['onbehalf'] == "L"){
			$originatersql = "SELECT ud2.user_id, ud1.location_id FROM user_locations ud1, user_locations ud2  WHERE ud1.company_id ='".$get['company_id']."' AND ud1.company_id = ud2.company_id AND ud1.user_id = '".$get['user_id']."' AND ud1.location_id = ud2.location_id AND ud1.is_active = ud2.is_active AND ud1.is_active = 0 GROUP BY ud2.user_id, ud1.location_id";
			$originaterres =  $callConfig->getAllRows($originatersql);
			foreach($originaterres as $originater0){
				$originator[$originater0->user_id] = $originater0->user_id;
			}
		}elseif($approvedusercriteria['onbehalf'] == "U"){
			$originator = json_decode($approvedusercriteria['foruser'],1);
		}
	}
	$returnres['originator'] = $originator;
	return $returnres;
////////////////////////////////////////////////////////////////////////////
}
function getTopUpdetails($get){
	global $callConfig;
	$application_table = $get['transaction_table'];
	$condition = "";
	$getnew = $get;
	$getnew['transaction_date_check'] = $get['transaction_date_check'];
	//$getnew['user_id'] = $get['oid'];
	$returnres = $this->getdocumentsAccessSetupsRule($getnew);
	$displayattributessql = "SELECT id,application_table_name,help_text,list_attributes,empty_table_message,insert_page_type, help_text, file_upload FROM display_attributes WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$application_table."' AND is_active = 0";
	$displayattributesres =  $callConfig->getRow($displayattributessql);
	$returnres['display_attributes'] = $displayattributesres;


	$lists = json_decode($displayattributesres->list_attributes,1);
	$type_array = array('select','multi_select','disable_select','radio','checkbox', 'color_pick','image');
	foreach ($lists as $key => $value){
		if(in_array($value['type'], (array)$type_array)){
			$tablefield = $this->getDyanamicSelectData($application_table, $key); 
			if($tablefield['type'] != 'function'){
				$field[$key] = $tablefield['res'];
			}else{
				$field[$key] =  $tablefield;
			}
		}
	}
	$returnres['field_result']  = $field;

	$displayattributestypesql = "SELECT content_details,field_name FROM display_attribute_types WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$application_table."'";
	$returnres['displayattributestypesql'] = $displayattributestypesql;
	$displayattributestyperes =  $callConfig->getAllRows($displayattributestypesql);
	foreach($displayattributestyperes as $fieldtype){
		$fieldtype->content_details_decode = json_decode(urldecode($fieldtype->content_details),1);
		$returnres['display_attributes_type'][$fieldtype->field_name] = $fieldtype;
	}

	return $returnres;
}

function dynamicCheckQtyValidation($get){
	global $callConfig;
	if($get['ref_table'] !=""){
		
		// if($get['ref_table'] == 'quotations'){
		// 	$talsql1 = "SELECT id, ref_type, ref_id FROM quotations WHERE company_id = '".$get['company_id']."' AND id = '".$get['ref_id']."' AND is_active = 0";	
		// 	$talres1=$callConfig->getRow($talsql1);
		// 	if($talres1->ref_type !="" AND $talres1->ref_id !=""){
		// 		$get['ref_table'] = $talres1->ref_type;
		// 		$get['ref_id'] = $talres1->ref_id;
		// 	} 
		// }
		$dmtsql = "SELECT id,page_title,application_table_name,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$get['ref_table']."' AND is_active = 0";
		$dmtres=$callConfig->getRow($dmtsql);
		if(($get['ref_table'] == 'enquiries' OR $get['ref_table'] == 'estimates' OR $get['ref_table'] == 'sales_orders') && ($get['table_name'] == 'requisitions' OR $get['table_name'] == 'quotations' OR $get['table_name'] == 'purchase_orders')){
			$select_pending_qty = ", pending_order_qty as pending_qty";
		//}elseif(($get['table_name'] == 'supplier_bills' OR $get['table_name'] ==  'purchase_invoices') AND ($get['ref_table'] =="purchase_orders")){
		}elseif(($get['table_name'] == "purchase_invoices" OR $get['table_name'] == "sales_invoices") AND ($get['ref_table']  == "purchase_orders" OR $get['ref_table'] == "sales_orders")){
			$select_pending_qty = ", ref_pending_qty_1 as pending_qty";
		}else{
			$select_pending_qty = ", pending_qty";
		}
		//$talsql = "SELECT id ".$select_pending_qty." FROM ".$dmtres->item_table." WHERE company_id = '".$get['company_id']."' AND transaction_id = '".$get['ref_id']."' AND item_id = '".$get['item_id']."' AND is_active = 0";
		if($get['ref_id'] !=""){
			$talsql = "SELECT id ".$select_pending_qty." FROM ".$dmtres->item_table." WHERE company_id = '".$get['company_id']."' AND transaction_id = '".$get['ref_id']."' AND id = '".$get['ref_transaction_item_table_id']."' AND is_active = 0";
		}else{ 
			$talsql = "SELECT id ".$select_pending_qty." FROM ".$dmtres->item_table." WHERE company_id = '".$get['company_id']."' AND id = '".$get['ref_transaction_item_table_id']."' AND is_active = 0";
		}
		$talres=$callConfig->getRow($talsql);
		$return['talres_Sql'] =$talsql;
		$return['talres'] =$talres;
	}elseif($get['table_name'] !=""){
		//$trnsactioncheckmaxlimit  = array('requisitions','quotations','purchase_orders','supplier_bills');
		$trnsactioncheckmaxlimit  = array('supplier_bills','purchase_invoices');
		$trnsactioncheckminlimit  = array('sales_orders','sales_invoices');
		if(in_array($get['table_name'],(array)$trnsactioncheckmaxlimit)){
			$res=$this->togetitemvalues($get['item_id']);
			$return['res'] =$res; 
			if($res->quantity_check == '1'){
				$stock_in_hand = $res->stock_in_hand!=""?$res->stock_in_hand:0;
				$purchase_order_qty = $res->purchase_order_qty!=""?$res->purchase_order_qty:0;
				$maximum_capacity = $res->maximum_capacity !=""?$res->maximum_capacity:0;
				//$pending_qty = ($maximum_capacity - ($purchase_order_qty+$stock_in_hand));
				$pending_qty = (($purchase_order_qty+$stock_in_hand) - $maximum_capacity);
				
				$pending_qtys = $pending_qty !=""?$pending_qty:0;
				$talres['pending_qty'] = round($pending_qtys,2);
			}
			$return['talres'] =$talres; 
		}elseif(in_array($get['table_name'],(array)$trnsactioncheckminlimit)){
			$res=$this->togetitemvalues($get['item_id']);
			$return['res'] =$res; 
			if($res->quantity_check == '1'){
				$stock_in_hand = $res->stock_in_hand!=""?$res->stock_in_hand:0;
				$sales_order_qty = $res->sales_order_qty!=""?$res->sales_order_qty:0;
				$minimum_level = $res->minimum_level!=""?$res->minimum_level:0;
				$pending_qty = ($stock_in_hand - ($sales_order_qty + $minimum_level));
				//$pending_qty = (($sales_order_qty + $minimum_level)-$stock_in_hand);
				$pending_qtys = $pending_qty !=""?$pending_qty:0;
				$talres['pending_qty'] = round($pending_qtys,2);
			}
			$return['talres'] =$talres; 
		}
	}else{
		$talres['pending_qty'] = round(99999999,2);
	}
	//return $return;
	return $talres;
}



