	} **/
	return $return; 
}

function getDynamicTransactionInvoices($get){
	global $callConfig;
	$return = array();
	$return['get'] = $get;
	$originator = $get['fieldaccess'] !=""?"party_id":"originator";
	$checkuserid = $get['fieldaccess'] !=""?$get['vendor_id']:$get['user_id'];
	
	if($get['admin_type'] != 1){
		$condition = " AND transa.".$originator." = '".$checkuserid."'";
	}

	$get['table'] =$get['transaction_table'];
	$status_progress = $this->getStatusProgressList($get);
	foreach($status_progress as $statusprogress){
		$return['status_progress'][$statusprogress->status] = $statusprogress;
	}
	
	$dmtsql = "SELECT id, page_title, application_table_name,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$get['transaction_table']."' AND is_active = 0";
	$dmtres=$callConfig->getRow($dmtsql);
	$return['dynamic_mapping_tables'] = $dmtres;
	
	if($get['refrance_res'] == "Y"){ 
		$condition = " AND transa.ref_type = '".$get['ref_table']."' AND transa.ref_id = '".$get['ref_id']."'";
	}
	$listsql ="SELECT transa.id, transa.transaction_number, transa.transaction_date, transa.originator, transa.party_id, transa.party_name,transa.amount, transa.discount_amount, transa.tax_amount,transa.total_amount, itemtb.item_id, itemtb.item_name, itemtb.item_quantity, itemtb.pending_qty, itemtb.item_amount as atm_item_amount , itemtb.tax_amount as itm_tax_amount ,itemtb.total_amount as atm_total_amount, transa.current_status, transa.ref_type, transa.ref_no FROM ".$dmtres->application_table_name." transa, ".$dmtres->item_table." itemtb WHERE transa.company_id = '".$get['company_id']."' AND transa.company_id = itemtb.company_id AND transa.id = itemtb.transaction_id AND transa.is_active = itemtb.is_active AND transa.is_active = 0 ".$condition;	
	$listres=$callConfig->getAllRows($listsql);
	
	$list = array();
	foreach($listres as $listre){
		$list[$listre->id][] = $listre;
	}
	$return['transaction_list'] = $list;
	$return['sql'] = $listsql;
	return $return;
	
}

