function getDocumentAccessSetups($get){
	global $callConfig;
	if($get['ajaxcall'] =='Y'){
		$userarray = explode(",",$get['userlist']);
	}else{
		$return['table_list'] = $this->getListTable();
	}
	$return['userarray'] = $userarray;
	$application_userssql = "SELECT id,display_name,user_photo FROM application_users where company_id = '".$get['company_id']."' ".$condition." AND is_active= 0 ORDER BY display_name ASC";
	$application_usersres=$callConfig->getAllRows($application_userssql);
	foreach($application_usersres as $application_user){
		if($get['ajaxcall'] =='Y'){
			if(in_array($application_user->id, (array)$userarray)){
				$return['application_users'][] = $application_user;
			}
		}else{
			$return['application_users'][] = $application_user;
		}
	}
	$return['application_users_sql'] = $application_userssql;
	$return['application_users_all'] = $application_usersres;
	$capexopexsql = "SELECT genc_detail_name, genc_detail_code FROM general_code_details WHERE genc_code = 'OPEXCAPEX' AND company_id = '".$get['company_id']."' AND is_active = 0";
	$capexopexres=$callConfig->getAllRows($capexopexsql);
	$return['capexopexres'] = $capexopexres;
	$item_categoriessql = "SELECT id, category_description FROM item_categories WHERE company_id = '".$get['company_id']."' AND is_active = 0";
	$item_categoriesres=$callConfig->getAllRows($item_categoriessql);
	$return['item_categories'] = $item_categoriesres;

	$document_access_setupssql = "SELECT * FROM document_access_setups WHERE company_id = '".$get['company_id']."' AND id = '".$get['rid']."' AND is_active = 0";
	$document_access_setupsres=$callConfig->getRow($document_access_setupssql);
	$return['document_access_setups'] = $document_access_setupsres;

	$document_access_setup_userssql = "SELECT * FROM document_access_setup_users WHERE company_id = '".$get['company_id']."' AND document_access_setup_id = '".$get['rid']."' AND is_active = 0";
	$document_access_setup_usersres=$callConfig->getAllRows($document_access_setup_userssql);
	foreach($document_access_setup_usersres as $document_access_setup_user){
		$document_access_setup_users[$document_access_setup_user->user_id] = $document_access_setup_user;
	}
	$return['approved_user_criteria'] = $document_access_setup_users;
	return $return;
}
