		$newdate = $this->dateconvertdbformat($post['from_date'][$userid]);
		$old_from_date = $this->dateconvertdbformat($post['old_from_date'][$userid]);
		if($post['dasu_id'][$userid] !=""){
			if($old_from_date == $newdate){
				$insertuserarray['updated_date']=date('Y-m-d h:i:s');
				$insertuserarray['updated_by']=$post['user_id'];
				$return['insert_user_setup_up'][] = $callConfig->updateRecord('document_access_setup_users',$insertuserarray,'id',$post['dasu_id'][$userid]);
			}else{
