				$insertuserarray['to_date']="5099-12-31";
				$insertuserarray['created_by']=$post['user_id'];
				$insertuserarray['created_date']=date("Y-m-d H:i:s");
				$return['insert_user_setup'][] = $callConfig->insertRecord('document_access_setup_users',$insertuserarray);

				$return['insert_user_setup_up'][] = $callConfig->updateRecord('document_access_setup_users',array('is_active'=>'0','to_date'=>date('Y-m-d', strtotime("-1 days",strtotime($newdate)))),'id',$post['dasu_id'][$userid]);
