function SubInsertApplicationRole($post,$user_access_role){
	global $callConfig;
	$return =array();
	$rolesql = "SELECT id FROM application_roles WHERE company_id = '".$post['company_id']."' AND role_short_code = '".$user_access_role."' AND is_active = 0";
	$roleres=$callConfig->getRow($rolesql);
	$role_id = $roleres->id;
	if(!isset($roleres->id)){
		$insertarray=array('company_id'=>$post['company_id'],'module_setup_id'=>$callConfig->module_id,'name'=>strtolower($user_access_role),'display_name'=>strtolower($user_access_role),'description'=>strtolower($user_access_role),'view_nav'=>'["LN","TN","TNC","TNL","TNR"]','role_short_code'=>$user_access_role,'application_module'=>$callConfig->module_id,'is_active'=>'0','current_status'=>'0');
		$returnres = $callConfig->insertRecord('application_roles',$insertarray);
		$role_id = $returnres['LASTID'];	
	}
	
	$userarylist = implode(",",(array)$post['create_access_users']);
	
	$updateallrolesql = "UPDATE application_users SET role_id = JSON_REMOVE(role_id, JSON_UNQUOTE(JSON_SEARCH(role_id,'one','CREATE_REQUISITIONS'))) WHERE company_id = '".$post['company_id']."' AND is_active = 0 AND JSON_SEARCH(role_id, 'one', 'CREATE_REQUISITIONS') IS NOT NULL";
	$updateallroleusers = $callConfig->executeQuery($updateallrolesql);


	$updary = array('updated_date'=>date('Y-m-d h:i:s'),'updated_by'=>$post['user_id'],'is_active'=>null);
	$whr =" company_id = '".$post['company_id']."' AND role_short_code = '".$user_access_role."' AND is_active = 0";
	$callConfig->updateRecord('application_user_module_roles',$updary,'','',$whr);
	

	$appusersql = "SELECT id, role_id FROM application_users WHERE company_id = '".$post['company_id']."' AND id IN(".$userarylist.") AND is_active = 0";
	$appuserres=$callConfig->getAllRows($appusersql);
	foreach($appuserres as $appuserre){
		$updateary = array();
		$exploderole = json_decode($appuserre->role_id,1);
		$return['application_users'][] = $explode;
		if(!in_array($user_access_role, $exploderole)){
			$exploderole[] = $user_access_role;
			$updateary['updated_date']=date('Y-m-d h:i:s');
			$updateary['updated_by']=$post['user_id'];
			$updateary['role_id']=json_encode($exploderole);
			$return['updateuser'][] = $callConfig->updateRecord('application_users',$updateary,'id',$appuserre->id);
			
			//application_user_module_roles
			unset($updateary['role_id']);
			$updateary['role_short_code'] = $user_access_role;
			$updateary['module_setup_id'] = $callConfig->module_id;
			$updateary['user_id'] = $appuserre->id;
			
			$updateary['company_id'] = $post['company_id'];
			$updateary['is_active'] = '0';
			$updateary['current_status'] = '0';

			$return['insertrolesmodule'][] = $callConfig->insertRecord('application_user_module_roles',$updateary);	
		}
	}
	$return['returnres'] = $returnres;
	return $return;
}
function getApplicationRoles($get){
	global $callConfig;
	$return =array();
	$rolesql = "SELECT id, name, display_name, description, view_nav, role_short_code, dashboard_url, application_module FROM application_roles ar WHERE company_id = '".$get['company_id']."' AND ar.is_active = 0";
	$roleres=$callConfig->getAllRows($rolesql);
	$return['application_roles'] = $roleres;

	$module_setupsql = "SELECT module_id, display_name FROM module_setup WHERE company_id = '".$get['company_id']."' AND is_active = 0";
	$module_setupres=$callConfig->getAllRows($module_setupsql);
	$return['module_setup'] = $module_setupres;

	$aplproccessql = "SELECT apr.id, ap.process_name, apr.application_role_id FROM application_process_role apr, application_process ap WHERE apr.company_id = '".$get['company_id']."' AND apr.company_id = ap.company_id AND apr.application_process_id = ap.id AND apr.is_active = ap.is_active AND apr.is_active = 0";
	$aplproccesres=$callConfig->getAllRows($aplproccessql);
	foreach($aplproccesres as $aplproc){
		$return['application_process'][$aplproc->application_role_id][] = $aplproc;	
	}
	
	return $return;

}
