function currencyConversionRate($get){
	global $callConfig;
	$return =array();
	$rolesql = "SELECT id, ex_rate FROM `currency_convertor` WHERE company_id = '".$get['company_id']."'  AND from_currency = '".$get['originator_currency_id']."' AND to_currency = '".$get['currency_id']."' AND ex_date <= '".$this->dateconvertdbformat($get['trandate'])."' AND is_active = 0 ORDER BY ex_date DESC limit 0,1  ";
	$roleres=$callConfig->getRow($rolesql);
	$return['rolesql'] =$rolesql;
	$return['operater'] = "*";
	if($roleres->id ==""){
		$rolesql1 = "SELECT id, ex_rate FROM `currency_convertor` WHERE company_id = '".$get['company_id']."' AND to_currency = '".$get['originator_currency_id']."' AND from_currency = '".$get['currency_id']."' AND ex_date <= '".$this->dateconvertdbformat($get['trandate'])."' AND is_active = 0 ORDER BY ex_date DESC limit 0,1";
		$roleres=$callConfig->getRow($rolesql1);
		$return['rolesql22'] =$rolesql1;
		$return['operater'] = "/";
	}
	$return['currency_convertor'] = $roleres;
	return $return;
}
function userAndCurrencyDetails($get){
	global $callConfig;
	$return =array();
	$sql = "SELECT au.id, au.default_state_id, au.default_currency_id, (SELECT conf.default_currency_id FROM config conf WHERE au.company_id = conf.company_id AND au.is_active = conf.is_active) config_currency_id, (SELECT comp.state FROM companies comp WHERE au.company_id = comp.id AND au.is_active = comp.is_active) company_state_id FROM application_users au WHERE au.company_id = '".$get['company_id']."' AND au.id = '".$get['selectuserid']."' AND au.is_active = 0";
	$res=$callConfig->getRow($sql);
	//$return['rolesql'] = $sql;
	$return['application_users'] = $res;	
	if($res->default_state_id !="" AND $res->default_state_id !="0"){
		$state_id = $res->default_state_id;
	}elseif($res->company_state_id){
		$state_id = $res->company_state_id;
	}
	if($res->default_currency_id !="" AND $res->default_currency_id !="0"){
		$currency_id = $res->default_currency_id;
	}elseif($res->config_currency_id){
		$currency_id = $res->config_currency_id;
	}
	$get['originator_currency_id'] = $currency_id;
	$currency_convertor = $this->currencyConversionRate($get);
	$return['currency_convertor'] = $currency_convertor;
	$rate = $currency_convertor['currency_convertor']->ex_rate;
	$return['au'] = array("state_id"=>$state_id,"currency_id"=>$currency_id,"rate"=>$rate);
	//$return['currency_convertor'] = $currency_convertor['currency_convertor'];
	return $return;

}
function tochecktransactionlocationwarehouse($post,$get){
	global $callConfig;
	$location = $post['transaction_location_id'];
	$warehouse_id = $post['transaction_warehouse_id'];
	$status = "success";
	foreach ($post['productCode'] as $key => $item) {
		//$item_id[] = $item;		
		$item_name = $post['item_name'][$key];
		$query = "SELECT id FROM item_locations WHERE company_id = ".$get['company_id']." AND item_id =".$item." AND location_id = ".$location."  AND warehouse_id = ".$warehouse_id." AND is_active=0";
		$fdata = $callConfig->getRow($query);
		if($fdata->id!=""){
			$query = "SELECT * FROM user_locations ul, user_warehouse uw WHERE ul.company_id = uw.company_id AND ul.company_id = ".$get['company_id']." AND ul.user_id = uw.user_id AND  ul.user_id = ".$post['originator']." AND ul.location_id = uw.location_id AND ul.location_id = ".$location." AND uw.ware_house_id = ".$warehouse_id." AND ul.is_active = uw.is_active AND ul.is_active =0";
			$mdata = $callConfig->getRow($query);
			if($mdata->id==""){
				$status = "fail";
				$return[$item]['item_name'] = $item_name;
				$return[$item]['error'] = "9069";
				$return[$item]['query'] = $query;
			}
		}else{
			$status = "fail";
			$return[$item]['item_name'] = $item_name;
			$return[$item]['error'] = "9070";
			$return[$item]['query'] = $query;
		}
	}
	return array('status'=>$status, 'data'=>$return); 
}
