	function insertReceipts($post){
		global $callConfig;
		$return = array();
		$return['post']= $post;
		if($post['transaction_type']=="employees"){
			$party_id = $post['employee_id'];
		}else{
			$party_id = $post['customer_id'];
		}
		$transaction_no	= $this->toGetApplicationSerialNumber('receipts',$post);
		$bankaccnumber = '';
		if($post['payment_type']== 'bank'){
			$banckaccountsql = "SELECT account_code FROM bank_accounts WHERE company_id = '".$post['company_id']."' AND id = '".$post['bank_account_id']."' AND is_active=0";
	    	$banckaccountres = $callConfig->getRow($banckaccountsql);
	    	$bankaccnumber = $banckaccountres->account_code;
    	}
    	//Start paid amount And TDS Amount
    	$paid_amonut = $tds_amonut = 0;
    	foreach($post['check'] as $key=>$value){
    		$paid_amonut += $post['paid_amonut'][$key];
    		$tds_amonut += $post['tds_paid_amonut'][$key];
    	}
    	//End paid amount And TDS Amount
   		$paymentarray = array('company_id'=>$post['company_id'],'transaction_type'=>$post['transaction_type'],'transaction_no'=>$transaction_no,'payment_date'=>$this->dateconvertdbformat($post['payment_date']),'party_id'=>json_encode($party_id),'payment_type'=>$post['payment_type'],'bank_account_id'=>$post['bank_account_id'],'account_code'=>$bankaccnumber,'amount'=>$post['amount'],'ref_no'=>$post['ref_no'],'due_date'=>$this->dateconvertdbformat($post['due_date']),'unallocated_amount'=>$post['unallocated_amount'],'allocated_amount'=>$post['allocated_amount'],'remarks'=>$post['remarks'],'originator'=>$post['user_id'],'is_active'=>'0','current_status'=>'0','paid_amonut'=>$paid_amonut,'tds_amount'=>$tds_amonut,'payment_process'=>$post['payment_process'],'receipt_image'=>$post['receipt_image']);
			if($post['rid'] !=""){
				$paymentarray['updated_date']=date('Y-m-d h:i:s');
				$paymentarray['updated_by']=$post['user_id'];
				$res = $callConfig->updateRecord('receipts',$paymentarray,'id',$post['rid']);
				$payment_id = $post['rid'];
			}else{
				$paymentarray['created_by']=$post['user_id'];
				$paymentarray['created_date']=date("Y-m-d H:i:s");
				$res = $callConfig->insertRecord('receipts',$paymentarray);
				$payment_id = $res['LASTID'];
			}
		$return['payments'] = $res;

		if($res['status'] == 'sucess'){
			$callConfig->updateRecord('receipt_allocations',array('is_active'=>null),'receipt_id',$payment_id); 
    		foreach($post['check'] as $key=>$value){
				$transactiontable = $post['transaction_table'][$key];
				$transaction_id = $post['transaction_id'][$key];
				$paymentallocationarray = array('company_id'=>$post['company_id'],'receipt_id'=>$payment_id,'transaction_table'=>$transactiontable,'transaction_id'=>$transaction_id,'transaction_no'=>$post['invoice_number'][$key],'total_amount'=>$post['invoice_total'][$key],'pending_amount'=>$post['pending_amount'][$key],'paid_amonut'=>$post['paid_amonut'][$key],'is_active'=>'0','current_status'=>'0','created_by'=>$post['user_id'],'created_date'=>date("Y-m-d H:i:s"),'tds_amount'=>$post['tds_paid_amonut'][$key],'total_paid_amonut'=>$post['total_paid_amonut'][$key],'total_tax_split_details'=>$post['total_tax_split_details'][$key],'party_id'=>$post['transaction_party_id'][$key]);
			
				if($post['payment_allocation_id'][$key] !=""){
					$paymentallocationarray['updated_date']=date('Y-m-d h:i:s');
					$paymentallocationarray['updated_by']=$post['user_id'];
					$payallocationres = $callConfig->updateRecord('receipt_allocations',$paymentallocationarray,'id',$post['payment_allocation_id'][$key]);
				}else{
					$paymentallocationarray['created_by']=$post['user_id'];
					$paymentallocationarray['created_date']=date("Y-m-d H:i:s");
					$payallocationres = $callConfig->insertRecord('receipt_allocations',$paymentallocationarray);
				}
				$return['payment_allocations'][] = $payallocationres;
			}
		}
		return $return;
	}
	function insertPayments($post){
		global $callConfig;
		$return = array();
		$return['post']= $post;
		if($post['transaction_type']=="customers"){
			$party_id = $post['customer_id'];
		}elseif($post['transaction_type']=="employees"){
			$party_id = $post['employee_id'];
		}else{
			$party_id = $post['vendor_id'];
		}
		$transaction_no	= $this->toGetApplicationSerialNumber('payments',$post);
		$bankaccnumber = '';
		if($post['payment_type']== 'bank'){
			$banckaccountsql = "SELECT account_code FROM bank_accounts WHERE company_id = '".$post['company_id']."' AND id = '".$post['bank_account_id']."' AND is_active=0";
	    	$banckaccountres = $callConfig->getRow($banckaccountsql);
	    	$bankaccnumber = $banckaccountres->account_code;
    	}
    	//Start paid amount And TDS Amount
    	$paid_amonut = $tds_amonut = 0;
    	foreach($post['check'] as $key=>$value){
    		$paid_amonut += $post['paid_amonut'][$key];
    		$tds_amonut += $post['tds_paid_amonut'][$key];
