	function getPayments($get){
		global $callConfig;
		$return = array();

		if($get['rid'] !=""){
			$paymentssql = "SELECT * FROM payments WHERE company_id = '".$get['company_id']."' AND id = ".$get['rid']." AND is_active = 0";
			$paymentsres = $callConfig->getRow($paymentssql);
			$return['payments'] = $paymentsres;

			$payment_allocationssql = "SELECT * FROM payment_allocations WHERE company_id = '".$get['company_id']."' AND payment_id = ".$get['rid']." AND is_active = 0";
			$payment_allocationsres = $callConfig->getAllRows($payment_allocationssql);
			$return['payment_allocations'] = $payment_allocationsres;

			$get['transaction_type'] = $paymentsres->transaction_type;
			$get['party_id'] = urlencode($paymentsres->party_id);
			$get['due_date'] = $paymentsres->due_date;
			$get['payment_process'] = $paymentsres->payment_process;
			$return['transaction_invoice']= $this->toGetblancebill($get);
		}
		
		$employeessql = "SELECT emp.id,emp.display_name , sum(emp_ex.pending_amount) as pending_amount FROM employees emp, emp_expenses emp_ex WHERE emp.company_id = '".$get['company_id']."' AND emp_ex.company_id=emp.company_id AND emp_ex.emp_id =emp.id AND emp_ex.is_active =emp.is_active AND emp.is_active = 0 GROUP BY emp.id";
		$employeesres = $callConfig->getAllRows($employeessql);
		$return['employees'] = $employeesres;

		$vendorssql = "SELECT id, company, display_name FROM vendors WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$vendorres = $callConfig->getAllRows($vendorssql);
		$return['vendors'] = $vendorres;

		$customerssql = "SELECT id, company, display_name FROM customers WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$customersres = $callConfig->getAllRows($customerssql);
		$return['customers'] = $customersres;

		$bankaccountssql = "SELECT id, account_code, bank_account_name, bank_account_number FROM bank_accounts WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$bankaccountsres = $callConfig->getAllRows($bankaccountssql);
		$return['bank_accounts'] = $bankaccountsres;
		if($get['type'] == 'list'){
			$condition = "";
			if($get['vendor_id'] !=""){
				$condition .= " AND transaction_type = 'vendors' AND JSON_SEARCH(party_id, 'one', '".$get['vendor_id']."') IS NOT NULL";
			
			}
			if($get['customer_id'] !=""){
				$condition .= " AND transaction_type = 'customers' AND JSON_SEARCH(party_id, 'one', '".$get['customer_id']."') IS NOT NULL";
			}
			if($get['employee_id'] !=""){
				$condition .= " AND transaction_type = 'employees' AND JSON_SEARCH(party_id, 'one', '".$get['employee_id']."') IS NOT NULL";
			}
			if($get['filter_text'] !=""){
				$condition .= " AND (transaction_no LIKE  ('%".$get['filter_text']."%') OR payment_date LIKE  ('%".$get['filter_text']."%') OR ref_no LIKE  ('%".$get['filter_text']."%'))";
			}	
			$paymentssql = "SELECT * FROM payments WHERE company_id = '".$get['company_id']."' AND is_active = 0".$condition;
			$paymentsres = $callConfig->getAllRows($paymentssql);
			$return['payments'] = $paymentsres;
			$return['payments_sql'] = $paymentssql;

			$payment_allocationssql = "SELECT payment_id, transaction_table, transaction_id, transaction_no, total_amount, pending_amount, paid_amonut FROM payment_allocations WHERE company_id = '".$get['company_id']."' AND is_active = 0";
			$payment_allocationsres = $callConfig->getAllRows($payment_allocationssql);
			$payment_allocations = array();
			foreach($payment_allocationsres as $paymnet){
			  $payment_allocations[$paymnet->payment_id][] = $paymnet;
			}
			$return['payment_allocations'] = $payment_allocations;
		}
		return $return;

	}
