	function getBillsStackDashboardChart($get){
			global $callConfig;
			//$exploderole = explode(',', $get['roleshortcode']);
			//if(!in_array(CLAIM_EXECUTIVE_ROLE, $exploderole)){
				//$condition = " AND emp_id = ".$get['emp_id'];
			//}
			$transaction_table = $get['transaction_table'];
			if($get['admin_type'] != '1'){
				$condition = "AND originator = '".$get['user_id']."'";
			}
			$year = $get['reimbursementsyear'];
			$startdate = date($year.'-01-01');
			$lastdate = date($year.'-31-12');
			$montharay = array('1'=>'01','2'=>'02','3'=>'03','4'=>'04','5'=>'05','6'=>'06','7'=>'07','8'=>'08','9'=>'09','10'=>'10','11'=>'11','12'=>'12');
			$expensessql = "SELECT sum(total_amount) as total_amount, sum(	) as pending_amount, MONTH(due_date) as month,YEAR(due_date) as year FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' ".$condition." AND due_date BETWEEN '".$startdate."' AND '".$lastdate."'  AND is_active = 0 GROUP BY YEAR(due_date), MONTH(due_date)";
			// AND due_date >= '".$startdate."' AND due_date <= '".$lastdate."'
			$expensesres = $callConfig->getAllRows($expensessql);
			foreach($expensesres as $empexp){
				$expensetotal[$empexp->month]= $empexp->total_amount;
				$expensepending[$empexp->month]= $empexp->pending_amount;
			}
			foreach($montharay as $monthary=>$moth){
				$expensetotalamt = isset($expensetotal[$monthary])?$expensetotal[$monthary]:"0";
				$expensependingamt = isset($expensepending[$monthary])?$expensepending[$monthary]:"0";
				$totalpendin = $expensetotalamt-$expensependingamt;
				$expensemontharray[] = array("date"=>date($year.'-'.$moth.'-01'),"market1"=>round($expensetotalamt),"market2"=>round($totalpendin));
			}
			///print_r($expensemontharray);
			return $expensemontharray;
		}
	function getreportnagerandbuddy($get){
		global $callConfig;
		 $query = "SELECT count(id) as cnt FROM application_users WHERE company_id = ".$get['company_id']." AND reports_to =".$get['user_id'];
		$rdata = $callConfig->getRow($query);
		$return['reports_to'] = $rdata->cnt; 
		$query = "SELECT count(id) as cnt FROM employees WHERE company_id = ".$get['company_id']." AND hr_buddy =".$get['emp_id'];
		$hdata = $callConfig->getRow($query);
		$query = "SELECT count(id) as cnt FROM employees WHERE company_id = ".$get['company_id']." AND finance_buddy =".$get['emp_id'];
		$fdata = $callConfig->getRow($query);
		$return['buddy'] = $hdata->cnt+$fdata->cnt;
		$query = "SELECT count(id) as cnt FROM payroll_area_admins WHERE company_id = ".$get['company_id']." AND emp_id =".$get['emp_id'];
		$pdata = $callConfig->getRow($query);
		$return['pay_admin'] = $pdata->cnt; 
		return $return;
	}
