		}
		$return['month_holidays'] = $mnholiday;

		$query = "SELECT id,attendace_date FROM employee_daily_attendances WHERE company_id=".$get['company_id']."  AND employee_id=".$get['emp_id']." AND  YEAR(attendace_date)=".date('Y')." AND MONTH(attendace_date)= ".date('m')."  AND  is_active=0 ";
		$return['attedance'] =  $callConfig->getAllRows($query);
