	function submitSetupVerticals($post){
		global $callConfig;
    	$callConfig->executeQuery('TRUNCATE verticals');
    	$insertdivi = "INSERT INTO `verticals`(`company_id`, `vertical_name`, `vertical_description`, `is_active`, `current_status`,`created_date`, `created_by`) VALUES ";
		foreach($post['vertical_name'] as $sdvkey=>$dvname){
			if($dvname !=""){	
				$insertst=0;
				$insertdivi .= "('".$post['company_id']."', '".$dvname."', '".$post['vertical_description'][$sdvkey]."','0','0', '".date("Y-m-d H:i:s")."', '".$post['user_id']."'),";
			}
		}
		if($insertst == '0'){
		 	$insertdivi = substr($insertdivi, 0, -1);
		 	$divisionsres = $callConfig->executeQueryString($insertdivi);
		}
		return $divisionsres; 
	}
	function submitSetupStockAdjustmentReasons($post){
		global $callConfig;
