		 	$insertdivi = substr($insertdivi, 0, -1);
		 	$divisionsres = $callConfig->executeQueryString($insertdivi);
		}
		return $divisionsres; 
	}
    function submitSetupEarningsComponents($post){
    	global $callConfig;
    	$callConfig->executeQuery('TRUNCATE earnings');
    	if(count((array)$post['selectedcomponentlist1']) != 0){
	    	$xyz = $post['selectedcomponentlist1'];
			sort($xyz);
			$query ="INSERT INTO `earnings`(`company_id`, `category_id`, `report_group_id`, `name`, `code`, `payslip_name`, `calculation_type`, `calculation_mode`, `calculation_category`, `calculation_number`, `calculation_formula`, `varible_pay`, `part_of_ctc`, `pro_rata`, `editable`, `mandatory`, `display_seq`, `taxable`, `taxable_limit`, `min_range`, `max_range`, `note`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, `created_by`, `updated_by`, `updated_date`) SELECT ".$post['company_id'].", `category_id`, `report_group_id`, `name`, `code`, `payslip_name`, `calculation_type`, `calculation_mode`, `calculation_category`, `calculation_number`, `calculation_formula`, `varible_pay`, `part_of_ctc`, `pro_rata`, `editable`, `mandatory`, `display_seq`, `taxable`, `taxable_limit`, `min_range`, `max_range`, `note`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, ".$post['user_id'].", `updated_by`, `updated_date`  FROM `system_earnings` WHERE id IN (".implode(",",$xyz).")";
			$return = $callConfig->executeQuery($query);
		}
		return $return; 

    }
