	function submitSetupWareHouses($post){
		global $callConfig;
		$wh = "company_id = '".$post['company_id']."' AND is_active =0";
		$callConfig->updateRecord('warehouses',array('is_active'=>null),'','',$wh); // all disabled
		$insertst = 1;
		$insertdivi = "INSERT INTO `warehouses`(`company_id`, `location_id`, `warehouse_short_name`, `warehouse_name`, `is_active`, `current_status`,`created_date`, `created_by`) VALUES ";
		foreach($post['location_id'] as $sdvkey=>$dvname){
			if($dvname !="" AND $post['warehouse_short_name'][$sdvkey] !=""){
				if($post['warehouse_id'][$sdvkey] !=""){
					$updatedivi = array('location_id'=>$dvname, 'warehouse_short_name'=>$post['warehouse_short_name'][$sdvkey], 'warehouse_name'=>$post['warehouse_name'][$sdvkey],'updated_date'=>date('Y-m-d h:i:s'),'updated_by'=>$post['user_id'],'is_active'=>0);
					$wh = " id = '".$post['warehouse_id'][$sdvkey]."'";
					$return['warehouses'][] = $callConfig->updateRecord('warehouses',$updatedivi,'','',$wh);
				}else{
					$insertst=0;
					$insertdivi .= "('".$post['company_id']."', '".$dvname."', '".$post['warehouse_short_name'][$sdvkey]."', '".$post['warehouse_name'][$sdvkey]."','0','0', '".date("Y-m-d H:i:s")."', '".$post['user_id']."'),";
				}
			}
		}
		if($insertst == '0'){
		 	$insertdivi = substr($insertdivi, 0, -1);
		 	$insertdivi .= " ON DUPLICATE KEY UPDATE updated_by = '".$post['user_id']."', updated_date = '".date("Y-m-d H:i:s")."'";
		 	$divisionsres = $callConfig->executeQueryString($insertdivi);
		 	$return['warehouses_sql'] = $insertdivi;
			$return['warehouses'] = $divisionsres;
	 	}
		return $return;
	}
