	function getApplicationEmptyTransactions($get){
		global $callConfig;
		$return = $transaction_table = array();
		$return['get'] = $get;
		if($get['rid'] !=""){
			$condition = " AND id = '".$get['rid']."'";
		}elseif($get['option'] !=""){
			$condition = " AND page_option = '".$get['option']."'";
		}elseif($get['module_id'] !=""){
			$condition = " AND module_setup_id = '".$get['module_id']."'";
		}
		$aetsql = "SELECT  * FROM application_missing_data_check WHERE company_id = '".$get['company_id']."' ".$condition." AND is_active=0";
    	$aetres = $callConfig->getRow($aetsql);
    	$return['application_empty_transactions'] = $aetres;

    	$module_setupsql = "SELECT  module_id, display_name FROM module_setup WHERE company_id = '".$get['company_id']."' AND is_active=0";
    	$module_setupres = $callConfig->getAllRows($module_setupsql);
    	$return['module_setup'] = $module_setupres;
    	
    	$application_messagessql = "SELECT  message_number, message_description FROM application_messages WHERE company_id = '".$get['company_id']."' AND is_active=0";
    	$application_messagesres = $callConfig->getAllRows($application_messagessql);
    	$return['application_messages'] = $application_messagesres;


    	$application_pagessaql = "SELECT  application_table_name, list_page_name, insert_page_name,edit_page_name,view_page_name,approval_page_name  FROM application_pages WHERE company_id = '".$get['company_id']."' AND is_active=0 ORDER BY application_table_name ASC";
    	$application_pagessres = $callConfig->getAllRows($application_pagessaql);
    	foreach($application_pagessres as $ap){
    		if($ap->application_table_name !=""){
    			$transaction_table[$ap->application_table_name] = $ap->application_table_name;
    		}
    		if($ap->list_page_name !=""){
    			$application_pages[$ap->list_page_name] = $ap->application_table_name." (".$ap->list_page_name.")";
    		}
    		if($ap->insert_page_name !=""){
    			$application_pages[$ap->insert_page_name] = $ap->application_table_name." (".$ap->insert_page_name.")";
    		}
    		if($ap->edit_page_name !=""){
    			$application_pages[$ap->edit_page_name] = $ap->application_table_name." (".$ap->edit_page_name.")";
    		}
    		if($ap->view_page_name !=""){
    			$application_pages[$ap->view_page_name] = $ap->application_table_name." (".$ap->view_page_name.")";
    		}
    		if($ap->approval_page_name !=""){
    			$application_pages[$ap->approval_page_name] = $ap->application_table_name." (".$ap->approval_page_name.")";
    		}
    	}
    	$return['application_pages'] = $application_pages;
    	$return['transaction_table'] = $transaction_table;
    	return $return;
	}
	function insertApplicationEmptyTransactions($post){
		global $callConfig;
		$return['post'] = $post;
		foreach($post['transaction_table'] as $sdvkey=>$tablename){
			if($tablename !="" AND $post['option_type'][$sdvkey] !="" AND ($post['application_message_code'][$sdvkey] !="" OR $post['extra_message'][$sdvkey] !="" )){
				$updatedivi[] = array('transaction_table'=>$tablename, 'option_type'=>$post['option_type'][$sdvkey], 'application_message_code'=>$post['application_message_code'][$sdvkey], 'extra_message'=>$post['extra_message'][$sdvkey]);

			}
		}
		$transaction_tables = json_encode($updatedivi,1);
		$insertary=array('company_id'=>$post['company_id'],'module_setup_id'=>$post['module_setup_id'],'page_option'=>$post['page_option'],'transaction_tables'=>$transaction_tables);
		if($post['rid'] !=""){
			$insertary['updated_date']=date('Y-m-d h:i:s');
			$insertary['updated_by']=$post['user_id'];
			$return['result'] = $callConfig->updateRecord('application_missing_data_check',$insertary,'id',$post['rid']);
		}else{
			$insertary['created_by']=$post['user_id'];
			$insertary['is_active']=0;
			$insertary['created_date']=date("Y-m-d H:i:s");
			$tapres = $callConfig->insertRecord('application_missing_data_check',$insertary);
			$return['result'] =$tapres;	
		}
		return $return;
	}
