	function setfollowUpLevels($get){
        global $callConfig;
        $return =array();
        $return['get'] = $get;
        $transaction_table = $get['transaction_table'];
        $transaction_id = $get['transaction_id'];
        $company_id = $get['company_id'];
        $transactionsql = "SELECT * FROM ".$transaction_table." WHERE company_id = ".$company_id." AND id = '".$transaction_id."' AND is_active =0";
        $transactionres = $callConfig->getRow($transactionsql);
        $follow_up_level_ids = json_decode($transactionres->follow_up_level_ids,1);
        $return['follow_up_level_ids']= $follow_up_level_ids;
        $return['transaction']= $transactionres;
        
        $follwupid = implode(',', (array)$follow_up_level_ids);
        $follow_up_levelssql = "SELECT id, follow_up_level_name, days, send_email, send_sms, follow_up_call, attach_invoice, email_content_id FROM follow_up_levels WHERE company_id = ".$company_id." AND id IN(".$follwupid.") AND is_active =0";
        $follow_up_levelsres = $callConfig->getAllRows($follow_up_levelssql);

        $deletsql = "DELETE FROM project_task_details WHERE company_id = '".$company_id."' AND transaction_table = '".$transaction_table."' AND transaction_id = ".$transaction_id;
        $callConfig->executeQuery($deletsql);

        foreach($follow_up_levelsres as $ful){
            //echo "<pre>"; print_r($ful);
            $task_date  = date('Y-m-d', strtotime($transactionres->transaction_date. ' + '.$ful->days.' days'));
            if($ful->send_email == '0'){
               $insertary=array('company_id'=>$company_id,'task_type'=>'2','assigen_id'=>$transactionres->originator,'task_name'=>EMAIL_TASK['message'],'planned_start'=>$task_date,'transaction_table'=>$transaction_table,'transaction_id'=>$transaction_id,'ref_table'=>'follow_up_levels','ref_id'=>$ful->id,'follow_up_type'=>EMAIL_TASK['type'],'is_active'=>'0','current_status'=>'0','created_by'=>$get['user_id'],'created_date'=>date("Y-m-d H:i:s"));
                $return[] = $callConfig->insertRecord('project_task_details',$insertary);
            }
            if($ful->send_sms == '0'){
                 $insertary=array('company_id'=>$company_id,'task_type'=>'2','assigen_id'=>$transactionres->originator,'task_name'=>SMS_TASK['message'],'planned_start'=>$task_date,'transaction_table'=>$transaction_table,'transaction_id'=>$transaction_id,'ref_table'=>'follow_up_levels','ref_id'=>$ful->id,'follow_up_type'=>EMAIL_TASK['type'],'is_active'=>'0','current_status'=>'0','created_by'=>$get['user_id'],'created_date'=>date("Y-m-d H:i:s"));
                $return[] = $callConfig->insertRecord('project_task_details',$insertary);
            }
            if($ful->follow_up_call == '0'){
                $insertary=array('company_id'=>$company_id,'task_type'=>'2','assigen_id'=>$transactionres->originator,'task_name'=>CALL_TASK['message'],'planned_start'=>$task_date,'transaction_table'=>$transaction_table,'transaction_id'=>$transaction_id,'ref_table'=>'follow_up_levels','ref_id'=>$ful->id,'follow_up_type'=>EMAIL_TASK['type'],'is_active'=>'0','current_status'=>'0','created_by'=>$get['user_id'],'created_date'=>date("Y-m-d H:i:s"));
                $return[] = $callConfig->insertRecord('project_task_details',$insertary);
            }  
        }
        $return['follow_up_levels']= $follow_up_levelsres;
        return $return;
    }
