    	}

    	$display_attribute_typessql = "SELECT content FROM display_attribute_types WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$transaction_table."' AND field_name = 'party_id'";	
		$parttable_name = $callConfig->getRow($display_attribute_typessql);
		$qquery = urldecode($parttable_name->content);
		$explosql = explode("FROM", $qquery); // splite from to get table name and other part get
		if(isset($explosql[1])){
			$explosql = explode(" ", trim($explosql[1])); //splite to space only get table name
		}
		$partytable = trim($explosql[0]); //get Table name
		$return['party_table'] = $partytable;


		$payment_termssql = "SELECT id, payment_term_name, content  FROM `payment_terms` WHERE company_id = '".$get['company_id']."' AND is_active =0";
        $payment_termsres = $callConfig->getAllRows($payment_termssql);
        $payment_terms = array();
        foreach($payment_termsres as $payterm){
        	$payment_terms[$payterm->id] = $payterm;
        }
       	$return['payment_terms']= $payment_terms;	


       	if($partytable !="" AND $rental_invoicesres->party_id !=""){
       		$party_sku_codes = array();
			if($partytable == "customers"){
				$itemskusql = "SELECT id, item_id, customer_id, customer_part_no as party_sku_number, customer_part_name as party_sku_name FROM customer_items WHERE company_id = '".$get['company_id']."' AND customer_id = '".$rental_invoicesres->party_id."' AND item_id IN(".$item_ids.") AND is_active = 0";	
				$itemskures = $callConfig->getAllRows($itemskusql);
				foreach($itemskures as $itsku){
		        	$party_sku_codes[$itsku->item_id] = $itsku;
		        }
			}elseif($partytable == "vendors"){
				$itemskusql = "SELECT id, item_id, vendor_id, vendor_part_no as party_sku_number, vendor_part_name as party_sku_name  FROM vendor_items WHERE company_id = '".$get['company_id']."' AND vendor_id = '".$rental_invoicesres->party_id."' AND item_id IN(".$item_ids.") AND is_active = 0";	
				$itemskures = $callConfig->getAllRows($itemskusql);
				foreach($itemskures as $itsku){
		        	$party_sku_codes[$itsku->item_id] = $itsku;
		        }
			}
	       	$return['party_sku_codes'] = $party_sku_codes;
		}

        return $return;
    }
    function cronJobFollowUpLevels($get){
        global $callConfig;
        $return =array();
        $return['get'] = $get;
        $company_id = $get['company_id'];
        $cornjobdate = date('Y-m-d');
        $application_task_logssql = "SELECT ptd.id, ptd.task_name, ptd.planned_start, ptd.transaction_table, ptd.assigen_id, ptd.transaction_id, ptd.ref_table, ptd.ref_id, ptd.follow_up_type, ful.attach_invoice, ful.email_content_id FROM project_task_details ptd, follow_up_levels ful WHERE ptd.company_id = ".$company_id." AND ptd.company_id = ful.company_id  AND ptd.ref_table = 'follow_up_levels' AND ptd.ref_id = ful.id AND ptd.current_status =0 AND ptd.company_id = ful.company_id AND ptd.is_active = ful.is_active AND ptd.is_active =0";
        $apptasklog = $callConfig->getAllRows($application_task_logssql); // get all task with date


        $return['project_task_details']= $apptasklog;
        $transactiontablewithid = $transactiontableidwithdata = $email_contentid = array();
        foreach($apptasklog as $tasklog){
            $transactiontablewithid[$tasklog->transaction_table][$tasklog->transaction_id] = $tasklog->transaction_id;
            if($tasklog->email_content_id !=""){
                $email_contentid[$tasklog->email_content_id] = $tasklog->email_content_id;
            }
        }

        $emailcontentid = implode(',', (array)$email_contentid);
        $sql = "SELECT id,template_reference_id FROM email_content WHERE company_id = ".$company_id." AND id IN(".$emailcontentid.") AND is_active =0";
        $result = $callConfig->getAllRows($sql);
        foreach($result as $emcont){
            $email_contentrefid[$emcont->id] = $emcont->template_reference_id;
        }
        foreach($transactiontablewithid as $transtable=>$transid){ // loop transaction table with multiple ids
            $ids = implode(',', (array)$transid);
            $sql = "SELECT * FROM ".$transtable." WHERE company_id = ".$company_id." AND id IN(".$ids.") AND is_active =0";
            $result = $callConfig->getAllRows($sql);
            foreach($result as $res){ // loop transaction table results
                $transactiontableidwithdata[$transtable][$res->id] =$res;  // transaction table and result id
            }
        }
        foreach($apptasklog as $tasklog){ // get all task Loop
            if($tasklog->follow_up_type == EMAIL_TASK['type']){ // Email Send Condition
                $get['transaction_table'] = $tasklog->transaction_table;
                $get['transaction_id'] = $tasklog->transaction_id;
                $get['template_reference_id'] = $email_contentrefid[$tasklog->email_content_id];
                $get['attach_invoice_or_not'] = $tasklog->attach_invoice;
                $get['reference_transaction_table'] = 'project_task_details';
                $get['reference_transaction_id'] = $tasklog->id;
                $this->emailInvoiceSend($get);
               	$updateary = array('current_status'=>ST_APPROVED,'updated_date'=>date('Y-m-d h:i:s'),'updated_by'=>$post['user_id']);
                $res33= $callConfig->updateRecord('project_task_details',$updateary,'id',$tasklog->id);
            }elseif($tasklog->follow_up_type == SMS_TASK['type']){ // Sms Send Condition
                //echo "send SMS";
            }elseif($tasklog->follow_up_type == CALL_TASK['type']){ // Follow-up Call Condition
                //echo "send CALL";
            }
           
        }
        return $return;
    }
