		$yearly_transaction_number = $transaction_number_details['yearly_transaction_number'];
		$lifetime_transaction_number = $transaction_number_details['lifetime_transaction_number'];
		
		$maintablesql = "INSERT INTO ".$transaction_table_with_clild['cancellation_application_table_name']." (`company_id`, `cost_center_id`, `transaction_number`, `transaction_date`, `transaction_location_id`, `transaction_warehouse_id`, `originator_currency_id`, `currency_id`, `currency_rate`, `originator`, `party_id`, `party_name`, `party_email`, `party_tax_number`, `party_phone`, `party_address`, `party_ship_adderss`, `originator_state_id`, `supplier_state_id`, `place_of_supply`, `payment_terms`, `notes`, `printing_notes`, `parent_id`, `amount`, `tax_amount`, `type`, `tax_type`, `discount_type`, `discount_value`, `discount_amount`, `total_amount`, `shipping_tax`, `shipping_amount`, `shipping_tax_amount`, `tax_state`, `opex_cpex`, `doc_ref_no`, `doc_ref_date`, `due_date`, `ref_type`, `ref_id`, `ref_no`, `ref_date`, `old_ref_no`, `old_ref_date`, `payment_term_history`, `follow_up_level_ids`, `pending_amount`, `additional_charges`, `additional_attributes`, `pdf_name`, `total_tds_amount`, `advance_payment`, `pending_advance_payment`, `total_tax_split_details`, `rounding_off`, `party_additional_details`, `compliance_specification_documents`, `discount_mode`, `multi_reference`, `monthly_transaction_number`, `yearly_transaction_number`, `lifetime_transaction_number`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, `created_by`)SELECT `company_id`, `cost_center_id`,'".$transaction_number."', `transaction_date`, `transaction_location_id`, `transaction_warehouse_id`, `originator_currency_id`, `currency_id`, `currency_rate`, `originator`, `party_id`, `party_name`, `party_email`, `party_tax_number`, `party_phone`, `party_address`, `party_ship_adderss`, `originator_state_id`, `supplier_state_id`, `place_of_supply`, `payment_terms`, `notes`, `printing_notes`, `parent_id`, `amount`, `tax_amount`, `type`, `tax_type`, `discount_type`, `discount_value`, `discount_amount`, `total_amount`, `shipping_tax`, `shipping_amount`, `shipping_tax_amount`, `tax_state`, `opex_cpex`,  `doc_ref_no`, `doc_ref_date`, `due_date`, '".$transaction_table."', `id`, `transaction_number`, `ref_date`, `old_ref_no`, `old_ref_date`, `payment_term_history`, `follow_up_level_ids`, `pending_amount`, `additional_charges`, `additional_attributes`, `pdf_name`, `total_tds_amount`, `advance_payment`, `pending_advance_payment`, `total_tax_split_details`, `rounding_off`, `party_additional_details`, `compliance_specification_documents`, `discount_mode`, `multi_reference`, '".$monthly_transaction_number."', '".$yearly_transaction_number."', '".$lifetime_transaction_number."', `is_active`, '".ST_APPROVED."', `status_date`, `from_date`, `to_date`,'".date("Y-m-d H:i:s")."','".$post['user_id']."' FROM ".$transaction_table." WHERE company_id = '".$post['company_id']."' AND id = '".$transaction_id."' AND is_active = 0";
		$mainres  = $callConfig->executeQuery($maintablesql);
		$return['main'] = $mainres;

		if($mainres['status'] == 'sucess'){
			$query = "SELECT * FROM ".$transaction_table_with_clild['item']." WHERE company_id = '".$post['company_id']."' AND transaction_id = '".$transaction_id."' AND is_active = 0";
			$itemsrow = $callConfig->getAllRows($query);
			foreach($itemsrow as $itrow){
				$itmetablesql = "INSERT INTO ".$clone_transaction_table_with_clild['item']."( `company_id`, `transaction_id`, `item_id`, `account_code`, `item_name`, `description`, `purchase_uom`, `item_quantity`, `item_price`, `item_amount`, `tax_amount`, `discount_amount`, `total_amount`, `doc_ref_no`, `doc_ref_date`, `req_date`, `item_st_cost`, `item_fifo_cost`, `item_lifo_cost`, `item_wa_cost`, `approved_quantity`, `transaction_type`, `transaction_qty`, `pending_qty`, `item_details`, `tds_amount`, `ref_transaction_item_table_id`, `ref_transaction_table_id`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, `created_by`) 
				SELECT  `company_id`, '".$mainres['LASTID']."', `item_id`, `account_code`, `item_name`, `description`, `purchase_uom`, `item_quantity`, `item_price`, `item_amount`, `tax_amount`, `discount_amount`, `total_amount`, `doc_ref_no`, `doc_ref_date`, `req_date`, `item_st_cost`, `item_fifo_cost`, `item_lifo_cost`, `item_wa_cost`, `approved_quantity`, `transaction_type`, `transaction_qty`, `pending_qty`, `item_details`, `tds_amount`, '".$itrow->id."', $transaction_id ,`is_active`, `current_status`, `status_date`, `from_date`, `to_date`, '".date("Y-m-d H:i:s")."','".$post['user_id']."' FROM ".$transaction_table_with_clild['item']." WHERE company_id = '".$post['company_id']."' AND id = '".$itrow->id."' AND is_active = 0";	
				$itemres = $callConfig->executeQuery($itmetablesql);
				$return['items'] = $itemres;

				if($itemres['status'] == 'sucess'){
					$taxtablesql = "INSERT INTO ".$clone_transaction_table_with_clild['tax']." (`company_id`, `transaction_id`, `transaction_item_id`, `tax_name`, `tax_value`, `tax_id`, `amount`, `tax_amount`, `total_amount`, `tax_type`, `tax_split_details`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, `created_date`, `created_by`,`transaction_item_row_id`)
					 SELECT `company_id`, '".$mainres['LASTID']."', `transaction_item_id`, `tax_name`, `tax_value`, `tax_id`, `amount`, `tax_amount`, `total_amount`, `tax_type`, `tax_split_details`, `is_active`, `current_status`, `status_date`, `from_date`, `to_date`, '".date("Y-m-d H:i:s")."','".$post['user_id']."', '".$itemres['LASTID']."' FROM ".$transaction_table_with_clild['tax']." WHERE company_id = '".$post['company_id']."' AND transaction_id = '".$transaction_id."' AND transaction_item_row_id = '".$itrow->id."' AND is_active = 0 ";	
					$return['tax'] = $callConfig->executeQuery($taxtablesql);
				}

			}

		}

		$jvpassary = array('supplier_bills', 'sales_invoices', 'purchase_invoices');
		if(in_array($transaction_table,(array)$jvpassary)){
			$return['jv'] = $this->tocreatejounalvoucherbaseallcases($transaction_table_with_clild['cancellation_application_table_name'],$mainres['LASTID']);
		}

		$query = "SELECT * FROM ".$transaction_table." WHERE company_id = '".$post['company_id']."' AND id = '".$transaction_id."' AND is_active = 0";
		$transaction_details = $callConfig->getRow($query);
		if($transaction_details->current_status == ST_APPROVED){
			$post['transaction_table'] = $transaction_table;
			$this->updateTransactionItemsQty($post,$transaction_details,"+");
		}
		return $return;
	}


