	function insertDynamicCancelInvoice($post){
		global $callConfig;
		$return['post'] =  $post;
		$transaction_table = $post['transaction_table'];
		$transaction_id = $post['transaction_id'];
		
		$cancel_pending_amount = $post['cancel_pending_amount'];
		$debitcreditnotetable = $post['debitcreditnotetable'];
		$debit_credit_note = $post['debit_credit_note'];

		$cancel_invoice_date = $this->dateconvertdbformat($post['cancel_invoice_date']);
		$updateary = array('cancel_invoice'=>'Y','cancel_invoice_date'=>$cancel_invoice_date,'cancel_invoice_reason'=>$post['cancel_invoice_reason'],'updated_by'=>$post['user_id'],'updated_date'=>date('Y-m-d h:i:s'));
		$return['res'] = $callConfig->updateRecord($transaction_table,$updateary,'id',$transaction_id);
		
		$return['cancel_invoices'] =$this->cancellationTransactions($post, $transaction_table,$transaction_id);
	
		if($debit_credit_note == 'Y'){
			
			$transactionsql = "SELECT * FROM ".$transaction_table." WHERE company_id = '".$post['company_id']."' AND id = '".$transaction_id."' AND is_active = 0";
			$transactionres = $callConfig->getRow($transactionsql);


			$display_attribute_typessql = "SELECT content FROM display_attribute_types WHERE company_id = '".$post['company_id']."' AND application_table_name = '".$transaction_table."' AND field_name = 'party_id'";	
			$parttable_name = $callConfig->getRow($display_attribute_typessql);
			$qquery = urldecode($parttable_name->content);
			$explosql = explode("FROM", $qquery); // splite from to get table name and other part get
			if(isset($explosql[1])){
				$explosql = explode(" ", trim($explosql[1])); //splite to space only get table name
			}
			$partytable = trim($explosql[0]); //get Table name
			$partysql = "SELECT account_code FROM ".$partytable." WHERE company_id = '".$post['company_id']."' AND id  = '".$transactionres->party_id."' AND is_active = 0";	
			$partyres = $callConfig->getRow($partysql);
			$party_account_number = $partyres->account_code; //get customers and vendor id

			$gettables = $this->toGetInvoicetabledata($debitcreditnotetable);
			$transaction_number = $this->toGetApplicationSerialNumber($debitcreditnotetable,$post);
			$transaction_date = $due_date = $this->dateconvertdbformat($post['cancel_invoice_date']);
			
			$insertcust = array('company_id'=>$post['company_id'],'transaction_number'=>$transaction_number,'transaction_date'=>$transaction_date,'originator'=>$post['user_id'],'party_id'=>$transactionres->party_id,'party_name'=>$transactionres->party_name,'party_email'=>$transactionres->party_email,'party_phone'=>$transactionres->party_phone,'party_address'=>$transactionres->party_address,'amount'=>$cancel_pending_amount,'tax_amount'=>'0','total_amount'=>$cancel_pending_amount,'due_date'=>$due_date,'ref_type'=>$transaction_table,'ref_id'=>$transaction_id,'ref_date'=>$transactionres->transaction_date,'ref_no'=>$transactionres->transaction_number,'pending_amount'=>$cancel_pending_amount,'is_active'=>0,'current_status'=>0,'created_by'=>$post['user_id'],'created_date'=>date("Y-m-d H:i:s"));
			$res = $callConfig->insertRecord($debitcreditnotetable,$insertcust);
			$rid = $res['LASTID'];
			$return['notes'] = $res;

			$insertcust = array('company_id'=>$post['company_id'],'transaction_id'=>$rid,'item_id'=>'0','account_code'=>$party_account_number,'item_name'=>$post['cancel_invoice_reason'],'description'=>$post['cancel_invoice_reason'],'purchase_uom'=>'UN','item_quantity'=>'1','item_price'=>$cancel_pending_amount,'item_amount'=>$cancel_pending_amount,'tax_amount'=>'0','total_amount'=>$cancel_pending_amount,'approved_quantity'=>'1','transaction_qty'=>'1','pending_qty'=>'1','is_active'=>0,'current_status'=>0,'created_by'=>$post['user_id'],'created_date'=>date("Y-m-d H:i:s"));
			$rental_invoicesins = $callConfig->insertRecord($gettables['item'],$insertcust);
			$return['note_items'] = $rental_invoicesins;
		}
		return $return;
	}

