		$application_userssql = "SELECT user_email FROM ".MAINDB.".user_registered_groups WHERE user_email IN('".$emailid."') AND is_active = 0";
		$application_usersrtes=$callConfig->getAllRows($application_userssql);
		$application_users = array();
		foreach($application_usersrtes as $aures){
