	function  tocreateprocesstaskintotaskdatail($get){
		global $callConfig;
		$query = "SELECT * FROM process_task_settings WHERE company_id = ".$get['company_id']."  AND process_type = '".$get['process_type']."' AND is_active = 0";
		$return['process_query'] = $query;
