	function updateApplicationUsers($post){
		global $callConfig;
		$return['post'] =$post;
		if($post['formtype'] == 'application_users_form'){
			$usertablefields = array('user_name', 'first_name', 'middle_name', 'last_name', 'display_name', 'user_mobile', 'cost_center', 'location_id', 'default_warehouse_id', 'work_station_id', 'remember_token', 'last_logged_in_at', 'user_photo', 'pref_language', 'confirmed_basic_ino', 'user_activated', 'country_id', 'default_state_id', 'timezone', 'default_currency_id', 'hr_connect', 'finance_connect', 'admin_connect', 'project_connect', 'location_connect', 'esop_connect', 'legal_connect', 'reports_to', 'approval_manager', 'user_type', 'mapping_code','is_active');
			$updateuserary = array();
			foreach($post as $key => $post1){
				if(in_array($key,(array)$usertablefields)){
					//if($key == "date_of_birth" || $key == "wedding_date" || $key == "reporting_date"){
						//$listcandi[$key] = $this->dateconvertdbformat($post1);	
					//}else{
						$updateuserary[$key] = $post1;
					//}	
				}
			}
			$return['updateuserary'] = $updateuserary; 	
			$updateuserary['updated_by'] = $post['user_id'];
			$updateuserary['updated_date'] = date('Y-m-d H:i:s');
			$return['respons']  = $callConfig->updateRecord('application_users',$updateuserary,'id',$post['rid']);

			if($post['user_photo'] !=""){
				$empupdateary = array('image'=>$post['user_photo']);
				$return['respons1']  = $callConfig->updateRecord('employees',$empupdateary,'user_id',$post['rid']);
			}



		}elseif($post['formtype'] == "application_user_module_roles"){

			$query = "SELECT application_module,id,role_short_code,id FROM application_roles where company_id = '".$post['company_id']."' AND role_short_code IN('".$post['role_short_code']."') AND is_active = 0";
			$roleres = $callConfig->getRow($query);
			//$return['query'] = $roleres;
			$insertarray = array("company_id"=>$post['company_id'],"user_id"=>$post['rid'],"module_setup_id"=>$roleres->application_module,"application_module_id"=>$roleres->application_module,"role_id"=>$roleres->id,"role_short_code"=>$roleres->role_short_code,"is_active"=>"0","current_status"=>"0","from_date"=>date('Y-m-d h:i:s'),"to_date"=>date('Y-m-d h:i:s',strtotime('+50 years')),"created_date"=>date('Y-m-d h:i:s'),"created_by"=>$post['user_id']);
			$return['respons']  = $callConfig->insertRecord('application_user_module_roles',$insertarray);

			$upsql = "UPDATE application_users SET role_id = JSON_ARRAY_APPEND(CASE WHEN JSON_VALID(role_id) THEN role_id ELSE JSON_ARRAY() END,'$','".$roleres->role_short_code."') WHERE id = '".$post['rid']."'";
			 $callConfig->executeQuery($upsql);
		}elseif($post['formtype'] == "remove_application_user_module_roles"){	

			$query = "SELECT id,role_short_code, user_id FROM application_user_module_roles where company_id = '".$post['company_id']."' AND id = '".$post['module_role_id']."' AND is_active = 0";
			$roleres = $callConfig->getRow($query);

			$updatearray = array("is_active"=>null,"to_date"=>date('Y-m-d h:i:s'),"updated_date"=>date('Y-m-d h:i:s'),"updated_by"=>$post['user_id']);
			$return['respons']  = $callConfig->updateRecord('application_user_module_roles',$updatearray,'id',$post['module_role_id']);
			if($roleres->role_short_code !=""){
				$updateallrolesql = "UPDATE application_users SET role_id = JSON_REMOVE(role_id, JSON_UNQUOTE(JSON_SEARCH(role_id,'one','".$roleres->role_short_code."'))) WHERE company_id = '".$post['company_id']."' AND is_active = 0 AND id = '".$post['rid']."'";
				$return['respons_application_users']  = $callConfig->executeQuery($updateallrolesql);
			}
		}
		return $return;
	}
	function getTransactionActivitySchedules($get){
		global $callConfig;
		$transaction_table = $get['transaction_table'];
		$transaction_id = $get['transaction_id'];
		$condition_task ="";
		if($transaction_table == "employees"){
			$finance_tax_year = $get['finance_tax_year'];
	        if($finance_tax_year !=""){
	            $startdate =date($finance_tax_year."-04-01");
	            $enddate =date(($finance_tax_year+1)."-03-31");
	        	$condition_task .=  " AND action_date >='".$startdate." 00:00:00' AND action_date <='".$enddate." 23:59:59'";
	        }
			
		}
		$tas_id = $get['tas_id'];
		$company_id = $get['company_id'];
		$return['get'] = $get;
		if($get['result_type'] == 'checklist'){
			$transaction_activity_schedulesql = "SELECT tas.id, tas.transaction_table, tas.transaction_id, tas.task_id, tas.assigned_to, tas.approval_user_id, tas.action_date, tas.revised_action_date, tas.actual_action_date, tas.completion_date, tas.approval_date, tas.action_flag, tas.comments, tas.note, tas.check_list, tas.finish_date, tas.current_status FROM transaction_activity_schedule tas WHERE tas.company_id = '".$company_id."' AND tas.id = '".$get['task_id']."' AND tas.is_active = 0";
			$transaction_activity_scheduleres = $callConfig->getRow($transaction_activity_schedulesql);
			$return['transaction_activity_schedule'] =$transaction_activity_scheduleres;
			//$return['checklist'] ="Y";
		}elseif($get['result_type'] == 'singlechecklist'){
			$transaction_activity_schedulesql = "SELECT tas.id, tas.transaction_table, tas.check_list, tas.assigned_to, tas.current_status FROM transaction_activity_schedule tas WHERE tas.company_id = '".$company_id."' AND tas.id = '".$get['task_id']."' AND tas.is_active = 0";
			$transaction_activity_scheduleres = $callConfig->getRow($transaction_activity_schedulesql);
			$return['transaction_activity_schedule'] =$transaction_activity_scheduleres;

			$display_attributessql = "SELECT id, file_upload FROM display_attributes WHERE company_id = '".$company_id."' AND application_table_name = 'transaction_activity_schedule' AND is_active = 0";
			$display_attributesres = $callConfig->getRow($display_attributessql);
			$return['display_attributes'] =$display_attributesres;

			//$return['checklist'] ="Y";
		}else{
			if($tas_id !=""){
				$transaction_activity_schedulesqls = "SELECT tas.transaction_table, tas.transaction_id FROM transaction_activity_schedule tas WHERE tas.company_id = '".$company_id."' AND tas.id = '".$tas_id."' AND tas.is_active = 0";
				$tas_res = $callConfig->getRow($transaction_activity_schedulesqls);
				$transaction_table = $tas_res->transaction_table;
				$transaction_id = $tas_res->transaction_id;
			}
			if($get['admin_type']!='1'){
				//$condition_task = " AND (tas.assigned_to = '".$get['user_id']."' OR tas.approval_user_id = '".$get['user_id']."')";
				$condition_task .= " AND (tas.assigned_to = '".$get['user_id']."' OR tas.approval_user_id = '".$get['user_id']."')";
			}
			$transaction_activity_schedulesql = "SELECT tas.id, tas.transaction_table, tas.transaction_id, tas.task_id, tas.assigned_to, tas.approval_user_id, tas.action_date, tas.revised_action_date, tas.actual_action_date, tas.completion_date, tas.approval_date, tas.action_flag, tas.comments, tas.note, tas.check_list, tas.finish_date, tas.current_status, tas.task_name, tas.process_id FROM transaction_activity_schedule tas WHERE tas.company_id = '".$company_id."'  AND tas.transaction_table = '".$transaction_table."' AND tas.transaction_id = '".$transaction_id."' AND tas.is_active = 0 ".$condition_task;
			$return['transaction_activity_schedulesql'] =$transaction_activity_schedulesql;
			$transaction_activity_scheduleres = $callConfig->getAllRows($transaction_activity_schedulesql);
			$transaction_activity_schedule = array();
			foreach($transaction_activity_scheduleres as $tas){
				$transaction_activity_schedule[$tas->process_id][$tas->id] = $tas;
			}
			$return['transaction_activity_schedule'] =$transaction_activity_schedule;
			//$return['transaction_activity_schedule_sql'] =$transaction_activity_schedule;

			$action_transaction_activity_schedulesql = "SELECT tas.id, tas.transaction_table, tas.transaction_id, tas.task_id, tas.assigned_to, tas.approval_user_id, tas.action_date, tas.revised_action_date, tas.actual_action_date, tas.completion_date, tas.approval_date, tas.action_flag, tas.comments, tas.note, tas.check_list, tas.finish_date, tas.current_status, tas.task_name, tas.process_id, tal.request_date, tal.response_date, tal.comments, tal.response_type FROM transaction_activity_schedule tas,  transaction_approval_logs tal WHERE tas.company_id = '".$company_id."' AND tas.company_id = tal.company_id AND tas.transaction_table = '".$transaction_table."' AND tas.transaction_id = '".$transaction_id."' AND tas.id = tal.transaction_id AND tal.transaction_table ='transaction_activity_schedule' AND  tal.user_id = '".$get['user_id']."' AND tas.is_active = 0";
			$return['action_transaction_activity_schedulesql'] =$action_transaction_activity_schedulesql;
			$action_transaction_activity_scheduleres = $callConfig->getAllRows($action_transaction_activity_schedulesql);
			$action_transaction_activity_schedule = array();
			foreach($action_transaction_activity_scheduleres as $tas){
				$action_transaction_activity_schedule[$tas->process_id][$tas->id] = $tas;
			}
			$return['action_transaction_activity_schedule'] =$action_transaction_activity_schedule;


			$tasks_categoriessql = "SELECT id, category_name FROM tasks_categories WHERE company_id = '".$get['company_id']."' AND is_active = 0";
			$tasks_categoriesres = $callConfig->getAllRows($tasks_categoriessql);
			$tasks_categories = array();
			foreach($tasks_categoriesres as $tc){
				$tasks_categories[$tc->id] = $tc;
			}
			$return['tasks_categories'] =$tasks_categories;

			$get['table'] =$transaction_table;
			$status_progress = $this->getStatusProgressList($get);
			$statustep = array();
			foreach($status_progress as $sp){
				$statustep[$sp->status] = $sp;
			}
			$return['status_progress'] =$statustep;
		}
		return $return;
	}
	function getTransactionActivitySchedulesDashboartd($get){
		global $callConfig;
		$return['get'] =$get;
		if($get['transaction_table'] !=""){
			$sql = "SELECT id,display_name FROM ".$get['transaction_table']." WHERE  company_id = '".$get['company_id']."' AND is_active = 0";
			$res = $callConfig->getAllRows($sql);
			$return['transactions'] =$res;

			$transaction_activity_schedulesql = "SELECT assigned_to, transaction_id, count(*) as total_task_cnt, sum(if(current_status=".ST_APPROVED.",1,0)) as approve_cnt, sum(if(current_status=".ST_COMPLETE.",1,0)) as review_cnt, sum(if(current_status=".ST_INPROGRESS.",1,0)) as inprogress_cnt, sum(if(current_status=".ST_ACTIVE.",1,0)) as yet_to_start_cnt, sum(if(action_date < completion_date,1,0)) as delayed_cnt FROM transaction_activity_schedule tas WHERE  tas.company_id = '".$get['company_id']."' AND tas.transaction_table = '".$get['transaction_table']."'  AND tas.is_active = 0 GROUP BY tas.assigned_to";
			$transaction_activity_scheduleres = $callConfig->getAllRows($transaction_activity_schedulesql);
			$transaction_activity_schedule = array();
			foreach($transaction_activity_scheduleres as $tas){
				$transaction_activity_schedule[$tas->transaction_id] = $tas;
			}
			$return['transaction_activity_schedule'] =$transaction_activity_schedule;
		}else{
			$tasktables = array('vendor_registers','vendors','customers','candidates','employees');
			$dynamicsql = "SELECT ";
			$transactiondetails = array();
			foreach($tasktables as $transaction_table){
				$dynamicsql .= "(Select count(id) as cnt FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' AND is_active = 0 limit 1) as ".$transaction_table.",";
			}
			$dynamicsql = substr($dynamicsql, 0, -1);
			$tableresult = $callConfig->getRow($dynamicsql);
			$return['transactions'] =$tableresult;
		}
		return $return;
	}	
	function creatQRCode($text,$path){
		$filename = "qr_code_".time().'.png';
		$size = 10;
		QRcode::png($text, $path.$filename, QR_ECLEVEL_L, $size);
		return $filename;
	}	
