	function newitempruchasehistories($data,$get,$rid){
		global $callConfig;
		//echo $rid; print_r($get);
		$key = explode(":", $rid);
		$query = "SELECT purchase_price, sale_price FROM item_pruchase_histories WHERE item_id  =".$key['1']." ORDER BY id DESC LIMIT 0,1";
		//echo $query;
		$value = $callConfig->getRow($query);
		$insert_array = array('company_id'=>$get['company_id'],'item_id'=>$key['1'],'purchase_price'=>$data['purchase_price'], 'sale_price'=>$data['sale_price'],'is_active'=>0,'current_status'=>0,'created_by'=>$get['user_id']);
		if(count((array)$value)>0){
			//echo "Good"; exit;
			if(round($value->purchase_price,2) != round($data['purchase_price'],2) || round($value->sale_price,2) != round($data['sale_price'],2) ){
				$checkres = $callConfig->insertRecord('item_pruchase_histories',$insert_array);
			}			
		}else{
			//echo "bad"; exit;
			$checkres = $callConfig->insertRecord('item_pruchase_histories',$insert_array);
		}
		return $checkres;
	}
	function getitempricehistoriesbyitemid($get){
		global $callConfig;
		$query = "SELECT it.id, it.item_id, it.purchase_price, it.sale_price, it.created_date , au.id user_id, au.display_name , au.user_email, au.user_mobile, au.user_photo image FROM item_pruchase_histories it, application_users au WHERE it.company_id = au.company_id AND it.company_id = ".$get['company_id']." AND it.created_by = au.id AND it.item_id = ".$get['item_id']." AND it.is_active = 0";
		$data = $callConfig->getAllRows($query);
		return $data;
	}
	function getItemsOrders($get){
		global $callConfig;
		$return['get'] = $get;
		$tables = $this->toGetInvoicetabledata($get['table_name']);
        $posql = "SELECT tt.id, tt.transaction_number, tt.transaction_date, tt.party_name, ti.item_quantity, ti.item_price, ti.item_amount FROM ".$get['table_name']." tt, ".$tables['item']." ti WHERE tt.company_id = '".$get['company_id']."' AND tt.company_id = ti.company_id AND tt.id = ti.transaction_id AND tt.current_status ='".ST_APPROVED."' AND ti.item_id = '".$get['item_id']."' AND tt.is_active = ti.is_active AND tt.is_active = 0 ORDER BY tt.transaction_date DESC limit 5";	
		$pores = $callConfig->getAllRows($posql);
		$return['res'] = $pores;
		return $return;
	}
	function getPartyDetails($get){
		global $callConfig;
		$return['get'] = $get;
        $sql = "SELECT *,(SELECT pt.payment_term_name FROM payment_terms pt where pt.company_id = ven.company_id AND pt.id=ven.payment_terms AND pt.is_active = ven.is_active) as payment_term_name FROM ".$get['part_table']." ven WHERE ven.company_id = '".$get['company_id']."' AND ven.id = '".$get['party_id']."' AND ven.is_active = 0";	
		$res = $callConfig->getRow($sql);
		$return['party_detail'] = $res;
		if($get['part_table'] == "vendors"){
			$invsql = "SELECT (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Indentings') FROM requisitions WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0) as req_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Quotations') FROM quotations WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0) as quo_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Purchase Orders') FROM purchase_orders WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0) as po_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||',IFNULL(SUM(pending_amount),'0'),'||','Purchase Invoices') FROM purchase_invoices WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND cancel_invoice = 'N' AND current_status ='".ST_APPROVED."' AND is_active = 0) as pi_cnt";
			$invres = $callConfig->getRow($invsql);
			$return['invoice_detail_sql'] = $invsql;
			$return['invoice_detail'] = $invres;
			
			$transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, current_status FROM purchase_invoices WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0";	
			$transres = $callConfig->getAllRows($transsql);
			$return['all_transactions'] = $transres;

			$transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, pending_amount, due_date,  current_status FROM purchase_invoices WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND cancel_invoice = 'N' AND is_active = 0 AND pending_amount > 0";	
			$transres = $callConfig->getAllRows($transsql);
			$return['pending_amt_transactions'] = $transres;

			$transsql = "SELECT pt.item_id, pt.item_name, SUM(pt.item_quantity) as item_quantity, SUM(pt.item_price) as item_price, SUM(pt.item_amount) as item_amount , SUM(pt.tax_amount) as tax_amount, SUM(pt.total_amount) as total_amount FROM purchase_invoices pi, pi_items pt WHERE pi.company_id = '".$get['company_id']."'  AND pi.company_id = pt.company_id AND pi.id = pt.transaction_id AND pi.party_id = '".$get['party_id']."' AND pi.current_status ='".ST_APPROVED."' AND pi.is_active = pt.is_active AND pi.is_active = 0 GROUP BY pt.item_id, pt.item_name";	
			$transres = $callConfig->getAllRows($transsql);
			$return['transaction_items'] = $transres;
			

			$query = "SELECT id, payment_terms, total_amount, party_id, party_name, due_date, payment_term_history FROM purchase_invoices WHERE company_id = ".$get['company_id']." AND (pending_amount IS NULL OR  pending_amount !=0) AND party_id = '".$get['party_id']."' AND cancel_invoice = 'N' AND current_status ='".ST_APPROVED."' AND is_active = 0";
			$return['bills_sql'] = $query;
			$return['bills'] = $callConfig->getAllRows($query);

		}else{
		
			$invsql = "SELECT (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Indentings') FROM requisitions WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 5) as req_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Sales Orders') FROM sales_orders WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0) as quo_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||','Sales Returns') FROM sales_returns WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0) as po_cnt, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||',IFNULL(SUM(pending_amount),'0'),'||','Sales Invoices') FROM sales_invoices WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND cancel_invoice = 'N' AND current_status ='".ST_APPROVED."' AND is_active = 0) as pi_cnt";
			$invres = $callConfig->getRow($invsql);
			$return['invoice_detail_sql'] = $invsql;
			$return['invoice_detail'] = $invres;

			$transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, current_status FROM sales_invoices WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND is_active = 0";	
			$transres = $callConfig->getAllRows($transsql);
			$return['all_transactions'] = $transres;

			$transsql = "SELECT id, transaction_number, transaction_date, originator, amount, tax_amount, discount_amount, total_amount, shipping_amount, shipping_tax_amount, cancel_invoice, pending_amount, due_date,  current_status FROM sales_invoices WHERE company_id = '".$get['company_id']."' AND party_id = '".$get['party_id']."' AND current_status ='".ST_APPROVED."' AND cancel_invoice = 'N' AND is_active = 0 AND pending_amount > 0";	
			$transres = $callConfig->getAllRows($transsql);
			$return['pending_amt_transactions'] = $transres;

			$transsql = "SELECT pt.item_id, pt.item_name, SUM(pt.item_quantity) as item_quantity, SUM(pt.item_price) as item_price, SUM(pt.item_amount) as item_amount , SUM(pt.tax_amount) as tax_amount, SUM(pt.total_amount) as total_amount FROM sales_invoices pi, si_items pt WHERE pi.company_id = '".$get['company_id']."'  AND pi.company_id = pt.company_id AND pi.id = pt.transaction_id AND pi.party_id = '".$get['party_id']."' AND pi.current_status ='".ST_APPROVED."' AND pi.is_active = pt.is_active AND pi.is_active = 0 GROUP BY pt.item_id, pt.item_name";	
			$transres = $callConfig->getAllRows($transsql);
			$return['transaction_items'] = $transres;
			

			$query = "SELECT id, payment_terms, total_amount, party_id, party_name, due_date, payment_term_history FROM sales_invoices WHERE company_id = ".$get['company_id']." AND (pending_amount IS NULL OR  pending_amount !=0) AND party_id = '".$get['party_id']."' AND cancel_invoice = 'N' AND current_status ='".ST_APPROVED."' AND is_active = 0";
			$return['bills_sql'] = $query;
			$return['bills'] = $callConfig->getAllRows($query);
		
		}

		return $return;
		
	}
	function updateApplicationFavourites($post){
		global $callConfig;
		$return['post'] = $post;
		if($post['type'] =="F"){
			$insertary=array('company_id'=>$post['company_id'],'application_table_name'=>$post['application_table_name'],'transaction_id'=>$post['transaction_id'],'user_id'=>$post['user_id'],'created_by'=>$post['user_id'],'is_active'=>0,'created_date'=>date("Y-m-d H:i:s"));
			$tapres = $callConfig->insertRecord('application_favourites',$insertary);
			$return['result'] =$tapres;	
		}else{
			$updatedary['is_active']=null;
			$updatedary['updated_date']=date('Y-m-d h:i:s');
			$updatedary['updated_by']=$post['user_id'];
			$wh = " company_id = '".$post['company_id']."' AND application_table_name = '".$post['application_table_name']."' AND transaction_id = '".$post['transaction_id']."' AND user_id = '".$post['user_id']."' AND is_active = 0";
			$return['result'] = $callConfig->updateRecord('application_favourites',$updatedary,'','',$wh);
		}
		return $return;
	}
