	function setCronJobWorkFlowConfigurationsNew($get){
		global $callConfig;
		$return['get'] =$get;
		//http://dev.infistaq.in//api.php/?mode=setcronjobworkflowconfigurationsnew&admin_type=0&admin_access_employee=N&page_option=&data_name=infistaqin_infisuite_2&user_id=1&company_id=1&module_id=&module_group_id=&ipaddress=59.95.107.153
		//Start cron job start entry
		$insert_array = array('company_id'=>$get['company_id'], 'start_date_time'=>date('Y-m-d h:i:s'), 'command'=> 'user.class.php/setCronJobWorkFlowConfigurationsNew' , 'is_active'=>'0', 'current_status'=>'0', 'created_date'=>date('Y-m-d h:i:s'));
	 	$ccres = $callConfig->insertRecord('cron_jobs', $insert_array);
	 	//print_r($ccres);
	 	//End cron job start entry
	 	
		$todaydate = date('Y-m-d'); 
		//Start Get All Users
		$application_userssql = "SELECT id, company_id, display_name, user_email, reports_to FROM application_users WHERE company_id='".$get['company_id']."' AND is_active = 0";
		$application_usersres=$callConfig->getAllRows($application_userssql);
		$application_users = array();
		foreach($application_usersres as $aures){
			$application_users[$aures->id] = $aures; //users store in array With Id
		}
		//Start Get All Users

		//Start Get All page with link
		$pageurlsql = "SELECT insert_page_name, approval_page_name, application_table_name FROM application_pages WHERE company_id='".$get['company_id']."' AND is_active =0"; 
		$pageurl = $callConfig->getAllRows($pageurlsql);
		$application_pages = array();
		foreach($pageurl as $pag){
			$approval_page_name = $pag->approval_page_name != ""?$pag->approval_page_name:$pag->insert_page_name;
			$application_pages[$pag->application_table_name] = $approval_page_name;
		}
		//Start Get All page with link
		//Start Get Workflow
		$workflow_configurations_newsql = "SELECT * FROM workflow_configurations_new WHERE company_id = '".$get['company_id']."' AND process_name='requisitions' AND is_active = 0";
		$workflow_configurations_newres = $callConfig->getAllRows($workflow_configurations_newsql);
		$return['workflow_configurations_new'] =$workflow_configurations_newres;
		//End Get Workflow
		
		foreach($workflow_configurations_newres as $wf){ // loop Work flow
			$status_progres = array();
			$postget['table'] =$wf->process_name;
			$status_progress = $this->getStatusProgressList($postget);
			foreach($status_progress as $statusprogress){
				$status_progres[$statusprogress->status] = $statusprogress;
			}
			//Start Follow Up
			if($wf->follow_up =="Y"){ // follow Up Check - Yes/ NO
				$followup_with_userid = array();
				$transaction_table = $wf->process_name; // Get Transaction table
				$follow_up_day = $wf->follow_up_day; // follow Up days
				$follow_up_email_content_ref_id = $wf->follow_up_email_content_ref_id; // follow email id
				$transactionlogsql = "SELECT tal.id, tal.response_type, tal.transaction_table, tal.transaction_id, tal.request_date, tal.user_id, tal.previous_status, trans.current_status  FROM transaction_approval_logs tal, ".$transaction_table." trans WHERE tal.company_id = '".$get['company_id']."' AND tal.company_id = trans.company_id AND tal.transaction_id = trans.id AND tal.transaction_table = '".$transaction_table."' AND tal.response_type = 0 AND tal.send_back_flag = 0 AND tal.call_back = 1 AND tal.request_date <= '".$todaydate."' AND trans.is_active = 0";
				$transactionlogres = $callConfig->getAllRows($transactionlogsql);
				//$return['transaction'][$transaction_table] =$transactionlogres; 
				foreach($transactionlogres as $tl){ // loop all logs
					$followupdate = date('Y-m-d', strtotime('+'.$follow_up_day.' days', strtotime($tl->request_date))); //approvbe requist date added follow up days 
					if(strtotime($todaydate) >= strtotime($followupdate)){ // check max followup days
						$followup_with_userid[$tl->user_id][] =$tl;
					}
				}
				foreach($followup_with_userid as $userid=>$esaldata){
					if($application_users[$userid]){ // check user available or not
						$userdetail = $application_users[$userid];
						$transactionlisttable = "<table width ='100%'><tr><th style='text-align: center'>#</th><th style='text-align: center'>Submitted Date</th><th style='text-align: center'>Current Status</th><th style='text-align: center'>Action</th></tr>";
						$mk = 1;
						foreach($esaldata as $datas){
							$request_dates = date("d M Y",strtotime($datas->request_date));
							//notification part
							$notarry = array();
							$msg = "Follow-Up on ".ucwords(str_replace('_', ' ', $transaction_table))." - ".$request_dates;
							$option = $application_pages[$transaction_table];
							$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$datas->transaction_id,'application_table_name'=>$transaction_table,'type'=>'ACTION', 'notification_users'=>array($datas->user_id),'option'=>$option,'assigner_id'=>$datas->user_id);
							//$sendnotification = $this->tosendnotifiations($notarry);
							//notification part
							$transactionlisttable .="<tr>";
							$transactionlisttable .="<td style='text-align: center'>".$mk."</td>";
							$transactionlisttable .="<td style='text-align: center'>".$request_dates."</td>";
							$transactionlisttable .="<td style='text-align: center'>".$status_progres[$datas->current_status]->name."</td>";
							$transactionlisttable .="<td style='text-align: center'><a href='".SITEURL."index.php?option=".$option."&Rid=".base64_encode(base64_encode('id:'.$datas->transaction_id))."'><button class='btn btn-primary waves-effect waves-light'>Click Here</button></a></td>";
							$transactionlisttable .="</tr>";
							$mk++;

							$crondetail = array('company_id'=>$get['company_id'], 'execution_date_time'=>date('Y-m-d h:i:s'), 'cron_job_id'=>$ccres['LASTID'],'transaction_table'=>'transaction_approval_logs','transaction_id'=>$datas->transaction_id,'parent_transaction_table'=>'workflow_configurations_new','parent_transaction_id'=>$wf->id,'transaction_details'=>json_encode($datas), 'comment'=>'Follow Up', 'is_active'=>'0', 'current_status'=>'0', 'created_date'=>date('Y-m-d h:i:s'));
	 						$return['cron_job_details'][] = $callConfig->insertRecord('cron_job_details', $crondetail);

						}
						$transactionlisttable .= "</table>";
						//Email part
						$emailarray['approval_user_email_id'] = $userdetail->user_email;
						$emailarray['user_display_name'] = $userdetail->display_name;
						$emailarray['to_company_id'] = $userdetail->display_name;
						$emailarray['session_company_id'] = $userdetail->company_id;
						$emailarray['created_by'] = $userdetail->id;
						$emailarray['transaction_name'] = ucwords(str_replace('_', ' ', $transaction_table));
						$emailarray['transaction_list'] = $transactionlisttable;
						$emailarray['request_date'] = date("d M Y",strtotime($todaydate));;
						//Email part
						$notarry = array();
						// $email = $this->sendNotificationAndEmails($notarry,$emailarray,$follow_up_email_content_ref_id);
						// $return['emailarray'][$transaction_table][] =$emailarray;
						// $return['email'][$transaction_table][] =$email;

					}
				}
			}
			//End Follow Up
			//Start Escalation 
			if($wf->escalation =="Y"){ // follow Up Check - Yes/ NO
				$escalation_with_userid = array();
				$transaction_table = $wf->process_name; // Get Transaction table
				$escalation_day = $wf->escalation_day; // follow Up days
				$escalation_email_content_ref_id = $wf->escalation_email_content_ref_id; // follow email id
				$transactionlogsql = "SELECT tal.id, tal.response_type, tal.transaction_table, tal.transaction_id, tal.request_date, tal.user_id, tal.previous_status, trans.current_status  FROM transaction_approval_logs tal, ".$transaction_table." trans WHERE tal.company_id = '".$get['company_id']."' AND tal.company_id = trans.company_id AND tal.transaction_id = trans.id AND tal.transaction_table = '".$transaction_table."' AND tal.response_type = 0 AND tal.send_back_flag = 0 AND tal.call_back = 1 AND tal.request_date <= '".$todaydate."' AND trans.is_active = 0";
				$transactionlogres = $callConfig->getAllRows($transactionlogsql);
				$return['transaction'][$transaction_table] =$transactionlogres; 
				foreach($transactionlogres as $tl){ // loop all logs
					$followupdate = date('Y-m-d', strtotime('+'.$escalation_day.' days', strtotime($tl->request_date))); //approvbe requist date added follow up days 
					if(strtotime($todaydate) >= strtotime($followupdate)){ // check max followup days
						$escalation_with_userid[$tl->user_id][] =$tl;
					}
				}
				foreach($escalation_with_userid as $userid=>$esaldata){
					if($application_users[$userid]){ // check user available or not
						$reportdetail = $application_users[$userid];
						$transactionlisttable = "<table width ='100%'><tr><th style='text-align: center'>#</th><th style='text-align: center'>Submitted Date</th><th style='text-align: center'>Submitted To</th><th style='text-align: center'>Current Status</th><th style='text-align: center'>Action</th></tr>";
						$mk = 1;
						foreach($esaldata as $datas){
							$request_dates = date("d M Y",strtotime($datas->request_date));
							//notification part
							$notarry = array();
							$option = $application_pages[$transaction_table];
							$msg = "Escalation on ".ucwords(str_replace('_', ' ', $transaction_table))." - ".$request_dates;
							$notarry = array('company_id'=>$get['company_id'],'notification_message'=>$msg, 'id'=>$datas->transaction_id,'application_table_name'=>$transaction_table,'type'=>'ACTION', 'notification_users'=>array($datas->user_id),'option'=>$option,'assigner_id'=>$datas->user_id);
							//$sendnotification = $this->tosendnotifiations($notarry);
							//notification part
							$transactionlisttable .="<tr>";
							$transactionlisttable .="<td style='text-align: center'>".$mk."</td>";
							$transactionlisttable .="<td style='text-align: center'>".$request_dates."</td>";
							$transactionlisttable .="<td style='text-align: center'>".$reportdetail->display_name."</td>";
							$transactionlisttable .="<td style='text-align: center'>".$status_progres[$datas->current_status]->name."</td>";
							$transactionlisttable .="<td style='text-align: center'><a href='".SITEURL."index.php?option=".$option."&Rid=".base64_encode(base64_encode('id:'.$datas->transaction_id))."'><button class='btn btn-primary waves-effect waves-light'>Click Here</button></a></td>";
							$transactionlisttable .="</tr>";
							$mk++;

							$crondetail = array('company_id'=>$get['company_id'], 'execution_date_time'=>date('Y-m-d h:i:s'), 'cron_job_id'=>$ccres['LASTID'],'transaction_table'=>'transaction_approval_logs','transaction_id'=>$datas->transaction_id,'parent_transaction_table'=>'workflow_configurations_new','parent_transaction_id'=>$wf->id,'transaction_details'=>json_encode($datas), 'comment'=>'Escalation', 'is_active'=>'0', 'current_status'=>'0', 'created_date'=>date('Y-m-d h:i:s'));
	 						$return['cron_job_details'][] = $callConfig->insertRecord('cron_job_details', $crondetail);
						}
						$transactionlisttable .= "</table>";
						$userdetail = $application_users[$reportdetail->reports_to];
						//Email part
						$emailarray1['user_email_id'] = $userdetail->user_email;
						$emailarray1['user_display_name'] = $userdetail->display_name;
						$emailarray1['to_company_id'] = $userdetail->display_name;
						$emailarray1['session_company_id'] = $userdetail->company_id;
						$emailarray1['created_by'] = $userdetail->id;
						$emailarray1['transaction_name'] = ucwords(str_replace('_', ' ', $transaction_table));
						$emailarray1['transaction_list'] = $transactionlisttable;
						$emailarray1['request_date'] = date("d M Y",strtotime($todaydate));;
						//Email part
						$notarry = array();
						//$email = $this->sendNotificationAndEmails($notarry,$emailarray1,$escalation_email_content_ref_id);
						// $return['emailarray'][$transaction_table][] =$emailarray1;
						// $return['email'][$transaction_table][] =$email;

					}
				}	
			}
			//End Escalation 
			//Start Escalation 
			if($wf->auto_forward =="Y"){ // follow Up Check - Yes/ NO
				$transaction_table = $wf->process_name; // Get Transaction table
				$auto_forward = $wf->auto_forward_day; // follow Up days
				$transactionlogsql = "SELECT tal.id, tal.response_type, tal.transaction_table, tal.transaction_id, tal.request_date, tal.user_id, tal.previous_status, trans.current_status  FROM transaction_approval_logs tal, ".$transaction_table." trans WHERE tal.company_id = '".$get['company_id']."' AND tal.company_id = trans.company_id AND tal.transaction_id = trans.id AND tal.transaction_table = '".$transaction_table."' AND tal.response_type = 0 AND tal.send_back_flag = 0 AND tal.call_back = 1 AND tal.request_date <= '".$todaydate."' AND trans.is_active = 0";
				$transactionlogres = $callConfig->getAllRows($transactionlogsql);
				//$return['transaction'][$transaction_table] =$transactionlogres; 
				foreach($transactionlogres as $tl){ // loop all logs
					$followupdate = date('Y-m-d', strtotime('+'.$auto_forward.' days', strtotime($tl->request_date))); //approvbe requist date added follow up days 
					if(strtotime($todaydate) >= strtotime($followupdate)){ // check max followup days
						$get['transaction_no'] = $tl->transaction_id;
						$get['transaction_table'] = $tl->transaction_table;
						$get['current_status'] = $tl->current_status;
						$get['company_id'] = $get['company_id'];
						$getDynamicWorkFlowSteps = $this->getDynamicWorkFlowSteps($get);
						$nextstepkeyvalue = $getDynamicWorkFlowSteps['nextstepkeyvalue'];
						$nextstatus = $nextstepkeyvalue[$tl->current_status];
						if($nextstatus !=""){ 
							$get['transaction_table'] = $tl->transaction_table;
							$get['current_status'] = $tl->current_status;
							$get['transaction_no'] = $tl->transaction_id;
							$get['next_status'] = $nextstatus;
							$get['comment'] = 'Cron Job Approved';
							$get['user_id'] = $tl->user_id;
							//$auto_forward_docs = $this->submitStatusDynamicWorkFlow($get);
							//print_r($auto_forward_docs);

							$crondetail = array('company_id'=>$get['company_id'], 'execution_date_time'=>date('Y-m-d h:i:s'), 'cron_job_id'=>$ccres['LASTID'],'transaction_table'=>$tl->transaction_table,'transaction_id'=>$tl->transaction_id,'parent_transaction_table'=>'transaction_approval_logs','parent_transaction_id'=>$tl->id,'transaction_details'=>json_encode($tl), 'comment'=>'Auto Forward', 'is_active'=>'0', 'current_status'=>'0', 'created_date'=>date('Y-m-d h:i:s'));
	 						$return['cron_job_details'][] = $callConfig->insertRecord('cron_job_details', $crondetail);

						}
					}
				}
			}
		}

		//Start cron job End entry
	 	if($ccres['LASTID'] !=""){		
		 	$update_array = array('end_date_time'=>date('Y-m-d h:i:s'),'updated_date'=>date('Y-m-d h:i:s'));
			$wh = "id = '".$ccres['LASTID']."'";
			$ccresupdate = $callConfig->updateRecord('cron_jobs',$update_array,'','',$wh);
		}

		//End cron job End entry

		//print_r($return);
		return $return;
	}
	function getEmployeesDisplayFields($get){
		global $callConfig;
		$return = array();
		if($get['Role'] != ""){
			$condition = " AND role_id = '".$get['Role']."'";
		}else{
			$condition = " AND id = '".$get['Rid']."'";	
		}
		$employees_display_fieldssql = "SELECT *,role_id as role_short_code FROM employees_display_fields WHERE company_id = '".$get['company_id']."' ".$condition."  AND is_active = 0";
		$employees_display_fieldsres=$callConfig->getRow($employees_display_fieldssql);
		$return['employees_display_fields'] = $employees_display_fieldsres;

		$application_rolessql = "SELECT name, role_short_code FROM application_roles WHERE company_id = '".$get['company_id']."' AND application_module = '".$callConfig->module_id."' AND is_active = 0";
		$application_rolesres=$callConfig->getAllRows($application_rolessql);
		$return['application_roles'] = $application_rolesres;
		return $return;
	}
	function insertEmployeesDisplayFields($post){
		global $callConfig;
		$return = array();
		$return['post'] = $post;	
		$fielddata = json_encode($post['fieldgrpaccess']);
		$return['post'] = $post;	
		if(isset($post['Rid']) AND $post['Rid'] !=""){
			$post_array= array("role_id"=>$post['role_short_code'],"field_list"=>$fielddata,"updated_by"=>$post['user_id'],"updated_date"=>date('Y-m-d H:i:s'));
			$res=$callConfig->updateRecord('employees_display_fields',$post_array,'id',$post['Rid']);	
		}else{
			$post_array = array("company_id"=>$post['company_id'],"role_id"=>$post['role_short_code'],"field_list"=>$fielddata,"is_active"=>"0","current_status"=>"0","created_date"=>date('Y-m-d h:i:s'),"created_by"=>$post['user_id']);
			$res = $callConfig->insertRecord('employees_display_fields',$post_array);	
		}
		$return['result'] = $res;
		return $return;
	}
	function getApplicationReports($get){
		global $callConfig;
		$return['get']= $get;
		$party_table = $get['party_table'];
		$transaction_table = $get['transaction_table'];
		$customer_condition= "";
		if($get['party_id'] !=""){
			$customer_condition = " AND id = '".$get['party_id']."'";
			$invoice_condition = " AND ri.party_id = '".$get['party_id']."'";
			$invoicecondition = " AND party_id = '".$get['party_id']."'";
		}
		$customerssql = "SELECT id, display_name, company FROM ".$party_table." WHERE company_id = '".$get['company_id']."' ".$customer_condition." AND is_active =0";
		$customersres =$callConfig->getAllRows($customerssql);
		$return['party_list_sql'] =$customerssql;
		$return['party_list'] =$customersres;

		$customerssql = "SELECT id, display_name, company FROM ".$party_table." WHERE company_id = '".$get['company_id']."' AND is_active =0";
		$customersres =$callConfig->getAllRows($customerssql);
		$all_parties = array();
		foreach($customersres as $part){
			$all_parties[$part->id]= $part;
		}
		$return['all_parties'] =$all_parties;
		
		if($get['reporttype'] == "MONTHLY"){
			$sdate = date("Y-m-01",strtotime($get['start_month']));
			$previouslastdate = date('Y-m-d', strtotime($sdate .' - 1 days'));
			$edate = date("Y-m-t",strtotime($get['end_month']));
			$startDate = new DateTime($sdate);
			$endDate = new DateTime($edate);
			$i = 0;
			$monthyearary =array();
			while($startDate <= $endDate){
				$monthandyear = $startDate->format('M Y');
				$monthyearkey = $startDate->format('mY');
				$monthyearary[$monthyearkey] = $monthandyear;
				$startDate->modify('+1 month'); 
			}
			$return['monthyearary'] = $monthyearary;
			$invoices = $opening_balance_inv =  array();
			//Start opening balance
			$ob_rental_invoicessql = "SELECT party_id, SUM(amount) as amount, SUM(tax_amount) as tax_amount, SUM(total_amount) as total_amount, SUM(pending_amount) as pending_amount FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' AND is_active =0 AND current_status = '".ST_APPROVED."' ".$invoicecondition." AND transaction_date <= '".$previouslastdate."' GROUP BY party_id";
			$return['ob_rental_invoicessql'] = $ob_rental_invoicessql;
			$ob_rental_invoicesres=$callConfig->getAllRows($ob_rental_invoicessql);
			foreach($ob_rental_invoicesres as $ri){
				$opening_balance_inv[$ri->party_id]= $ri;
			}
			$return['opening_balance'] = $opening_balance_inv;
			//End opening balance
			
			$rental_invoicessql = "SELECT transaction_date, party_id, SUM(amount) as amount, SUM(tax_amount) as tax_amount, SUM(total_amount) as total_amount, SUM(pending_amount) as pending_amount FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' AND is_active =0 AND current_status = '".ST_APPROVED."' AND transaction_date >= '".$sdate."' AND transaction_date <=  '".$edate."' ".$invoicecondition." GROUP BY MONTH(transaction_date), YEAR(transaction_date),party_id";
			$return['rent_sql'] = $rental_invoicessql;
			$rental_invoicesres=$callConfig->getAllRows($rental_invoicessql);
			foreach($rental_invoicesres as $ri){
				$monthyear = date('mY',strtotime($ri->transaction_date));
				$invoices[$ri->party_id][$monthyear]= $ri;
			}

			$return['invoices'] = $invoices;

			$paymentssql = "SELECT SUM(unallocated_amount) as unallocated_amount, party_id FROM payments WHERE company_id = '".$get['company_id']."' AND payment_date <= '".$edate."' AND transaction_type = '".$party_table."' ".$invoicecondition." AND is_active =0 GROUP BY transaction_type,party_id";
			$paymentsres=$callConfig->getAllRows($paymentssql);
			$payments =  array();
			foreach($paymentsres as $ri){
				$payments[$ri->party_id]= $ri;
			}
			$return['payments'] = $payments;

			$credit_notessql = "SELECT SUM(total_amount) as total_amount, party_id FROM credit_notes WHERE company_id = '".$get['company_id']."' AND ref_type = '".$transaction_table."' AND transaction_date >= '".$edate."' ".$invoicecondition." AND is_active =0 GROUP BY transaction_date,party_id";
			$credit_notesres=$callConfig->getAllRows($credit_notessql);
			$credit_notes =  array();
			foreach($credit_notesres as $ri){
				$credit_notes[$ri->party_id]= $ri;
			}
			$return['credit_notes'] = $credit_notes;

			$debit_notessql = "SELECT SUM(total_amount) as total_amount, party_id FROM debit_notes WHERE company_id = '".$get['company_id']."' AND ref_type = '".$transaction_table."' AND transaction_date >= '".$edate."' ".$invoicecondition." AND is_active =0 GROUP BY transaction_date,party_id";
			$debit_notesres=$callConfig->getAllRows($debit_notessql);
			$debit_notes =  array();
			foreach($debit_notesres as $ri){
				$debit_notes[$ri->party_id]= $ri;
			}
			$return['debit_notes'] = $debit_notes;
		}elseif($get['reporttype'] == "INVOICESUM"){
			$startmothyear = date("Y-m-01",strtotime($get['start_month']));
			$endmothyear = date("Y-m-t",strtotime($get['end_month']));
			$invoicesql = "SELECT ri.party_id, ri.id, SUM(ri.amount) as amount, SUM(ri.tax_amount) as tax_amount, SUM(ri.total_amount) as total_amount, SUM(ri.pending_amount) as pending_amount, (SELECT SUM(dn.pending_amount) FROM debit_notes dn WHERE dn.company_id = ri.company_id  AND dn.ref_type = '".$transaction_table."' AND FIND_IN_SET(dn.ref_id, GROUP_CONCAT(ri.id)) AND dn.is_active = ri.is_active AND dn.current_status = '".ST_APPROVED."') as debit_total_amount, (SELECT SUM(cn.pending_amount) FROM credit_notes cn WHERE cn.company_id = ri.company_id  AND cn.ref_type = '".$transaction_table."' AND FIND_IN_SET(cn.ref_id, GROUP_CONCAT(ri.id)) AND cn.is_active = ri.is_active AND cn.current_status = '".ST_APPROVED."') as credit_total_amount FROM ".$transaction_table." ri WHERE ri.company_id = '".$get['company_id']."' AND ri.is_active = 0 AND ri.current_status = '".ST_APPROVED."' AND ri.transaction_date >= '".$startmothyear."' AND ri.transaction_date <=  '".$endmothyear."' ".$invoice_condition." GROUP BY ri.party_id";
			$invoices=$callConfig->getAllRows($invoicesql);
			$return['invoicesql'] = $invoicesql;
			$return['invoices'] = $invoices;	


		}elseif($get['reporttype'] == "INVOICEREPORT"){
			$startmothyear = date("Y-m-01",strtotime($get['start_month']));
			$endmothyear = date("Y-m-t",strtotime($get['end_month']));
			$invoicesql = "SELECT ri.id, ri.party_id, ri.transaction_number, ri.transaction_date, ri.due_date,  ri.amount as amount, ri.tax_amount as tax_amount, ri.total_amount as total_amount, ri.pending_amount as pending_amount, (SELECT SUM(dn.pending_amount) FROM debit_notes dn WHERE dn.company_id = ri.company_id  AND dn.ref_type = '".$transaction_table."' AND dn.ref_id =ri.id AND dn.is_active = ri.is_active AND dn.current_status = '".ST_APPROVED."') as debit_total_amount, (SELECT SUM(cn.pending_amount) FROM credit_notes cn WHERE cn.company_id = ri.company_id  AND cn.ref_type = '".$transaction_table."' AND cn.ref_id = ri.id AND cn.is_active = ri.is_active AND cn.current_status = '".ST_APPROVED."') as credit_total_amount FROM ".$transaction_table." ri WHERE ri.company_id = '".$get['company_id']."' AND ri.is_active = 0 AND ri.current_status = '".ST_APPROVED."' AND ri.transaction_date >= '".$startmothyear."' AND ri.transaction_date <=  '".$endmothyear."' ".$invoice_condition;
			$rires =$callConfig->getAllRows($invoicesql);
			$invoices = array();
			foreach($rires as $ri){
				$invoices[$ri->party_id][] = $ri;
			}
			$return['invoicesql'] = $invoicesql;
			$return['invoices'] = $invoices;	
		}

		return $return;
	}
