	function getEMPBanks($get){
		global $callConfig;
		
		$bankssql = "SELECT id,bank_name FROM banks WHERE company_id='".$get['company_id']."' AND is_active='0'"; 
		$banksres = $callConfig->getAllRows($bankssql);
		foreach($banksres as $bnk){
			$banks[$bnk->id] = $bnk;
		}
		$return['banks'] = $banks;	
		$rid = $get['rid'];
		$emp_bankssql = "SELECT * FROM emp_banks WHERE company_id='".$get['company_id']."' AND id=".$rid." AND is_active='0'"; 
		$emp_banksres = $callConfig->getRow($emp_bankssql);
		$return['emp_banks'] = $emp_banksres;
		$return['emp_bankssql'] = $emp_bankssql;
	return $return;
	}
