	function toupdateEMPBanks($get){
		global $callConfig;

		$emp_bankssql = "SELECT id,emp_id,bank_id,ifsc_code,bank_account_no FROM emp_banks WHERE company_id='".$get['company_id']."' AND id=".$get['transaction_no']." AND is_active='0'"; 
		$emp_banksres = $callConfig->getRow($emp_bankssql);

		if($emp_banksres->emp_id !=""){
			$callConfig->updateRecord('emp_banks',array("activation_status"=>"N"),'emp_id',$emp_banksres->emp_id);
			
			$updatemepbank = array("activation_status"=>"Y","activation_date"=>date('Y-m-d'),"updated_date"=>date('Y-m-d H:i:s'),"updated_by"=>$get['user_id']);		
			$callConfig->updateRecord('emp_banks',$updatemepbank,'id',$emp_banksres->id);


			$updateempary = array("bank_id"=>$emp_banksres->bank_id,"bank_link"=>$emp_banksres->ifsc_code,"bank_account_no"=>$emp_banksres->bank_account_no,"updated_date"=>date('Y-m-d H:i:s'),"updated_by"=>$get['user_id']);
			$res = $callConfig->updateRecord('employees',$updateempary,'id',$emp_banksres->emp_id);
		
		}
		return $res;
	}
	function userPasswordReset($get){
		global $callConfig;
		$sql = "SELECT id,user_email FROM application_users WHERE company_id = '".$get['company_id']."' AND id = '".$get['resetpass_user_id']."' AND is_active = 0";
		$application_users=$callConfig->getRow($sql);
		if($application_users->id !=""){
			$this->forgotpassword($application_users->user_email);
			return array('result'=>'Y');
		}else{
			return array('result'=>'N');
		}
	}
	function getPurchaseInviceandSupplireInvoiceDashboard($get){
		global $callConfig;
		if($get['admin_type']!='1'){
			$condition = " AND originator = '".$get['user_id']."'";
		}
		$invsql = "SELECT 
		(SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||',IFNULL(SUM(pending_amount),'0')) FROM purchase_invoices WHERE company_id = '".$get['company_id']."' AND cancel_invoice = 'N' AND current_status ='".ST_APPROVED."' ".$condition." AND is_active = 0) as purchase_invoices,(SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0')) FROM requisitions WHERE company_id = '".$get['company_id']."' AND current_status ='".ST_APPROVED."' ".$condition." AND is_active = 0) as requisitions, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0')) FROM quotations WHERE company_id = '".$get['company_id']."' AND current_status ='".ST_APPROVED."' ".$condition." AND is_active = 0) as quotations, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0'),'||',IFNULL(SUM(pending_amount),'0')) FROM sales_invoices WHERE company_id = '".$get['company_id']."' AND cancel_invoice = 'N' AND current_status ='".ST_APPROVED."' ".$condition." AND is_active = 0) as sales_invoices,(SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0')) FROM enquiries WHERE company_id = '".$get['company_id']."' AND current_status ='".ST_APPROVED."' ".$condition." AND is_active = 0) as enquiries, (SELECT CONCAT(IFNULL(count(id),'0'),'||',IFNULL(SUM(total_amount),'0')) FROM estimates WHERE company_id = '".$get['company_id']."' AND current_status ='".ST_APPROVED."' ".$condition." AND is_active = 0) as estimates";
		$invres = $callConfig->getRow($invsql);
		$return['invoice_detail_sql'] = $invsql;
		$return['invoice_detail'] = $invres;


		$spend_by_vendor_category_sql = "SELECT ic.id, ic.category_description,  SUM(pii.total_amount) as total_amount FROM item_categories ic, items itm, pi_items pii WHERE ic.company_id = '".$get['company_id']."' AND ic.company_id = itm.company_id AND ic.company_id = pii.company_id AND ic.id = itm.category_id AND itm.id = pii.item_id AND ic.is_active = itm.is_active AND ic.is_active = pii.is_active AND ic.is_active =0 GROUP BY  ic.id, ic.category_description";
		$spend_by_vendor_category_res = $callConfig->getAllRows($spend_by_vendor_category_sql);
		$return['spend_by_vendor_category'] = $spend_by_vendor_category_res;

		$spend_by_customer_category_sql = "SELECT ic.id, ic.category_description,  SUM(pii.total_amount) as total_amount FROM item_categories ic, items itm, si_items pii WHERE ic.company_id = '".$get['company_id']."' AND ic.company_id = itm.company_id AND ic.company_id = pii.company_id AND ic.id = itm.category_id AND itm.id = pii.item_id AND ic.is_active = itm.is_active AND ic.is_active = pii.is_active AND ic.is_active =0 GROUP BY  ic.id, ic.category_description";
		$spend_by_customer_category_res = $callConfig->getAllRows($spend_by_customer_category_sql);
		$return['spend_by_customer_category'] = $spend_by_customer_category_res;


		$spend_by_vendors_sql = "SELECT pi.party_id, (SELECT ven.company FROM vendors ven WHERE ven.company_id = pi.company_id AND ven.id = pi.party_id AND ven.is_active = pi.is_active) as vendor_company, COUNT(pi.id) as total_invoice_cnt, SUM(pii.total_amount) as total_amount, SUM(pii.total_amount) as total_amount, SUM(pii.item_quantity) as item_quantity FROM purchase_invoices pi, pi_items pii WHERE pi.company_id = '".$get['company_id']."' AND pi.company_id = pii.company_id AND pi.id = pii.transaction_id AND pi.is_active = pii.is_active AND pi.is_active = 0 GROUP BY pi.party_id ORDER BY pii.total_amount DESC limit 5";
		$spend_by_vendors_res = $callConfig->getAllRows($spend_by_vendors_sql);
		$return['spend_by_vendors'] = $spend_by_vendors_res;

		$spend_by_customers_sql = "SELECT si.party_id, (SELECT cust.company FROM customers cust WHERE cust.company_id = si.company_id AND cust.id = si.party_id AND cust.is_active = si.is_active) as customer_company, COUNT(si.id) as total_invoice_cnt, SUM(sii.total_amount) as total_amount, SUM(sii.total_amount) as total_amount, SUM(sii.item_quantity) as item_quantity FROM sales_invoices si, si_items sii WHERE si.company_id = '".$get['company_id']."' AND si.company_id = sii.company_id AND si.id = sii.transaction_id AND si.is_active = sii.is_active AND si.is_active = 0 GROUP BY si.party_id ORDER BY sii.total_amount DESC limit 5";
		$spend_by_customers_res = $callConfig->getAllRows($spend_by_customers_sql);
		$return['spend_by_customers'] = $spend_by_customers_res;


		return $return;
	}
	function getVendorCustomerItems($get){
		global $callConfig;
		$return = array();
		$return['get'] = $get;
		$transaction_table = $get['transaction_table'];
		$transaction_id = $get['transaction_id'];
		if($transaction_table == "vendors"){
			$party_table = "vendor_items";
			$whercondition = " AND vendor_id=".$transaction_id;
			$selectcond = "id, item_id,vendor_id, vendor_part_no, vendor_part_name";
		
		}elseif($transaction_table == "customers"){
			$party_table = "customer_items";
			$whercondition = " AND customer_id=".$transaction_id;
			$selectcond = "id, item_id,customer_id as vendor_id, customer_part_no as vendor_part_no, customer_part_name as vendor_part_name";
		}

		$item_categoriessql = "SELECT id, category_description FROM item_categories WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$item_categoriesres=$callConfig->getAllRows($item_categoriessql);
		foreach($item_categoriesres as $ic){
			$item_categories[$ic->id] = $ic;
		}
		$return['item_categories'] = $item_categories;

		$itemssql = "SELECT id, sku, item_name, item_image, category_id FROM items WHERE company_id = '".$get['company_id']."' AND is_active = 0";
		$itemsres=$callConfig->getAllRows($itemssql);
		foreach($itemsres as $ic){
			$all_items[$ic->id] = $ic;
		}
		$return['all_items'] = $all_items;
		

		if($get['item_id'] !=""){
			$itemssql = "SELECT id, sku, item_name, item_image, category_id FROM items WHERE company_id='".$get['company_id']."' AND id=".$get['item_id']." AND is_active='0'"; 
			$itemsres = $callConfig->getRow($itemssql);
			$return['items'] = $itemsres;

			$partyitemsql = "SELECT ".$selectcond." FROM ".$party_table." WHERE company_id='".$get['company_id']."' AND item_id=".$get['item_id']." ".$whercondition." AND is_active='0'"; 
			$partyitemres = $callConfig->getRow($partyitemsql);
			$return['party_table_detail_sql'] = $partyitemsql;
			$return['party_table_detail'] = $partyitemres;	
		}else{
			$partyitemsql = "SELECT ".$selectcond." FROM ".$party_table." WHERE company_id='".$get['company_id']."' ".$whercondition." AND is_active='0'"; 
			$partyitemres = $callConfig->getAllRows($partyitemsql);
			$return['all_party_table_detail'] = $partyitemres;	

		}
		
		return $return;
	

	}
	function insertVendorCustomerItems($post){
		global $callConfig;
		$return = array();
		$transaction_table = $post['transaction_table'];
		if($post['type'] == "REMOVE"){
			if($transaction_table == "vendors"){
				$updaterow = array('is_active'=>null);
				$res = $callConfig->updateRecord('vendor_items',$updaterow,'id',$post['party_item_id']);
				$return['result'] = $res; 
			}elseif($transaction_table == "customers"){
				$updaterow = array('is_active'=>null);
				$res = $callConfig->updateRecord('customer_items',$updaterow,'id',$post['party_item_id']);
				$return['result'] = $res; 
					
			}
		}else{
			$postdata = array('company_id'=>$post['company_id'],'item_id'=>$post['item_id'],'is_active'=>'0');
			if($transaction_table == "vendors"){
				$insert_table = "vendor_items";
				$postdata['vendor_id'] = $post['transaction_id'];
				$postdata['vendor_part_no'] = $post['sku'];
				$postdata['vendor_part_name'] = $post['item_name'];
				$partyitemsql = "SELECT * FROM vendor_items WHERE company_id='".$post['company_id']."' AND item_id=".$post['item_id']." AND vendor_id=".$transaction_id; 
				$partyitemres = $callConfig->getRow($partyitemsql);
			}elseif($transaction_table == "customers"){
				$insert_table = "customer_items";
				$postdata['customer_id'] = $post['transaction_id'];
				$postdata['customer_part_no'] = $post['sku'];
				$postdata['customer_part_name'] = $post['item_name'];
				$partyitemsql = "SELECT * FROM customer_items WHERE company_id='".$post['company_id']."' AND item_id=".$post['item_id']." AND customer_id=".$transaction_id; 
				$partyitemres = $callConfig->getRow($partyitemsql);
			
			}
			if($post['Rid']!="" OR $partyitemres->id !=""){
				$rid = $post['Rid']!=""?$post['Rid']:$partyitemres->id;	
				$postdata['updated_date'] = date('Y-m-d H:i:s');
				$postdata['updated_by'] = $post['user_id'];
				$res=$callConfig->updateRecord($insert_table,$postdata,'id',$rid);
			}else{
				$postdata['current_status'] = '0';
				$postdata['created_date'] = date('Y-m-d H:i:s');
				$postdata['created_by'] = $post['user_id'];
				$res=$callConfig->insertRecord($insert_table,$postdata);
			}
			$return['result'] = $res; 
		}
		return $return;
	}
	function updateTransactionTDS($get){
		global $callConfig; 
		$transaction_table = $get['transaction_table'];
		$transaction_no = $get['transaction_no'];
		$company_id = $get['company_id'];
		$vendortable = array('purchase_orders','supplier_bills','purchase_invoices');
		$customertable = array('sales_invoices');
		$total_tds = 0;

		$sql = "SELECT * FROM ".$transaction_table." WHERE company_id = '".$company_id."' AND  id = '".$transaction_no."' AND is_active = 0";
		$partyinvoice = $callConfig->getRow($sql);
		$tds_details = array(); 
	// TDS PArt Updatetions
		if(in_array($transaction_table, (array)$vendortable)){
			$party_transaction_table = "vendors"; 
			$partyinvoiceitem_total = 0;
			if($partyinvoice->party_id !=""){
				$pasrtysql = "SELECT * FROM vendors WHERE company_id = '".$company_id."' AND  id = '".$partyinvoice->party_id."' AND is_active = 0";
				$party_detail = $callConfig->getRow($pasrtysql);
			}	
			if($partyinvoice->transaction_date !=""){
				$taxdetailsql = "SELECT * FROM tax_deducted_sources WHERE company_id = '".$company_id."' AND financial_year_start <= '".$partyinvoice->transaction_date."' AND financial_year_end >= '".$partyinvoice->transaction_date."' AND is_active = 0";
				$taxdetailres = $callConfig->getAllRows($taxdetailsql);
				foreach($taxdetailres as $tx){
					$tds_details[$tx->id] = $tx; 
				}
			}
			$mappingtabsql = "SELECT id,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$company_id."' AND application_table_name = '".$transaction_table."' AND item_table !='' AND is_active = 0";
			$mappingtabres=$callConfig->getRow($mappingtabsql);
			if($mappingtabres->item_table !="" AND $partyinvoice->party_id !=""){	
				$sbsql = "SELECT SUM(item_amount) as total_payments FROM ".$transaction_table." sb, ".$mappingtabres->item_table." sbi WHERE sb.company_id ='".$company_id."' AND sb.company_id = sbi.company_id  AND sb.id = sbi.transaction_id AND sb.party_id = '".$partyinvoice->party_id."' AND sb.is_active = sbi.is_active AND sb.current_status = '".ST_APPROVED."' AND sb.is_active = 0 ";
				$sbres=$callConfig->getRow($sbsql);
				if($sbres->total_payments !="" AND isset($sbres->total_payments)){
					$total_payments = $sbres->total_payments+$partyinvoiceitem_total;
				}
			} 
			if($mappingtabres->item_table !="" AND $partyinvoice->id !=""){
				$partyinvoiceitemsql = "SELECT iv.*, it.item_name, it.category_id, ic.category_description, ic.tax_deducted_source_id, ic.tax_collected_source_id FROM ".$mappingtabres->item_table." iv, items it ,item_categories ic WHERE iv.company_id = '".$company_id."' AND iv.company_id = it.company_id AND iv.company_id = ic.company_id AND iv.item_id = it.id AND it.category_id = ic.id AND iv.transaction_id = '".$partyinvoice->id."' AND iv.is_active = it.is_active AND iv.is_active = ic.is_active AND iv.is_active = 0";
				$partyinvoiceitemres=$callConfig->getAllRows($partyinvoiceitemsql);
				
				$partinvoiceitemid = array();
				foreach($partyinvoiceitemres as $itemres){
					$partinvoiceitemid[$itemres->item_id] = $itemres->item_id;
					$partyinvoiceitem_total += $itemres->item_amount;
				} 
				$partinvoiceitemids = implode(',', (array)$partinvoiceitemid);
				$total_tds = 0; 
				foreach($partyinvoiceitemres as $itemres){
					if(isset($tds_details[$itemres->tax_deducted_source_id])){
						$applaytds = $tds_details[$itemres->tax_deducted_source_id];
						if($party_detail->tds_type == "I"){
							$applay_percentage = $applaytds->individual_percentage;
						}elseif($party_detail->tds_type == "H"){
							$applay_percentage = $applaytds->huf_percentage;
						}elseif($party_detail->tds_type == "O"){
							$applay_percentage = $applaytds->other_percentage;
						}
						$vendoritem_amount = $total_payments;
						$tds_threshold = $applaytds->threshold;  
						if($tds_threshold <= $vendoritem_amount AND $tds_threshold !="" AND $vendoritem_amount !=""){
								$tdsitempayment = ($itemres->item_amount*$applay_percentage)/100; 
								$total_tds += $tdsitempayment; 
								$updatedata['tds_amount'] = $tdsitempayment;
								$updatedata['tax_deducted_source_id'] = $applaytds->id;
								$updatedata['updated_date'] = date('Y-m-d H:i:s');
								$updatedata['updated_by'] = $post['user_id'];
								$res=$callConfig->updateRecord($mappingtabres->item_table,$updatedata,'id',$itemres->id);
								$insertapplicationtdstcs = array('company_id'=>$company_id,'transaction_table'=>$transaction_table,'transaction_id'=>$transaction_no,'transaction_number'=>$partyinvoice->transaction_number,'party_transaction_table'=>$party_transaction_table,'party_id'=>$partyinvoice->party_id,'transaction_item_table'=>$mappingtabres->item_table,'transaction_item_table_id'=>$itemres->id,'item_id'=>$itemres->item_id,'item_amount'=>$itemres->item_amount,'tax_amount'=>$itemres->tax_amount,'total_amount'=>$itemres->total_amount,'tds_tcs_id'=>$applaytds->id,'tds_tcs_amount'=>$tdsitempayment,'tds_tcs_details'=>urlencode(json_encode((array)$applaytds)),'transaction_table_details'=>urlencode(json_encode((array)$partyinvoice)),'party_transaction_table_details'=>urlencode(json_encode((array)$party_detail)),'transaction_item_table_details'=>urlencode(json_encode((array)$itemres)),'is_active'=>0,'current_status'=>0,'created_date'=>date('Y-m-d H:i:s'),'created_by'=>$get['user_id']);
								$atdstcsres = $callConfig->insertRecord('application_tds_tcs_transactions',$insertapplicationtdstcs);
						}else{
							//not added tds
						}
					}
				}
			} 
			$mainupdate['total_tds_amount'] = $total_tds;
			$mainupdate['updated_date'] = date('Y-m-d H:i:s');
			$mainupdate['updated_by'] = $post['user_id'];
			$callConfig->updateRecord($transaction_table,$mainupdate,'id',$transaction_no);
			

	// TDS PArt Updatetions

		}elseif(in_array($transaction_table, $customertable)){
			
			$party_transaction_table = "customers";
			$pasrtysql = "SELECT * FROM customers WHERE company_id = '".$company_id."' AND  id = '".$partyinvoice->party_id."' AND is_active = 0";
			$party_detail = $callConfig->getRow($pasrtysql);

			$partyinvoiceitemsql = "SELECT iv.*, it.item_name, it.category_id, ic.category_description, ic.tax_deducted_source_id, ic.tax_collected_source_id FROM si_items iv, items it ,item_categories ic WHERE iv.company_id = '".$company_id."' AND iv.company_id = it.company_id AND iv.company_id = ic.company_id AND iv.item_id = it.id AND it.category_id = ic.id AND iv.transaction_id = '".$partyinvoice->id."' AND iv.is_active = it.is_active AND iv.is_active = ic.is_active AND iv.is_active = 0";
			$partyinvoiceitemres=$callConfig->getAllRows($partyinvoiceitemsql);
			foreach($partyinvoiceitemres as $itemres){
				if($itemres->tax_collected_source_id !="" AND $itemres->tax_collected_source_id !="0"){
					$tdsitempayment = $itemres->tds_amount;
					$total_tds += $itemres->tds_amount; 
					$insertapplicationtdstcs = array('company_id'=>$company_id,'transaction_table'=>$transaction_table,'transaction_id'=>$transaction_no,'transaction_number'=>$partyinvoice->transaction_number,'party_transaction_table'=>$party_transaction_table,'party_id'=>$partyinvoice->party_id,'transaction_item_table'=>'si_items','transaction_item_table_id'=>$itemres->id,'item_id'=>$itemres->item_id,'item_amount'=>$itemres->item_amount,'tax_amount'=>$itemres->tax_amount,'total_amount'=>$itemres->total_amount,'tds_tcs_id'=>$itemres->tax_collected_source_id,'tds_tcs_amount'=>$tdsitempayment,'tds_tcs_details'=>urlencode(json_encode((array)$itemres)),'transaction_table_details'=>urlencode(json_encode((array)$partyinvoice)),'party_transaction_table_details'=>urlencode(json_encode((array)$party_detail)),'transaction_item_table_details'=>urlencode(json_encode((array)$itemres)),'is_active'=>0,'current_status'=>0,'created_date'=>date('Y-m-d H:i:s'),'created_by'=>$get['user_id']);
					$atdstcsres = $callConfig->insertRecord('application_tds_tcs_transactions',$insertapplicationtdstcs);
				}
					
			}
		}
		$payment_term_history = json_decode($partyinvoice->payment_term_history,1);
		if(count((array)$payment_term_history) != "0"){
			$pth_cnt = count((array)$payment_term_history);
			$mk = 1;
			foreach($payment_term_history as $key=>$pterh){ 
				if($pth_cnt == $key AND in_array($transaction_table, $customertable)){
					$pterh['amount']  = $pterh['amount']+$total_tds;
				}
				$insertdata = array('company_id'=>$company_id,'transaction_table'=>$transaction_table,'transaction_id'=>$transaction_no,'transaction_number'=>$partyinvoice->transaction_number,'party_id'=>$partyinvoice->party_id,'due_date'=>$this->dateconvertdbformat($pterh['due_date']),'due_amount'=>$pterh['amount'],'advance_offer_date'=>$this->dateconvertdbformat($pterh['extra_date']),'advance_offer_amount'=>$pterh['extra_amt'],'pending_amount'=>$pterh['amount'],'is_active'=>'0','current_status'=>'0','created_date'=>date('Y-m-d H:i:s'),'created_by'=>$get['user_id'],'amount'=>$pterh['without_tax_amount'],'tax_amount'=>$pterh['tax_amount'],'percentage'=>$pterh['percentage'],'without_tax_pending_amount'=>$pterh['without_tax_amount'],'tax_pending_amount'=>$pterh['tax_amount']);
				$callConfig->insertRecord('payment_term_transactions',$insertdata);
				$mk++;
			}	
		}


