	function togetnewwithoutworkindays($from, $to){
		global $callConfig;
		$attstc = "SELECT * FROM attendance_settings WHERE company_id= 1 AND is_active=0";
		$atsdata = $callConfig->getRow($attstc);
		$workingdays = $atsdata->working_days;
		//print_r($workingdays); exit;
		$working_days = json_decode($workingdays,1);
		$datediff = strtotime($to) - strtotime($from);
		$datediff = floor($datediff/(60*60*24));
		$resday = 0;
		for($i = 0; $i < $datediff + 1; $i++){
			$valda =  date("Y-m-d", strtotime($from . ' + ' . $i . 'day'));
			$valday = ucwords(date("l", strtotime($from . ' + ' . $i . 'day')));
			if(in_array($valday, (array)$working_days)){
				$resday = $resday+1;
			}
		}
		//echo "ooooo".$resday;
		return $resday;
	}
	function updateTransactionTCS($transaction_table,$transaction_no,$get){
		global $callConfig; 
		$return = array();
		$company_id = $get['company_id'];
		$sql = "SELECT * FROM ".$transaction_table." WHERE company_id = '".$company_id."' AND  id = '".$transaction_no."' AND is_active = 0";
		$partyinvoice = $callConfig->getRow($sql);
		$total_tds = 0;
		$party_transaction_table = "customers";
		$pasrtysql = "SELECT * FROM ".$party_transaction_table." WHERE company_id = '".$company_id."' AND  id = '".$partyinvoice->party_id."' AND is_active = 0";
		$party_detail = $callConfig->getRow($pasrtysql);
		
		$taxdetailsql = "SELECT * FROM tax_collected_sources WHERE company_id = '".$company_id."' AND is_active = 0";
		$taxdetailres = $callConfig->getAllRows($taxdetailsql);
		foreach($taxdetailres as $tx){
			$tds_details[$tx->id] = $tx; 
		}
		$mappingtabsql = "SELECT id,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$company_id."' AND application_table_name = '".$transaction_table."' AND item_table !='' AND is_active = 0";
		$mappingtabres=$callConfig->getRow($mappingtabsql);
		$partyinvoiceitemsql = "SELECT iv.*, it.item_name, it.category_id, ic.category_description, ic.tax_deducted_source_id, ic.tax_collected_source_id FROM ".$mappingtabres->item_table." iv, items it ,item_categories ic WHERE iv.company_id = '".$company_id."' AND iv.company_id = it.company_id AND iv.company_id = ic.company_id AND iv.item_id = it.id AND it.category_id = ic.id AND iv.transaction_id = '".$partyinvoice->id."' AND iv.is_active = it.is_active AND iv.is_active = ic.is_active AND iv.is_active = 0";
		$partyinvoiceitemres=$callConfig->getAllRows($partyinvoiceitemsql);
		foreach($partyinvoiceitemres as $itemres){
			$applaytds = $tds_details[$itemres->tax_collected_source_id];
			$applay_percentage = 0;	
			if($applaytds->id !=""){
				$applay_percentage = $applaytds->percentage;
				$tdsitempayment = ($itemres->item_amount*$applay_percentage)/100; 
				$total_tds += $tdsitempayment; 
				$updatedata['tds_amount'] = $tdsitempayment;
				$updatedata['tax_deducted_source_id'] = $applaytds->id;
				$updatedata['updated_date'] = date('Y-m-d H:i:s');
				$updatedata['updated_by'] = $get['user_id'];
				$return['childupdate'][] = $updatedata;
				$res=$callConfig->updateRecord('si_items',$updatedata,'id',$itemres->id);
				$return['childupdate_res'][] = $res;
			}
		}
		$mainupdate['total_amount'] = $partyinvoice->total_amount+$total_tds;
		$mainupdate['pending_amount'] = $partyinvoice->pending_amount+$total_tds;
		$mainupdate['total_tds_amount'] = $total_tds;
		$mainupdate['updated_date'] = date('Y-m-d H:i:s');
		

		$return['payment_term_history11'] = $partyinvoice->payment_term_history;
		$payment_term_history = json_decode($partyinvoice->payment_term_history,1);
		$payment_term_history11 = array();
		if(count((array)$payment_term_history) != "0"){
			$pth_cnt = count((array)$payment_term_history);
			$return['pth_cnt'] =$pth_cnt;
			foreach($payment_term_history as $kk=>$pterh){ 
				if($pth_cnt == $kk){
					$pterh['amount'] = $pterh['amount']+$total_tds;
				}
				$payment_term_history11[$kk] = $pterh;
			}	
		}
		$mainupdate['payment_term_history'] = json_encode($payment_term_history11);
		$callConfig->updateRecord($transaction_table,$mainupdate,'id',$transaction_no);
		$return['mainupdate'] = $mainupdate;
		//echo "<pre>"; print_r($return);
		return $return;
	}
