	function generateOTP($length = 4) {
	    $otp = '';
	    for ($i = 0; $i < $length; $i++) {
	        $otp .= mt_rand(1, 9); // Generate a random number between 0 and 9 and append it to the OTP string
	    }
	    if(strlen($otp)!=$length){
	    	$otp = $this->generateOTP($length);
	    }
	    return $otp;
	}
