	function recallgetSLSTrackingLogReports($get){
		global $callConfig;
		static $transaction_result = [];
		$transaction_table = $get['transaction_table'];
		$transaction_id = $get['transaction_id'];
		//$transaction_result['all_transaction_tables'][$transaction_table] = $transaction_table;
		$transaction_sql = "SELECT id, transaction_number, transaction_date, originator, party_id, party_name, ref_type, ref_id, ref_no, ref_date FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' AND id ='".$transaction_id."' AND is_active = 0";
		//echo "transaction_sql - ".$transaction_sql."</br>";
		$transaction_res=$callConfig->getRow($transaction_sql);
		if(isset($transaction_res->id)){
			$sla_tracking_logs = array();
			$slalogsql = "SELECT transaction_id, originator, request_datetime, remarks, sla_type, previous_status, response_status FROM sla_tracking_logs WHERE company_id =".$get['company_id']." AND transaction_id = '".$transaction_id."' AND transaction_table = '".$transaction_table."' AND is_active =0 ORDER BY `request_datetime` ASC";
			$slalogres = $callConfig->getAllRows($slalogsql);
			foreach($slalogres as $slalg){
				$sla_tracking_logs[$slalg->originator][] = $slalg;
			}
			$transaction_res->sla_tracking_logs = $sla_tracking_logs;
			$transaction_result[$transaction_table][] = $transaction_res;		
			// if($transaction_table == "sales_invoices" AND $transaction_res->ref_no !=""){
			// 	$get['transaction_table'] =  'delivery_orders';
			// 	$get['transaction_id'] =  $transaction_res->ref_no;
			// 	$this->recallgetSLSTrackingLogReports($get);
			// }else

			if($transaction_res->ref_type !="" and $transaction_res->ref_id !=""){
				$get['transaction_table'] =  $transaction_res->ref_type;
				$get['transaction_id'] =  $transaction_res->ref_id;
				$this->recallgetSLSTrackingLogReports($get);
			}
			// if($transaction_res->ref_type !="" and $transaction_res->ref_id !=""){
			// 	$get['transaction_table'] =  $transaction_res->ref_type;
			// 	$get['transaction_id'] =  $transaction_res->ref_id;
			// 	$this->recallgetSLSTrackingLogReports($get);
			// }
		}
		return $transaction_result;
	}

	function toritivedatabasevalue($get,$table, $ids){
		global $callConfig;
		$frist_array = json_decode(base64_decode($get['transation_table_list']),1);
		foreach($frist_array[$table] as $secnd){
			$transaction_sql = "SELECT id, transaction_number, transaction_date, originator, party_id, party_name, ref_type,ref_id, ref_no, ref_date FROM ".$secnd." WHERE company_id = '".$get['company_id']."' AND ref_type ='".$table."' AND ref_id IN(".implode(',',$ids).")  AND is_active = 0 order BY transaction_date DESC";
			$tr_transaction_res=$callConfig->getAllRows($transaction_sql);

			$sla_tracking_logs = array();
			$slalogsql = "SELECT transaction_id, originator, request_datetime, remarks, sla_type, previous_status, response_status FROM sla_tracking_logs WHERE company_id =".$get['company_id']." AND transaction_table = '".$secnd."' AND is_active =0 ORDER BY `request_datetime` ASC";
			$slalogres = $callConfig->getAllRows($slalogsql);
			foreach($slalogres as $slalg){
				$sla_tracking_logs[$slalg->transaction_id][] = $slalg;
			}

			if(count($tr_transaction_res)>0){
				foreach($tr_transaction_res as $tr_res){
					$send_id = array();
					$tr_res->sla_tracking_logs = $sla_tracking_logs[$tr_res->id];
					$return[$secnd][$tr_res->id] = $tr_res;
					$send_id[] =$tr_res->id;
					$return[$secnd][$tr_res->id]->child = $this->toritivedatabasevalue($get,$secnd,$send_id);				
				}
				//$return[$secnd]['child'] = $this->toritivedatabasevalue($get,$secnd,$send_id);
			}
		}
		return $return;
	}

	function getSLSTrackingLogReports($get){
		global $callConfig;
		$return['get'] = $get;	
		$return['selected_transaction_table'] = $get['transaction_table'];

		if($get['ajaxcll'] == "Y"){
			
			$frist_array = json_decode(base64_decode($get['transation_table_list']),1);
			foreach($frist_array as $frist_key =>$frist){
				$transaction_sql = "SELECT id, transaction_number, transaction_date, originator, party_id, party_name, ref_type, ref_id, ref_no, ref_date FROM ".$frist_key." WHERE company_id = '".$get['company_id']."' AND ref_type IS NULL AND ref_id  IS NULL  AND is_active = 0 order BY transaction_date DESC";
				$frist_transaction_res=$callConfig->getAllRows($transaction_sql);

				$sla_tracking_logs = array();
				$slalogsql = "SELECT transaction_id, originator, request_datetime, remarks, sla_type, previous_status, response_status FROM sla_tracking_logs WHERE company_id =".$get['company_id']." AND transaction_table = '".$frist_key."' AND is_active =0 ORDER BY `request_datetime` ASC";
				$slalogres = $callConfig->getAllRows($slalogsql);
				foreach($slalogres as $slalg){
					$sla_tracking_logs[$slalg->transaction_id][] = $slalg;
				}

				$transaction_details[$frist_key] = array();
				if(count($frist_transaction_res)>0){
					foreach($frist_transaction_res as $frist_data){
						$send_id = array();
						$frist_data->sla_tracking_logs = $sla_tracking_logs[$frist_data->id];
						$transaction_details[$frist_key][$frist_data->id] = $frist_data;
						$send_id[] = $frist_data->id;
						//$return[$frist_key][$frist_data->id]->child = "scsdcsd";
						
						$transaction_details[$frist_key][$frist_data->id]->child = $this->toritivedatabasevalue($get,$frist_key,$send_id);
					}
				}
			}
			$return['transaction_details'] = $transaction_details;
			$transaction_table = $get['transaction_table'];
		}else{
			$dynamic_mapping_tablessql = "SELECT id, page_title, application_table_name,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$get['company_id']."' AND is_active = 0 AND item_table !='' AND tax_table!=''";
			$dynamic_mapping_tablesres=$callConfig->getAllRows($dynamic_mapping_tablessql);
			$return['dynamic_mapping_tablessql'] = $dynamic_mapping_tablessql;	
			$return['dynamic_mapping_tables'] = $dynamic_mapping_tablesres;	

			$ausql = "SELECT id, display_name FROM application_users WHERE company_id = '".$get['company_id']."' AND is_active = 0";
			$aures=$callConfig->getAllRows($ausql);
			foreach($aures as $aures1){
				$application_users[$aures1->id] = $aures1;
			}
			$return['application_users'] = $application_users;
		}
		return $return;
	}
	function getItemSearch($get){
		global $callConfig;
		$return['get'] = $get;
		if($get['usertype'] != "U"){
			$itemssql = "SELECT * FROM items WHERE  company_id = '".$get['company_id']."' AND id = '".$get['item_id']."' AND is_active=0";
	        $itemsres = $callConfig->getRow($itemssql);
	        $return['items'] = $itemsres;
		}
		if($get['usertype'] == "U"){
	        $itemssql = "SELECT au.display_name FROM user_items ui, application_users au WHERE ui.company_id = '".$get['company_id']."' AND ui.company_id = au.company_id AND ui.item_id = '".$get['item_id']."' AND ui.user_id = au.id  AND ui.is_active = au.is_active AND ui.is_active=0";
	        $uiitemsres = $callConfig->getAllRows($itemssql);
	        $return['user_items'] = $uiitemsres;
	        $return['itemssql'] = $itemssql;

		}elseif($get['usertype'] == "V"){
			$itemssql = "SELECT vi.vendor_part_no, vi.vendor_part_name,  ven.company FROM vendor_items vi, vendors ven WHERE vi.company_id = '".$get['company_id']."' AND vi.company_id = ven.company_id AND vi.item_id = '".$get['item_id']."' AND vi.vendor_id = ven.id  AND vi.is_active = ven.is_active AND vi.is_active=0";
	        $uiitemsres = $callConfig->getAllRows($itemssql);
	        $return['vendor_items'] = $uiitemsres;	
	         $return['itemssql'] = $itemssql;

		}elseif($get['usertype'] == "C"){
			$itemssql = "SELECT ci.customer_part_no, ci.customer_part_name,  cust.company FROM customer_items ci, customers cust WHERE ci.company_id = '".$get['company_id']."' AND ci.company_id = cust.company_id AND ci.item_id = '".$get['item_id']."' AND ci.customer_id = cust.id  AND ci.is_active = cust.is_active AND ci.is_active=0";
	        $uiitemsres = $callConfig->getAllRows($itemssql);
	        $return['customer_items'] = $uiitemsres;	
	         $return['itemssql'] = $itemssql;

		}else{
		
			if($get['submitsearchform'] == "Y"){
				$dynamiccondition = "";
				if($get['item_name_sku_code'] !=""){
					$dynamiccondition .= " AND (sku LIKE '%".$get['item_name_sku_code']."%' OR item_name LIKE '%".$get['item_name_sku_code']."%')"; 
				}
				if($get['item_type'] !=""){
					$dynamiccondition .= " AND item_type = '".$get['item_type']."'";
				}
				if($get['category_id'] !=""){
					$dynamiccondition .= " AND category_id = '".$get['category_id']."'";
				}
				if($get['location_id'] !=""){
					$dynamiccondition .= " AND id IN(SELECT item_id FROM item_locations il WHERE il.company_id = '".$get['company_id']."' AND il.location_id = '".$get['location_id']."' AND il.is_active = 0)";
				}
				if($get['warehouse_id'] !=""){
					$dynamiccondition .= " AND id IN(SELECT item_id FROM item_locations il WHERE il.company_id = '".$get['company_id']."' AND il.warehouse_id = '".$get['warehouse_id']."' AND il.is_active = 0)";
				}
				if($get['vendor_id'] !=""){
					$dynamiccondition .= " AND id IN(SELECT item_id FROM vendor_items il WHERE il.company_id = '".$get['company_id']."' AND il.vendor_id = '".$get['vendor_id']."' AND il.is_active = 0)";
				}
				if($get['customer_id'] !=""){
					$dynamiccondition .= " AND id IN(SELECT item_id FROM customer_items il WHERE il.company_id = '".$get['company_id']."' AND il.customer_id = '".$get['customer_id']."' AND il.is_active = 0)";
				}

				$itemssql = "SELECT * FROM items WHERE  company_id = '".$get['company_id']."' AND is_active=0".$dynamiccondition;
	        	$itemsres = $callConfig->getAllRows($itemssql);
	        	$return['items'] = $itemsres;
	        	$return['itemssql'] = $itemssql;
	     	}	   
			$itemtypes_sql = "SELECT id,item_type_name FROM item_types WHERE  company_id = '".$get['company_id']."' AND is_active=0";
	        $itemtypes_res = $callConfig->getAllRows($itemtypes_sql);
	        $return['item_types'] = $itemtypes_res;
	        
	        $category_sql = "SELECT id, category_description, parent_item_category_id  FROM  item_categories WHERE company_id = '".$get['company_id']."' AND is_active ='0'  ORDER BY category_description ASC";
	        $category_res = $callConfig->getAllRows($category_sql);
	        $return['item_categories'] = $category_res;
	  		
	  		$customers_sql = "SELECT id,display_name,company FROM  customers WHERE  company_id = '".$get['company_id']."' AND is_active ='0'  ORDER BY display_name ASC";
	        $customers_res = $callConfig->getAllRows($customers_sql);
	        $return['customers'] = $customers_res;

	        $vendors_sql = "SELECT id,display_name,company FROM vendors WHERE  company_id = '".$get['company_id']."' AND is_active ='0'  ORDER BY display_name ASC";
	        $vendors_res = $callConfig->getAllRows($vendors_sql);
	        $return['vendors'] = $vendors_res;
	 		
	 		$locationssql = "SELECT id, location_name FROM locations WHERE company_id = '".$get['company_id']."' AND is_active ='0'";
	        $locationssres = $callConfig->getAllRows($locationssql);
	        $return['locations'] = $locationssres;

	        $warehousessql = "SELECT id, location_id, warehouse_name FROM warehouses WHERE company_id = '".$get['company_id']."' AND is_active ='0'";
	        $warehousesres = $callConfig->getAllRows($warehousessql);
	        $return['warehouses'] = $warehousesres;
	    }
		return $return;
	}
	function insertImportExcelData($post){
		global $callConfig;
		$returnaray['post'] = $post;
		if($post['recordupdate'] == "N"){
			$importdata = $post['csvdata'];
			$header = $data = array();
			foreach($importdata[1] as $idata){
					$header[] = $idata;
			}
			unset($importdata[0]);
			unset($importdata[1]);
			foreach($importdata as $idata){
				if($idata[0] !=""){  //id possition
					$data[] = $idata;
				}
			}
			$returnaray['post'] = $post;
			$jsonheader  = json_encode($header);
			$jsondata  = json_encode($data);
			$insertuserarray1=array('company_id'=>$post['company_id'],'file_name'=>$post['file_name'],'header'=>$jsonheader,'data'=>$jsondata,'system_start_date'=>$this->dateconvertdbformat($post['system_start_date']),'is_active'=>'0','current_status'=>'0','created_by'=>$post['user_id'],'created_date'=>date("Y-m-d H:i:s"));
			$tapres = $callConfig->insertRecord('import_excel_data',$insertuserarray1);
			$returnaray['respons'] = $tapres;

		}elseif($post['recordupdate'] == "Y"){
			$itemssql = "SELECT * FROM import_excel_data WHERE company_id = '".$post['company_id']."' AND file_name ='".$post['FIN']."' AND is_active=0";
	    	$itemsres = $callConfig->getRow($itemssql);
	    	$returnaray['import_excel_data'] = $itemsres;
	    	$importdata  = json_decode($itemsres->data,1);
	    	$system_start_date =$this->dateconvertdbformat($itemsres->system_start_date);
	    	$items = array();
			$itemssql = "SELECT id, opening_quantity FROM items WHERE  company_id = '".$post['company_id']."' AND opening_quantity IS NOT NULL AND opening_quantity !='0' AND is_active=0";
		    $itemsres11 = $callConfig->getAllRows($itemssql);
		    $returnaray['itemsres11'] = $itemsres11;
		    foreach($itemsres11 as $ires){
		    	$items[$ires->id] = $ires->id;
		    }
	    	foreach($importdata as $idata){
				if($idata[0] !=""){  //id possition
					if($idata[5] !="" AND $idata[5] !="0"){
						if(!in_array($idata[0], (array)$items)){ // already update open qty
							$postupd['updated_date'] = date('Y-m-d H:i:s');
							$postupd['updated_by'] = $post['user_id'];
							$postupd['opening_quantity'] = $idata[5];
							//$postupd['sale_price'] = $idata[10];
							//$postupd['purchase_price'] = $idata[10];
							$postupd['opening_quantity_date'] = $system_start_date;
							$postupd['warehouse_id'] = 1;
							$returnaray['items_update_ary'][] = $postupd;
							$res=$callConfig->updateRecord('items',$postupd,'id',$idata[0]);
							$returnaray['items_update'][] = $res;
							$mainitem = $this->togetitemvalues($idata[0]);
