				}
			}
		}
		return $returnaray;
	}
	function getImportCxcelData($get){
		global $callConfig;
		if($get['LIST'] == "Y"){
			$itemssql = "SELECT * FROM import_excel_data WHERE company_id = '".$get['company_id']."' AND is_active=0";
		    $itemsres = $callConfig->getAllRows($itemssql);
		    $return['import_excel_data'] = $itemsres;
		    $return['import_excel_data_sql'] = $itemssql;
		}else{

			$itemssql = "SELECT * FROM items WHERE  company_id = '".$get['company_id']."' AND is_active=0";
		    $itemsres = $callConfig->getAllRows($itemssql);
		    foreach($itemsres as $ires){
		    	$items[$ires->id] = $ires;
		    }
		    $return['items_sql'] = $itemssql;
			$return['items'] = $items;
			$itemssql = "SELECT * FROM import_excel_data WHERE company_id = '".$get['company_id']."' AND file_name ='".$get['FIN']."' AND is_active=0";
		    $itemsres = $callConfig->getRow($itemssql);
		    $return['import_excel_data'] = $itemsres;
		    $return['import_excel_data_sql'] = $itemssql;

		}
		
		return $return;
	}
