	function tosendmessagetomobile($data){
    	global $callConfig;
    	//print_r($data); //exit;
    	$query = "SELECT * FROM sms_config WHERE company_id =".$data['company_id']." AND is_active =0";
    	//echo $query;
    	$row = $callConfig->getRow($query);
    	//print_r($row); exit;
    	if(count((array)$row)>0){
    		//print_r($row); exit;
	    	$array = [];
			$array['template_id'] = $row->template_id;
			$array['short_url'] = '1'; 
			$array['short_url_expiry'] = '60';
			$array['realTimeResponse'] = '1';
			$array['recipients'] = [
			    [
			        'mobiles' => '91'.$data['mobile_no'],
			        'name'    => $data['message']
			    ]
			];
			$curl = curl_init();
			curl_setopt_array($curl, [
			  CURLOPT_URL => $row->api_url,
			  CURLOPT_RETURNTRANSFER => true,
			  CURLOPT_ENCODING => "",
			  CURLOPT_MAXREDIRS => 10,
			  CURLOPT_TIMEOUT => 30,
			  CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
			  CURLOPT_CUSTOMREQUEST => "POST",
			  CURLOPT_POSTFIELDS => json_encode($array, JSON_UNESCAPED_SLASHES), // proper encoding
			  CURLOPT_HTTPHEADER => [
			    "accept: application/json",
			    "authkey: ".$row->auth_key,
			    "content-type: application/json"
			  ],
			]);

			$response = curl_exec($curl);
			$err = curl_error($curl);
			if ($err) {
			  $return['status'] = 'Fail';
			  $return['res'] = "cURL Error #:" . $err;
			} else {
				$return['status'] = 'Success';
			    $return['res'] = $response;
			    $return['get'] = $data;
			}
		}else{
			$return['status'] = 'Fail';
			$return['res'] = "SMS config is not set";
			$return['get'] = $data;
		}
		return $return;
    }
    function tosendwhatsappdata($data){
    	global $callConfig;
    	$query = "SELECT * FROM whatsapp_config WHERE company_id =".$data['company_id']." AND is_active =0";
    	//echo $query;
    	$row = $callConfig->getRow($query);
    	//print_r($row); exit;
    	$authKey = $row->auth_key;
    	$data['send_no'] = $data['send_no']!="" ? $data['send_no'] : COMPANY_SEND_NO;
		$integrated_number = "91".$data['send_no'];
		$recipient_number = "91".$data['recivce_no'];
		$template_name = "meeting_confirmation"; 
		$language_code = "en";
		$template_variables = [
		    "John Doe",          // {{1}} - Recipient's name
		    "INFISUITE",         // {{2}} - Host's name or company
		    $data['message'],   // {{3}} - Topic
		    "2025-08-25",        // {{4}} - Date
		    "11:00 AM",          // {{5}} - Time
		    "123 Main St, Anytown" // {{6}} - Location
		];

		$payload = [
		    "integrated_number" => $integrated_number,
		    "content_type" => "template",
		    "payload" => [
		        "type" => "template",
		        "template" => [
		            "name" => $template_name,
		            "language" => [
		                "code" => $language_code,
		            ],
		            "to_and_components" => [
		                [
		                    "to" => [
		                        $recipient_number
		                    ],
		                    "components" => [
		                        "body_1" => [ "type" => "text", "value" => $template_variables[0] ],
		                        "body_2" => [ "type" => "text", "value" => $template_variables[1] ],
		                        "body_3" => [ "type" => "text", "value" => $template_variables[2] ],
		                        "body_4" => [ "type" => "text", "value" => $template_variables[3] ],
		                        "body_5" => [ "type" => "text", "value" => $template_variables[4] ],
		                        "body_6" => [ "type" => "text", "value" => $template_variables[5] ]
		                    ]
		                ]
		            ]
		        ]
		    ]
		];

		// --- Step 4: Make the cURL request to the Msg91 API ---
		$api_url = $row->api_url;

		$curl = curl_init();
		curl_setopt_array($curl, [
		    CURLOPT_URL => $api_url,
		    CURLOPT_RETURNTRANSFER => true,
		    CURLOPT_CUSTOMREQUEST => "POST",
		    CURLOPT_POSTFIELDS => json_encode($payload),
		    CURLOPT_HTTPHEADER => [
		        "accept: application/json",
		        "authkey: " . $authKey,
		        "content-type: application/json"
		    ],
		]);

		$response = curl_exec($curl);
		$err = curl_error($curl);
		if ($err) {
		    $return['status'] = 'Fail';
			  $return['res'] = "cURL Error #:" . $err;
			  $return['get'] = $data;
		} else {
		     $return['status'] = 'Fail';
			$return['res'] = "SMS config is not set";
			$return['get'] = $data;
		}
		return $return;
    }
