	function insertskucode($post)
	{
		global $callConfig;
		$return = []; 
		$insertary = ['company_id' => $post['company_id'] ?? null, 'module_setup_id' => $post['module_setup_id'] ?? null, 'sku_generator_name' => $post['sku_generator_name'] ?? '', 'serial_number' => $post['serial_number'] ?? '', 'serial_number_length' => $post['serial_number_length'] ?? '', 'separation_symbol' => $post['separation_symbol'] ?? '', 'sku_generator_detail' => json_encode($post['sku_generator_detail'] ?? [])];
		try { 
			if (!empty($post['rid'])) {
				$insertary['updated_date'] = date('Y-m-d H:i:s');
				$insertary['updated_by'] = $post['user_id'] ?? null; 
				$res = $callConfig->updateRecord( 'application_item_sku_generators', $insertary, 'id', $post['rid'] ); 
				if ($res) {
					$return = [ 'status' => 'success', 'message' => 'SKU generator updated successfully.', 'action' => 'update', 'sku_generator_id' => $post['rid'] ];
				} else {
					$return = [ 'status' => 'error', 'message' => 'Failed to update SKU generator.' ];
				} 
			} else { 
				$insertary['created_by'] = $post['user_id'] ?? null;
				$insertary['created_date'] = date('Y-m-d H:i:s');
				$insertary['is_active'] = 0;
				$insertary['current_status'] = 0; 
				$res = $callConfig->insertRecord( 'application_item_sku_generators', $insertary ); 
				if (!empty($res['LASTID'])) {
					$return = [ 'status' => 'success', 'message' => 'SKU generator created successfully.', 'action' => 'insert', 'sku_generator_id' => $res['LASTID'] ];
				} else {
					$return = [ 'status' => 'error', 'message' => 'Failed to create SKU generator.' ];
				}
			} 
		} catch (Exception $e) {
			$return = [ 'status' => 'error', 'message' => 'Exception: ' . $e->getMessage() ];
		} 
		return $return;
	}
	function setSku($data)
	{
	    global $callConfig; 
	    $configSql = "SELECT sku_generators_id FROM config WHERE id = 1 LIMIT 1";
	    $configRow = $callConfig->getRow($configSql);
	    if (!$configRow || empty($configRow->sku_generators_id)) {
	        return ["error" => "No SKU generator configured"];
	    } 
	    $skuSql = "SELECT id, sku_generator_name, serial_number, serial_number_length, separation_symbol, sku_generator_detail  FROM application_item_sku_generators  WHERE id = '" . $configRow->sku_generators_id . "'  AND is_active = 0  LIMIT 1";
	    $skuRow = $callConfig->getRow($skuSql);
	    if (!$skuRow) {
	        return ["error" => "No SKU generator found"];
	    } 
	    $details    = json_decode($skuRow->sku_generator_detail, true);
	    $sep        = $skuRow->separation_symbol ?: "-";
	    $serialLen  = $skuRow->serial_number_length ?: 0;
	    $components = []; 
	    if (!empty($details['category_name']['enabled']) && !empty($data['category_id'])) {
	        $catSql = "SELECT category_short_name  FROM item_categories  WHERE id = '" . $data['category_id'] . "'  AND is_active = 0  LIMIT 1";
	        $catRow = $callConfig->getRow($catSql);
	        if ($catRow) {
	            $components[] = [
	                "seq"   => (int)$details['category_name']['sequence'],
	                "value" => $catRow->category_short_name
	            ];
	        }
	    } 
	    if (!empty($details['item_type']['enabled']) && !empty($data['item_type'])) {
	        $typeSql = "SELECT item_type_name  FROM item_types   WHERE id = '" . $data['item_type'] . "'  AND is_active = 0  LIMIT 1";
	        $typeRow = $callConfig->getRow($typeSql);
	        if ($typeRow) {
	            $words     = preg_split('/\s+/', trim($typeRow->item_type_name));
	            $shortCode = strtoupper(implode('', array_map(fn($w) => $w[0], $words)));
	            $components[] = [
	                "seq"   => (int)$details['item_type']['sequence'],
	                "value" => $shortCode
	            ];
	        }
	    } 
	    if (!empty($details['warehouse_name']['enabled']) && !empty($data['warehouse_id'])) {
	        $whSql = "SELECT warehouse_short_name, location_id 
	                  FROM warehouses 
	                  WHERE id = '" . $data['warehouse_id'] . "' 
	                    AND is_active = 0 
	                  LIMIT 1";
	        $whRow = $callConfig->getRow($whSql);
	        if ($whRow) {
	            $components[] = [
	                "seq"   => (int)$details['warehouse_name']['sequence'],
	                "value" => $whRow->warehouse_short_name
	            ];
	            if (!empty($details['location_name']['enabled']) && !empty($whRow->location_id)) {
	                $locSql = "SELECT short_name  FROM locations  WHERE id = '" . $whRow->location_id . "'  AND is_active = 0  LIMIT 1";
	                $locRow = $callConfig->getRow($locSql);
	                if ($locRow) {
	                    $components[] = [
	                        "seq"   => (int)$details['location_name']['sequence'],
	                        "value" => $locRow->short_name
	                    ];
	                }
	            }
	        }
	    } 
	    usort($components, fn($a, $b) => $a['seq'] <=> $b['seq']);
	    $parts     = array_column($components, "value");
	    $skuPrefix = implode($sep, $parts); 
	    $lastSkuSql = "SELECT sku FROM application_list_sku   WHERE sku LIKE '" . $skuPrefix . "%'  ORDER BY id DESC  LIMIT 1";
	    $lastSkuRow = $callConfig->getRow($lastSkuSql); 
	    if ($lastSkuRow && preg_match('/(\d+)$/', $lastSkuRow->sku, $matches)) {
	        $lastSerial = (int)$matches[1];
	        $serial     = $lastSerial + 1;
	    } else {
	        $serial = $skuRow->serial_number ?: 1;
	    } 
	    $serialFormatted = str_pad($serial, $serialLen, "0", STR_PAD_LEFT);
	    $finalSku        = $skuPrefix . $sep . $serialFormatted; 
	    $skuArray = [ "sku"           => $finalSku, "current_status"=> '0', "is_active"     => '0', "created_date"  => date('Y-m-d H:i:s'), "created_by"    => $data['user_id'] ?? 0 ];
	    $callConfig->insertRecord('application_list_sku', $skuArray); 
	    return ["sku" => $finalSku];
	} /**/
	 //End Omkar Code added 26-09-2025
