	function sendotptoverifymobile($get){
		global $callConfig;
		$updatequery = "UPDATE user_otp_authentication SET is_active = NULL WHERE company_id = ".$get['company_id']." AND mobile = ".$get['mobile']." AND is_active =0";
		$upquery = $callConfig->executeQuery($updatequery);

		$otp = $this->generateOTP(4);
		//echo "Check".$otp; exit;	
		$insert_array = array('company_id'=>$get['company_id'],'user_id'=>$get['user_id'],'otp_number'=>$otp,'created_by'=>$get['user_id'], 'mobile'=>$get['mobile'] ,'created_date'=>date("Y-m-d H:i:s"),'is_active'=>'0','current_status'=>'0');	
		//echo "Check".$otp; print_r($insert_array); exit;	
		$insert_data=$callConfig->insertRecord('user_otp_authentication',$insert_array);


		$res = array('status'=>'success',  'msg'=>'An OTP has been sent to your registered email ID and is also available on our web portal.');
		
		$message = 'Your OTP for mobile verification is '.$otp;
		$array = array('company_id'=>$get['company_id'], 'mobile_no'=>$get['mobile'], 'message'=>$message, 'send_no'=> '8179947020', 'recivce_no'=> $get['mobile'],'data_name'=>$get['data_name']);
		$res['msg_otp']['mobile'] = $this->tosendmessagetomobile($array);
		$res['msg_otp']['whatsup'] = $this->tosendwhatsappdata($array);
		return $res;
	}

	function verifyotpsendtomobile($get){
		global $callConfig;
		$query = "SELECT otp_number FROM user_otp_authentication WHERE company_id = ".$get['company_id']." AND mobile = ".$get['mobile']." AND is_active =0";
		$data = $callConfig->getRow($query);
		$return = array('status'=>'fail', 'msg'=>'OTP is wrong, Please reenter the OTP');
		if($get['otp']!=""){
			if($data->otp_number == $get['otp']){
				$return = array('status'=>'success', 'otp'=>$data->otp_number, 'msg'=>'OTP is verifed');
			}
		}
		return $return;
	}

	function toupdatestationerydetails($transaction_id,$get){
		global $callConfig;
		$res = array();
