	function generatingApplicationSerialNumberMasters($transaction_table,$get){
		global $callConfig;
		$return = array();
		$transaction_date = $get['transaction_date']!=""?$get['transaction_date']:date('Y-m-d');
		$party_id =  $get['party_id'];
		$transaction_type =  $get['transaction_type'];
		$asnsql = "SELECT * FROM application_serial_number_masters WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$transaction_table."' AND is_active = 0";
		$asnres = $callConfig->getRow($asnsql);
		if($asnres->id !=""){
			$main_transaction_no_type = $asnres->reset_type;
			$serial_number_position = $asnres->serial_number_position;
			$financial_year_position = $asnres->financial_year_position;
			$numLength   = !empty($asnres->doc_no_length) ? (int)$asnres->doc_no_length : 3;
			    	
			$display_attribute_typessql = "SELECT content FROM display_attribute_types WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$transaction_table."' AND field_name = 'party_id'";	
			$parttable_name = $callConfig->getRow($display_attribute_typessql);
			$qquery = urldecode($parttable_name->content);
			$explosql = explode("FROM", $qquery); // splite from to get table name and other part get
			if(isset($explosql[1])){
				$explosql = explode(" ", trim($explosql[1])); //splite to space only get table name
			}
			$partytable = trim($explosql[0]); //get Table name

			$checksequincerow = array();
			$transdate = $transaction_date !=""?$this->dateconvertdbformat($transaction_date):date('Y-m-d');
			$finyaer = date("m",strtotime($transdate)) >= 4 ? date("Y",strtotime($transdate)). '-' . (date("y",strtotime($transdate))+1) : (date("Y",strtotime($transdate)) - 1). '-' . date("y",strtotime($transdate));
			
	    	$additional_settings = json_decode($asnres->additional_settings,1);
	    	$position_with_val = array(); 
	    	foreach($additional_settings as $adsetting){
	    		$position_with_val[$adsetting['positions']] = $adsetting; 
	    	}
	    	
	    	$parts = [];
		    for ($m = 1; $m <= 10; $m++) {
		    	if (!empty($asnres->serial_number) && $serial_number_position == $m){
		            $parts[$m] = $serial;
		        }
		        if (!empty($finyaer) && $asnres->financial_year_check == "Y" && $financial_year_position == $m){
		            $parts[$m] = $finyaer;
		            //$checksequincerow[$m] = $finyaer;
		        }
		        if(isset($position_with_val[$m]) AND $position_with_val[$m]['display_type'] =="STATIC"){
		            if($position_with_val[$m]['static_value'] != ""){
		            	//$parts[$m] = $position_with_val[$m]['static_value'];
		            	$checksequincerow[$m] = $position_with_val[$m]['static_value'];
		            }
		        }elseif(isset($position_with_val[$m]) AND $position_with_val[$m]['display_type'] =="DYNAMIC"){
		            if($position_with_val[$m]['dynamic_value'] != ""){
		            	//$parts[$m] = $position_with_val[$m]['dynamic_value'];
		            	$checksequincerow[$m] = $position_with_val[$m]['dynamic_value'];
		            }
		        }
			}

			$insertwithconditionary = array();
		    $additional_conditions = "";
		    foreach($checksequincerow as $seq_key=>$seq_val){

		    	if($seq_val == "PARTY_NAME"){

					if($partytable !="" AND $party_id !=""){
						$partysql = "SELECT id, short_name FROM ".$partytable." WHERE company_id = ".$get['company_id']." AND id = ".$party_id." AND is_active = 0";
						$partyres = $callConfig->getRow($partysql);
						if($partyres->short_name !=""){
							$additional_conditions .= " AND position_".$seq_key." = '".$partyres->short_name."'";
							$insertwithconditionary["position_".$seq_key] = $partyres->short_name;
							$parts[$seq_key] = $partyres->short_name;
						}else{
							$additional_conditions .= " AND position_".$seq_key." = '".$seq_val."'";
							$insertwithconditionary["position_".$seq_key] = $seq_val;
							$parts[$seq_key] = $seq_val;
						}
					}else{
						$additional_conditions .= " AND position_".$seq_key." = '".$seq_val."'";
						$insertwithconditionary["position_".$seq_key] = $seq_val;
						$parts[$seq_key] = $seq_val;
					}
		    	
		    	}elseif($seq_val == "TRANSACTION_TYPE"){
		    		if($transaction_type !=""){
		    			$additional_conditions .= " AND position_".$seq_key." = '".$transaction_type."'";
		    			$insertwithconditionary["position_".$seq_key] = $transaction_type;
		    			$parts[$seq_key] = $transaction_type;
		    		}else{
		    			$additional_conditions .= " AND position_".$seq_key." = '".$seq_val."'";
		    			$insertwithconditionary["position_".$seq_key] = $seq_val;
		    			$parts[$seq_key] = $seq_val;
		    		}

		    	}elseif($seq_val == "TRANSACTION_LOCATION"){

		    		$locationsql = "SELECT prty.id, loc.short_name FROM ".$partytable." as prty, locations as loc WHERE prty.company_id = ".$get['company_id']." AND prty.company_id = loc.company_id AND prty.location_id = loc.id AND prty.is_active = loc.is_active AND prty.id = ".$party_id." AND prty.is_active = 0";
					$locationres = $callConfig->getRow($locationsql);
					if($locationres->short_name){
						$additional_conditions .= " AND position_".$seq_key." = '".$locationres->short_name."'";
						$insertwithconditionary["position_".$seq_key] = $locationres->short_name;
						$parts[$seq_key] = $locationres->short_name;
					}else{
						$additional_conditions .= " AND position_".$seq_key." = '".$seq_val."'";
						$insertwithconditionary["position_".$seq_key] = $seq_val;
						$parts[$seq_key] = $seq_val;
					}
		    	}else{
		    		$additional_conditions .= " AND position_".$seq_key." = '".$seq_val."'";
		    		$insertwithconditionary["position_".$seq_key] = $seq_val;
		    		$parts[$seq_key] = $seq_val;
		    	}
		    }	

		    ksort($parts);

			$monthlysql = "SELECT * FROM application_serial_number_master_details WHERE company_id = '".$get['company_id']."' AND application_serial_number_master_id = '".$asnres->id."' AND serial_number_reset_type = 'MT' AND from_date <= '".$this->dateconvertdbformat($transaction_date)."' AND to_date >= '".$this->dateconvertdbformat($transaction_date)."' AND is_active = 0".$additional_conditions;
			$monthlyres = $callConfig->getRow($monthlysql);

			if($monthlyres->id !=""){
					$serial_number = $monthlyres->serial_number+1;

					
					$serial = str_pad((string)$serial_number, $numLength, '0', STR_PAD_LEFT);
					$parts[$serial_number_position] = $serial;
					$callConfig->updateRecord('application_serial_number_master_details',array('serial_number' =>$serial_number),'id',$monthlyres->id);
			}else{

				$from_date = date("Y-m-01",strtotime($transaction_date));
				$to_date = date("Y-m-t",strtotime($transaction_date));

				$serial_number = 1;
				$serial = str_pad((string)$serial_number, $numLength, '0', STR_PAD_LEFT);
				$parts[$serial_number_position] = $serial;
				$insertary = array('company_id'=>$get['company_id'],'application_serial_number_master_id'=>$asnres->id, 'serial_number_reset_type'=>'MT','from_date'=>$from_date,'to_date'=>$to_date,'serial_number'=>1,'created_by'=>$get['user_id'],'created_date'=>date('Y-m-d H:i:s'),'current_status'=>0, 'is_active'=>0);
				foreach($insertwithconditionary as $fieldkey=>$filedval){
					$insertary[$fieldkey] = $filedval;	
				}
				$return['res'] = $callConfig->insertRecord('application_serial_number_master_details', $insertary);

			}

			$parts[$financial_year_position] = date("M-Y",strtotime($transaction_date));
			$monthly_transaction_number = trim(implode($asnres->separator_symbols, (array)$parts));
			$yearlysql = "SELECT * FROM application_serial_number_master_details WHERE company_id = '".$get['company_id']."' AND application_serial_number_master_id = '".$asnres->id."' AND serial_number_reset_type = 'YR' AND from_date <= '".$this->dateconvertdbformat($transaction_date)."' AND to_date >= '".$this->dateconvertdbformat($transaction_date)."' AND is_active = 0".$additional_conditions;
			$yearlyres = $callConfig->getRow($yearlysql);
			
			if(date("m",strtotime($transaction_date)) >= 4){
                $startyear = date("Y",strtotime($transaction_date));
                $endyear = (date("Y",strtotime($transaction_date))+1);
                $from_date = $startyear."-04-01";
                $to_date = $endyear."-03-31";
            }else{
                $startyear = (date("Y",strtotime($transaction_date)) - 1);
                $endyear = date("Y",strtotime($transaction_date));
                $from_date = $startyear."-04-01";
                $to_date = $endyear."-03-31";
            }

			if($yearlyres->id !=""){
				$serial_number = $yearlyres->serial_number+1;
				$serial = str_pad((string)$serial_number, $numLength, '0', STR_PAD_LEFT);
				$parts[$serial_number_position] = $serial;
				$callConfig->updateRecord('application_serial_number_master_details',array('serial_number' =>$serial_number),'id',$yearlyres->id);
			}else{
                $serial_number = 1;
				$serial = str_pad((string)$serial_number, $numLength, '0', STR_PAD_LEFT);
				$parts[$serial_number_position] = $serial;
				$insertary = array('company_id'=>$get['company_id'],'application_serial_number_master_id'=>$asnres->id, 'serial_number_reset_type'=>'YR','from_date'=>$from_date,'to_date'=>$to_date,'serial_number'=>1,'created_by'=>$get['user_id'],'created_date'=>date('Y-m-d H:i:s'),'current_status'=>0, 'is_active'=>0);
				foreach($insertwithconditionary as $fieldkey=>$filedval){
					$insertary[$fieldkey] = $filedval;	
				}
				$return['res'] = $callConfig->insertRecord('application_serial_number_master_details', $insertary);

			}
			$parts[$financial_year_position] = date("Y",strtotime($from_date))."-".date("y",strtotime($to_date));
			$yearly_transaction_number = trim(implode($asnres->separator_symbols, (array)$parts));
			$lifetimesql = "SELECT * FROM application_serial_number_master_details WHERE company_id = '".$get['company_id']."' AND application_serial_number_master_id = '".$asnres->id."' AND serial_number_reset_type = 'LT' AND from_date <= '".$this->dateconvertdbformat($transaction_date)."' AND to_date >= '".$this->dateconvertdbformat($transaction_date)."' AND is_active = 0".$additional_conditions;
			$lifetimeres = $callConfig->getRow($lifetimesql);

			if($lifetimeres->id !=""){
				$serial_number = $lifetimeres->serial_number+1;
				$serial = str_pad((string)$serial_number, $numLength, '0', STR_PAD_LEFT);
				$parts[$serial_number_position] = $serial;
				$callConfig->updateRecord('application_serial_number_master_details',array('serial_number' =>$serial_number),'id',$lifetimeres->id);
			}else{

			    $from_date = "2020-04-01";
                $to_date = "3020-03-31";
            	$serial_number = 1;
				$serial = str_pad((string)$serial_number, $numLength, '0', STR_PAD_LEFT);
				$parts[$serial_number_position] = $serial;
				$insertary = array('company_id'=>$get['company_id'],'application_serial_number_master_id'=>$asnres->id, 'serial_number_reset_type'=>'LT','from_date'=>$from_date,'to_date'=>$to_date,'serial_number'=>1,'created_by'=>$get['user_id'],'created_date'=>date('Y-m-d H:i:s'),'current_status'=>0, 'is_active'=>0);
				foreach($insertwithconditionary as $fieldkey=>$filedval){
					$insertary[$fieldkey] = $filedval;	
				}
				$return['res'] = $callConfig->insertRecord('application_serial_number_master_details', $insertary);
			}
			if($asnres->financial_year_check == "Y"){
				$parts[$financial_year_position] = date("Y",strtotime($transaction_date));
			}else{
				unset($parts[$financial_year_position]);
			}
			$lifetime_transaction_number = trim(implode($asnres->separator_symbols, (array)$parts));
		}
		$main_transaction_number = rand();
		$monthly_transaction_number = $monthly_transaction_number !=""?$monthly_transaction_number:rand();
		$yearly_transaction_number = $yearly_transaction_number !=""?$yearly_transaction_number:rand();
		$lifetime_transaction_number = $lifetime_transaction_number !=""?$lifetime_transaction_number:rand();
		if($main_transaction_no_type=="MT"){
			$main_transaction_number = $monthly_transaction_number;
		}elseif($main_transaction_no_type=="YR"){
			$main_transaction_number = $yearly_transaction_number;
		}elseif($main_transaction_no_type=="LT"){
			$main_transaction_number = $lifetime_transaction_number;
		}
		$returnres = array('main_transaction_number'=>$main_transaction_number,'monthly_transaction_number'=>$monthly_transaction_number, 'yearly_transaction_number'=>$yearly_transaction_number, 'lifetime_transaction_number'=>$lifetime_transaction_number);	
		return 	$returnres;		
	}
	function getAuditTrails_new($get){
		global $callConfig;
		$return['get'] = $get;
		$decod = json_decode($get['action_type'],1);
		$return['decod'] = $decod;
		if($get['type'] == "login"){
			if($get['from_date'] !="" && $get['to_date'] !=""){
				$condition .=" AND login_from between '".$this->dateconvertdbformat($get['from_date'])." 00:00:00' AND '".$this->dateconvertdbformat($get['to_date'])." 23:59:59'";	
			}
			$audit_trailssql = "SELECT user_id,login_from, login_to FROM application_user_logins WHERE company_id = '".$get['company_id']."' ".$condition." AND user_id = '".$get['user_id']."' ORDER BY DATE(login_from) DESC LIMIT 20";
			$audit_trailsres=$callConfig->getAllRows($audit_trailssql);
			$return['login'] = $audit_trailsres;
			$return['loginsql']= $audit_trailssql;	
		}elseif($get['type'] == "approval"){
			$json  = implode("','",(array)$decod);
			$condition .=" AND type IN('".$json."')";
			if($get['from_date'] !="" && $get['to_date'] !=""){
				$condition .=" AND request_date between '".$this->dateconvertdbformat($get['from_date'])." 00:00:00' AND '".$this->dateconvertdbformat($get['to_date'])." 23:59:59'";	
			}
			$transaction_approval_logssql = "SELECT transaction_table,transaction_id, response_type,user_id,request_date,response_date FROM transaction_approval_logs WHERE user_id = '".$get['user_id']."' ORDER BY DATE(request_date) DESC limit 20";
			$transaction_approval_logsres=$callConfig->getAllRows($transaction_approval_logssql);
			$return['approval'] = $transaction_approval_logsres;
			$return['approvalsql']= $transaction_approval_logssql;	
		}else{	
			if($get['action_type'] !="" AND $get['action_type'] != "null"){
				$json  = implode("','",(array)$decod);
				$condition .=" AND type IN('".$json."')";
			}else{
				$condition .=" AND type IN('VIEW')";
			}
			if($get['from_date'] !="" && $get['to_date'] !=""){
				$condition .=" AND created_date between '".$this->dateconvertdbformat($get['from_date'])." 00:00:00' AND '".$this->dateconvertdbformat($get['to_date'])." 23:59:59'";	
			}
			$audit_trailssql = "SELECT * FROM audit_trails WHERE company_id = '".$get['company_id']."' ".$condition." AND transaction_table LIKE '%employee_daily_attendances%' AND is_active = 0 ORDER BY created_date DESC limit 20";
			$audit_trailsres=$callConfig->getAllRows($audit_trailssql);
			$return['audit_trails'] = $audit_trailsres;
			$return['sql']= $audit_trailssql;

			$application_pagessql = "SELECT application_table_name FROM application_pages WHERE company_id = '".$get['company_id']."' AND is_active = 0";
			$application_pagesres=$callConfig->getAllRows($application_pagessql);
			$return['application_pages'] = $application_pagesres;
		}	
		return $return;
	}
    // related to manufacturing
    function saveStockRequestOrder($transaction_no, $get){

		global $callConfig;
		$return_arr = array();
		$company_id = $get['company_id'];
		$user_id = $get['user_id'];
		
		// Get manufacturing work order data
		$work_order_sql = "SELECT * FROM manufacturing_work_orders WHERE company_id = '".$company_id."' AND id = '".$transaction_no."' AND is_active = 0";
		$work_order_res = $callConfig->getRow($work_order_sql);
		$return_arr['work_order'] = $work_order_res;
		
		if(!empty($work_order_res)){
			$existing_stock_request_sql = "SELECT * FROM stock_requests WHERE company_id = '".$company_id."' AND ref_type = 'manufacturing_work_orders' AND ref_id = '".$transaction_no."' AND is_active = 0";
			$existing_stock_request_res = $callConfig->getRow($existing_stock_request_sql);
			if(!empty($existing_stock_request_res->id)){
				$return_arr['stock_request_existing'] = $existing_stock_request_res;
				$return_arr['message'] = 'Stock request already exists for this work order.';
				return $return_arr;
			}

			// Get manufacturing work order items
			$work_order_items_sql = "SELECT * FROM manufacturing_work_order_items WHERE company_id = '".$company_id."' AND transaction_id = '".$transaction_no."' AND is_active = 0";
			$work_order_items_res = $callConfig->getAllRows($work_order_items_sql);
			$return_arr['work_order_items'] = $work_order_items_res;
			if(empty($work_order_items_res)){
				$return_arr['message'] = 'No active work order items found for stock request creation.';
				return $return_arr;
			}
			
			// Get all items at once for efficiency
			$item_ids = array_filter(array_unique(array_map(function($item) { return intval($item->item_id); }, $work_order_items_res)));
			if(empty($item_ids)){
				$return_arr['message'] = 'No valid item ids found for stock request creation.';
				return $return_arr;
			}
			$item_ids_str = implode(',', $item_ids);
			$items_sql = "SELECT * FROM items WHERE company_id = '".$company_id."' AND id IN (".$item_ids_str.") AND is_active = 0";
			$items_all_res = $callConfig->getAllRows($items_sql);

			
			// Create items array keyed by id for quick lookup
			$items_array = array();
			foreach($items_all_res as $item){
				$items_array[$item->id] = $item;
			}
			
			$get['transaction_date'] = date('Y-m-d');
			// Generate transaction number
			$transaction_number = $this->toGetApplicationSerialNumber('stock_requests',$get);
			$request_warehouse_id = !empty($work_order_res->warehouse) ? $work_order_res->warehouse : 0;
			
			// Insert into stock_requests table
			$stock_request_data = array(
				'company_id' => $work_order_res->company_id,
				'cost_center_id' => 0,
				'transaction_number' => $transaction_number,
				'transaction_date' => $work_order_res->transaction_date,
				'transaction_location_id' => 0,
				'transaction_warehouse_id' => $request_warehouse_id,
				'request_warehouse_id' => $request_warehouse_id,
				'originator' => $work_order_res->originator,
				'parent_id' => $work_order_res->parent_manufacturing_work_order_id ?? '',
				'ref_type' => 'manufacturing_work_orders',
				'ref_id' => $work_order_res->id,
				'ref_no' => $work_order_res->transaction_no,
				'ref_date' => $work_order_res->transaction_date,
				'is_active' => 0,
				'current_status' => ST_APPROVED,
				'status_date' => date('Y-m-d'),
				'from_date' => $work_order_res->from_date ?? date('Y-m-d'),
				'to_date' => $work_order_res->to_date ?? date('Y-m-d'),
				'created_by' => $user_id,
				'created_date' => date('Y-m-d H:i:s'),
				'updated_by' => $user_id,
				'updated_date' => date('Y-m-d H:i:s')
			);
			
			$stock_request_insert = $callConfig->insertRecord('stock_requests', $stock_request_data);
			$return_arr['stock_request_insert'] = $stock_request_insert;

			

			
			if($stock_request_insert['status'] == 'sucess' && !empty($work_order_items_res)){
				$stock_request_id = $stock_request_insert['LASTID'];
				$stock_request_amount = 0;
				$stock_request_tax_amount = 0;
				
				// Loop through work order items and insert into stkreq_items
				foreach($work_order_items_res as $work_item){
					// Get item from pre-fetched array
					if(isset($items_array[$work_item->item_id])){
						$item_res = $items_array[$work_item->item_id];
						
						$item_price = !empty($work_item->rate) ? $work_item->rate : $item_res->purchase_price;
						$item_quantity = !empty($work_item->request_qty) ? $work_item->request_qty : 0;
						$item_amount = $item_price * $item_quantity;
						
						// Tax amount set to 0 (will be implemented later)
						$tax_amount = 0;
						
						$total_amount = $item_amount + $tax_amount;
						$stock_request_amount += $item_amount;
						$stock_request_tax_amount += $tax_amount;
						
						$stkreq_item_data = array(
							'company_id' => $work_item->company_id,
							'transaction_id' => $stock_request_id,
							'item_id' => $work_item->item_id,
							'item_name' => $item_res->item_name,
							'description' => $work_item->description ?? $item_res->item_description,
							'purchase_uom' => $work_item->uom ?? $item_res->purchase_uom,
							'item_quantity' => $item_quantity,
							'item_price' => $item_price,
							'item_amount' => $item_amount,
							'tax_amount' => $tax_amount,
							'total_amount' => $total_amount,
							'approved_quantity' => 0,
							'pending_qty' => $item_quantity,
							'transaction_qty' => $item_quantity,
							'ref_transaction_table_id' => $work_order_res->id,
							'ref_transaction_item_table_id' => $work_item->id,
							'is_active' => 0,
							'current_status' => 0,
							'status_date' => date('Y-m-d'),
							'from_date' => $work_item->from_date ?? date('Y-m-d'),
							'to_date' => $work_item->to_date ?? date('Y-m-d'),
							'created_by' => $user_id,
							'created_date' => date('Y-m-d H:i:s'),
							'updated_by' => $user_id,
							'updated_date' => date('Y-m-d H:i:s')
						);
						
						$stkreq_item_insert = $callConfig->insertRecord('stkreq_items', $stkreq_item_data);
						$return_arr['stkreq_items_insert'][] = $stkreq_item_insert;
						$callConfig->updateRecord('manufacturing_work_order_items', array('stock_request_id' => $stock_request_id, 'stock_request_qty' => $item_quantity), 'id', $work_item->id);
					}
				}
				$stock_request_total_amount = $stock_request_amount + $stock_request_tax_amount;
				$callConfig->updateRecord('stock_requests', array('amount' => $stock_request_amount, 'tax_amount' => $stock_request_tax_amount, 'total_amount' => $stock_request_total_amount, 'pending_amount' => $stock_request_total_amount), 'id', $stock_request_id);
				$return_arr['shortage_requisition'] = $this->createManufacturingShortageRequisition($stock_request_id, $get);
			}
		}
		
		return $return_arr;
	}

	function createManufacturingShortageRequisition($stock_request_id, $get){
		global $callConfig;
		$return_arr = array('status' => 'skipped', 'message' => 'No purchase shortage found');
		$stock_request_id = intval($stock_request_id);
		$company_id = intval($get['company_id'] ?? 0);
		$user_id = intval($get['user_id'] ?? 0);
		if($stock_request_id <= 0 || $company_id <= 0){
			return $return_arr;
		}

		$existing_requisition = $callConfig->getRow("SELECT id, transaction_number FROM requisitions WHERE company_id = '".$company_id."' AND ref_type = 'stock_requests' AND ref_id = '".$stock_request_id."' AND is_active = 0 LIMIT 0,1");
		if(!empty($existing_requisition->id)){
			return array('status' => 'skipped', 'message' => 'Shortage requisition already exists', 'requisition_id' => $existing_requisition->id, 'transaction_number' => $existing_requisition->transaction_number);
		}

		$stock_request = $callConfig->getRow("SELECT * FROM stock_requests WHERE company_id = '".$company_id."' AND id = '".$stock_request_id."' AND ref_type = 'manufacturing_work_orders' AND is_active = 0");
		if(empty($stock_request->id)){
			return $return_arr;
		}

		$items = $callConfig->getAllRows("SELECT sri.*, itm.item_name AS master_item_name, itm.item_description, itm.purchase_price, itm.purchase_uom AS master_purchase_uom, itm.base_uom, itm.inventory_asset_account, itm.purchase_expense_account, itm.purchase_price AS item_st_cost
			FROM stkreq_items sri
			LEFT JOIN items itm ON itm.company_id = sri.company_id AND itm.id = sri.item_id AND itm.is_active = 0
			WHERE sri.company_id = '".$company_id."' AND sri.transaction_id = '".$stock_request_id."' AND sri.is_active = 0");
		$shortage_items = array();
		$amount = 0;
		foreach((array)$items as $item){
			$item_id = intval($item->item_id ?? 0);
			$request_qty = floatval($item->item_quantity ?? 0);
			if($item_id <= 0 || $request_qty <= 0){
				continue;
			}
			$balance = $callConfig->getRow("SELECT closing_qty FROM item_wa_balances WHERE company_id = '".$company_id."' AND item_id = '".$item_id."' ORDER BY balance_date DESC, id DESC LIMIT 0,1");
			$available_qty = floatval($balance->closing_qty ?? 0);
			$po_row = $callConfig->getRow("SELECT SUM(pi.pending_qty) AS pending_qty FROM purchase_orders po INNER JOIN po_items pi ON pi.company_id = po.company_id AND pi.transaction_id = po.id AND pi.is_active = po.is_active WHERE po.company_id = '".$company_id."' AND po.current_status = '".ST_APPROVED."' AND po.is_active = 0 AND pi.item_id = '".$item_id."'");
			$pending_po_qty = floatval($po_row->pending_qty ?? 0);
			$shortage_qty = $request_qty - $available_qty - $pending_po_qty;
			if($shortage_qty <= 0){
				continue;
			}
			$item_price = floatval($item->item_price ?? 0);
			if($item_price <= 0){
				$item_price = floatval($item->purchase_price ?? 0);
			}
			$item_amount = $shortage_qty * $item_price;
			$amount += $item_amount;
			$item->shortage_qty = $shortage_qty;
			$item->shortage_amount = $item_amount;
			$item->available_qty = $available_qty;
			$item->pending_po_qty = $pending_po_qty;
			$item->shortage_price = $item_price;
			$shortage_items[] = $item;
		}

		if(count($shortage_items) == 0){
			return $return_arr;
		}

		$user = $callConfig->getRow("SELECT location_id, default_warehouse_id, default_currency_id, cost_center, default_state_id FROM application_users WHERE company_id = '".$company_id."' AND id = '".$user_id."' AND is_active = 0");
		$get['transaction_date'] = date('Y-m-d');
		$transaction_number = $this->toGetApplicationSerialNumber('requisitions', $get);
		$requisition = array(
			'company_id' => $company_id,
			'cost_center_id' => intval($user->cost_center ?? 0),
			'transaction_number' => $transaction_number,
			'transaction_date' => date('Y-m-d'),
			'transaction_location_id' => intval($stock_request->transaction_location_id ?? ($user->location_id ?? 0)),
			'transaction_warehouse_id' => intval($stock_request->request_warehouse_id ?? ($user->default_warehouse_id ?? 0)),
			'currency_id' => intval($user->default_currency_id ?? 0),
			'currency_rate' => 1,
			'originator' => intval($stock_request->originator ?? $user_id),
			'party_id' => 0,
			'notes' => 'Auto requisition for manufacturing material shortage against '.$stock_request->transaction_number,
			'amount' => $amount,
			'tax_amount' => 0,
			'total_amount' => $amount,
			'pending_amount' => $amount,
			'type' => 'U',
			'tax_type' => 'E',
			'discount_type' => 'P',
			'discount_value' => 0,
			'discount_amount' => 0,
			'shipping_tax' => 0,
			'shipping_amount' => 0,
			'shipping_tax_amount' => 0,
			'tax_state' => 'S',
			'opex_cpex' => 0,
			'ref_type' => 'stock_requests',
			'ref_id' => $stock_request->id,
			'ref_no' => $stock_request->transaction_number,
			'ref_date' => $stock_request->transaction_date,
			'originator_currency_id' => intval($user->default_currency_id ?? 0),
			'originator_state_id' => intval($user->default_state_id ?? 0),
			'supplier_state_id' => intval($user->default_state_id ?? 0),
			'additional_charges' => '[]',
			'total_tax_split_details' => '[]',
			'rounding_off' => 0,
			'party_additional_details' => '{}',
			'compliance_specification_documents' => '[]',
			'discount_mode' => 'DO',
			'is_active' => 0,
			'current_status' => ST_DRAFT,
			'created_by' => $user_id,
			'created_date' => date('Y-m-d H:i:s')
		);
		$requisition_insert = $callConfig->insertRecord('requisitions', $requisition);
		$return_arr = array('status' => 'created', 'requisition_insert' => $requisition_insert, 'shortage_items' => count($shortage_items));
		if($requisition_insert['status'] == 'sucess'){
			$requisition_id = intval($requisition_insert['LASTID']);
			foreach($shortage_items as $item){
				$item_details = json_encode(array(
					'qoh' => $item->available_qty,
					'po' => $item->pending_po_qty,
					'available' => $item->available_qty + $item->pending_po_qty,
					'shortage' => $item->shortage_qty,
					'stock_request_id' => $stock_request_id
				));
				$rq_item = array(
					'company_id' => $company_id,
					'transaction_id' => $requisition_id,
					'item_id' => $item->item_id,
					'account_code' => $item->purchase_expense_account ?: $item->inventory_asset_account,
					'item_name' => $item->item_name ?: $item->master_item_name,
					'description' => $item->description ?: $item->item_description,
					'purchase_uom' => $item->purchase_uom ?: $item->master_purchase_uom,
					'item_quantity' => $item->shortage_qty,
					'item_price' => $item->shortage_price,
					'item_amount' => $item->shortage_amount,
					'tax_amount' => 0,
					'total_amount' => $item->shortage_amount,
					'item_wa_cost' => $item->shortage_price,
					'item_st_cost' => floatval($item->item_st_cost ?? $item->purchase_price ?? 0),
					'item_fifo_cost' => $item->shortage_price,
					'item_lifo_cost' => $item->shortage_price,
					'req_date' => date('Y-m-d'),
					'approved_quantity' => 0,
					'transaction_qty' => 0,
					'pending_qty' => $item->shortage_qty,
					'item_details' => $item_details,
					'ref_transaction_table_id' => $stock_request_id,
					'ref_transaction_item_table_id' => $item->id,
					'is_active' => 0,
					'current_status' => 0,
					'created_by' => $user_id,
					'created_date' => date('Y-m-d H:i:s')
				);
				$return_arr['rq_items_insert'][] = $callConfig->insertRecord('rq_items', $rq_item);
			}
		}
		return $return_arr;
	}
