	function getModuleRoleLogs($get){
		global $callConfig;
		$return = array();
		$return['module_role_logs'] = array();
		$return['filter_modules'] = array();
		$return['filter_roles'] = array();

		$company_id = isset($get['company_id']) ? $get['company_id'] : '';
		if($company_id == ''){
			return $return;
		}

		$modules_sql = "SELECT module_id, display_name FROM module_setup WHERE company_id = '".$company_id."' AND is_active = 0 ORDER BY display_name ASC";
		$modules_res = $callConfig->getAllRows($modules_sql);
		if(count((array)$modules_res) > 0){
			foreach($modules_res as $module_row){
				$return['filter_modules'][] = $module_row;
			}
		}

		$roles_sql = "SELECT id, display_name, role_short_code, application_module FROM application_roles WHERE company_id = '".$company_id."' AND application_module IN (SELECT module_id FROM module_setup WHERE company_id = '".$company_id."' AND is_active = 0) AND is_active = 0 ORDER BY display_name ASC";
		$roles_res = $callConfig->getAllRows($roles_sql);
		if(count((array)$roles_res) > 0){
			foreach($roles_res as $role_row){
				$return['filter_roles'][] = $role_row;
			}
		}

		$filters_only = isset($get['filters_only']) ? $get['filters_only'] : '';
		if($filters_only == 'Y'){
			return $return;
		}

		$common_where = " aumr.company_id = '".$company_id."' ";

		$user_id = isset($get['filter_user_id']) ? $get['filter_user_id'] : '';
		if($user_id == '' && isset($get['filter_user'])){
			$user_id = $get['filter_user'];
		}
		if($user_id != ''){
			$common_where .= " AND aumr.user_id = '".$user_id."' ";
		}

		$module_id = isset($get['filter_module_id']) ? $get['filter_module_id'] : '';
		if($module_id != ''){
			$common_where .= " AND aumr.application_module_id = '".$module_id."' ";
		}

		$role_id = isset($get['filter_role_id']) ? $get['filter_role_id'] : '';
		if($role_id != ''){
			$common_where .= " AND aumr.role_id = '".$role_id."' ";
		}

		$from_date = isset($get['from_date']) ? $get['from_date'] : '';
		$to_date = isset($get['to_date']) ? $get['to_date'] : '';
		$action_filter = isset($get['action']) ? $get['action'] : '';
		$action_by = isset($get['action_by']) ? $get['action_by'] : '';

		$assigned_where = $common_where;
		$removed_where = $common_where." AND aumr.is_active IS NULL ";

		if($from_date != '' && $to_date != ''){
			$assigned_where .= " AND aumr.created_date BETWEEN '".$from_date." 00:00:00' AND '".$to_date." 23:59:59' ";
			$removed_where .= " AND COALESCE(aumr.updated_date, aumr.to_date) BETWEEN '".$from_date." 00:00:00' AND '".$to_date." 23:59:59' ";
		}

		if($action_by != ''){
			$assigned_where .= " AND aumr.created_by = '".$action_by."' ";
			$removed_where .= " AND aumr.updated_by = '".$action_by."' ";
		}

		$assigned_sql = "SELECT aumr.id AS log_id, aumr.user_id, 'Assigned' AS action_type, aumr.application_module_id, aumr.role_id, aumr.role_short_code, aumr.created_by AS action_by, aumr.created_date AS action_date, ms.display_name AS module_name, ar.display_name AS role_name FROM application_user_module_roles aumr LEFT JOIN module_setup ms ON aumr.company_id = ms.company_id AND aumr.application_module_id = ms.module_id AND ms.is_active = 0 LEFT JOIN application_roles ar ON aumr.company_id = ar.company_id AND aumr.role_id = ar.id AND ar.is_active = 0 WHERE ".$assigned_where;

		$removed_sql = "SELECT aumr.id AS log_id, aumr.user_id, 'Removed' AS action_type, aumr.application_module_id, aumr.role_id, aumr.role_short_code, aumr.updated_by AS action_by, COALESCE(aumr.updated_date, aumr.to_date) AS action_date, ms.display_name AS module_name, ar.display_name AS role_name FROM application_user_module_roles aumr LEFT JOIN module_setup ms ON aumr.company_id = ms.company_id AND aumr.application_module_id = ms.module_id AND ms.is_active = 0 LEFT JOIN application_roles ar ON aumr.company_id = ar.company_id AND aumr.role_id = ar.id AND ar.is_active = 0 WHERE ".$removed_where;

		if($action_filter == 'Assigned'){
			$sql = $assigned_sql." ORDER BY action_date DESC";
		}elseif($action_filter == 'Removed'){
			$sql = $removed_sql." ORDER BY action_date DESC";
		}else{
			$sql = "SELECT * FROM (".$assigned_sql." UNION ALL ".$removed_sql.") AS module_role_log_events ORDER BY action_date DESC";
		}

		$return['sql'] = $sql;
		$logs_res = $callConfig->getAllRows($sql);
		if(count((array)$logs_res) > 0){
			foreach($logs_res as $log_row){
				$return['module_role_logs'][] = $log_row;
			}
		}

		return $return;
	}
	function getFailedLoginAttempts($get){
		global $callConfig;
		$return = array();
		$return['failed_login_attempts'] = array();

		$db_name = isset($get['data_name']) ? $get['data_name'] : '';
		if($db_name == ''){
			return $return;
		}

		$where = " db_name = '".$db_name."' ";

		$from_date = isset($get['from_date']) ? $get['from_date'] : '';
		$to_date = isset($get['to_date']) ? $get['to_date'] : '';
		if($from_date != '' && $to_date != ''){
			$where .= " AND created_date BETWEEN '".$from_date." 00:00:00' AND '".$to_date." 23:59:59' ";
		}

		$email_id = isset($get['email_id']) ? trim($get['email_id']) : '';
		if($email_id != ''){
			$where .= " AND email_id LIKE '%".$email_id."%' ";
		}

		/*$domain_name = isset($get['domain_name']) ? trim($get['domain_name']) : '';
		if($domain_name != ''){
			$where .= " AND domain_name LIKE '%".$domain_name."%' ";
		}*/

		$device_source = isset($get['device_source']) ? trim($get['device_source']) : '';
		if($device_source != ''){
			$where .= " AND device_source LIKE '%".$device_source."%' ";
		}

		$having = "";
		$frequency = isset($get['frequency']) ? $get['frequency'] : '';
		if($frequency == 'once'){
			$having = " HAVING attempt_count = 1 ";
		}elseif($frequency == 'more_than_1'){
			$having = " HAVING attempt_count > 1 ";
		}elseif($frequency == 'more_than_2'){
			$having = " HAVING attempt_count > 2 ";
		}elseif($frequency == 'more_than_3'){
			$having = " HAVING attempt_count > 3 ";
		}elseif($frequency == 'more_than_4'){
			$having = " HAVING attempt_count > 4 ";
		}elseif($frequency == 'more_than_5'){
			$having = " HAVING attempt_count > 5 ";
		}

		$sql = "SELECT email_id, COUNT(*) AS attempt_count, MAX(created_date) AS last_attempt_date, MAX(domain_name) AS domain_name, MAX(device_source) AS device_source FROM ".MAINDB.".user_failed_login_attempts WHERE ".$where." GROUP BY email_id ".$having." ORDER BY last_attempt_date DESC";
		$return['sql'] = $sql;
		$rows = $callConfig->getAllRows($sql);
		if(count((array)$rows) > 0){
			foreach($rows as $row){
				$return['failed_login_attempts'][] = $row;
			}
		}

		return $return;
	}

	function getFailedLoginAttemptDetails($get){
		global $callConfig;
		$return = array();
		$return['failed_login_attempt_details'] = array();
 
		$db_name = isset($get['data_name']) ? $get['data_name'] : '';
		$email_id = isset($get['email_id']) ? $get['email_id'] : '';
		if($db_name == '' || $email_id == ''){
			return $return;
		}
 
		$where = " db_name = '".$db_name."' AND email_id = '".$email_id."' ";
 
		$from_date = isset($get['from_date']) ? $get['from_date'] : '';
		$to_date = isset($get['to_date']) ? $get['to_date'] : '';
		if($from_date != '' && $to_date != ''){
			$where .= " AND created_date BETWEEN '".$from_date." 00:00:00' AND '".$to_date." 23:59:59' ";
		}
 
		$sql = "SELECT id, email_id, password, device_source, domain_name, zqr_connect, db_name, created_date FROM ".MAINDB.".user_failed_login_attempts WHERE ".$where." ORDER BY created_date DESC";
		$return['sql'] = $sql;
		$rows = $callConfig->getAllRows($sql);
 
		$zqr_connect_ids = array();
		if(count((array)$rows) > 0){
			foreach($rows as $row){
				if(isset($row->zqr_connect) && $row->zqr_connect != '' && $row->zqr_connect != '0'){
					$zqr_connect_ids[$row->zqr_connect] = $row->zqr_connect;
				}
			}
		}
 
		$zqr_connect_db_map = array();
		if(count((array)$zqr_connect_ids) > 0){
			$allocation_db = MAINDB;
			$table_check_sql = "SHOW TABLES FROM `".MAINDB."` LIKE 'database_allocations'";
			$table_check = $callConfig->getAllRows($table_check_sql);
			if(count((array)$table_check) == 0){
				$allocation_db = 'infistaqin_infisuite_common';
			}
			$alloc_sql = "SELECT id, db_name FROM ".$allocation_db.".database_allocations WHERE id IN (".implode(',', (array)$zqr_connect_ids).")";
			$return['alloc_sql'] = $alloc_sql;
			$alloc_rows = $callConfig->getAllRows($alloc_sql);
			if(count((array)$alloc_rows) > 0){
				foreach($alloc_rows as $alloc_row){
					$zqr_connect_db_map[$alloc_row->id] = $alloc_row->db_name;
				}
			}
		}
 
		if(count((array)$rows) > 0){
			foreach($rows as $row){
				$row->zqr_db_name = '';
				if(isset($row->zqr_connect) && isset($zqr_connect_db_map[$row->zqr_connect])){
					$row->zqr_db_name = $zqr_connect_db_map[$row->zqr_connect];
				}
				$return['failed_login_attempt_details'][] = $row;
			}
		}
 
		return $return;
	}
	function getCancelInvoicePopUp($get){
		global $callConfig;
		$transaction_table = $get['transaction_table'];
		$transaction_id = $get['transaction_id'];
		$query = "SELECT * FROM ".$transaction_table." WHERE company_id = '".$get['company_id']."' AND id = '".$transaction_id."' AND is_active = 0";
		$transaction_details = $callConfig->getRow($query);
		$return['transaction'] = $transaction_details;
		

		$query = "SELECT transaction_table, reference_table FROM `dynamic_reference_tables` WHERE transaction_table = '".$transaction_table."'";
		$reftrans = $callConfig->getAllRows($query);
		foreach($reftrans as $reftra){
			$dmtsql = "SELECT id, page_title, application_table_name,display_table,item_table,tax_table FROM `dynamic_mapping_tables` WHERE company_id = '".$get['company_id']."' AND application_table_name = '".$reftra->reference_table."' AND is_active = 0 AND item_table !='' AND tax_table!=''";
			$dmtres=$callConfig->getRow($dmtsql);
			$return['dynamic_mapping_tables'][] = $dmtres;
			$query = "SELECT po.id, po.transaction_number, po.transaction_date FROM ".$dmtres->application_table_name." po, ".$dmtres->item_table." poi WHERE po.company_id = '".$get['company_id']."' AND po.ref_type = '".$transaction_table."' AND poi.ref_transaction_table_id = '".$transaction_details->id."' AND po.id = poi.transaction_id AND po.is_active = 0";
			$ref_transaction = $callConfig->getRow($query);
			if($ref_transaction->id  !=""){
				$return['ref_transaction_sql'][$dmtres->application_table_name] = $query;
				$return['ref_transaction'][$dmtres->application_table_name] = $ref_transaction;
			}
			
		}		
		return $return;
	}
